window.QUIZ_ZK_DATA=window.QUIZ_ZK_DATA||{};
window.QUIZ_ZK_DATA["mk15044"]=[{"id":"mk15044-pl-P4803353","type":"sc","tier":"基础","conf":"adapt","chap":"第3-4章","q":"社会存在是指（）","opts":["A. 社会物质生产资料的总和","B. 社会物质生活资料的总和","C. 社会物质生产关系的总和","D. 社会物质生活条件的总和"],"ans":3,"explain":"社会存在是指社会物质生活条件，主要包括自然地理环境、人口因素和物质生产方式，所以是社会物质生活条件的总和。"},{"id":"mk15044-pl-P4803354","type":"sc","tier":"基础","conf":"adapt","chap":"第3-4章","q":"下列选项中属于意识形态的是（）","opts":["A. 语言学","B. 物理学","C. 哲学","D. 数学"],"ans":2,"explain":"意识形态通常包括政治法律思想、道德、艺术、宗教、哲学等，自然科学和语言学、形式逻辑等一部分社会科学属于非意识形态，所以哲学属于意识形态。"},{"id":"mk15044-pl-P4803355","type":"sc","tier":"基础","conf":"adapt","chap":"第3-4章","q":"地理环境在社会发展中的作用是（）","opts":["A. 影响社会结构的划分","B. 影响社会发展的速度","C. 决定社会制度的性质","D. 决定社会形态的更替"],"ans":1,"explain":"地理环境是人类社会生存和发展的必要条件，其优劣影响劳动生产率，进而影响社会发展的速度，但不能决定社会制度的性质和社会形态的更替。"},{"id":"mk15044-pl-P4803356","type":"sc","tier":"基础","conf":"adapt","chap":"第3-4章","q":"在人类社会发展中起决定作用的是（）","opts":["A. 差异多样的地理环境","B. 丰腴富饶的自然资源","C. 协调合理的人口结构","D. 物质资料的生产方式"],"ans":3,"explain":"物质生产方式是社会存在和发展的基础及决定力量，它决定社会的结构、性质和面貌，制约社会生活各方面，其变化发展决定社会历史的变化发展和社会形态的更替。"},{"id":"mk15044-pl-P4803357","type":"sc","tier":"基础","conf":"adapt","chap":"第3-4章","q":"“作为观念形态的文艺作品，都是一定的社会生活在人脑中反映的产物”，这句话强调的是（）","opts":["A. 社会意识根源于社会存在","B. 社会意识具有历史继承性","C. 社会存在根源于社会意识","D. 社会意识具有相对独立性"],"ans":0,"explain":"社会意识是社会存在的反映，该句话表明文艺作品这种观念形态的社会意识来源于社会生活，即社会意识根源于社会存在。"},{"id":"mk15044-pl-P4803358","type":"sc","tier":"基础","conf":"adapt","chap":"第3-4章","q":"先进的社会意识之所以对社会存在的发展起促进作用，是由于（）","opts":["A. 它是对社会存在的能动反映","B. 它是对社会规律的正确反映","C. 它应社会生活的需求而产生","D. 它随着社会生活发展而变化"],"ans":1,"explain":"先进的社会意识对社会存在起促进作用，是因为它正确反映了社会规律，能预见社会发展趋势，为社会实践提供正确指导。"},{"id":"mk15044-pl-P4803359","type":"sc","tier":"基础","conf":"adapt","chap":"第3-4章","q":"在社会存在与社会意识的关系问题上，两种根本对立的观点是（）","opts":["A. 历史唯物主义和历史唯心主义","B. 反映论和先验论","C. 机械唯物主义和辩证唯物主义","D. 唯理论和经验论"],"ans":0,"explain":"在社会存在与社会意识的关系问题上，历史唯物主义认为社会存在决定社会意识，历史唯心主义认为社会意识决定社会存在，这是两种根本对立的观点。"},{"id":"mk15044-pl-P4803360","type":"sc","tier":"基础","conf":"adapt","chap":"第3-4章","q":"下列各项中属于社会心理的是（）","opts":["A. 政治与法律","B. 哲学与宗教","C. 科学与艺术","D. 风俗与习惯"],"ans":3,"explain":"社会心理是低层次的社会意识，表现为人们的感知、情绪、情感、心态、习俗等，风俗与习惯属于社会心理，而政治与法律、哲学与宗教、科学与艺术属于社会意识形式。"},{"id":"mk15044-pl-P4803361","type":"sc","tier":"基础","conf":"adapt","chap":"第3-4章","q":"唯物史观认为，地理环境是（）","opts":["A. 社会物质生活的必要条件","B. 经济社会形态的划分依据","C. 社会形态更替的决定力量","D. 技术社会形态的划分依据"],"ans":0,"explain":"地理环境是人们物质生活的必要条件之一，为人类生存和发展提供自然基础，但它不是经济社会形态划分的依据，也不是社会形态更替的决定力量和技术社会形态划分的依据。"},{"id":"mk15044-pl-P4803362","type":"sc","tier":"基础","conf":"adapt","chap":"第3-4章","q":"下列各项正确说明人口因素在社会发展中作用的是（）","opts":["A. 人口因素决定社会制度的性质","B. 人口因素为人类提供生存的场所","C. 人口因素决定社会制度的更替","D. 人口状况能加速或延缓社会发展"],"ans":3,"explain":"人口因素对社会发展起着制约和影响作用，适度的人口能加速社会发展，过密或过疏的人口则延缓社会发展，但人口因素不能决定社会制度的性质和更替，为人类提供生存场所的主要是地理环境。"},{"id":"mk15044-pl-P4803363","type":"sc","tier":"基础","conf":"adapt","chap":"第3-4章","q":"社会意识具有复杂而精微的结构。从反映社会存在的程度和特点来看，社会意识包括（）","opts":["A. 社会心理和思想体系","B. 意识形态和非意识形态","C. 个体意识和群体意识","D. 主流意识和非主流意识"],"ans":0,"explain":"从反映社会存在的程度和特点来看，社会意识分为社会心理和社会意识形式（思想体系），社会心理是低层次的、自发的社会意识，社会意识形式是高层次的、系统的社会意识。"},{"id":"mk15044-pl-P4803364","type":"sc","tier":"基础","conf":"adapt","chap":"第3-4章","q":"在现代生产力系统中，自然科学属于（）","opts":["A. 实体性因素","B. 运筹性因素","C. 渗透性因素","D. 准备性因素"],"ans":2,"explain":"在现代生产力系统中，自然科学属于渗透性因素，它能渗透到生产力的其他要素中，转化为实际生产能力。"},{"id":"mk15044-pl-P4803365","type":"sc","tier":"基础","conf":"adapt","chap":"第3-4章","q":"在生产关系的各项内容中，起决定作用的是（）","opts":["A. 人们在生产中的地位","B. 人们在生产中的相互关系","C. 产品的分配方式","D. 生产资料的所有制形式"],"ans":3,"explain":"生产资料所有制关系是生产关系中最基本的方面，它决定了人们在生产中的地位、相互关系以及产品的分配方式，是整个生产关系的基础。"},{"id":"mk15044-pl-P4803366","type":"sc","tier":"基础","conf":"adapt","chap":"第3-4章","q":"判断一种生产关系是先进还是落后，主要是看（）","opts":["A. 它是计划经济还是市场经济","B. 它是按劳分配还是按资分配","C. 它是生产资料公有制还是私有制","D. 它是促进生产力发展还是阻碍生产力发展"],"ans":3,"explain":"判断生产关系先进与否的主要标准是看其对生产力的作用，能促进生产力发展的就是先进的生产关系，阻碍生产力发展的则是落后的生产关系。"},{"id":"mk15044-pl-P4803367","type":"sc","tier":"基础","conf":"adapt","chap":"第3-4章","q":"在劳动资料这一复杂系统中，最能标志生产力发展水平的是（）","opts":["A. 运输设备","B. 传动装置","C. 动力系统","D. 生产工具"],"ans":3,"explain":"生产工具是劳动资料中最重要的部分，是区分社会经济时代的客观依据，最能标志生产力发展水平。"},{"id":"mk15044-pl-P4803368","type":"sc","tier":"基础","conf":"adapt","chap":"第3-4章","q":"衡量生产力水平的客观尺度是（）","opts":["A. 生产工具的状况","B. 劳动对象的广度","C. 劳动产品的数量","D. 劳动产品的质量"],"ans":0,"explain":"生产工具的状况如质量、数量等，是衡量生产力水平的客观尺度，它直接反映了人们改造自然的能力。"},{"id":"mk15044-pl-P4803369","type":"sc","tier":"基础","conf":"adapt","chap":"第3-4章","q":"在现代生产力系统中，教育属于（）","opts":["A. 实体性因素","B. 运筹性因素","C. 准备性因素","D. 渗透性因素"],"ans":2,"explain":"在现代生产力系统中，教育属于准备性因素，它为生产力发展培养人才，提高劳动者素质。"},{"id":"mk15044-pl-P4803370","type":"sc","tier":"基础","conf":"adapt","chap":"第3-4章","q":"生产关系范畴反映的是人与人之间的（）","opts":["A. 经济关系","B. 政治关系","C. 思想关系","D. 血缘关系"],"ans":0,"explain":"生产关系是人们在物质生产过程中形成的经济关系，反映的是人与人之间的经济联系。"},{"id":"mk15044-pl-P4803371","type":"sc","tier":"基础","conf":"adapt","chap":"第3-4章","q":"在上层建筑的各种要素中，居于主导地位的是（）","opts":["A. 艺术","B. 宗教","C. 政治","D. 哲学"],"ans":2,"explain":"在整个上层建筑中，政治上层建筑居于主导地位，国家政权是政治上层建筑的核心，政治对其他上层建筑要素有重要影响。"},{"id":"mk15044-pl-P4803372","type":"sc","tier":"基础","conf":"adapt","chap":"第3-4章","q":"“科学技术是第一生产力”这一著名论断的提出者是（）","opts":["A. 毛泽东","B. 邓小平","C. 江泽民","D. 胡锦涛"],"ans":1,"explain":"“科学技术是第一生产力”是邓小平提出的著名论断，强调了科学技术在生产力发展中的重要地位。"},{"id":"mk15044-pl-P4803373","type":"sc","tier":"基础","conf":"adapt","chap":"第3-4章","q":"下列范畴中，反映人与人之间经济关系的是（）","opts":["A. 生产力","B. 生产关系","C. 生产方式","D. 生产资料"],"ans":1,"explain":"生产关系是人们在物质生产过程中结成的经济关系，直接反映人与人之间的经济联系。"},{"id":"mk15044-pl-P4803374","type":"sc","tier":"基础","conf":"adapt","chap":"第3-4章","q":"在现代生产力系统中，经济管理和预测决策属于（）","opts":["A. 独立的实体性因素","B. 运筹性的综合因素","C. 渗透性因素","D. 准备性因素"],"ans":1,"explain":"在现代生产力系统中，运筹性的综合因素包括分工协作、经济管理、预测决策等，它们对生产力发展起组织、协调作用。"},{"id":"mk15044-pl-P4803375","type":"sc","tier":"基础","conf":"adapt","chap":"第3-4章","q":"下列关于生产力和生产关系的表述中，不正确的是（）","opts":["A. 生产力的性质决定生产关系的性质","B. 生产力的发展决定生产关系的改变","C. 生产关系对生产力具有巨大的反作用","D. 生产关系总是适应生产力发展要求"],"ans":3,"explain":"生产力决定生产关系，生产关系反作用于生产力，但生产关系并不总是适应生产力发展要求，当生产关系不适应生产力时，会阻碍生产力发展。"},{"id":"mk15044-pl-P4803376","type":"sc","tier":"基础","conf":"adapt","chap":"第3-4章","q":"在现代生产力系统中，生产工具属于（）","opts":["A. 实体性因素","B. 运筹性因素","C. 渗透性因素","D. 准备性因素"],"ans":0,"explain":"在现代生产力系统中，生产工具属于独立的实体性因素，以物质实体形式存在，是劳动资料的重要组成部分。"},{"id":"mk15044-pl-P4803377","type":"sc","tier":"基础","conf":"adapt","chap":"第3-4章","q":"下列各项属于政治上层建筑的是（）","opts":["A. 政府机关","B. 政治思想","C. 社会科学","D. 自然科学"],"ans":0,"explain":"政治上层建筑包括国家政治制度、立法司法制度和行政制度，以及国家政权机构等，政府机关属于政治上层建筑，政治思想属于观念上层建筑，社会科学和自然科学不属于上层建筑范畴（若不涉及为特定阶级服务的意识形态内容）。"},{"id":"mk15044-pl-P4803378","type":"sc","tier":"基础","conf":"adapt","chap":"第3-4章","q":"下列选项中属于观念上层建筑的是（）","opts":["A. 哲学","B. 数学","C. 逻辑学","D. 物理学"],"ans":0,"explain":"观念上层建筑通常包括政治法律思想、道德、艺术、宗教、哲学等，数学、逻辑学、物理学属于自然科学或科学知识范畴，不属于观念上层建筑。"},{"id":"mk15044-pl-P4803379","type":"sc","tier":"基础","conf":"adapt","chap":"第3-4章","q":"经济基础决定上层建筑，说的是（）","opts":["A. 任何社会的上层建筑都根源于它的经济基础","B. 任何社会的上层建筑都产生于它的经济基础之后","C. 上层建筑任何部分的变化都与经济基础的变化同步","D. 上层建筑任何部分的性质都由经济基础直接决定"],"ans":0,"explain":"经济基础是上层建筑产生、存在和发展的物质基础，任何社会的上层建筑都能从其经济基础中找到根源，但上层建筑并非都产生于经济基础之后，二者变化也并非完全同步，上层建筑部分性质的形成还受其他因素影响。"},{"id":"mk15044-pl-P4803380","type":"sc","tier":"基础","conf":"adapt","chap":"第3-4章","q":"下列选项属于经济社会形态的是（）","opts":["A. 农业社会","B. 工业社会","C. 信息社会","D. 奴隶社会"],"ans":3,"explain":"经济社会形态划分法包括五种社会形态划分法（原始社会、奴隶社会、封建社会、资本主义社会、共产主义社会）和三种社会形态划分法，农业社会、工业社会、信息社会属于技术社会形态划分法中的类别，奴隶社会属于经济社会形态。"},{"id":"mk15044-pl-P4803381","type":"sc","tier":"基础","conf":"adapt","chap":"第3-4章","q":"下列各项中，属于技术社会形态序列的是（）","opts":["A. 原始社会","B. 封建社会","C. 工业社会","D. 个人全面发展的社会"],"ans":2,"explain":"技术社会形态划分法将人类社会划分为渔猎社会、农业社会、工业社会、信息社会等，原始社会、封建社会属于经济社会形态划分法中的类别，个人全面发展的社会属于从人的发展角度划分的类别。"},{"id":"mk15044-pl-P4803382","type":"sc","tier":"基础","conf":"adapt","chap":"第3-4章","q":"按照技术社会形态的划分标准，我们可以把人类历史划分为（）","opts":["A. 人的依赖性社会、物的依赖性社会、个人全面发展的社会","B. 渔猎社会、农业社会、工业社会、信息社会","C. 自然经济社会、商品经济社会、产品经济社会","D. 古代社会、近代社会、现代社会"],"ans":1,"explain":"按照技术社会形态的划分标准，人类历史可分为渔猎社会、农业社会、工业社会、信息社会。A选项是从人的发展角度进行的三种社会形态划分；C选项是从经济形态角度划分；D选项不属于依据技术社会形态划分标准的分类。"},{"id":"mk15044-pl-P4803383","type":"sc","tier":"基础","conf":"adapt","chap":"第3-4章","q":"“社会形态的发展是一个自然历史过程”，这句话说的是（）","opts":["A. 社会规律和自然规律没有差别","B. 社会发展排斥主体选择的作用","C. 社会发展取决于主体自由选择","D. 社会发展具有不依人的意志为转移的客观规律性"],"ans":3,"explain":"“社会形态的发展是一个自然历史过程”意味着人类社会的发展如同自然界一样，具有客观规律性，是不以人的意志为转移的。社会规律和自然规律存在差别，A错误；社会发展并不排斥主体选择的作用，B错误；社会发展是由客观规律决定的，并非取决于主体自由选择，C错误。"},{"id":"mk15044-pl-P4803384","type":"sc","tier":"基础","conf":"adapt","chap":"第3-4章","q":"社会形态的发展是一种自然历史过程，这种观点属于（）","opts":["A. 机械决定论","B. 历史宿命论","C. 历史唯物论","D. 历史唯心论"],"ans":2,"explain":"历史唯物论认为社会形态的发展是客观的、物质的、辩证的过程，具有不依人的意志为转移的客观规律性，即社会形态的发展是一种自然历史过程。机械决定论夸大必然性，否定偶然性；历史宿命论强调命运决定一切，否定人的主观能动性；历史唯心论认为社会意识决定社会存在，均不符合该观点。"},{"id":"mk15044-pl-P4803385","type":"sc","tier":"基础","conf":"adapt","chap":"第3-4章","q":"既承认历史发展的决定性又承认历史发展的选择性，这属于（）","opts":["A. 历史唯物论观点","B. 相对主义观点","C. 历史循环论观点","D. 折衷主义观点"],"ans":0,"explain":"历史唯物论认为社会形态更替具有必然性，是由生产力与生产关系、经济基础与上层建筑的矛盾运动决定的；同时也承认人们在遵循社会发展规律的基础上具有历史选择性。相对主义否认事物的相对稳定性和客观标准；历史循环论认为历史是周而复始的循环；折衷主义是把各种不同的观点无原则地拼凑在一起，均不符合题意。"},{"id":"mk15044-pl-P4803386","type":"sc","tier":"基础","conf":"adapt","chap":"第3-4章","q":"社会历史发展的决定性是指（）","opts":["A. 历史决定论","B. 历史被动论","C. 历史宿命论","D. 历史意志论"],"ans":0,"explain":"社会历史发展的决定性指历史决定论，即社会形态更替的过程和规律是客观的，其发展的基本趋势是确定不移的，是由社会基本矛盾运动决定的。历史被动论强调人在历史发展中被动受支配；历史宿命论强调命运主宰历史；历史意志论强调人的意志决定历史，均与社会历史发展的决定性含义不符。"},{"id":"mk15044-pl-P4803387","type":"sc","tier":"基础","conf":"adapt","chap":"第3-4章","q":"既承认社会形态发展的统一性，又承认社会形态发展的多样性，这是一种（）","opts":["A. 机械决定论观点","B. 历史唯物主义观点","C. 历史循环论观点","D. 历史虚无主义观点"],"ans":1,"explain":"历史唯物主义认为社会形态发展具有统一性，表现为五种社会形态的依次更替是一般过程和规律；同时也承认多样性，如不同国家和民族在社会发展历程中会有不同特点。机械决定论、历史循环论、历史虚无主义都不符合对社会形态发展统一性和多样性的正确理解。"},{"id":"mk15044-pl-P4803388","type":"sc","tier":"基础","conf":"adapt","chap":"第3-4章","q":"划分阶级的唯一标准是（）","opts":["A. 政治标准","B. 思想标准","C. 经济标准","D. 文化标准"],"ans":2,"explain":"阶级是一个经济范畴，划分阶级的唯一标准是经济标准，即人们在社会经济结构中所处的地位不同，其中主要是对生产资料的占有关系不同。政治标准、思想标准、文化标准均不是划分阶级的标准。"},{"id":"mk15044-pl-P4803389","type":"sc","tier":"基础","conf":"adapt","chap":"第3-4章","q":"阶级斗争归根结底是由（）","opts":["A. 物质利益的对立引起的","B. 思想观念的分歧引起的","C. 政治理念的差异引起的","D. 宗教信仰的不同引起的"],"ans":0,"explain":"阶级斗争根源于阶级之间物质利益的根本对立，根源于社会经济关系的冲突。思想观念的分歧、政治理念的差异、宗教信仰的不同可能会引发矛盾，但不是阶级斗争的根本原因。"},{"id":"mk15044-pl-P4803390","type":"sc","tier":"基础","conf":"adapt","chap":"第3-4章","q":"阶级作为一种社会现象首先是（）","opts":["A. 经济范畴","B. 政治范畴","C. 文化范畴","D. 交往范畴"],"ans":0,"explain":"阶级首先是一个经济范畴，是一些经济集团，由于它们在一定社会经济结构中所处的地位不同，其中一个集团能够占有另一个集团的劳动。阶级在政治、文化等方面有表现，但本质上是经济范畴。"},{"id":"mk15044-pl-P4803391","type":"sc","tier":"基础","conf":"adapt","chap":"第3-4章","q":"从历史上看，暴力革命是社会革命的（）","opts":["A. 唯一形式","B. 基本形式","C. 辅助形式","D. 补充形式"],"ans":1,"explain":"社会革命的基本形式是暴力革命，当旧的生产关系严重阻碍生产力发展，旧的上层建筑极力维护旧的经济基础时，往往需要通过暴力革命推翻反动阶级的统治，实现社会形态的更替。但暴力革命不是唯一形式，在一定条件下也存在和平过渡等形式。"},{"id":"mk15044-pl-P4803392","type":"sc","tier":"基础","conf":"adapt","chap":"第3-4章","q":"除了生产力与生产关系的矛盾，另一对社会基本矛盾是（）","opts":["A. 社会存在与社会意识的矛盾","B. 社会生产和社会消费的矛盾","C. 经济基础与上层建筑的矛盾","D. 先进意识和落后意识的矛盾"],"ans":2,"explain":"生产力与生产关系、经济基础与上层建筑之间的矛盾，是人类社会基本矛盾。社会存在与社会意识的矛盾是社会历史观的基本问题，但不是社会基本矛盾；社会生产和社会消费的矛盾、先进意识和落后意识的矛盾不属于社会基本矛盾范畴。"},{"id":"mk15044-pl-P4803393","type":"sc","tier":"基础","conf":"adapt","chap":"第3-4章","q":"阶级产生的根本前提是（）","opts":["A. 用暴力掠夺他人财产","B. 由于生产力的发展出现剩余产品","C. 用特权侵吞共有财产","D. 由于产品分配不公出现两极分化"],"ans":1,"explain":"阶级产生的基本前提是由于生产力的发展出现剩余产品，这使得一部分人能够占有他人的劳动成果，同时私有制的形成也是阶级产生的重要条件。用暴力掠夺他人财产、用特权侵吞共有财产、产品分配不公出现两极分化都是在生产力发展出现剩余产品和私有制形成之后才可能出现的情况，不是阶级产生的根本前提。"},{"id":"mk15044-pl-P4803394","type":"sc","tier":"基础","conf":"adapt","chap":"第3-4章","q":"改革不仅存在于社会主义社会中，而且存在于其他社会形态中。这说明改革具有（）","opts":["A. 主体能动性","B. 历史局限性","C. 普遍性","D. 特殊性"],"ans":2,"explain":"社会改革的普遍性是指社会改革不仅存在于社会主义社会中，而且存在于有史以来的各种社会制度中。主体能动性强调人的主观能动作用；历史局限性指受当时历史条件的限制；特殊性是指不同时期、不同国家的改革具有自己的特点，均不符合题意。"},{"id":"mk15044-pl-P4803395","type":"sc","tier":"基础","conf":"adapt","chap":"第3-4章","q":"推动社会历史发展的动力是多方面的，其中最基本的动力是（）","opts":["A. 科学和技术","B. 广大人民群众","C. 革命和改革","D. 社会基本矛盾"],"ans":3,"explain":"社会基本矛盾，即生产力和生产关系、经济基础和上层建筑的矛盾，是社会发展的基本动力，它贯穿社会发展过程始终，规定社会发展过程的基本性质和基本趋势，推动社会向前发展。科学和技术、广大人民群众、革命和改革都是推动社会发展的动力，但不是最基本的动力。"},{"id":"mk15044-pl-P4803396","type":"sc","tier":"基础","conf":"adapt","chap":"第3-4章","q":"推动阶级社会发展的直接动力是（）","opts":["A. 社会基本矛盾","B. 阶级斗争","C. 科学技术革命","D. 社会改革"],"ans":1,"explain":"阶级斗争是社会基本矛盾在阶级社会中的表现，是阶级社会发展的直接动力。社会基本矛盾是社会发展的基本动力；科学技术革命是推动经济和社会发展的强大杠杆；社会改革是推动社会发展的重要动力，但不是阶级社会发展的直接动力。"},{"id":"mk15044-pl-P4803397","type":"sc","tier":"基础","conf":"adapt","chap":"第3-4章","q":"阶级斗争是阶级社会发展的（）","opts":["A. 直接动力","B. 根本动力","C. 最终动力","D. 唯一动力"],"ans":0,"explain":"阶级斗争是阶级社会发展的直接动力，它突出地表现在社会形态的更替中，也表现在同一社会形态的量变过程中。社会基本矛盾是社会发展的根本动力，不存在“最终动力”“唯一动力”的说法。"},{"id":"mk15044-pl-P4803398","type":"sc","tier":"基础","conf":"adapt","chap":"第3-4章","q":"下列各项关于社会改革的说法中，正确的是（）","opts":["A. 社会改革仅仅是经济领域的变革","B. 社会改革仅仅是社会心态的改良","C. 社会改革是制度体制的根本改变","D. 社会改革是社会体制的改善和革新"],"ans":3,"explain":"社会改革是一定社会为了解决社会基本矛盾而对生产关系和上层建筑进行的深刻的改变和革新，是社会制度的自我调整和完善，是社会体制的改善和革新，涉及经济、政治、文化等多个领域，并非仅仅是经济领域变革或社会心态改良，也不是制度体制的根本改变，因为改革是在不改变社会基本制度的前提下进行的。"},{"id":"mk15044-pl-P4803399","type":"sc","tier":"基础","conf":"adapt","chap":"第3-4章","q":"生产力和生产关系的矛盾、经济基础和上层建筑的矛盾是社会基本矛盾。从这两对矛盾的关系上看，二者（）","opts":["A. 相互孤立","B. 相互平行","C. 相互决定","D. 相互制约"],"ans":3,"explain":"生产力和生产关系的矛盾、经济基础和上层建筑的矛盾相互制约，有主次之分。生产力与生产关系的矛盾对于经济基础与上层建筑的矛盾起主导作用，同时，生产力和生产关系矛盾的解决，又有赖于经济基础和上层建筑矛盾的解决。它们不是相互孤立、相互平行的关系，也不是相互决定的关系。"},{"id":"mk15044-pl-P4803400","type":"sc","tier":"基础","conf":"adapt","chap":"第3-4章","q":"人的本质在于（）","opts":["A. 人的自然属性","B. 人的道德素质","C. 人的社会属性","D. 人的文化素质"],"ans":2,"explain":"人的本质是由人的社会属性决定的，人的本质在其现实性上，是一切社会关系的总和。人的自然属性是人的肉体存在及其特性，但不是人的本质；人的道德素质、文化素质是人的社会属性的具体表现，但不能等同于人的本质。"},{"id":"mk15044-pl-P4803401","type":"sc","tier":"基础","conf":"adapt","chap":"第3-4章","q":"唯物史观认为，人的本质在其现实性上是（）","opts":["A. 人的价值追求","B. 人的政治立场","C. 人的情感态度","D. 人的一切社会关系的总和"],"ans":3,"explain":"马克思指出，人的本质不是单个人所固有的抽象物，在其现实性上，它是一切社会关系的总和。人的价值追求、政治立场、情感态度都受社会关系的影响，但都不是人的本质的定义。"},{"id":"mk15044-pl-P4803402","type":"sc","tier":"基础","conf":"adapt","chap":"第3-4章","q":"人区别于动物的根本标志在于人能够（）","opts":["A. 制造和使用工具","B. 创造和使用语言符号","C. 积极地适应外部环境","D. 能动地反映客观世界"],"ans":0,"explain":"劳动是人的本质，人区别于动物的根本标志和特征是人能制造和使用生产工具从事生产劳动。动物也能在一定程度上适应外部环境，部分动物也有简单的信息交流方式，但它们无法制造和使用工具进行有目的、有计划的生产劳动；能动地反映客观世界并非人区别于动物的根本标志。"},{"id":"mk15044-pl-P4803403","type":"sc","tier":"基础","conf":"adapt","chap":"第3-4章","q":"在历史创造者问题上，两种根本对立的观点是（）","opts":["A. 群众史观和英雄史观","B. 一元论和二元论","C. 宿命论和唯意志论","D. 唯理论和经验论"],"ans":0,"explain":"在历史创造者问题上，唯物史观主张群众史观，认为人民群众是历史的创造者；唯心史观主张英雄史观，认为少数英雄人物创造历史，这是两种根本对立的观点。一元论和二元论是关于世界本原的不同观点；宿命论强调命运的决定性，唯意志论夸大意志的作用；唯理论和经验论是关于知识来源的不同理论，均与历史创造者问题的两种对立观点无关。"},{"id":"mk15044-pl-P4803404","type":"sc","tier":"基础","conf":"adapt","chap":"第3-4章","q":"社会下列关于人的本质的表述正确的是（）","opts":["A. 人的本质不是后天的而是先天的","B. 人的本质不是具体的而是抽象的","C. 人的本质不是变化的而是永恒的","D. 在阶级社会里人的本质是有阶级性的"],"ans":3,"explain":"人的本质是一切社会关系的总和，是后天形成的、具体的、随着社会关系变化而变化的。在阶级社会中，人们处于不同的阶级关系中，人的本质具有阶级性。A、B、C选项的表述均错误。"},{"id":"mk15044-pl-P4803405","type":"sc","tier":"基础","conf":"adapt","chap":"第3-4章","q":"群众路线的基本出发点和最终归宿是（）","opts":["A. 一切为了群众","B. 从群众中来","C. 一切依靠群众","D. 到群众中去"],"ans":0,"explain":"“一切为了群众”是群众路线的基本出发点和最终归宿，体现了无产阶级政党全心全意为人民服务的宗旨。“一切依靠群众”是群众路线的根本要求；“从群众中来，到群众中去”是无产阶级政党的领导方法和基本工作方法。"},{"id":"mk15044-pl-P4803406","type":"sc","tier":"基础","conf":"adapt","chap":"第3-4章","q":"唯心史观在历史创造者问题上的根本错误在于（）","opts":["A. 否认个人在历史发展中的作用","B. 否认思想动机在历史发展中的作用","C. 否认少数英雄人物是推动历史发展的决定力量","D. 否认广大人民群众是推动历史发展的决定力量"],"ans":3,"explain":"唯心史观从社会意识决定社会存在的前提出发，认为历史是少数英雄人物创造的，否认人民群众是推动历史发展的决定力量。唯心史观并不否认个人在历史发展中的作用，反而夸大少数英雄人物的作用；它也不否认思想动机的作用，只是将思想动机作为历史发展的决定因素；C选项与唯心史观观点相悖。"},{"id":"mk15044-pl-P4803407","type":"sc","tier":"基础","conf":"adapt","chap":"第3-4章","q":"区分普通个人和历史人物，主要是看他们（）","opts":["A. 对历史发展作用的大小","B. 对历史发展的作用是积极的还是消极的","C. 对历史发展的作用是主动的还是被动的","D. 对历史发展的作用是必然的还是偶然的"],"ans":0,"explain":"个人按其对历史发展作用的大小，可以区分为普通个人和历史人物。对历史发展起积极或消极作用，是区分进步历史人物和反动历史人物的标准；个人在历史发展中的作用是否主动、是必然还是偶然，都不是区分普通个人和历史人物的主要依据。"},{"id":"mk15044-pl-P4803408","type":"sc","tier":"基础","conf":"adapt","chap":"第3-4章","q":"人的本质是由人的社会属性，而非自然属性决定的。人的自然属性指的是（）","opts":["A. 人与动物相区别的劳动本质","B. 人的肉体存在及其特性","C. 由个人需要决定的人的具体本质","D. 由社会关系决定的人的具体本质"],"ans":1,"explain":"人的自然属性是指人的肉体存在及其特性，如人的生理结构、生理机能等。人与动物相区别的劳动本质体现的是人的社会属性；人的本质是由社会关系决定的，但这不是人的自然属性的定义；由个人需要决定的人的具体本质这种说法不准确，且不属于人的自然属性范畴。"},{"id":"mk15044-pl-P4803409","type":"sc","tier":"基础","conf":"adapt","chap":"第3-4章","q":"“人的本质”是一切社会关系的总和，这一界定强调的是（）","opts":["A. 人与人之间的区别","B. 人与动物之间的区别","C. 一切人的共有本质","D. 人的肉体存在及其特性"],"ans":0,"explain":"“人的本质是一切社会关系的总和”强调的是人与人之间的区别，因为不同的人处于不同的社会关系中，从而具有不同的本质。该界定并非强调人与动物的区别；人的本质是具体的、不同的，不是一切人的共有本质；人的肉体存在及其特性属于人的自然属性，与“人的本质是一切社会关系的总和”所强调的内容无关。"},{"id":"mk15044-pl-P4803410","type":"sc","tier":"基础","conf":"adapt","chap":"第3-4章","q":"下列关于人的本质的表述，只涉及人与动物根本区别的是（）","opts":["A. 劳动是人的本质","B. 人的需要即人的本质","C. 人的本质是人的全部属性的总和","D. 人的本质是人的自然属性的总和"],"ans":0,"explain":"劳动是人的本质，人能制造和使用生产工具从事生产劳动，这是人与动物的根本区别。“人的需要即人的本质”这种说法不准确；人的本质是一切社会关系的总和，不是全部属性或自然属性的总和，且强调自然属性总和不能体现人与动物的根本区别。"},{"id":"mk15044-pl-P4803411","type":"sc","tier":"基础","conf":"adapt","chap":"第3-4章","q":"下列关于人的本质的说法中，不正确的是（）","opts":["A. 人的本质是发展变化的","B. 人的本质是现实具体的","C. 人的本质是后天形成的","D. 人的本质是人人相同的"],"ans":3,"explain":"人的本质是一切社会关系的总和，是后天形成的、现实具体的，并且会随着社会关系的变化而发展变化。不同的人处于不同的社会关系中，人的本质不是人人相同的，D选项表述错误。"},{"id":"mk15044-pl-P4803412","type":"sc","tier":"基础","conf":"adapt","chap":"第3-4章","q":"任何杰出人物都有巨大的历史功绩，他们在社会历史中的活动可以（）","opts":["A. 摆脱社会规律的制约","B. 有力地推动历史的发展","C. 不受历史条件的限制","D. 根本改变历史发展方向"],"ans":1,"explain":"杰出人物是历史人物中对推动历史发展作出重要贡献或起重要作用的人，他们能有力地推动历史的发展。但杰出人物也受社会规律的制约，不能摆脱历史条件的限制，也无法根本改变历史发展的总方向，历史发展方向是由社会基本矛盾运动决定的。"},{"id":"mk15044-pl-P4803413","type":"sc","tier":"基础","conf":"adapt","chap":"第3-4章","q":"正确认识和评价杰出人物的历史作用，一要坚持历史主义的原则，二要坚持（）","opts":["A. 阶级分析的方法","B. 实证分析的方法","C. 矛盾分析的方法","D. 规范分析的方法"],"ans":0,"explain":"在阶级社会里，评价历史人物要坚持历史分析方法和阶级分析方法。历史分析方法要求从特定的历史背景出发评价历史人物；阶级分析方法要求把历史人物置于一定的阶级关系中进行考察和评价。实证分析方法、矛盾分析方法、规范分析方法均不是评价历史人物的主要方法。"},{"id":"mk15044-pl-P4803414","type":"sc","tier":"基础","conf":"adapt","chap":"第3-4章","q":"群众是划分为阶级的，在阶级社会里，对群众在社会历史发展中的作用进行分析，主要是看（）","opts":["A. 群众的数量多少","B. 群众的文化程度高低","C. 哪个阶级是新的生产力和先进生产关系的代表","D. 群众的组织化程度"],"ans":2,"explain":"在阶级社会里，群众由不同阶级构成，各阶级在社会历史发展中的作用不同。判断群众在社会历史发展中的作用，关键是看哪个阶级是新的生产力和先进生产关系的代表，因为代表新的生产力和先进生产关系的阶级往往能推动社会发展。群众的数量、文化程度、组织化程度虽会对社会发展产生影响，但不是分析群众在社会历史发展中作用的主要依据。"},{"id":"mk15044-pl-P4803415","type":"sc","tier":"基础","conf":"adapt","chap":"第3-4章","q":"阶级通常是由政党领导的，政党是（）","opts":["A. 由本阶级全体成员组成的","B. 由本阶级中最有觉悟、最积极的分子组成的","C. 由社会各阶层的代表组成的","D. 由不同阶级的先进分子组成的"],"ans":1,"explain":"政党是阶级组织最集中、最严密、最高级的形式，一般而言，它是由本阶级中最有觉悟、最积极的分子组成的，有集中代表本阶级利益的政治纲领，是本阶级的实际组织者和领导者。政党不是由本阶级全体成员组成，也不是由社会各阶层代表或不同阶级先进分子组成。"},{"id":"mk15044-pl-P4803416","type":"sc","tier":"基础","conf":"adapt","chap":"第3-4章","q":"政党是由领袖来主持的，无产阶级革命领袖是（）","opts":["A. 在理论研究中产生的","B. 由政党任命的","C. 在长期的群众斗争、群众实践中产生的","D. 由全体人民选举产生的"],"ans":2,"explain":"无产阶级革命领袖是在长期的群众斗争、群众实践中产生的，他们代表无产阶级和人民群众的利益，具备卓越的领导才能和丰富的经验。无产阶级革命领袖不是单纯在理论研究中产生，也不是由政党任命或全体人民选举产生（在不同历史时期，其产生方式并非单纯选举）。"},{"id":"mk15044-pl-P4803570","type":"sa","tier":"创新","conf":"adapt","chap":"第3-4章","q":"简述社会意识的相对独立性的主要表现。","opts":[],"ans":null,"explain":"社会意识的相对独立性主要表现在：社会意识与社会存在变化发展的非完全同步性，可能超前或滞后于社会存在的发展；社会意识与社会经济发展水平具有不平衡性，经济发展水平高的地区，社会意识未必先进，反之亦然；社会意识的发展具有历史继承性，任何社会意识都能在继承前人成果的基础上发展；社会意识各种形式之间相互作用、相互影响，如政治思想影响艺术创作，艺术反映一定的道德观念等；社会意识对社会存在具有反作用，先进的社会意识促进社会发展，落后的社会意识阻碍社会发展。"},{"id":"mk15044-pl-P4803571","type":"sa","tier":"创新","conf":"adapt","chap":"第3-4章","q":"简述地理环境在社会发展中的作用。","opts":[],"ans":null,"explain":"地理环境在社会发展中的作用如下：是人类社会生存和发展永恒的、必要的条件，为人类提供生活和生产的自然基础，如提供自然资源等；影响社会的发展：通过对生产的影响，加速或延缓社会发展，优越的地理环境有利于提高劳动生产率，反之则阻碍；通过对军事、政治的影响，在一定程度上制约不同国家社会的发展，如某些地理条件影响国家战略布局。"},{"id":"mk15044-pl-P4803572","type":"sa","tier":"创新","conf":"adapt","chap":"第3-4章","q":"简述人口因素在社会发展中的作用。","opts":[],"ans":null,"explain":"人口因素在社会发展中的作用如下：一定数量人口是社会物质生产的必要前提，没有一定数量的人口，生产难以组织和进行；人口状况能加速或延缓社会的发展，适度的人口对社会发展起加速作用，过密或过疏的人口则对社会发展起延缓作用，并且人口的质量、职业构成等在现代社会对社会发展产生重要影响。"},{"id":"mk15044-pl-P4803573","type":"sa","tier":"创新","conf":"adapt","chap":"第3-4章","q":"什么是生产方式？为什么说生产方式在社会发展中起决定作用？","opts":[],"ans":null,"explain":"生产方式是人们为获取物质生活资料而进行的生产活动的方式，是生产力和生产关系的统一体。生产方式在社会发展中起决定作用的原因：生产方式或生产活动是人区别于动物的根本标志，人类通过特定的生产方式进行生产劳动，与动物的本能活动相区别；生产方式是人类和人类社会存在和发展的基础，为人类生存和社会运行提供物质保障；生产活动是形成人类一切社会关系的基础，生产过程中形成的生产关系是其他社会关系的基础；生产方式决定社会制度的性质和社会制度的更替，不同的生产方式决定了不同的社会形态。"},{"id":"mk15044-pl-P4803574","type":"sa","tier":"创新","conf":"adapt","chap":"第3-4章","q":"什么是生产关系？为什么说生产资料所有制形式是整个生产关系的基础？","opts":[],"ans":null,"explain":"生产关系是人们在物质生产过程中结成的经济关系。生产资料所有制形式是整个生产关系的基础，原因如下：是生产劳动得以进行的前提，只有确定了生产资料的归属，生产活动才能有序开展；决定整个生产关系的性质，不同的所有制形式决定生产关系是公有制还是私有制等不同性质；决定人们在生产中的地位和相互关系，生产资料所有者在生产中往往处于主导地位，决定着其他参与者的地位和彼此关系；决定产品的分配方式，如公有制下可能更倾向于公平分配，私有制下分配可能更取决于生产资料占有情况。"},{"id":"mk15044-pl-P4803575","type":"sa","tier":"创新","conf":"adapt","chap":"第3-4章","q":"什么是社会基本矛盾？简述社会基本矛盾是社会发展的基本动力。","opts":[],"ans":null,"explain":"社会基本矛盾是指生产力和生产关系、经济基础和上层建筑的矛盾。社会基本矛盾是社会发展的基本动力，体现在：生产力是社会基本矛盾运动中最基本的动力因素，是人类社会发展和进步的最终决定力量，生产力的发展推动生产关系变革，进而带动整个社会变革；社会基本矛盾特别是生产力和生产关系的矛盾，决定着社会中其他矛盾的存在和发展，生产力和生产关系的矛盾变化会引发经济基础和上层建筑的矛盾，以及其他社会矛盾；社会基本矛盾具有不同的表现形式和解决方式，在阶级社会中通过阶级斗争、社会革命解决，在同一社会形态发展中通过改革解决，从而推动社会形态的变化和发展。"},{"id":"mk15044-pl-P4803576","type":"sa","tier":"创新","conf":"adapt","chap":"第3-4章","q":"简述两种历史观在历史创造者问题上的根本分歧。","opts":[],"ans":null,"explain":"在历史创造者问题上，两种历史观的根本分歧如下：历史唯心主义从社会意识决定社会存在的前提出发，认为历史是少数英雄人物创造的，否认人民群众是推动历史发展的决定力量，这是英雄史观；历史唯物主义从社会存在决定社会意识、物质资料的生产方式是人类社会存在和发展的基础的基本原理出发，认为人类历史首先是生产发展的历史，是物质生产的承担者劳动群众的历史，得出人民群众是历史的创造者的结论。"},{"id":"mk15044-pl-P4803577","type":"sa","tier":"创新","conf":"adapt","chap":"第3-4章","q":"说明人与社会是具体的、历史的统一。","opts":[],"ans":null,"explain":"人与社会是具体的、历史的统一，具体体现在：人的出现与社会的产生是一致的，人类的产生过程也是社会形成的过程，二者相互依存、相互促进；人的活动与社会结构及其发展变化是一致的，人的实践活动推动社会结构的演变，社会结构又制约和影响人的活动；社会的本质和人的本质是一致的，这种一致的基础是实践，人通过实践活动塑造社会，社会也在实践中塑造人；个人的解放与社会的解放是一致的，社会的进步为个人解放创造条件，个人的解放又推动社会的进一步发展。"},{"id":"mk15044-pl-P4803578","type":"sa","tier":"创新","conf":"adapt","chap":"第3-4章","q":"简述社会改革在社会发展中的作用。","opts":[],"ans":null,"explain":"社会改革在社会发展中的作用主要有：巩固新生的社会制度或使原有的社会制度持续存在并获得一定程度的发展，通过调整生产关系和上层建筑，使其适应生产力发展水平，促进社会稳定和进步；在社会主义社会以前，社会改革为新社会制度的诞生做量变和部分质变的准备，积累社会变革的条件；在社会经济、政治等社会体制改革的过程中，必然伴随着人们思想观念和价值取向的变更，推动社会思想的进步和发展。"},{"id":"mk15044-pl-P4803579","type":"sa","tier":"创新","conf":"adapt","chap":"第3-4章","q":"简述群众路线的内容及坚持无产阶级政党群众路线的工作方法。","opts":[],"ans":null,"explain":"群众路线的内容是“一切为了群众，一切依靠群众，从群众中来，到群众中去”。“一切为了群众”是群众路线的基本出发点和最终归宿，体现了无产阶级政党全心全意为人民服务的宗旨；“一切依靠群众”是群众路线的根本要求，强调依靠人民群众的力量；“从群众中来，到群众中去”是无产阶级政党的领导方法和基本工作方法。坚持无产阶级政党群众路线的工作方法，要做到领导和群众相结合，一般号召和个别指导相结合。将群众分散、无系统的意见集中起来，经过研究化为集中、系统的意见，再到群众中宣传解释，化为群众的行动，并在群众行动中考验这些意见是否正确，不断循环往复，提高领导水平和工作效果。"},{"id":"mk15044-pl-P4803537","type":"sa","tier":"创新","conf":"adapt","chap":"第3-4章","q":"试述社会存在与社会意识辩证关系的原理及其对社会文化建设的指导意义。","opts":[],"ans":null,"explain":"社会存在与社会意识辩证关系原理如下：社会存在决定社会意识：社会存在是社会意识的根源，社会意识是社会存在的反映。社会意识的内容来源于社会存在，社会意识随社会存在的发展变化而变化。例如，随着生产力的发展和生产关系的变革，人们的思想观念、价值取向等也会相应改变。社会意识反作用于社会存在：先进的社会意识对社会存在的发展起积极的推动作用，它能够预见社会发展的趋势，为社会实践提供正确的指导；落后的社会意识对社会存在的发展起消极的阻碍作用，它会束缚人们的思想，阻碍社会的进步。该原理对社会文化建设的指导意义在于：我国社会文化建设必须立足现实的社会存在，从我国的基本国情和发展要求出发。社会文化是社会意识的重要组成部分，只有基于现实的社会物质生活条件，才能制定出符合实际的文化发展战略和政策。要充分发挥社会意识对社会存在的能动作用。积极发展先进文化，弘扬优秀传统文化，推进社会主义核心价值观建设。先进文化能够为社会发展提供思想保证、精神动力和智力支持，促进社会的全面进步；弘扬优秀传统文化可以增强民族凝聚力和认同感；推进社会主义核心价值观建设有助于形成良好的社会风尚，推动社会的和谐发展。"},{"id":"mk15044-pl-P4803538","type":"sa","tier":"创新","conf":"adapt","chap":"第3-4章","q":"试述上层建筑必须适合经济基础发展要求的规律及其现实指导意义。","opts":[],"ans":null,"explain":"上层建筑必须适合经济基础发展要求的规律包含以下内容：经济基础决定上层建筑：经济基础是上层建筑产生、存在和发展的物质基础。经济基础决定上层建筑的产生，上层建筑是适应经济基础的需要而产生的；经济基础的性质决定上层建筑的性质，有什么样的经济基础，就有什么样的上层建筑；经济基础的变更必然引起上层建筑的变革，并决定变革的方向。上层建筑反作用于经济基础：上层建筑为经济基础服务，维护其统治地位。当上层建筑适合经济基础状况时，会促进经济基础的巩固和发展，推动社会进步；当上层建筑不适合经济基础状况时，会阻碍经济基础的发展，进而阻碍社会发展。经济基础与上层建筑相互作用构成矛盾运动：这种矛盾运动在不同情况下表现不同，在同一社会形态中，上层建筑可能存在不完善的部分与经济基础产生矛盾；在社会形态更替时，矛盾更为复杂。这一规律的现实指导意义在于：是无产阶级政党制定正确路线、方针、政策的重要依据。正确把握这一规律，有助于党根据经济基础的发展状况，制定适合的上层建筑改革措施，推动社会发展。对我国当前的经济体制改革和政治体制改革具有重要指导意义。在深化经济体制改革时，要注重调整上层建筑，使其适应经济基础的变化，如推进政治体制改革，加强法治建设，完善民主制度等，以促进经济发展和社会全面进步。"},{"id":"mk15044-pl-P4803539","type":"sa","tier":"创新","conf":"adapt","chap":"第3-4章","q":"试述社会形态发展的统一性和多样性的含义及表现。","opts":[],"ans":null,"explain":"社会形态发展的统一性和多样性含义及表现如下：含义：统一性指不同国家和民族的历史发展具有共同性、普遍性，遵循着一定的规律，如都经历从低级到高级的发展阶段，都存在生产力与生产关系、经济基础与上层建筑的矛盾运动。多样性指不同国家和民族的历史发展具有各自的特点和特色，在社会形态的演进过程中，表现出不同的发展道路和模式。表现：处于同一社会形态的不同国家和民族的历史具有各自的特点，例如同样是封建社会，中国和欧洲在政治制度、经济结构、文化传统等方面存在诸多差异。各国在不同的社会形态中具有的典型意义不同，有些国家在特定社会形态下的发展模式对其他国家产生重要影响，成为某种典型范例。在由较低的社会形态向较高的社会形态转变时，不同国家和民族采取的过渡形式各有特点，有的通过暴力革命，有的通过和平改革等方式实现社会变革。有些国家由于特殊的社会条件，在社会形态转变过程中，可能超越某一个或某几个社会形态，如俄国在一定历史条件下超越了资本主义充分发展阶段，直接进入社会主义社会。"},{"id":"mk15044-pl-P4803540","type":"sa","tier":"创新","conf":"adapt","chap":"第3-4章","q":"试述社会历史发展的决定性与选择性的关系。","opts":[],"ans":null,"explain":"社会历史发展的决定性与选择性是辩证统一的关系：社会历史发展的决定性指社会发展具有客观规律性，社会形态更替是由生产力与生产关系、经济基础与上层建筑的矛盾运动决定的，其发展趋势是确定不移的。社会历史发展的选择性指主体在遵循社会发展规律的基础上，对社会发展的多种可能性进行选择。这种选择是基于主体的目的、利益和对社会发展规律的认识。二者的关系：社会发展的决定性为选择性提供了基础和前提。社会发展的规律和趋势限定了主体选择的范围和可能性，主体只能在社会发展规律所允许的范围内进行选择。社会发展的选择性是对决定性的能动反映。主体的选择不是随意的，而是在认识和遵循社会发展规律的基础上进行的，选择的结果又会反作用于社会发展，推动社会沿着符合规律的方向前进。社会历史发展是决定性与选择性的统一。例如，中国在新民主主义革命胜利后，选择走社会主义道路，这是基于对社会发展规律的认识和中国国情的考虑，既符合社会发展的决定性要求，又体现了中国人民的历史选择。"},{"id":"mk15044-pl-P4803541","type":"sa","tier":"创新","conf":"adapt","chap":"第3-4章","q":"试述两对社会基本矛盾之间的关系以及社会基本矛盾在社会发展中的作用。","opts":[],"ans":null,"explain":"生产力和生产关系、经济基础和上层建筑这两对社会基本矛盾之间相互制约、有主次之分：生产力与生产关系的矛盾是更为基本的矛盾，它决定经济基础与上层建筑矛盾的产生和发展。生产力的发展变化会引起生产关系的变革，进而导致经济基础的改变，最终引发上层建筑的调整。经济基础和上层建筑的矛盾也会影响和制约生产力和生产关系的矛盾。当上层建筑适应经济基础时，能促进经济基础的巩固和发展，为生产力发展创造良好环境；反之，则会阻碍生产力和生产关系矛盾的解决。社会基本矛盾在社会发展中起根本性的推动作用：生产力是社会发展的最终决定力量，是社会进步的根本内容和衡量社会进步的根本尺度。生产力的发展推动生产关系的变革，进而带动整个社会的变革。社会基本矛盾决定着社会中其他矛盾的存在和发展。生产力和生产关系的矛盾变化会引发一系列社会矛盾，经济基础和上层建筑的矛盾也会影响其他社会矛盾的发展。社会基本矛盾的运动推动社会形态的更替和发展。在阶级社会中，社会基本矛盾的尖锐化会引发阶级斗争和社会革命，实现社会形态的变革；在同一社会形态内，通过改革解决基本矛盾，推动社会的发展和进步。"},{"id":"mk15044-pl-P4803500","type":"sc","tier":"基础","conf":"adapt","chap":"第5-7章","q":"社会主义在实践中开拓前进必须遵循的规律不包括（）。","opts":["A. 人类社会发展规律","B. 社会主义建设规律","C. 市场经济规律","D. 共产党执政规律"],"ans":2,"explain":"社会主义在实践中开拓前进必须遵循人类社会发展规律、社会主义建设规律、共产党执政规律，不包括市场经济规律。"},{"id":"mk15044-pl-P4803501","type":"sc","tier":"基础","conf":"adapt","chap":"第5-7章","q":"中国共产党区别于其他政党的显著标志是（）。","opts":["A. 坚持以人民为中心","B. 勇于自我革命","C. 坚持党的全面领导","D. 坚持科学执政、民主执政、依法执政"],"ans":1,"explain":"勇于自我革命是中国共产党区别于其他政党的显著标志。"},{"id":"mk15044-pl-P4803502","type":"sc","tier":"基础","conf":"adapt","chap":"第5-7章","q":"中国式现代化的特征不包括（）。","opts":["A. 人口规模巨大的现代化","B. 部分人民富裕的现代化","C. 物质文明和精神文明相协调的现代化","D. 人与自然和谐共生的现代化"],"ans":1,"explain":"中国式现代化是全体人民共同富裕的现代化，不是部分人民富裕的现代化。A、C、D选项均是中国式现代化的特征。"},{"id":"mk15044-pl-P4803503","type":"sc","tier":"基础","conf":"adapt","chap":"第5-7章","q":"社会主义建设过程中，国际资本主义对社会主义进攻方式转变为以“和平演变”为主是在（）。","opts":["A. 社会主义国家成立之初","B. 社会主义建设取得重大成就后","C. 世界社会主义运动进入低潮时","D. 社会主义国家经济落后时"],"ans":1,"explain":"在社会主义建设取得了重大成就，社会主义制度有了长足进步之后，国际资本主义对社会主义的进攻方式往往转变为以“和平演变”为主。"},{"id":"mk15044-pl-P4803504","type":"sc","tier":"基础","conf":"adapt","chap":"第5-7章","q":"社会主义发展道路多样性的原因中，起决定性作用的是（）。","opts":["A. 历史文化传统的差异性","B. 时代和实践的不断发展","C. 各个国家的生产力发展状况和社会发展阶段","D. 无产阶级政党自身成熟程度"],"ans":2,"explain":"各个国家的生产力发展状况和社会发展阶段决定了社会主义发展道路具有不同的特点，在社会主义发展道路多样性的原因中起决定性作用。"},{"id":"mk15044-pl-P4803505","type":"sc","tier":"基础","conf":"adapt","chap":"第5-7章","q":"社会主义事业在实践中开拓前进，必须凝聚起磅礴力量，其核心是（）。","opts":["A. 不怕牺牲的斗争意志","B. 高度的建设热情","C. 坚定的共产主义理想信念","D. 勇于开拓创新的精神"],"ans":2,"explain":"社会主义事业在实践中开拓前进，所有精神集中到一点，就是要有坚定的共产主义理想信念，凝聚起推动事业发展的磅礴力量。"},{"id":"mk15044-pl-P4803506","type":"sc","tier":"基础","conf":"adapt","chap":"第5-7章","q":"中国共产党跳出治乱兴衰历史周期率的第二个答案是（）。","opts":["A. 人民监督政府","B. 自我革命","C. 统一战线","D. 武装斗争"],"ans":1,"explain":"中国共产党以党的自我革命推进社会革命，找到了跳出治乱兴衰历史周期率的第二个答案。"},{"id":"mk15044-pl-P4803507","type":"sc","tier":"基础","conf":"adapt","chap":"第5-7章","q":"“共产主义”一词不包含以下哪层含义（）。","opts":["A. 共产主义思想体系","B. 共产主义运动","C. 共产主义社会制度","D. 共产主义文化体系"],"ans":3,"explain":"“共产主义”一词主要有三层含义：一是指共产主义思想体系；二是指共产主义运动；三是指共产主义社会制度。不包含共产主义文化体系，所以选D。"},{"id":"mk15044-pl-P4803508","type":"sc","tier":"基础","conf":"adapt","chap":"第5-7章","q":"马克思主义与空想社会主义在展望未来社会问题上的根本区别是（）。","opts":["A. 是否对未来社会进行了描绘","B. 是否坚持科学的立场观点方法","C. 是否批判资本主义社会","D. 是否提出未来社会的具体方案"],"ans":1,"explain":"在展望未来社会的问题上，是否坚持科学的立场观点方法是马克思主义与空想社会主义的根本区别，所以选B。"},{"id":"mk15044-pl-P4803509","type":"sc","tier":"基础","conf":"adapt","chap":"第5-7章","q":"马克思主义经典作家预见未来社会的方法论原则不包括（）。","opts":["A. 在揭示人类社会发展一般规律的基础上指明社会发展的方向","B. 在剖析资本主义旧世界的过程中阐发未来新世界的特点","C. 详细描绘未来社会的具体细节","D. 立足于揭示未来社会的一般特征，而不对各种细节作具体描绘"],"ans":2,"explain":"马克思主义经典作家在展望未来社会时，只限于指出未来社会发展的方向、原则和基本特征，而把具体情形留给后来的实践去回答，不会详细描绘未来社会的具体细节，所以选C。"},{"id":"mk15044-pl-P4803510","type":"sc","tier":"基础","conf":"adapt","chap":"第5-7章","q":"共产主义社会实现“各尽所能，按需分配”的分配原则的前提是（）。","opts":["A. 社会生产力高度发展，产品极大丰富","B. 人们的思想觉悟极大提高","C. 消灭了私有制","D. 国家已经消亡"],"ans":0,"explain":"马克思指出，只有在生产力增长起来，在集体财富的一切源泉都充分涌流之后，才能实行共产主义“各尽所能，按需分配”的分配原则，所以社会生产力高度发展，产品极大丰富是前提，选A。"},{"id":"mk15044-pl-P4803511","type":"sc","tier":"基础","conf":"adapt","chap":"第5-7章","q":"共产主义社会阶级将会消亡，其根本原因是（）。","opts":["A. 人们的思想觉悟极大提高","B. 社会生产力高度发展使所有人的物质利益都得到保障","C. 国家已经消亡","D. 分工不再存在"],"ans":1,"explain":"到了共产主义社会，由于生产力的高度发展已经使所有人的物质利益都得到了保障，分工不再具有经济利益划分的性质，全体社会成员根本利益一致，所以阶级将会消亡，选B。"},{"id":"mk15044-pl-P4803512","type":"sc","tier":"基础","conf":"adapt","chap":"第5-7章","q":"共产主义社会中，国家消亡是指（）。","opts":["A. 社会管理机构的消亡","B. 政治国家的消亡，作为阶级压迫工具的国家机器的消亡","C. 所有国家组织的消亡","D. 国家职能的全部消失"],"ans":1,"explain":"共产主义社会中，国家的消亡是指政治国家的消亡，是作为阶级压迫工具的国家机器的消亡，并不是指社会管理机构的消亡，所以选B。"},{"id":"mk15044-pl-P4803513","type":"sc","tier":"基础","conf":"adapt","chap":"第5-7章","q":"实现人的自由而全面的发展是（）。","opts":["A. 共产主义社会的根本特征","B. 社会主义社会的根本特征","C. 资本主义社会的根本特征","D. 所有社会的共同追求"],"ans":0,"explain":"实现人的自由而全面的发展，是马克思主义追求的根本价值目标，也是共产主义社会的根本特征，所以选A。"},{"id":"mk15044-pl-P4803514","type":"sc","tier":"基础","conf":"adapt","chap":"第5-7章","q":"共产主义理想一定会实现的依据是（）。","opts":["A. 人类社会发展规律以及资本主义社会的基本矛盾发展","B. 人们对美好社会的向往","C. 社会主义国家的存在","D. 无产阶级的壮大"],"ans":0,"explain":"共产主义理想一定会实现，是以人类社会发展规律以及资本主义社会的基本矛盾发展为依据的，所以选A。"},{"id":"mk15044-pl-P4803515","type":"sc","tier":"基础","conf":"adapt","chap":"第5-7章","q":"实现共产主义是人类最伟大的事业，因为（）。","opts":["A. 实现共产主义是无产阶级的愿望","B. 实现共产主义是全人类解放的根本要求和体现","C. 实现共产主义可以带来物质享受","D. 实现共产主义可以摆脱劳动"],"ans":1,"explain":"无产阶级的解放与全人类的解放是完全一致的，争取共产主义的最终实现，不仅是无产阶级彻底解放的标志，也是全人类得到解放的根本要求和体现，所以实现共产主义是人类最伟大的事业，选B。"},{"id":"mk15044-pl-P4803516","type":"sc","tier":"基础","conf":"adapt","chap":"第5-7章","q":"从资本主义到共产主义的转变必然是一个长期而艰难的历史过程，原因不包括（）。","opts":["A. 社会形态的产生发展都经历很长历史时期","B. 旧的社会形态走向没落并被新的社会形态代替是长期过程","C. 资本主义向社会主义转变后不需要发展就可进入共产主义","D. 从资本主义到共产主义是整个社会的根本改造"],"ans":2,"explain":"从资本主义到共产主义的转变是一种根本的转变，不仅是具体制度的更替，更是整个社会的根本改造，且社会主义社会也需要充分发展才能向共产主义过渡，不是转变后不需要发展就可进入共产主义，所以选C。"},{"id":"mk15044-pl-P4803517","type":"sc","tier":"基础","conf":"adapt","chap":"第5-7章","q":"社会主义社会的充分发展和最终向共产主义过渡需要很长的历史时期，这是因为（）。","opts":["A. 社会主义社会是一个很长的历史时期，需要为实现共产主义准备充分物质基础","B. 社会主义社会会很快进入共产主义","C. 共产主义很容易实现","D. 社会主义社会不需要发展生产力"],"ans":0,"explain":"共产主义只有在社会主义社会充分发展和高度发达的基础上才能实现，社会主义社会为实现共产主义准备充分物质基础需要很长时间，所以社会主义社会的充分发展和最终向共产主义过渡需要很长的历史时期，选A。"},{"id":"mk15044-pl-P4803518","type":"sc","tier":"基础","conf":"adapt","chap":"第5-7章","q":"中国特色社会主义道路是（）。","opts":["A. 中华民族最终走向共产主义的必由之路","B. 与共产主义无关的道路","C. 只适合中国现阶段发展的道路","D. 实现共产主义的唯一道路"],"ans":0,"explain":"中国特色社会主义道路是中华民族最终走向共产主义的必由之路，只有沿着这条道路前进，中国的社会主义建设才能取得成功，才能逐步迈向共产主义社会，选A。"},{"id":"mk15044-pl-P4803519","type":"sc","tier":"基础","conf":"adapt","chap":"第5-7章","q":"从时间维度看，共产主义远大理想与中国特色社会主义共同理想的关系是（）。","opts":["A. 最高纲领与最低纲领的关系","B. 全人类理想与全体中国人民理想的关系","C. 最终理想与阶段性理想的关系","D. 整体与部分的关系"],"ans":2,"explain":"从时间上看，远大理想与共同理想的关系是最终理想与阶段性理想的关系，共产主义远大理想是最终理想，中国特色社会主义共同理想是阶段性理想，选C。"},{"id":"mk15044-pl-P4803520","type":"sc","tier":"基础","conf":"adapt","chap":"第5-7章","q":"从层次上看，共产主义远大理想与中国特色社会主义共同理想的关系是（）。","opts":["A. 最终理想与阶段性理想的关系","B. 最高纲领与最低纲领的关系","C. 全人类理想与全体中国人民理想的关系","D. 理论与实践的关系"],"ans":1,"explain":"从层次上看，远大理想与共同理想的关系是最高纲领与最低纲领的关系，我们党的最高理想和最终目标是实现共产主义，这是最高纲领，当前推进中国特色社会主义事业是最低纲领在当前的要求，选B。"},{"id":"mk15044-pl-P4803521","type":"sc","tier":"基础","conf":"adapt","chap":"第5-7章","q":"当代青年要坚定理想信念，需要深入学习（）。","opts":["A. 马克思主义基本原理和马克思主义中国化时代化的理论成果","B. 西方哲学思想","C. 古代经典文学作品","D. 各类自然科学知识"],"ans":0,"explain":"当代青年要坚定理想信念，就要深入学习马克思主义基本原理和马克思主义中国化时代化的理论成果，特别是要学习习近平新时代中国特色社会主义思想，选A。"},{"id":"mk15044-pl-P4803522","type":"sc","tier":"基础","conf":"adapt","chap":"第5-7章","q":"共产主义社会中，劳动将成为（）。","opts":["A. 单纯的谋生手段","B. 生活的第一需要","C. 与个人发展无关的活动","D. 只是为了获取物质报酬的活动"],"ans":1,"explain":"在共产主义社会，劳动不再是单纯的谋生手段，而成为“生活的第一需要”，选B。"},{"id":"mk15044-pl-P4803523","type":"sc","tier":"基础","conf":"adapt","chap":"第5-7章","q":"共产主义社会实现后，人类将（）。","opts":["A. 从自由王国向必然王国飞跃","B. 从必然王国向自由王国飞跃","C. 一直处于必然王国","D. 一直处于自由王国"],"ans":1,"explain":"共产主义社会实现了人类解放，人类将最终从支配他们生活和命运的异己力量中解放出来，实现从必然王国向自由王国的飞跃，选B。"},{"id":"mk15044-pl-P4803524","type":"sc","tier":"基础","conf":"adapt","chap":"第5-7章","q":"社会主义代替资本主义和最后实现共产主义的历史进程，离不开（）。","opts":["A. 少数英雄人物的努力","B. 工人阶级及其政党能动性的发挥","C. 自然的演变","D. 等待历史的恩赐"],"ans":1,"explain":"社会主义代替资本主义和最后实现共产主义的历史进程，离不开工人阶级及其政党能动性的发挥，离不开社会主义国家建设事业的推进，离不开世界社会主义运动的发展，选B。"},{"id":"mk15044-pl-P4803525","type":"sc","tier":"基础","conf":"adapt","chap":"第5-7章","q":"在共产主义实现的历史必然性中包含着（）。","opts":["A. 少数人的追求","B. 无产阶级和广大人民群众对共产主义理想的追求","C. 个别政党的追求","D. 某个阶级的追求"],"ans":1,"explain":"在共产主义实现的历史必然性中就包含着无产阶级和广大人民群众对共产主义理想的追求，选B。"},{"id":"mk15044-pl-P4803526","type":"sc","tier":"基础","conf":"adapt","chap":"第5-7章","q":"青年一代有理想、有本领、有担当，国家就有前途，民族就有希望，这是因为（）。","opts":["A. 青年是社会的少数群体","B. 青年是祖国的未来、民族的希望","C. 青年都能实现自己的理想","D. 青年不需要努力就能成功"],"ans":1,"explain":"青年是祖国的未来、民族的希望，青年一代的理想信念、精神状态、综合素质，是一个国家发展活力的重要体现，也是一个国家核心竞争力的重要因素，所以青年一代有理想、有本领、有担当，国家就有前途，民族就有希望，选B。"},{"id":"mk15044-pl-P4803527","type":"sc","tier":"基础","conf":"adapt","chap":"第5-7章","q":"共产主义社会中，个人消费品的分配方式是（）。","opts":["A. 按劳分配","B. 按需分配","C. 按资分配","D. 平均分配"],"ans":1,"explain":"在共产主义社会，个人消费品的分配方式是“各尽所能，按需分配”，选B。"},{"id":"mk15044-pl-P4803528","type":"sc","tier":"基础","conf":"adapt","chap":"第5-7章","q":"共产主义社会中，“三大差别”将会（）。","opts":["A. 不断扩大","B. 归于消失","C. 永远存在","D. 只存在城乡差别"],"ans":1,"explain":"在共产主义社会，由于私有制和利益对立的消除以及旧式分工的消除和人的全面发展，工业与农业、城市与乡村、脑力劳动与体力劳动的差别即“三大差别”必将归于消失，选B。"},{"id":"mk15044-pl-P4803529","type":"sc","tier":"基础","conf":"adapt","chap":"第5-7章","q":"实现共产主义必须经历许多历史阶段，其中不包括（）。","opts":["A. 资本主义从兴盛走向衰落和灭亡","B. 从资本主义到社会主义的过渡时期","C. 社会主义社会的初级阶段","D. 直接从资本主义进入共产主义高级阶段"],"ans":3,"explain":"实现共产主义必须经历许多历史阶段，包括资本主义从兴盛走向衰落和灭亡、从资本主义到社会主义的过渡时期、社会主义社会的初级阶段等，不能直接从资本主义进入共产主义高级阶段，选D。"},{"id":"mk15044-pl-P4803530","type":"sc","tier":"基础","conf":"adapt","chap":"第5-7章","q":"资本主义走向灭亡的过程是（）。","opts":["A. 短期内迅速完成的","B. 一个长期的历史过程","C. 已经完成的","D. 不会发生的"],"ans":1,"explain":"资本主义作为一个社会形态，其走向灭亡是一个长期的历史过程，选B。"},{"id":"mk15044-pl-P4803531","type":"sc","tier":"基础","conf":"adapt","chap":"第5-7章","q":"中国特色社会主义共同理想主要面向的对象是（）。","opts":["A. 全人类","B. 全体中国人民和中华民族","C. 世界各国无产阶级","D. 发展中国家人民"],"ans":1,"explain":"中国特色社会主义共同理想，主要是面向中国人民和中华民族的，是全体中华儿女和中国人民的“共同理想”，选B。"},{"id":"mk15044-pl-P4803532","type":"sc","tier":"基础","conf":"adapt","chap":"第5-7章","q":"当代青年积极投身新时代中国特色社会主义伟大事业，要以（）为己任。","opts":["A. 实现个人利益最大化","B. 实现中华民族伟大复兴","C. 追求物质享受","D. 获得高社会地位"],"ans":1,"explain":"新时代的中国青年要以实现中华民族伟大复兴为己任，增强做中国人的志气、骨气、底气，所以选B。"},{"id":"mk15044-pl-P4803533","type":"sc","tier":"基础","conf":"adapt","chap":"第5-7章","q":"预见未来社会的方法论原则中，马克思主义经典作家强调从（）中寻找启示来认识未来共产主义社会。","opts":["A. 资本主义社会","B. 社会主义社会的建设与发展","C. 空想社会主义理论","D. 历史上的理想社会构想"],"ans":1,"explain":"预见未来共产主义社会的基本特征，既从资本主义社会中寻找灵感，更从社会主义社会的建设与发展中寻找启示，所以选B。"},{"id":"mk15044-pl-P4803580","type":"sa","tier":"创新","conf":"adapt","chap":"第5-7章","q":"简述空想社会主义的发展阶段及代表人物和著作。","opts":[],"ans":null,"explain":"空想社会主义的发展阶段、代表人物及著作是了解社会主义思想早期发展的重要内容，这些内容在教材中有明确阐述，不同阶段的代表人物和著作反映了空想社会主义思想的演变和发展。\n空想社会主义的发展经历了三个阶段：①16到17世纪的早期空想社会主义，代表著作有托马斯・莫尔的《乌托邦》、康帕内拉的《太阳城》；②18世纪的空想平均共产主义，代表著作有摩莱里的《自然法典》和马布利的《论法制或法律的原则》；③19世纪初期批判的空想社会主义，代表人物有法国的圣西门、傅立叶和英国的欧文，圣西门提出“实业制度”，傅立叶提出“和谐社会”并进行“法郎吉”试验，欧文进行了新拉纳克大棉纺厂慈善试验和“新和谐公社”共产主义试验。"},{"id":"mk15044-pl-P4803548","type":"sa","tier":"创新","conf":"adapt","chap":"第5-7章","q":"论述社会主义从空想到科学的发展历程及其重要意义。","opts":[],"ans":null,"explain":"社会主义从空想到科学的发展历程是社会主义思想演进的关键阶段，理解这一过程及其意义有助于把握社会主义理论的发展脉络和历史贡献，教材对其背景、理论基础和意义有全面阐述。\n社会主义从空想到科学的发展是历史的必然。空想社会主义产生于16世纪初期，到19世纪上半叶达到顶峰，经历了早期空想社会主义、空想平均共产主义、批判的空想社会主义三个阶段。代表人物有托马斯・莫尔、康帕内拉、摩莱里、马布利、圣西门、傅立叶、欧文等，他们的著作和实践描绘了理想社会的蓝图，对资本主义进行了批判，反映了早期无产阶级的愿望。但空想社会主义存在局限性，“没有能够指出真正的出路”，其理论是同不成熟的资本主义生产状况、不成熟的阶级状况相适应的。随着社会化大生产的发展和资本主义矛盾的激化，无产阶级与资产阶级的斗争更加激烈，为社会主义从空想发展到科学提供了社会需要和客观条件。马克思、恩格斯创立和发展了唯物史观和剩余价值学说，为实现这一飞跃奠定了坚实的理论基础。唯物史观揭示了人类历史发展的一般规律、人民群众的历史主体作用和阶级斗争的作用；剩余价值学说揭示了资本家剥削工人的秘密和无产阶级的历史使命。在此基础上，马克思、恩格斯创立了科学社会主义学说，科学论证了社会主义代替资本主义的历史必然性，阐明了无产阶级的历史使命，提出了战略策略，预见了未来社会的基本特征，实现了社会主义从空想到科学的伟大飞跃。这一飞跃具有极其重要的意义，它把社会主义建立在对社会发展客观规律科学认识的基础上，为无产阶级革命提供了科学的理论指导，使社会主义运动有了明确的方向和目标，推动了国际工人运动的发展，为人类社会的进步开辟了新的道路。"},{"id":"mk15044-pl-P4803549","type":"sa","tier":"创新","conf":"adapt","chap":"第5-7章","q":"论述中国特色社会主义是如何坚持和发展科学社会主义基本原则的。","opts":[],"ans":null,"explain":"中国特色社会主义是科学社会主义在中国的实践和发展，从多个维度分析其对科学社会主义基本原则的坚持和发展，有助于理解中国特色社会主义的本质和优势，教材中对中国特色社会主义的各个方面有详细阐述。\n中国特色社会主义始终坚持科学社会主义基本原则，并结合中国实际和时代特征赋予其鲜明特色，在多方面进行了坚持和发展。在经济方面，坚持生产资料公有制为主体、多种所有制经济共同发展，按劳分配为主体、多种分配方式并存，社会主义市场经济体制等基本经济制度。既坚持了生产资料公有制的根基地位，又根据中国生产力发展水平和要求，探索出多种所有制共同发展的模式；在分配上，实行按劳分配并多种分配方式并存，激发了劳动者的积极性和创造性；强调发挥市场在资源配置中的决定性作用和更好发挥政府作用，正确处理了计划与市场的关系，满足全体社会成员的需要，促进经济发展。在政治方面，坚持走中国特色社会主义政治发展道路，强调人民民主是社会主义的生命，全面发展全过程人民民主，使民主政治制度化、规范化、程序化全面推进，社会主义协商民主广泛开展。这体现了科学社会主义关于人民当家作主和无产阶级专政的理论，保障了人民的政治权利。在文化方面，坚持马克思主义在意识形态领域指导地位的根本制度，大力发展社会主义先进文化，加强理想信念教育，弘扬革命文化，传承中华优秀传统文化。以马克思主义为指导，引领社会风尚，同时吸收和弘扬优秀文化成果，为社会主义建设提供精神动力和智力支持。在社会建设方面，坚持在发展中保障和改善民生，实现好、维护好、发展好最广大人民的根本利益，不断实现人民对美好生活的向往，努力消除两极分化，逐步实现共同富裕，体现了社会主义以人民为中心的发展思想。在生态文明建设方面，坚持人与自然和谐共生，不断取得社会主义生态文明建设新成就，遵循了科学社会主义关于合乎自然规律地改造和利用自然的原则。在党的领导方面，坚持和加强中国共产党的全面领导，发挥党总揽全局、协调各方的领导核心作用，坚持无产阶级政党领导作用的原则，同时以党的自我革命推进社会革命，保持党的先进性和纯洁性。中国特色社会主义将科学社会主义基本原则与中国实际紧密结合，在实践中不断丰富和发展科学社会主义，使科学社会主义在中国焕发出蓬勃生机。"},{"id":"mk15044-pl-P4803550","type":"sa","tier":"创新","conf":"adapt","chap":"第5-7章","q":"结合实际，论述社会主义在实践中开拓前进的必要性以及如何以自信担当、开拓奋进的姿态走向社会主义光明未来。","opts":[],"ans":null,"explain":"社会主义在实践中开拓前进的必要性和走向光明未来的方式是理解社会主义发展的重要内容，结合实际案例能更深刻地阐述这一主题，教材对相关理论和实践有详细分析和说明。\n社会主义在实践中开拓前进具有必要性。首先，社会主义是亿万人民群众的伟大实践，离开了人民群众的实际行动，就无法把握社会主义的真谛。人民群众是历史的创造者，社会主义事业需要人民群众的广泛参与和积极创造。其次，社会主义实践是一个不断探索的过程。社会主义是崭新的事业，没有现成的路可走，科学社会主义基本原则虽指明方向，但不能提供具体问题的答案，必须结合各国实际不断探索，才能掌握社会主义建设与发展的规律。最后，实践探索中出现某种曲折并不改变社会主义的前进趋势。人类社会发展不是直线式的，社会主义发展也会遇到曲折，如东欧剧变、苏联解体，但我们要正确认识曲折，从曲折中吸取教训，坚定信念，推动社会主义继续前进。要以自信担当、开拓奋进的姿态走向社会主义光明未来，需做到以下几点：一是正确看待21世纪世界社会主义的形势。东欧剧变、苏联解体虽使世界社会主义进入低潮，但社会主义具有强大生命力。当前，世界资本主义进入衰退期，而世界社会主义以中国特色社会主义的发展为依托进入上升期，我们要对社会主义的未来充满信心。二是充分认识中国特色社会主义的成功实践对世界社会主义发展的意义。中国特色社会主义取得举世瞩目的成就，进入新时代，为世界社会主义发展提供了新的思路和模式。中国式现代化为人类实现现代化提供了新选择，证明了科学社会主义的真理性，极大地鼓舞了世界人民对社会主义的信心。三是坚定信心、振奋精神。社会主义前进道路上会有困难和挑战，但只要共产党人和人民群众坚定社会主义信念，勇于在实践中开拓前进，就一定能战胜困难。中国人民在中国共产党领导下，全面贯彻习近平新时代中国特色社会主义思想，以自信担当的精神状态和开拓奋进的奋斗姿态，全力战胜前进道路上的各种困难，把社会主义事业不断推向前进。例如，中国在脱贫攻坚、科技创新、生态保护等方面取得的巨大成就，都是在不断探索和奋斗中实现的，彰显了社会主义制度的优势和中国人民的担当精神。总之，社会主义在实践中开拓前进是必然要求，我们要坚定信心，积极探索，以实际行动走向社会主义光明未来。"},{"id":"mk15044-pl-P4803551","type":"sa","tier":"创新","conf":"adapt","chap":"第5-7章","q":"论述共产主义社会“各尽所能，按需分配”原则的意义及与社会主义社会“各尽所能，按劳分配”原则的区别。","opts":[],"ans":null,"explain":"理解共产主义社会和社会主义社会分配原则的差异与联系，有助于深入认识不同社会形态的本质特征和发展阶段，这部分内容在教材中有理论阐述，通过对比分析可更清晰地把握。\n“各尽所能，按需分配”是共产主义社会个人消费品的分配方式，具有重大意义，与社会主义社会“各尽所能，按劳分配”原则存在明显区别。“各尽所能，按需分配”的意义：①实现了人类在分配上的真正平等。在社会主义社会，“各尽所能，按劳分配”虽以劳动为分配标准，相较于之前是巨大进步，但仍存在局限性，默认劳动者不同天赋导致的收入差距，且未考虑劳动者家庭负担等。而共产主义社会的“各尽所能，按需分配”突破了这种局限，根据人们的需要进行生活资料分配，实现了真正的平等。②体现了高度发展的社会生产力和社会文明。只有在社会生产力高度发展，集体财富的一切源泉都充分涌流，人们的思想觉悟极大提高，劳动不再是谋生手段而是成为生活第一需要之后，才能实现按需分配。这表明社会物质和精神文明都达到了极高水平。二者的区别：①分配标准不同。“按劳分配”以劳动为尺度，按照劳动者提供的劳动数量和质量分配个人消费品；“按需分配”则以人的实际需要为标准进行分配，更能满足人的全面发展需求。②平等程度不同。“按劳分配”在形式上平等，但因劳动者能力差异会导致实际收入不平等；“按需分配”消除了这种基于劳动能力差异的不平等，实现了更高层次的平等。③所处社会阶段不同。“按劳分配”是社会主义社会的分配原则，与社会主义社会的生产力发展水平和人们的思想觉悟相适应；“按需分配”是共产主义社会高级阶段的分配原则，是在社会主义充分发展、生产力高度发达、人们精神境界极大提高的基础上实现的。综上所述，“各尽所能，按需分配”是共产主义社会的重要特征，是对“各尽所能，按劳分配”的超越，反映了社会发展的更高阶段和更高级的分配公平。"},{"id":"mk15044-pl-P4803552","type":"sa","tier":"创新","conf":"adapt","chap":"第5-7章","q":"结合历史和现实，论述实现共产主义的历史必然性以及实现过程的长期性和曲折性。","opts":[],"ans":null,"explain":"实现共产主义的历史必然性、长期性和曲折性是共产主义理论的重要内容，结合历史和现实案例能更全面、深入地理解这一复杂的历史进程，教材从不同角度对其进行了分析。\n实现共产主义具有历史必然性，但实现过程充满长期性和曲折性。历史必然性：①从社会发展规律来看，人类社会从低级到高级的发展是一个客观必然的历史进程。马克思主义揭示了人类社会发展的一般规律和资本主义社会发展的特殊规律，资本主义的基本矛盾，即生产社会化与生产资料资本主义私人占有之间的矛盾，决定了资本主义必然走向灭亡，社会主义必然代替资本主义，并最终实现共产主义。②社会主义运动的实践为共产主义理想的实现提供了有力证明。从社会主义国家的兴起和发展来看，如俄国十月革命的胜利、中国等一系列国家走上社会主义道路，都表明共产主义理想具有现实可能性。这些国家在社会主义建设过程中取得的成就，如生产力的发展、人民生活水平的提高等，都在朝着共产主义的方向迈进，为共产主义的最终实现积累了经验和物质基础。长期性和曲折性：①资本主义的灭亡是一个长期的过程。资本主义从兴盛走向衰落需要相当长的历史时期，其内部的调整和自我修复能力使其不会轻易退出历史舞台。例如，第二次世界大战后，资本主义通过一系列政策调整，如加强国家对经济的干预、发展科技等，实现了经济的恢复和发展，呈现出一定的繁荣景象。而且，在资本主义走向灭亡的过程中，其向社会主义转变后，还需要经历社会主义的发展阶段，逐步消除旧社会的痕迹，实现生产力的高度发展和社会的全面进步，才能最终迈向共产主义。②社会主义社会自身的发展也是一个长期过程。社会主义建设面临诸多挑战，如经济文化相对落后国家建设社会主义，要解决生产力发展、经济基础和上层建筑完善、国际环境压力等问题。我国处于社会主义初级阶段，生产力水平与发达国家相比还有差距，在社会主义建设过程中也经历过曲折，如“大跃进”和“文化大革命”等。同时，社会主义国家还面临着资本主义国家的“和平演变”等外部压力，这些都增加了社会主义发展的复杂性和长期性。综上所述，实现共产主义是历史发展的必然趋势，但我们必须充分认识到实现过程的长期性和曲折性，坚定信心，在实践中不断探索和前进。"},{"id":"mk15044-pl-P4803553","type":"sa","tier":"创新","conf":"adapt","chap":"第5-7章","q":"论述当代青年应如何坚定理想信念，投身新时代中国特色社会主义伟大事业，为实现共产主义远大理想而奋斗。","opts":[],"ans":null,"explain":"当代青年在实现共产主义事业中具有重要作用，从理论学习、实践参与、品德培养和国际视野等方面论述，有助于引导青年明确自身责任和行动方向，这部分内容与现实联系紧密，在教材相关理论基础上可结合实际情况进行阐述。\n当代青年肩负着实现中华民族伟大复兴的历史使命，应从以下方面坚定理想信念，投身新时代中国特色社会主义伟大事业，为实现共产主义远大理想而奋斗：①深入学习理论知识，筑牢理想信念根基。当代青年要深入学习马克思主义基本原理和马克思主义中国化时代化的理论成果，特别是习近平新时代中国特色社会主义思想。通过学习，深刻理解社会发展规律，把握共产主义远大理想和中国特色社会主义共同理想的内涵，用科学理论武装头脑，坚定对马克思主义的信仰、对中国特色社会主义的信念、对实现中华民族伟大复兴中国梦的信心，让真理指引前进方向。例如，通过学习习近平新时代中国特色社会主义思想，了解我国社会发展的战略布局和目标任务，明确自身在时代发展中的责任和使命。②积极参与社会实践，在实践中践行理想信念。青年应积极投身新时代中国特色社会主义伟大事业，将个人理想融入国家和民族的事业中。在学习和工作中，勇于担当、敢于创新，努力提高自身本领，为推动社会发展贡献力量。比如，在科技创新领域，青年科研人员可以努力攻克关键技术难题，助力我国科技自立自强；在乡村振兴中，青年干部可以扎根基层，带领群众发展产业，实现共同富裕。③培养高尚道德品质，弘扬时代精神。当代青年要树立正确的世界观、人生观、价值观，培养良好的道德品质和行为习惯。弘扬社会主义核心价值观，倡导社会公德、职业道德和家庭美德，在社会生活中发挥积极的示范作用。同时，要弘扬时代精神，勇于面对困难和挑战，在挫折中磨炼意志，保持积极向上的精神状态。④增强国际视野，胸怀天下。在全球化背景下，当代青年应具有国际视野，关注人类命运共同体的建设。积极参与国际交流与合作，传播中国声音，讲好中国故事，为推动全球发展和人类进步贡献智慧和力量。例如，参与国际志愿服务活动，为解决全球性问题如环境保护、贫困问题等贡献自己的一份力量。总之，当代青年要坚定理想信念，脚踏实地，在新时代的广阔舞台上展现青春风采，为实现共产主义远大理想不懈奋斗。"},{"id":"mk15044-pl-P4803306","type":"sc","tier":"基础","conf":"adapt","chap":"第2章","q":"马克思主义认为，社会生活在本质上是（）","opts":["A. 丰富的","B. 精神的","C. 发展的","D. 实践的"],"ans":3,"explain":"马克思主义指出，以物质生活资料生产为根本的社会实践活动是人类社会存在和发展的基础，所以社会生活在本质上是实践的。"},{"id":"mk15044-pl-P4803307","type":"sc","tier":"基础","conf":"adapt","chap":"第2章","q":"辩证唯物主义认识论首要的和基本的观点是（）","opts":["A. 实践的观点","B. 辩证法的观点","C. 可知论的观点","D. 唯物论的观点"],"ans":0,"explain":"马克思主义坚持实践观点和辩证观点，深刻揭示了实践观点是辩证唯物主义认识论首要的和基本的观点，实践是认识的基础，对认识具有决定性作用。"},{"id":"mk15044-pl-P4803308","type":"sc","tier":"基础","conf":"adapt","chap":"第2章","q":"人类认识发展的根本动力是（）","opts":["A. 兴趣爱好","B. 社会实践","C. 求知欲望","D. 好奇心理"],"ans":1,"explain":"实践的需要推动认识的产生和发展，推动人类的科学发现和技术发明，推动人类的思想进步和理论创新，所以社会实践是人类认识发展的根本动力。"},{"id":"mk15044-pl-P4803309","type":"sc","tier":"基础","conf":"adapt","chap":"第2章","q":"下列选项中属于最基本的实践活动的是（）","opts":["A. 社会管理活动","B. 科学实验活动","C. 社会改革活动","D. 物质生产活动"],"ans":3,"explain":"物质生产实践是人类最基本的实践活动，它解决人与自然的矛盾，满足人们的物质生活资料和生产劳动资料的需要，同时生产和再生产社会的基本经济关系，由此决定着社会的基本性质和面貌。"},{"id":"mk15044-pl-P4803310","type":"sc","tier":"基础","conf":"adapt","chap":"第2章","q":"实践作为一种感性物质活动，强调的是（）","opts":["A. 实践具有客观性","B. 实践具有主观性","C. 实践具有能动性","D. 实践具有历史性"],"ans":0,"explain":"实践具有客观实在性，构成实践活动的诸要素，即实践的主体、客体和中介，都是可感知的客观实在；实践的水平、广度、深度和发展过程，都受着客观条件的制约和客观规律的支配；实践能够引起客观世界的某种变化，可以把人脑中观念的存在变为现实的存在，给人们提供现实的成果。"},{"id":"mk15044-pl-P4803311","type":"sc","tier":"基础","conf":"adapt","chap":"第2章","q":"自觉能动性是实践的一个基本特点，表明实践是（）","opts":["A. 主体纯粹的思维活动","B. 主体有意识、有目的的活动","C. 主体感性的物质活动","D. 主体社会性、历史性的活动"],"ans":1,"explain":"与动物本能的、被动的适应性活动不同，人的实践活动是一种有目的、有意识的活动。目的性是能动性的主要表现，人的实践活动结束时得到的结果，在这个过程开始时就作为目的在实践者头脑中以观念的形式存在着，目的决定着实践者的行为。"},{"id":"mk15044-pl-P4803312","type":"sc","tier":"基础","conf":"adapt","chap":"第2章","q":"认识世界的根本目的是（）","opts":["A. 激发求知欲望","B. 指导社会实践","C. 满足好奇心理","D. 发展个人兴趣"],"ans":1,"explain":"人们通过实践获得认识，最终目的是为实践服务，指导实践，以满足人们生活和生产的需要。自然科学和人文社会科学的创新，都是为了更好地指导实践，推动社会发展和人的进步。"},{"id":"mk15044-pl-P4803313","type":"sc","tier":"基础","conf":"adapt","chap":"第2章","q":"与辩证唯物主义认识论相比较，旧唯物主义认识论有两个缺陷，一个是缺乏辩证法的观点，另一个是（）","opts":["A. 缺乏实践的观点","B. 缺乏反映论的观点","C. 缺乏一元论的观点","D. 缺乏可知论的观点"],"ans":0,"explain":"旧唯物主义认识论的基本特点是以感性直观为基础，把人的认识看成是消极地、被动地反映和接受外界对象，类似于照镜子那样的反射活动。它的缺陷一是离开实践考察认识问题，不了解实践对认识的决定作用；二是不了解认识的辩证本性，离开辩证法来考察认识问题。"},{"id":"mk15044-pl-P4803314","type":"sc","tier":"基础","conf":"adapt","chap":"第2章","q":"辩证唯物主义认为，认识的本质是（）","opts":["A. 主体对客体的直观反映","B. 绝对观念的显现","C. 主体对客体的能动反映","D. 神秘天意的启示"],"ans":2,"explain":"辩证唯物主义认识论是建立在实践基础上的能动的反映论，认为认识的本质是主体在实践基础上对客体的能动反映，这种能动反映不但具有反映客体内容的反映性特征，而且具有实践所要求的主体能动的、创造性的特征。"},{"id":"mk15044-pl-P4803315","type":"sc","tier":"基础","conf":"adapt","chap":"第2章","q":"认识主体与认识客体之间最基本的关系是（）","opts":["A. 改造与被改造的关系","B. 相互依存的关系","C. 反映与被反映的关系","D. 相互作用的关系"],"ans":0,"explain":"实践关系是认识主体和客体最基本的关系，主体通过实践活动对客体进行改造，在改造客体的过程中认识客体，进而实现认识的发展。"},{"id":"mk15044-pl-P4803316","type":"sc","tier":"基础","conf":"adapt","chap":"第2章","q":"唯物主义认识论和唯心主义认识论的根本区别是（）","opts":["A. 前者是可知论，后者是不可知论","B. 前者是能动反映论，后者是机械反映论","C. 前者是反映论，后者是先验论","D. 前者是唯理论，后者是经验论"],"ans":2,"explain":"唯物主义认识论坚持从物到感觉和思想的认识路线，认为认识是主体对客体的反映，属于反映论；唯心主义认识论坚持从思想和感觉到物的认识路线，否认认识是人脑对客观世界的反映，认为认识先于人的实践经验，属于先验论。"},{"id":"mk15044-pl-P4803317","type":"sc","tier":"基础","conf":"adapt","chap":"第2章","q":"能动反映论区别于机械反映论的根本标志是（）","opts":["A. 肯定思维能正确地反映存在","B. 认为认识过程是纯粹的观念创造","C. 肯定思维对存在的决定作用","D. 认为认识过程是反映和创造的统一"],"ans":3,"explain":"辩证唯物主义认识论把实践的观点引入认识论，把辩证法应用于反映论考察认识的发展过程，认为认识过程是反映和创造的统一，这是能动反映论区别于机械反映论的根本标志。"},{"id":"mk15044-pl-P4803318","type":"sc","tier":"基础","conf":"adapt","chap":"第2章","q":"那种主张“天赋的才能”“天生的天灵禀赋”的观点属于（）","opts":["A. 唯心主义先验论","B. 旧唯物主义的直观反映论","C. 唯物主义反映论","D. 辩证唯物论的能动反映论"],"ans":0,"explain":"唯心主义先验论认为人的认识与外部世界、人的直接经验没有关系，“天赋的才能”“天生的天灵禀赋”这类观点强调认识先于经验，属于唯心主义先验论。"},{"id":"mk15044-pl-P4803319","type":"sc","tier":"基础","conf":"adapt","chap":"第2章","q":"理性认识从低级到高级的发展过程是（）","opts":["A. 概念-判断-推理","B. 感觉-知觉-表象","C. 实践-认识-实践","D. 认识-实践-认识"],"ans":0,"explain":"理性认识包括概念、判断、推理三种形式，从概念到判断再到推理，是理性认识由低级到高级的发展，体现了人们对事物认识的不断深化。"},{"id":"mk15044-pl-P4803320","type":"sc","tier":"基础","conf":"adapt","chap":"第2章","q":"“感觉到了的东西，我们不能立刻理解它，只有理解了的东西才能更深刻地感觉它”，这句话表明（）","opts":["A. 感性认识是微不足道的","B. 感性认识是认识的高级阶段","C. 理性认识是唯一可靠的","D. 理性认识是认识的高级阶段"],"ans":3,"explain":"感性认识是认识的初级阶段，具有直接性和具体性，它反映的是事物的现象；理性认识是认识的高级阶段，具有抽象性和间接性，以反映事物的本质为内容，比感性认识更深刻。该句话体现了理性认识对感性认识的深化作用。"},{"id":"mk15044-pl-P4803321","type":"sc","tier":"基础","conf":"adapt","chap":"第2章","q":"一个完整的认识过程，需要经过两次飞跃。下列属于第二次飞跃的是（）","opts":["A. 调查研究，了解情况","B. 深入思考，形成理论","C. 精心安排，制定策略","D. 执行计划，付诸实践"],"ans":3,"explain":"认识的第二次飞跃是从理性认识到实践的飞跃，将理性认识应用于实践，通过实践检验和发展认识，执行计划、付诸实践属于这一过程。"},{"id":"mk15044-pl-P4803322","type":"sc","tier":"基础","conf":"adapt","chap":"第2章","q":"下列正确说明感性认识和理性认识联系的是（）","opts":["A. 理性认识依赖于感性认识","B. 感性认识可以自动上升到理性认识","C. 感性认识依赖于理性认识","D. 理性认识可以自动回归到感性认识"],"ans":0,"explain":"感性认识是认识过程的起点，是达到理性认识的必经阶段，理性认识依赖于感性认识；感性认识有待于发展和深化为理性认识，但需要经过科学的思维加工，不能自动上升。"},{"id":"mk15044-pl-P4803323","type":"sc","tier":"基础","conf":"adapt","chap":"第2章","q":"在认识论上，一切唯物主义都坚持（）","opts":["A. 实践论","B. 先验论","C. 反映论","D. 矛盾论"],"ans":2,"explain":"在认识论上，一切唯物主义都坚持反映论，认为认识是主体对客体的反映，这是唯物主义认识论的基本立场。"},{"id":"mk15044-pl-P4803324","type":"sc","tier":"基础","conf":"adapt","chap":"第2章","q":"人的认识是一个辩证发展的过程。作为认识的初级阶段的是（）","opts":["A. 直接认识","B. 间接认识","C. 感性认识","D. 理性认识"],"ans":2,"explain":"感性认识是认识的初级阶段，包括感觉、知觉和表象三种形式，是人们在实践基础上，由感觉器官直接感受到的关于事物的现象、事物的外部联系、事物的各个方面的认识。"},{"id":"mk15044-pl-P4803325","type":"sc","tier":"基础","conf":"adapt","chap":"第2章","q":"对于一个具体事物的认识要经历的完整过程是（）","opts":["A. 感性认识——理性认识——实践","B. 实践——理性认识——感性认识","C. 感性认识——实践——理性认识","D. 实践——感性认识——理性认识"],"ans":0,"explain":"认识过程首先是在实践基础上获得感性认识，然后经过思维加工上升到理性认识，最后将理性认识应用于实践，在实践中检验和发展认识，这是一个完整的认识过程。"},{"id":"mk15044-pl-P4803326","type":"sc","tier":"基础","conf":"adapt","chap":"第2章","q":"理性认识的三种形式是（）","opts":["A. 感觉、知觉、表象","B. 概念、判断、推理","C. 联想、想象、猜测","D. 直觉、顿悟、灵感"],"ans":1,"explain":"理性认识包括概念、判断、推理三种形式，概念是对同类事物共同的一般特性和本质属性的概括和反映；判断是展开了的概念，是对事物之间的联系和关系的反映；推理在形式上表现为判断与判断之间的联系，是从事物的联系或关系中由已知合乎逻辑地推出未知的反映形式。"},{"id":"mk15044-pl-P4803327","type":"sc","tier":"基础","conf":"adapt","chap":"第2章","q":"实践作为检验真理的标准，之所以具有相对性、不确定性，主要是因为一定历史条件下的具体实践都具有（）","opts":["A. 自觉能动性","B. 客观物质性","C. 直接现实性","D. 历史局限性"],"ans":3,"explain":"任何实践都会受到主客观条件的制约，由于历史条件的种种限制，实践对真理的检验具有相对性、有限性，表现为具体的实践往往只是在总体上证实认识与它所反映的客观事物是否相符合，而不可能绝对地、永恒地、一劳永逸地予以确证，所以实践标准具有不确定性。"},{"id":"mk15044-pl-P4803328","type":"sc","tier":"基础","conf":"adapt","chap":"第2章","q":"下列各项正确说明真理问题的是（）","opts":["A. 真理是“绝对理念”的自我显现","B. 真理是观念与主体的感觉相符合","C. 真理是对客观事物及其规律的能动反映","D. 真理是对客观事物及其规律的正确反映"],"ans":3,"explain":"真理是标志主观与客观相符合的哲学范畴，是对客观事物及其规律的正确反映。A选项是客观唯心主义的真理观，B选项是主观唯心主义的真理观，C选项“能动反映”表述不准确，认识的本质是主体在实践基础上对客体的能动反映，但真理强调的是正确反映。"},{"id":"mk15044-pl-P4803329","type":"sc","tier":"基础","conf":"adapt","chap":"第2章","q":"实践作为检验真理的标准，既具有确定性，又具有（）","opts":["A. 普遍性","B. 特殊性","C. 不确定性","D. 绝对性"],"ans":2,"explain":"实践标准是确定性与不确定性的统一，确定性指实践作为检验真理标准的唯一性、归根到底性、最终性；不确定性指实践作为检验真理标准的条件性，受主客观条件制约，对真理的检验具有相对性、有限性。"},{"id":"mk15044-pl-P4803330","type":"sc","tier":"基础","conf":"adapt","chap":"第2章","q":"绝对真理和相对真理是（）","opts":["A. 两种性质不同的真理","B. 真理发展的两个不同阶段","C. 两种各自独立的真理","D. 客观真理的两种不同属性"],"ans":3,"explain":"真理既具有绝对性，又具有相对性，它们是同一客观真理的两种属性，相互联系、不可分割。任何真理都是绝对性和相对性的统一，从真理的两重性上看，二者相互依存、相互包含；从真理的发展上看，人类的认识是一个不断由真理的相对性走向绝对性、接近绝对性的转化和发展过程。"},{"id":"mk15044-pl-P4803331","type":"sc","tier":"基础","conf":"adapt","chap":"第2章","q":"真理的发展是一个（）","opts":["A. 从主观真理走向客观真理的过程","B. 从局部真理走向全面真理的过程","C. 从具体真理走向抽象真理的过程","D. 从相对真理走向绝对真理的过程"],"ans":3,"explain":"人类的认识是一个不断深化的过程，真理永远处在由相对性走向绝对性、接近绝对性的转化和发展过程中，任何真理性的认识都是由真理的相对性向绝对性转化过程中的一个环节。"},{"id":"mk15044-pl-P4803332","type":"sc","tier":"基础","conf":"adapt","chap":"第2章","q":"检验真理的唯一标准是（）","opts":["A. 多数人认可","B. 权威认可","C. 方便实用","D. 社会实践"],"ans":3,"explain":"“判定认识或理论之是否真理，不是依主观上觉得如何而定，而是依客观上社会实践的结果如何而定。真理的标准只能是社会的实践。”"},{"id":"mk15044-pl-P4803333","type":"sc","tier":"基础","conf":"adapt","chap":"第2章","q":"马克思主义认识论认为，认识是否具有真理性（）","opts":["A. 可以从认识本身得到证实","B. 可以从认识对象中得到回答","C. 可以从认识主体自由判断","D. 只有在实践中才能得到验证"],"ans":3,"explain":"认识是否具有真理性，既不能从认识本身得到证实，也不能从认识对象中得到回答，只有在实践中才能得到验证。实践是检验真理的唯一标准，只有将认识应用于实践，通过实践的结果才能判断认识是否正确反映了客观事物及其规律。"},{"id":"mk15044-pl-P4803334","type":"sc","tier":"基础","conf":"adapt","chap":"第2章","q":"在真理标准问题上坚持辩证法，就是要承认实践标准（）","opts":["A. 既是抽象的又是具体的","B. 既是必然的又是偶然的","C. 既是普遍的又是特殊的","D. 既是绝对的又是相对的"],"ans":3,"explain":"实践标准是确定性（绝对性）与不确定性（相对性）的统一。实践标准的确定性指实践是检验真理的唯一标准等；不确定性指实践受主客观条件限制，对真理的检验具有相对性、有限性。在真理标准问题上坚持辩证法，就要承认实践标准的这种两重性。"},{"id":"mk15044-pl-P4803335","type":"sc","tier":"基础","conf":"adapt","chap":"第2章","q":"“没有理性，眼睛是最坏的见证人”这句话强调（）","opts":["A. 仅同事物的现象相符合的不一定是真相","B. 只要同事物的现象相符合的就是真理","C. 只要观察事物的外部联系就能获得真理","D. 只要观察事物的偶然联系就能获得真理"],"ans":0,"explain":"这句话强调只依靠感性认识，不经过理性思考，可能无法把握事物的真相。仅认识事物的现象不一定能得到正确的认识，因为现象可能是表面的、虚假的，需要理性思维去透过现象看本质。"},{"id":"mk15044-pl-P4803336","type":"sc","tier":"基础","conf":"adapt","chap":"第2章","q":"党的十八大报告指出，“爱国、敬业、诚信、友善”是（）","opts":["A. 从国家层面对社会主义核心价值观基本理论的凝练","B. 从社会层面对社会主义核心价值观基本理论的凝练","C. 从家庭层面对社会主义核心价值观基本理论的凝练","D. 从个人层面对社会主义核心价值观基本理论的凝练"],"ans":3,"explain":"社会主义核心价值观中，“爱国、敬业、诚信、友善”是从个人行为层面对社会主义核心价值观基本理念的凝练，倡导个人在日常生活和工作中践行这些价值准则。"},{"id":"mk15044-pl-P4803337","type":"sc","tier":"基础","conf":"adapt","chap":"第2章","q":"党的十八大报告指出要积极培育实践社会主义核心价值观，其中从国家层面对社会主义核心价值观基本理念的凝练表达是（）","opts":["A. 创新、包容、开放、进取","B. 富强、民主、文明、和谐","C. 自由、平等、公正、法治","D. 爱国、敬业、诚信、友善"],"ans":1,"explain":"“富强、民主、文明、和谐”是从国家层面对社会主义核心价值观基本理念的凝练表达，体现了国家在经济、政治、文化、社会等方面的价值追求。"},{"id":"mk15044-pl-P4803338","type":"sc","tier":"基础","conf":"adapt","chap":"第2章","q":"党的十八大报告提出要积极培育和践行社会主义核心价值观，其中从社会层面对社会主义核心价值观基本理念的凝练表达是（）","opts":["A. 富强、民主、文明、和谐","B. 自由、平等、公正、法治","C. 爱国、敬业、诚信、友善","D. 创新、包容、开放、进取"],"ans":1,"explain":"“自由、平等、公正、法治”是从社会层面对社会主义核心价值观基本理念的凝练表达，反映了社会在制度建设和社会关系方面的价值取向。"},{"id":"mk15044-pl-P4803339","type":"sc","tier":"基础","conf":"adapt","chap":"第2章","q":"在真理的检验标准问题上，下列说法正确的是（）","opts":["A. 多数人认可的就是真理","B. 个人觉得有用的就是真理","C. 少数人坚持的就是真理","D. 在实践中证实的才是真理"],"ans":3,"explain":"实践是检验真理的唯一标准，认识是否具有真理性，只能通过实践来验证。多数人认可、个人觉得有用或少数人坚持都不能作为判断真理的依据，因为这些都可能受到主观因素的影响，而实践具有直接现实性，能够客观地检验认识与客观实际是否相符。"},{"id":"mk15044-pl-P4803341","type":"sc","tier":"基础","conf":"adapt","chap":"第2章","q":"实践之所以能成为检验真理的唯一标准，主要在于（）","opts":["A. 实践具有直接现实性的品格","B. 实践具有自觉能动性的特点","C. 实践是客观的感性物质活动","D. 实践是推动认识发展的动力"],"ans":0,"explain":"实践具有直接现实性，能够把一定的认识、理论变成直接的、实实在在的现实，把主观的东西变为客观的东西。如果实践的结果与实践之前的认识和预想相符合，那么之前的认识就得到了证实，这是实践成为检验真理唯一标准的主要依据。"},{"id":"mk15044-pl-P4803342","type":"sc","tier":"基础","conf":"adapt","chap":"第2章","q":"党的思想路线的核心是（）","opts":["A. 一切从实际出发","B. 实事求是","C. 理论联系实际","D. 在实践中检验和发展真理"],"ans":1,"explain":"中国共产党思想路线的基本内涵是一切从实际出发，理论联系实际，实事求是，在实践中检验和发展真理，其中“实事求是”是核心。“实事求是”要求从客观实际出发，探索事物的内在联系和发展规律，体现了马克思主义认识论的根本要求。"},{"id":"mk15044-pl-P4803343","type":"sc","tier":"基础","conf":"adapt","chap":"第2章","q":"“哲学家们只是用不同的方式解释世界，问题在于改变世界”的提出者是（）","opts":["A. 黑格尔","B. 费尔巴哈","C. 马克思","D. 恩格斯"],"ans":2,"explain":"“哲学家们只是用不同的方式解释世界，问题在于改变世界”出自马克思的《关于费尔巴哈的提纲》，强调了实践在认识世界和改造世界中的重要性，突出马克思主义哲学不仅关注理论认知，更注重通过实践来改变现实世界。"},{"id":"mk15044-pl-P4803344","type":"sc","tier":"基础","conf":"adapt","chap":"第2章","q":"脱离实践的理论是空洞的理论；没有理论指导的实践是盲目的实践。这句话强调的是（）","opts":["A. 认识过程中摹写与创造的统一","B. 认识过程中感性与理性的统一","C. 认识过程中真理与价值的统一","D. 认识过程中理论与实践的统一"],"ans":3,"explain":"这句话表明理论不能脱离实践，否则就会空洞无物；实践也需要理论的指导，不然就会盲目进行。它强调了在认识过程中，理论与实践应紧密结合、相互统一，只有这样才能实现对世界的正确认识和有效改造。"},{"id":"mk15044-pl-P4803345","type":"sc","tier":"基础","conf":"adapt","chap":"第2章","q":"坚持马克思主义哲学的认识路线，就必须在工作中坚持（）","opts":["A. 一切从实际出发","B. 一切从主观的愿望出发","C. 一切从理论出发","D. 一切从臆造的规律出发"],"ans":0,"explain":"马克思主义哲学的认识路线强调从实际出发，尊重客观事实，按照客观世界的本来面目认识世界而不附加任何外来的主观成分。从实际出发是马克思主义认识论的根本要求和具体体现，只有坚持这一点，才能正确认识和解决问题。"},{"id":"mk15044-pl-P4803346","type":"sc","tier":"基础","conf":"adapt","chap":"第2章","q":"认识世界和改造世界的统一基础是（）","opts":["A. 理论","B. 实践","C. 真理","D. 价值"],"ans":1,"explain":"认识世界和改造世界是相互依赖、相互制约的辩证统一关系，二者统一的基础是实践。实践是认识的基础，通过实践人们认识世界，又在认识的指导下通过实践改造世界。"},{"id":"mk15044-pl-P4803347","type":"sc","tier":"基础","conf":"adapt","chap":"第2章","q":"马克思主义认为，自由是（）","opts":["A. 随心所欲，不受任何限制","B. 摆脱必然性的制约","C. 对必然的认识和对客观世界的改造","D. 与必然完全对立"],"ans":2,"explain":"马克思主义认为，自由是表示人的活动状态的范畴，是指人在活动中通过认识和利用必然所表现出的一种自觉自主的状态，即“自由是对必然的认识和对客观世界的改造”。人不能摆脱必然性的制约，只有认识必然并利用必然改造世界，才能获得自由。"},{"id":"mk15044-pl-P4803348","type":"sc","tier":"基础","conf":"adapt","chap":"第2章","q":"坚持实事求是，最基础的工作是（）","opts":["A. 搞清楚“实事”","B. 探求和掌握事物发展的规律","C. 解放思想","D. 理论联系实际"],"ans":0,"explain":"坚持实事求是，最基础的工作在于搞清楚“实事”，也就是了解实际、掌握实情，这是进行一切科学决策所必需的也是唯一可靠的前提和基础。只有了解实际情况，才能为后续的“求是”工作提供依据。"},{"id":"mk15044-pl-P4803349","type":"sc","tier":"基础","conf":"adapt","chap":"第2章","q":"坚持实事求是，关键在于（）","opts":["A. 一切从实际出发","B. 理论联系实际","C. 解放思想","D. “求是”"],"ans":3,"explain":"坚持实事求是，关键在于“求是”，就是探求和掌握事物发展的规律。对事物客观规律的认识只能在实践中完成，勇于实践、善于实践，在实践中积累经验，进行理论升华，再用以指导实践、推动实践，是把握客观规律的必由之路。"},{"id":"mk15044-pl-P4803350","type":"sc","tier":"基础","conf":"adapt","chap":"第2章","q":"守正创新中，守正的核心是（）","opts":["A. 坚持解放思想","B. 坚持实事求是，坚持真理性认识，坚持正确政治方向","C. 坚持开拓进取","D. 坚持与时俱进"],"ans":1,"explain":"守正就是坚持实事求是，坚持真理性认识，坚持正确政治方向。守正是创新的基本前提和可靠保障，只有坚守正道、追求真理，才能在创新过程中不迷失方向。"},{"id":"mk15044-pl-P4803351","type":"sc","tier":"基础","conf":"adapt","chap":"第2章","q":"理论创新和实践创新的良性互动中，实践创新的作用是（）","opts":["A. 为理论创新提供科学的行动指南","B. 为理论创新提供不竭的动力源泉","C. 决定理论创新的方向","D. 保障理论创新的成果"],"ans":1,"explain":"实践创新为理论创新提供不竭的动力源泉。时代变化和实践发展是理论创新的源头活水，世界上伟大的理论成果都是在回答和解决人与社会面临的重大问题中创造出来的，当代中国的实践创新给理论创新提供了强大动力和广阔空间。"},{"id":"mk15044-pl-P4803352","type":"sc","tier":"基础","conf":"adapt","chap":"第2章","q":"理论创新和实践创新不是孤立进行的，二者的关系是（）","opts":["A. 相互促进、辩证统一","B. 理论创新决定实践创新","C. 实践创新决定理论创新","D. 二者没有关联"],"ans":0,"explain":"理论创新和实践创新相互促进、辩证统一。实践创新为理论创新提供动力源泉，理论创新为实践创新提供科学的行动指南，二者在互动中完成，不断实现更高阶段的创新发展，离开了任何一方，另一方都难以有效推进。"},{"id":"mk15044-pl-P4803560","type":"sa","tier":"创新","conf":"adapt","chap":"第2章","q":"简述实践的含义及特点。","opts":[],"ans":null,"explain":"实践的含义明确了实践的主体（人类）、目的（改造世界）、性质（社会性的物质活动）。而其三个特点分别从不同角度体现了实践的本质特征。客观实在性强调实践的物质基础和客观制约性；自觉能动性突出了人的主观意识在实践中的作用；社会历史性则反映了实践活动与社会历史发展的紧密联系。这三个特点相互关联，共同构成了实践的完整特性。\n实践是人类能动地改造世界的社会性的物质活动。实践具有客观实在性、自觉能动性和社会历史性三个基本特征。客观实在性指构成实践活动的诸要素是可感知的客观实在，实践受客观条件制约和客观规律支配，且能引起客观世界变化；自觉能动性指人的实践活动是有目的、有意识的活动；社会历史性指实践是社会性的活动，且其内容、性质、范围、水平以及方式都受一定社会历史条件的制约，随社会历史条件变化而变化。"},{"id":"mk15044-pl-P4803561","type":"sa","tier":"创新","conf":"adapt","chap":"第2章","q":"简述实践在认识中的决定作用。","opts":[],"ans":null,"explain":"实践是认识的来源，因为只有通过实践与客观事物的直接接触，才能获取关于事物的信息和知识。实践作为认识发展的动力，是因为实践中产生的新问题、新需求促使人们去探索和研究，同时实践也为认识提供了各种资源和工具。认识服务于实践，这是认识的最终归宿，只有将认识应用于实践，才能实现其价值。而实践之所以是检验真理的唯一标准，是因为只有实践能将主观认识与客观实际进行对照，判断认识是否正确反映了客观事物。\n实践在认识中起决定性作用，主要表现在：①实践是认识的来源，认识的内容在实践活动基础上产生和发展，一切真知都源于直接经验；②实践是认识发展的动力，实践的需要推动认识产生和发展，为认识提供手段和条件，还能锻炼和提高人的认识能力；③实践是认识的目的，人们获得认识是为了服务实践，指导实践以满足生活和生产需要；④实践是检验认识真理性的唯一标准，认识是否具有真理性，只有在实践中才能得到验证。"},{"id":"mk15044-pl-P4803562","type":"sa","tier":"创新","conf":"adapt","chap":"第2章","q":"简述认识过程的第一次飞跃及实现的条件。","opts":[],"ans":null,"explain":"认识的第一次飞跃是认识过程中的关键阶段，从感性认识的直观、具体，上升到理性认识的抽象、概括，能更深入地把握事物本质。获取丰富且合乎实际的感性材料是基础，因为理性认识是对感性材料的加工和升华，没有丰富准确的素材，理性认识就会成为无源之水。而运用理论思维和科学抽象对感性材料进行处理，是实现飞跃的关键步骤，通过这些方法可以去除表面的、虚假的信息，抓住事物的内在联系和本质特征。\n认识过程的第一次飞跃是从实践到认识的过程，即在实践中，认识从感性认识上升到理性认识。实现这一飞跃的条件：①投身实践，深入调查，获取十分丰富和合乎实际的感性材料，这是实现由感性认识上升到理性认识的基础；②经过思考的作用，运用理论思维和科学抽象，将丰富的感性材料加以去粗取精、去伪存真、由此及彼、由表及里的处理加工，形成概念和理论的系统。"},{"id":"mk15044-pl-P4803563","type":"sa","tier":"创新","conf":"adapt","chap":"第2章","q":"简述感性认识和理性认识的辩证关系。","opts":[],"ans":null,"explain":"感性认识和理性认识的区别源于它们对事物反映的程度和方式不同。感性认识基于直接的感知，侧重于事物的现象；理性认识则经过思维加工，把握事物的本质。二者的联系体现了认识的连续性和发展性。理性认识依赖感性认识，没有感性认识提供的素材，理性认识就无法形成；感性认识需要上升到理性认识，才能更好地指导实践；而它们相互渗透则表明在实际认识过程中，很难将二者完全割裂开来，感性认识中往往包含着理性的因素，理性认识也需要借助感性的形式来表达和理解。\n感性认识和理性认识是认识的两个阶段，相互区别又相互联系，是对立统一的关系。区别：感性认识是认识的初级阶段，是对事物表面的、直接的、具体的、个别特性的反映，不深刻、片面；理性认识是认识的高级阶段，是对事物全体的、本质的、间接的、概括的反映，更深刻、全面、相对稳定。联系：①理性认识依赖感性认识，感性认识是认识过程的起点，是达到理性认识的必经阶段；②感性认识有待于发展和深化为理性认识；③感性认识和理性认识相互渗透、相互包含，感性中有理性，理性中有感性。"},{"id":"mk15044-pl-P4803564","type":"sa","tier":"创新","conf":"adapt","chap":"第2章","q":"简述真理的客观性的含义。","opts":[],"ans":null,"explain":"真理的客观性强调真理不依赖于人的主观意志。从内容上看，它是对客观事物及其规律的如实反映，不受人的主观想法干扰。而真理的一元性是其客观性的必然结果，在相同条件下，对同一事物的正确认识只有一个，这是因为客观事物的本质和规律是确定的，不以人的认识差异而改变。这种客观性和一元性保证了真理的科学性和可靠性。\n真理的客观性包含两层含义：①真理的内容是对客观事物及其规律的正确反映，真理中包含着不依赖于人和人的意识的客观内容；②真理的客观性决定了真理的一元性，即在同一条件下对于特定的认识客体的真理性认识只有一个，真理的客观内容就是客观事物的实际状况。"},{"id":"mk15044-pl-P4803565","type":"sa","tier":"创新","conf":"adapt","chap":"第2章","q":"简述真理的绝对性和相对性的含义及二者的辩证关系。","opts":[],"ans":null,"explain":"真理的绝对性体现了真理的确定性和客观性，强调真理的正确性和人类认识能力的无限可能性。真理的相对性则反映了人类认识的局限性，由于客观世界的复杂性和人类认识的阶段性，人们对真理的把握总是有限的。二者的辩证关系表明，真理是一个不断发展和深化的过程。相互依存说明没有纯粹的绝对真理或相对真理，它们是同一真理的两个方面；相互包含进一步阐述了二者的内在联系；而从发展角度看，人类不断在实践中丰富和完善对真理的认识，逐步从相对真理走向更接近绝对真理的状态。\n真理的绝对性指：①任何真理都标志着主观与客观相符合，都包含不依赖于人和人的意识的客观内容，都同谬误有原则界限；②人类认识按其本性来说，能够正确认识无限发展着的物质世界，每前进一步都是对无限发展着的物质世界的接近。真理的相对性指：①从客观世界的整体来看，任何真理都只是对客观世界的某一阶段、某一部分的正确认识，认识有待扩展；②就特定事物而言，任何真理都只是对客观对象一定方面、一定层次和一定程度的正确认识，认识有待深化。二者辩证关系：①相互依存，任何真理都既是绝对的，又是相对的；②相互包含，绝对之中有相对，相对之中有绝对，真理的绝对性通过真理的相对性表现出来，任何真理的相对性之中都包含着真理绝对性的颗粒；③从真理的发展上看，人类认识是不断由真理的相对性走向绝对性、接近绝对性的转化和发展过程。"},{"id":"mk15044-pl-P4803566","type":"sa","tier":"创新","conf":"adapt","chap":"第2章","q":"简述实践是检验真理的唯一标准的原因。","opts":[],"ans":null,"explain":"从真理的本性出发，真理要求主观与客观一致，而主观认识本身无法判断自身是否正确，客观事物也不会主动表明与人的认识是否相符，只有实践能搭建起二者沟通的桥梁。实践的直接现实性特点使其能够将抽象的认识转化为具体的客观成果，通过对比实践结果和预期，就能直观地判断认识是否符合客观实际，所以实践成为检验真理的唯一标准。\n实践是检验真理的唯一标准，原因如下：①从真理的本性看，真理是人们对客观事物及其发展规律的正确反映，其本性在于主观和客观相符合。检验真理就是检验主观认识同客观实际是否相符合，主观认识和客观事物本身都不能充当检验标准，只有社会实践能把主观认识与客观事物联系和沟通起来，从而检验二者是否相符；②从实践的特点看，实践具有直接现实性，能够把一定的认识、理论变成直接的、实实在在的现实，把主观的东西变为客观的东西，通过实践结果与预想的比较，就能验证认识是否为真理。"},{"id":"mk15044-pl-P4803567","type":"sa","tier":"创新","conf":"adapt","chap":"第2章","q":"简述价值的基本特性。","opts":[],"ans":null,"explain":"价值的主体性突出了主体在价值关系中的主导地位，不同主体对同一客体的价值判断可能不同。客观性强调价值并非完全主观臆造，而是基于主体和客体的客观存在和属性。多维性反映了价值的多样性，同一客体可以满足主体多方面的需求。社会历史性则体现了价值会随着社会发展和历史变迁而变化，这是由于主体和客体的状况在不断改变，导致价值关系也随之变动。\n价值具有主体性、客观性、多维性和社会历史性四个基本特性。主体性指价值直接与主体相联系，始终以主体为中心，价值关系的形成依赖于主体的存在和创造；客观性指在一定条件下客体对于主体的意义不依赖于主体的主观意识而存在，主体的存在和需要、客体的存在及属性都是客观的；多维性指每个主体的价值关系具有多样性，同一客体相对于主体的不同需要会产生不同的价值；社会历史性指主体和客体的不断变化决定了价值的社会历史性，价值关系中的主体是具体的人，随实践和历史发展，主体、客体及主客体关系发生变化，人们对客体价值的判断也会改变。"},{"id":"mk15044-pl-P4803568","type":"sa","tier":"创新","conf":"adapt","chap":"第2章","q":"简述认识世界和改造世界的辩证关系。","opts":[],"ans":null,"explain":"认识世界是改造世界的基础，只有正确认识事物的本质和规律，才能制定出合理有效的改造方案。而改造世界的实践活动又为认识世界提供了丰富的素材和动力，在实践中人们会遇到新问题，促使对世界有更深入的认识。理论与实践相结合是实现认识世界和改造世界统一的关键，理论指导实践，实践验证和发展理论，二者相辅相成。\n认识世界和改造世界是相互依赖、相互制约的辩证统一关系。一方面，认识世界有助于改造世界，正确认识世界是有效改造世界的必要前提，只有对事物的本质和规律有正确认识，才能在改造世界时采取正确的行动；另一方面，人们只有在改造世界的实践中才能不断地深化、拓展对世界的正确认识，实践为认识提供了来源和发展动力。认识世界和改造世界的统一，决定了理论与实践必须相结合。"},{"id":"mk15044-pl-P4803569","type":"sa","tier":"创新","conf":"adapt","chap":"第2章","q":"简述一切从实际出发是马克思主义认识论的根本要求的原因。","opts":[],"ans":null,"explain":"一切从实际出发符合马克思主义认识论对客观世界的尊重和对实践的重视。以客观事物为出发点，遵循客观规律，能确保认识和实践的科学性。马克思主义理论是普遍真理，但在不同的历史条件和现实情境下，需要结合具体实际灵活运用，否则就会陷入教条主义。注重事实是从实际出发的关键，只有基于真实可靠的事实，才能形成正确的思想理论，制定合理的政策，从而推动实践取得成功。\n一切从实际出发是马克思主义认识论的根本要求，原因在于：①从实际出发就是要把客观存在的事物作为观察和处理问题的根本出发点，按照客观世界的本来面目认识世界，从根本上说就是要从客观事物存在和发展的规律出发，在实践中按照客观规律办事；②马克思主义理论的实际运用要以当时的历史条件为根据，不能生搬硬套，只有从实际出发，才能正确运用马克思主义解决现实问题；③从实际出发，关键是要注重事实，从事实出发，只有以经过严格和确凿证明的事实作为思想理论和政策制定的前提，才是成功实践的必由之路。"},{"id":"mk15044-pl-P4803534","type":"sa","tier":"创新","conf":"adapt","chap":"第2章","q":"试述辩证唯物主义的反映论与旧唯物主义的反映论对于认识本质的回答有什么不同，并阐述辩证唯物主义反映论的科学性。","opts":[],"ans":null,"explain":"旧唯物主义反映论的缺陷主要源于其对实践和辩证法的忽视。离开实践，就无法理解认识的来源、动力和目的，也不能正确把握认识主体和客体的关系。而辩证唯物主义反映论的科学性在于其对实践和辩证法的重视。实践观点的引入，使认识活动与实践紧密相连，明确了认识的基础和发展动力。辩证法的应用，则揭示了认识过程中各种矛盾关系，强调认识是一个不断发展和深化的过程。能动反映论中反映性和创造性的统一，既保证了认识的客观性，又体现了认识的能动性，能够更全面、准确地把握事物的本质和规律。\n旧唯物主义的反映论把人的认识看成是消极地、被动地反映和接受外界对象，类似于照镜子那样的反射活动。其缺陷在于：①离开实践考察认识问题，不了解实践对认识的决定作用，把认识主体看作生物学意义上的人，把认识客体看作静观对象，主客体关系仅为反映和被反映关系；②不了解认识的辩证本性，离开辩证法考察认识问题，把复杂的认识过程简单化，把认识运动凝固化，把多方面的认识要素片面化，看不到主观和客观之间的矛盾及其相互作用，认为认识是一次性完成的。辩证唯物主义的反映论是建立在实践基础上的能动的反映论。其科学性体现在：①把实践的观点引入认识论，以实践的观点阐述人的认识活动及其规律，科学规定了认识的主体和客体及其相互关系，对认识的产生、发展、目的、作用以及检验标准等问题作出科学解释；②把辩证法应用于反映论考察认识的发展过程，科学揭示了认识过程中多方面的辩证关系，如主观和客观、认识和实践、感性和理性等关系，把认识看成一个充满矛盾的能动的认识过程，全面揭示了认识过程的辩证性质；③认识的本质是主体在实践基础上对客体的能动反映，这种能动反映具有反映性和创造性特征，反映特性确保认识以客观事物为原型，创造性特征使认识能透过现象把握本质，认识是反映性与创造性的统一。"},{"id":"mk15044-pl-P4803535","type":"sa","tier":"创新","conf":"adapt","chap":"第2章","q":"试述真理与价值的对立统一关系，并结合实际谈谈在实践中如何实现真理尺度与价值尺度的统一。","opts":[],"ans":null,"explain":"真理与价值的对立统一关系是理解人类实践活动的关键。其对立源于二者侧重点不同，真理追求客观真实，价值关注主体需求满足。而统一则体现在真理的价值属性以及真理对正确价值观形成的指导作用上。在实践中实现二者统一的要点，从三个方面展开。坚持真理尺度，就是在实践中遵循客观规律，只有这样实践活动才具有科学性，如科技创新领域，依据科学原理进行研究是取得成果的基础。把握价值尺度，意味着实践要以满足主体需求为导向，社会发展规划以人民利益为目标就是很好的体现。实现具体的、历史的统一，是因为实践处于不断发展变化中，不同时期的实践对真理和价值的要求不同。在新时代中国特色社会主义建设中，我们依据社会发展规律制定政策，同时以满足人民美好生活需要为出发点，这就是二者统一的生动实践。随着实践推进，我们要不断根据新情况调整对真理和价值的把握，促进二者相互协调，推动社会进步。\n真理与价值是对立统一的关系。对立表现在：真理体现的是认识与认识对象的相一致、相符合的关系，侧重于对客观事物及其规律的正确反映；而价值是指客体对人需要的满足，表示客体具有对人有用或对主体有意义的属性，侧重于主体的需求和利益。统一表现在：①真理能够指导社会实践成功地改造世界，以实践的成果来满足人的需要，这就是真理所表现出来的价值属性；②真理与正确的价值观相一致，正确的价值观是在真理指导下形成的。人们只有正确认识客观事物及其规律（真理），才能形成符合客观实际的价值观念，从而在实践中作出正确的价值选择。在实践中实现真理尺度与价值尺度的统一，需要做到：①坚持真理尺度，遵循客观规律。在实践活动中，必须以正确反映客观事物本质和规律的真理为指导，按照真理办事，才能保证实践活动的科学性和有效性。例如，在科技创新中，科研人员要依据科学原理和客观规律进行研究，才能取得真正有价值的成果。②把握价值尺度，满足主体需求。明确实践活动的目的是满足人类自身的需要，在实践中要充分考虑主体的利益和需求，使实践活动具有明确的指向性。比如在社会发展规划中，要以满足人民群众对美好生活的向往为目标，制定符合人民利益的政策和措施。③实现二者的具体的、历史的统一。由于实践是具体的、历史的，真理尺度与价值尺度的统一也应是具体的、历史的。随着实践的发展，不断调整和完善对真理的认识以及对价值的追求，使二者相互协调、相互促进。在新时代中国特色社会主义建设中，我们既要遵循社会发展规律（真理尺度），又要以人民为中心，满足人民对美好生活的需要（价值尺度），推动各项事业不断前进。"},{"id":"mk15044-pl-P4803536","type":"sa","tier":"创新","conf":"adapt","chap":"第2章","q":"试述党的思想路线，并说明马克思主义认识论是党的思想路线的理论基础。","opts":[],"ans":null,"explain":"党的思想路线是马克思主义认识论在实际工作中的具体体现。一切从实际出发，契合马克思主义认识论对客观世界的尊重和对实践基础地位的强调，只有立足实际，才能获取真实认识。理论联系实际体现了认识与实践的辩证关系，理论源于实践并指导实践，在实践中不断完善，这与马克思主义认识论中认识和实践相互作用的原理相符。“实事求是”作为核心，其内涵与马克思主义认识论通过实践探索规律的要求一致，突出了对客观规律的尊重和主动探索。在实践中检验和发展真理，与马克思主义认识论中实践是检验真理唯一标准以及认识发展的观点一致，表明认识需要在实践中不断检验和完善，以适应不断变化的客观实际。\n党的思想路线的基本内涵是一切从实际出发，理论联系实际，实事求是，在实践中检验和发展真理。马克思主义认识论是党的思想路线的理论基础，具体表现为：①党的思想路线坚持了一切从实际出发的原则，这与马克思主义认识论强调从客观存在的事物出发，尊重客观事实，按照客观世界的本来面目认识世界的要求一致。马克思主义认为实践是认识的基础，只有从实际出发，才能获取真实可靠的认识，为正确解决问题提供依据。②理论联系实际是党的思想路线的重要内容，这体现了马克思主义认识论中认识与实践相互作用的原理。理论来源于实践，又反过来指导实践，只有将理论与实际紧密结合，才能使理论发挥对实践的指导作用，同时在实践中检验和发展理论。③“实事求是”是党的思想路线的核心，也是马克思主义哲学及其认识论的精髓。“实事”就是客观存在着的一切事物，“是”就是客观事物的内部联系，即规律性，“求”就是去研究。这与马克思主义认识论中通过实践探索和把握事物规律的观点相契合，强调在实践基础上认识和把握客观规律。④党的思想路线强调在实践中检验和发展真理，这与马克思主义认识论中实践是检验真理的唯一标准，以及认识是一个不断发展的过程的观点一致。实践是检验认识真理性的客观标准，只有通过实践的检验，才能判断认识是否正确，并在实践中不断丰富和发展认识。"},{"id":"mk15044-pl-P4803417","type":"sc","tier":"基础","conf":"adapt","chap":"第3-4章","q":"商品经济产生的社会历史条件是（）。","opts":["A. 社会分工和生产资料及劳动产品属于不同所有者","B. 私有制的出现和阶级的产生","C. 国家的形成和市场的出现","D. 货币的产生和交换的发展"],"ans":0,"explain":"商品经济产生的社会历史条件有两个：一是存在社会分工，二是生产资料和劳动产品属于不同的所有者。"},{"id":"mk15044-pl-P4803418","type":"sc","tier":"基础","conf":"adapt","chap":"第3-4章","q":"价值规律的表现形式是（）。","opts":["A. 商品价格总是高于价值","B. 商品价格总是低于价值","C. 商品价格围绕价值自发波动","D. 商品价格与价值始终相等"],"ans":2,"explain":"在商品经济中，价值规律的表现形式是商品的价格围绕商品的价值自发波动。"},{"id":"mk15044-pl-P4803419","type":"sc","tier":"基础","conf":"adapt","chap":"第3-4章","q":"以私有制为基础的商品经济的基本矛盾是（）。","opts":["A. 使用价值和价值的矛盾","B. 具体劳动和抽象劳动的矛盾","C. 私人劳动和社会劳动的矛盾","D. 脑力劳动和体力劳动的矛盾"],"ans":2,"explain":"商品的使用价值和价值的矛盾、生产商品的具体劳动和抽象劳动的矛盾，根源于私人劳动和社会劳动的矛盾。私人劳动和社会劳动的矛盾是商品经济的基本矛盾。"},{"id":"mk15044-pl-P4803420","type":"sc","tier":"基础","conf":"adapt","chap":"第3-4章","q":"商品的价值量由（）决定。","opts":["A. 个别劳动时间","B. 社会必要劳动时间","C. 必要劳动时间","D. 剩余劳动时间"],"ans":1,"explain":"决定商品价值量的不是生产商品的个别劳动时间，而是社会必要劳动时间。"},{"id":"mk15044-pl-P4803421","type":"sc","tier":"基础","conf":"adapt","chap":"第3-4章","q":"货币的本质是（）。","opts":["A. 商品交换的媒介","B. 固定充当一般等价物的商品","C. 流通手段","D. 价值尺度"],"ans":1,"explain":"货币是在长期交换过程中形成的固定充当一般等价物的商品。"},{"id":"mk15044-pl-P4803422","type":"sc","tier":"基础","conf":"adapt","chap":"第3-4章","q":"生产商品的劳动二重性是（）。","opts":["A. 简单劳动和复杂劳动","B. 具体劳动和抽象劳动","C. 体力劳动和脑力劳动","D. 私人劳动和社会劳动"],"ans":1,"explain":"生产商品的劳动具有二重性，即具体劳动和抽象劳动。具体劳动创造商品的使用价值，抽象劳动形成商品的价值。"},{"id":"mk15044-pl-P4803423","type":"sc","tier":"基础","conf":"adapt","chap":"第3-4章","q":"商品的使用价值反映的是（）。","opts":["A. 人与人的关系","B. 人与自然的关系","C. 生产关系","D. 交换关系"],"ans":1,"explain":"使用价值是指商品能满足人的某种需要的有用性，反映的是人与自然之间的物质关系，是商品的自然属性。"},{"id":"mk15044-pl-P4803424","type":"sc","tier":"基础","conf":"adapt","chap":"第3-4章","q":"决定商品交换比例的是（）。","opts":["A. 使用价值","B. 价值","C. 交换价值","D. 价格"],"ans":1,"explain":"决定商品交换比例的不是商品的使用价值，而是价值。"},{"id":"mk15044-pl-P4803425","type":"sc","tier":"基础","conf":"adapt","chap":"第3-4章","q":"商品价值量与劳动生产率的关系是（）。","opts":["A. 成正比","B. 成反比","C. 没有关系","D. 不确定"],"ans":1,"explain":"商品的价值量与生产商品所耗费的社会必要劳动时间成正比，与劳动生产率成反比。"},{"id":"mk15044-pl-P4803426","type":"sc","tier":"基础","conf":"adapt","chap":"第3-4章","q":"马克思劳动价值论扬弃了（）的观点。","opts":["A. 美国古典政治经济学","B. 英国古典政治经济学","C. 法国古典政治经济学","D. 德国古典政治经济学"],"ans":1,"explain":"马克思劳动价值论扬弃了英国古典政治经济学的观点，为剩余价值论的创立奠定了基础。"},{"id":"mk15044-pl-P4803427","type":"sc","tier":"基础","conf":"adapt","chap":"第3-4章","q":"资本主义生产关系萌芽于（）。","opts":["A. 14世纪末15世纪初地中海沿岸的一些城市","B. 16世纪的大西洋沿岸城市","C. 18世纪的北美地区","D. 19世纪的欧洲大陆"],"ans":0,"explain":"资本主义萌芽于14世纪末15世纪初地中海沿岸的一些城市。"},{"id":"mk15044-pl-P4803428","type":"sc","tier":"基础","conf":"adapt","chap":"第3-4章","q":"资本原始积累主要通过的途径是（）。","opts":["A. 用暴力手段剥夺农民的土地和掠夺货币财富","B. 发展海外贸易和建立手工工场","C. 开展工业革命和进行殖民扩张","D. 推行圈地运动和发展商业资本"],"ans":0,"explain":"资本原始积累主要是通过两个途径进行的：一是用暴力手段剥夺农民的土地，二是用暴力手段掠夺货币财富。"},{"id":"mk15044-pl-P4803429","type":"sc","tier":"基础","conf":"adapt","chap":"第3-4章","q":"货币转化为资本的前提是（）。","opts":["A. 货币在运动中发生了价值增殖","B. 货币投入流通的目的是带来剩余价值","C. 劳动力成为商品","D. 货币可以购买到生产资料"],"ans":2,"explain":"劳动力成为商品是货币转化为资本的前提。"},{"id":"mk15044-pl-P4803430","type":"sc","tier":"基础","conf":"adapt","chap":"第3-4章","q":"资本主义生产方式的绝对规律是（）。","opts":["A. 价值规律","B. 剩余价值规律","C. 竞争规律","D. 资本积累规律"],"ans":1,"explain":"资本主义生产的直接目的和决定性动机，就是无休止地获取尽可能多的剩余价值，这种不以人的意志为转移的客观必然性就是剩余价值规律，它是资本主义生产方式的绝对规律。"},{"id":"mk15044-pl-P4803431","type":"sc","tier":"基础","conf":"adapt","chap":"第3-4章","q":"在资本主义生产过程中，价值增殖过程是（）。","opts":["A. 超过劳动力价值的补偿这个一定点而延长了的价值形成过程","B. 生产使用价值的劳动过程","C. 创造商品价值的过程","D. 转移生产资料价值的过程"],"ans":0,"explain":"价值增殖过程是超过劳动力价值的补偿这个一定点而延长了的价值形成过程。"},{"id":"mk15044-pl-P4803432","type":"sc","tier":"基础","conf":"adapt","chap":"第3-4章","q":"不变资本是指（）。","opts":["A. 以生产资料形态存在的资本","B. 用来购买劳动力的那部分资本","C. 在生产过程中价值发生增殖的资本","D. 在生产过程中其价值量会改变的资本"],"ans":0,"explain":"不变资本是以生产资料形态存在的资本，在生产过程中只转移自己的价值量，不发生增殖。"},{"id":"mk15044-pl-P4803433","type":"sc","tier":"基础","conf":"adapt","chap":"第3-4章","q":"相对剩余价值生产是通过（）实现的。","opts":["A. 延长工作日的长度","B. 提高劳动强度","C. 全社会劳动生产率的提高","D. 个别企业提高劳动生产率"],"ans":2,"explain":"相对剩余价值是指在工作日长度不变的条件下，通过缩短必要劳动时间而相对延长剩余劳动时间所生产的剩余价值，缩短必要劳动时间是通过全社会劳动生产率的提高实现的。"},{"id":"mk15044-pl-P4803434","type":"sc","tier":"基础","conf":"adapt","chap":"第3-4章","q":"资本积累的本质是（）。","opts":["A. 扩大生产规模","B. 增加社会财富","C. 资本家不断利用无偿占有的工人创造的剩余价值来扩大自己的资本规模","D. 提高资本有机构成"],"ans":2,"explain":"资本积累的本质，就是资本家不断地利用无偿占有的工人创造的剩余价值来扩大自己的资本规模，从而进一步扩大和加强对工人的剥削和统治。"},{"id":"mk15044-pl-P4803435","type":"sc","tier":"基础","conf":"adapt","chap":"第3-4章","q":"资本有机构成提高意味着在资本总额中（）。","opts":["A. 不变资本所占比重增加，可变资本所占比重减少","B. 不变资本所占比重减少，可变资本所占比重增加","C. 固定资本所占比重增加，流动资本所占比重减少","D. 固定资本所占比重减少，流动资本所占比重增加"],"ans":0,"explain":"资本有机构成是由资本的技术构成决定并反映技术构成变化的资本价值构成，在生产技术水平不断提高的条件下，随着资本积累的增长，不变资本部分日益增多，可变资本在资本总额中所占的比重日益下降，资本有机构成得以不断提高。"},{"id":"mk15044-pl-P4803436","type":"sc","tier":"基础","conf":"adapt","chap":"第3-4章","q":"资本主义经济危机的本质特征是（）。","opts":["A. 生产过剩","B. 生产不足","C. 经济过热","D. 通货膨胀"],"ans":0,"explain":"资本主义发展到一定阶段，就会发生以生产过剩为基本特征的经济危机，生产过剩是资本主义经济危机的本质特征，但这种过剩是相对过剩。"},{"id":"mk15044-pl-P4803437","type":"sc","tier":"基础","conf":"adapt","chap":"第3-4章","q":"资本主义国家的本质是（）。","opts":["A. 管理社会公共事务的机构","B. 资产阶级进行阶级统治的工具","C. 维护社会公平正义的组织","D. 保障公民权利的政治实体"],"ans":1,"explain":"资本主义国家本质上是资产阶级进行阶级统治的工具。"},{"id":"mk15044-pl-P4803438","type":"sc","tier":"基础","conf":"adapt","chap":"第3-4章","q":"资本主义民主制度的核心原则不包括（）。","opts":["A. 公有制原则","B. 私有制原则","C. 主权在民原则","D. 分权制衡原则"],"ans":0,"explain":"资本主义民主制度的核心原则包括私有制原则、主权在民原则、分权制衡原则、人权原则，不包括公有制原则。"},{"id":"mk15044-pl-P4803439","type":"sc","tier":"基础","conf":"adapt","chap":"第3-4章","q":"资本主义法律制度的核心是（）。","opts":["A. 民法","B. 刑法","C. 宪法","D. 商法"],"ans":2,"explain":"宪法是资本主义国家法律制度的核心，规定了国家的社会、经济和政治制度等。"},{"id":"mk15044-pl-P4803440","type":"sc","tier":"基础","conf":"adapt","chap":"第3-4章","q":"资本主义国家政权组织形式大多采用（）。","opts":["A. 分权制衡形式","B. 专制独裁形式","C. 议会君主制形式","D. 人民代表大会制形式"],"ans":0,"explain":"资本主义国家政权采取分权制衡的组织形式，即国家的立法权、行政权、司法权分别由三个权力主体独立行使，形成各主体之间的“制衡”。"},{"id":"mk15044-pl-P4803441","type":"sc","tier":"基础","conf":"adapt","chap":"第3-4章","q":"资本主义国家的选举制度是（）。","opts":["A. 公民参与国家事务的唯一形式","B. 资产阶级协调内部利益关系和矛盾的重要措施","C. 保障全体公民政治权利的制度","D. 实现社会公平正义的有效途径"],"ans":1,"explain":"从实际政治作用看，选举制是协调统治阶级内部利益关系和矛盾的重要措施。"},{"id":"mk15044-pl-P4803442","type":"sc","tier":"基础","conf":"adapt","chap":"第3-4章","q":"资本主义意识形态的核心思想是（）。","opts":["A. 集体主义和公有制观念","B. 私有制神圣不可侵犯观念和个人主义价值观","C. 公平正义和社会和谐理念","D. 民主平等和自由博爱思想"],"ans":1,"explain":"在资本主义国家中，占统治地位的意识形态一以贯之的核心思想，主要是私有制神圣不可侵犯观念和个人主义价值观。"},{"id":"mk15044-pl-P4803443","type":"sc","tier":"基础","conf":"adapt","chap":"第3-4章","q":"资本主义意识形态是（）。","opts":["A. 全体社会成员共同的思想观念","B. 为社会主义经济基础服务的","C. 资产阶级的阶级意识的集中体现","D. 无产阶级反对资产阶级的思想武器"],"ans":2,"explain":"资本主义意识形态是资产阶级的阶级意识的集中体现。"},{"id":"mk15044-pl-P4803444","type":"sc","tier":"基础","conf":"adapt","chap":"第3-4章","q":"资本主义国家政党制度的实质是（）。","opts":["A. 保障公民政治权利的制度安排","B. 维护资产阶级统治的政治制度","C. 实现社会民主平等的重要途径","D. 促进不同阶级合作的政治机制"],"ans":1,"explain":"从本质上说，资本主义国家多党制仍然是资产阶级选择自己的国家管理者、实现其内部利益平衡的政治机制，即维护资产阶级统治的政治制度。"},{"id":"mk15044-pl-P4803445","type":"sc","tier":"基础","conf":"adapt","chap":"第3-4章","q":"资本主义国家的对外职能本质上是（）。","opts":["A. 维护世界和平与发展","B. 促进国际间的经济文化交流","C. 服务于其政治统治","D. 保障本国公民的海外权益"],"ans":2,"explain":"资本主义国家的对外职能是国家对内政治统治职能的延伸，是服务于其政治统治的。"},{"id":"mk15044-pl-P4803446","type":"sc","tier":"基础","conf":"adapt","chap":"第3-4章","q":"资本主义政治制度的进步作用不包括（）。","opts":["A. 推动社会生产力大幅度发展","B. 使人们摆脱了封建专制主义的束缚","C. 消除了社会的阶级矛盾","D. 积累了丰富的政治统治和社会管理经验"],"ans":2,"explain":"资本主义政治制度在战胜封建社会生产方式等方面有进步作用，但并没有消除社会的阶级矛盾，C选项符合题意；其推动了生产力发展、使人们摆脱封建束缚、积累了政治管理经验，A、B、D选项不符合题意。"},{"id":"mk15044-pl-P4803542","type":"sa","tier":"创新","conf":"adapt","chap":"第3-4章","q":"论述马克思劳动价值论的理论和实践意义，并结合当代社会经济条件的变化，谈谈如何深化对马克思劳动价值论的认识。","opts":[],"ans":null,"explain":"马克思劳动价值论是政治经济学的重要基础，其理论意义体现在对古典经济学的发展和对经济内在矛盾的揭示上，实践意义则体现在对社会主义市场经济的指导作用。随着社会经济条件的变化，对劳动价值论的深化认识有助于适应新的经济形势，更好地理解和处理经济问题，这些内容在教材中有详细的理论阐述和分析。\n马克思劳动价值论的理论和实践意义如下：①扬弃了英国古典政治经济学的观点，为剩余价值论的创立奠定了基础，劳动二重性理论成为“理解政治经济学的枢纽”；②揭示了私有制条件下商品经济的基本矛盾，为从物与物的关系背后揭示人与人的关系提供了理论依据；③揭示了商品经济的一般规律，对理解社会主义市场经济具有指导意义。在当代条件下深化对马克思劳动价值论的认识，需做到：①深化对创造价值的劳动的认识，对生产性劳动作出新的界定，考虑社会主义市场经济条件下生产资料所有制关系和社会生产根本目的的变化；②深化对科技人员、经营管理人员在社会生产和价值创造中所起作用的认识，充分肯定他们的劳动贡献，合理分配收入；③深化对价值创造与价值分配关系的认识，明确价值创造是价值分配的前提和基础，但价值分配取决于生产资料所有制关系。"},{"id":"mk15044-pl-P4803543","type":"sa","tier":"创新","conf":"adapt","chap":"第3-4章","q":"论述资本主义经济危机的根源、本质特征、周期性及其对社会经济的影响。","opts":[],"ans":null,"explain":"资本主义经济危机是资本主义经济制度内在矛盾的集中体现，其根源、特征和周期性都与资本主义基本矛盾紧密相关，对社会经济的影响具有两面性，这些内容在教材中是重要的知识点，通过对其深入分析有助于理解资本主义经济的运行机制和内在矛盾。\n资本主义经济危机的根源是资本主义的基本矛盾，即生产社会化和生产资料资本主义私人占有之间的矛盾。这一矛盾具体表现在：生产无限扩大的趋势与劳动人民有支付能力的需求相对缩小的矛盾；单个企业内部生产的有组织性和整个社会生产的无政府状态之间的矛盾。本质特征是生产过剩，但这种过剩是相对过剩，即相对于劳动人民有支付能力的需求来说社会生产的商品显得过剩。资本主义经济危机具有周期性，这是由资本主义基本矛盾运动的阶段性决定的。当基本矛盾尖锐化时引发危机，危机爆发使供求矛盾缓解，但基本矛盾无法根除，随着经济恢复和高涨，矛盾又会激化导致新的危机。经济危机对社会经济的影响：一方面，造成社会资源的极大浪费，企业减产、停工，金融机构倒闭，社会经济生活混乱；另一方面，也在一定程度上强制解决社会再生产的实现问题，使社会再生产由失衡逐渐转变为平衡，但这是以社会经济生活的严重混乱和瘫痪为代价的。"},{"id":"mk15044-pl-P4803544","type":"sa","tier":"创新","conf":"adapt","chap":"第3-4章","q":"论述资本主义政治制度的本质、主要内容及其历史进步性与局限性。","opts":[],"ans":null,"explain":"资本主义政治制度是资本主义社会的重要组成部分，其本质反映了资产阶级的统治需求，主要内容体现了其政治运行的方式，历史进步性和局限性则是对其在历史发展过程中作用的全面评价，这些在教材中都有系统的阐述和分析。\n资本主义政治制度本质上是资产阶级进行政治统治和社会管理的手段和方式，是为资产阶级专政服务的。主要内容包括资本主义法律制度、政权组织形式、选举制度、政党制度等。历史进步性表现为：①作为上层建筑，在战胜封建社会生产方式、保护和促进资本主义生产方式方面起了重要作用，推动了社会生产力的大幅度发展；②使人们摆脱了封建专制主义的分封割据状态、等级压迫制度和人身依附关系，享有了更多政治自由，推进了人的发展和人类进步；③积累了丰富的政治统治和社会管理经验。局限性表现为：①资本主义的民主是金钱操纵下的民主，实际是资产阶级精英统治下的民主；②法律名义上的平等掩盖着事实上的不平等；③政党制是维护资产阶级统治的政治制度，政党恶斗相互掣肘，决策效率低下，激化社会矛盾。"},{"id":"mk15044-pl-P4803447","type":"sc","tier":"基础","conf":"adapt","chap":"第5-7章","q":"资本主义发展经历的两个阶段是（）。","opts":["A. 商品经济阶段和市场经济阶段","B. 自由竞争资本主义和垄断资本主义","C. 私人垄断资本主义和国家垄断资本主义","D. 工业资本主义和金融资本主义"],"ans":1,"explain":"资本主义的发展经历了自由竞争资本主义和垄断资本主义两个阶段。"},{"id":"mk15044-pl-P4803448","type":"sc","tier":"基础","conf":"adapt","chap":"第5-7章","q":"自由竞争引起生产集中和资本集中，生产集中和资本集中发展到一定阶段必然引起（）。","opts":["A. 竞争加剧","B. 经济危机","C. 垄断","D. 产业升级"],"ans":2,"explain":"自由竞争引起生产集中和资本集中，生产集中和资本集中发展到一定阶段必然引起垄断，这是资本主义发展的客观规律。"},{"id":"mk15044-pl-P4803449","type":"sc","tier":"基础","conf":"adapt","chap":"第5-7章","q":"垄断组织的本质是（）。","opts":["A. 通过联合实现独占和瓜分商品生产和销售市场，操纵垄断价格，以攫取高额垄断利润","B. 促进商品经济发展","C. 推动技术进步","D. 增加就业机会"],"ans":0,"explain":"垄断组织的本质是通过联合实现独占和瓜分商品生产和销售市场，操纵垄断价格，以攫取高额垄断利润。"},{"id":"mk15044-pl-P4803450","type":"sc","tier":"基础","conf":"adapt","chap":"第5-7章","q":"金融资本是由（）融合在一起而形成的一种垄断资本。","opts":["A. 工业垄断资本和商业垄断资本","B. 工业垄断资本和银行垄断资本","C. 商业垄断资本和银行垄断资本","D. 银行垄断资本和农业垄断资本"],"ans":1,"explain":"金融资本是由工业垄断资本和银行垄断资本融合在一起而形成的一种垄断资本。"},{"id":"mk15044-pl-P4803451","type":"sc","tier":"基础","conf":"adapt","chap":"第5-7章","q":"金融寡头在经济领域中的统治主要是通过（）实现的。","opts":["A. 暴力手段","B. 参与制","C. 个人联合","D. 控制舆论"],"ans":1,"explain":"金融寡头在经济领域中的统治主要是通过“参与制”实现的。"},{"id":"mk15044-pl-P4803452","type":"sc","tier":"基础","conf":"adapt","chap":"第5-7章","q":"垄断利润是（）。","opts":["A. 垄断资本家凭借其在社会生产和流通中的垄断地位而获得的超过平均利润的高额利润","B. 垄断资本家通过技术创新获得的利润","C. 垄断资本家通过扩大生产规模获得的利润","D. 垄断资本家通过降低成本获得的利润"],"ans":0,"explain":"垄断利润是垄断资本家凭借其在社会生产和流通中的垄断地位而获得的超过平均利润的高额利润。"},{"id":"mk15044-pl-P4803453","type":"sc","tier":"基础","conf":"adapt","chap":"第5-7章","q":"垄断价格包括（）。","opts":["A. 垄断高价和垄断低价","B. 成本价格和市场价格","C. 生产价格和销售价格","D. 批发价格和零售价格"],"ans":0,"explain":"垄断价格包括垄断高价和垄断低价两种形式。"},{"id":"mk15044-pl-P4803454","type":"sc","tier":"基础","conf":"adapt","chap":"第5-7章","q":"国家垄断资本主义是（）融合在一起的垄断资本主义。","opts":["A. 国家政权和私人垄断资本","B. 国家政权和产业资本","C. 国家政权和商业资本","D. 国家政权和金融资本"],"ans":0,"explain":"国家垄断资本主义是国家政权和私人垄断资本融合在一起的垄断资本主义。"},{"id":"mk15044-pl-P4803455","type":"sc","tier":"基础","conf":"adapt","chap":"第5-7章","q":"国家垄断资本主义产生的标志是（）。","opts":["A. 第一次世界大战期间资本主义交战国加强国家对经济的统治和管理","B. 1929-1933年经济危机后罗斯福实施“新政”","C. 凯恩斯《就业、利息和货币通论》的出版","D. 第二次世界大战后国家垄断资本主义在发达资本主义国家的普遍发展"],"ans":0,"explain":"第一次世界大战期间，资本主义交战国普遍加强了国家对社会经济和人民生活的统治和管理，国家垄断资本主义由此得以产生。"},{"id":"mk15044-pl-P4803456","type":"sc","tier":"基础","conf":"adapt","chap":"第5-7章","q":"国家垄断资本主义的主要形式不包括（）。","opts":["A. 国家所有并直接经营企业","B. 国家与私人共有、合营企业","C. 国家对企业的完全控制","D. 宏观调节"],"ans":2,"explain":"国家垄断资本主义的主要形式有国家所有并直接经营企业、国家与私人共有合营企业、国家参与私人垄断资本的再生产过程、宏观调节、微观规制，不包括国家对企业的完全控制。"},{"id":"mk15044-pl-P4803457","type":"sc","tier":"基础","conf":"adapt","chap":"第5-7章","q":"金融自由化与金融创新是（）得以形成和壮大的重要制度条件。","opts":["A. 产业资本","B. 商业资本","C. 金融垄断资本","D. 国家资本"],"ans":2,"explain":"金融自由化与金融创新是金融垄断资本得以形成和壮大的重要制度条件。"},{"id":"mk15044-pl-P4803458","type":"sc","tier":"基础","conf":"adapt","chap":"第5-7章","q":"垄断资本向世界范围扩展的基本形式不包括（）。","opts":["A. 商品资本输出","B. 借贷资本输出","C. 生产资本输出","D. 技术资本输出"],"ans":3,"explain":"垄断资本向世界范围扩展的基本形式有借贷资本输出、生产资本输出、商品资本输出，不包括技术资本输出。"},{"id":"mk15044-pl-P4803459","type":"sc","tier":"基础","conf":"adapt","chap":"第5-7章","q":"垄断资本向世界范围扩展的主要经济动因不包括（）。","opts":["A. 将国内过剩的资本输出，以便在国外谋求高额利润","B. 争夺世界霸权","C. 争夺商品销售市场","D. 确保原材料和能源的可靠来源"],"ans":1,"explain":"垄断资本向世界范围扩展的主要经济动因有将国内过剩的资本输出、将部分非要害的技术转移到国外、争夺商品销售市场、确保原材料和能源的可靠来源，不包括争夺世界霸权。"},{"id":"mk15044-pl-P4803460","type":"sc","tier":"基础","conf":"adapt","chap":"第5-7章","q":"经济全球化的表现不包括（）。","opts":["A. 生产全球化","B. 贸易全球化","C. 文化全球化","D. 金融全球化"],"ans":2,"explain":"经济全球化的表现有生产全球化、贸易全球化、金融全球化，不包括文化全球化。"},{"id":"mk15044-pl-P4803461","type":"sc","tier":"基础","conf":"adapt","chap":"第5-7章","q":"导致经济全球化迅猛发展的因素不包括（）。","opts":["A. 科学技术的进步和生产力的发展","B. 跨国公司的发展","C. 各国经济体制的变革和国际经济组织的发展","D. 人口的增长"],"ans":3,"explain":"导致经济全球化迅猛发展的因素有科学技术的进步和生产力的发展、跨国公司的发展、各国经济体制的变革和国际经济组织的发展，不包括人口的增长。"},{"id":"mk15044-pl-P4803462","type":"sc","tier":"基础","conf":"adapt","chap":"第5-7章","q":"第二次世界大战后，资本主义生产资料所有制发生的新变化是（）。","opts":["A. 私人资本所有制占主导地位","B. 私人股份资本所有制取代私人资本所有制","C. 国家资本所有制形成并发挥重要作用，法人资本所有制崛起并成为居主导地位的资本所有制形式","D. 个体资本所有制占主导地位"],"ans":2,"explain":"第二次世界大战后，资本主义生产资料所有制的新变化是国家资本所有制形成并发挥重要作用，法人资本所有制崛起并成为居主导地位的资本所有制形式。"},{"id":"mk15044-pl-P4803463","type":"sc","tier":"基础","conf":"adapt","chap":"第5-7章","q":"在资本主义发展初期，占主导地位的所有制形式是（）。","opts":["A. 私人股份资本所有制","B. 国家资本所有制","C. 私人资本所有制","D. 法人资本所有制"],"ans":2,"explain":"在资本主义发展初期，私人资本所有制是占主导地位的所有制形式。"},{"id":"mk15044-pl-P4803464","type":"sc","tier":"基础","conf":"adapt","chap":"第5-7章","q":"第二次世界大战后，发达资本主义国家为缓和矛盾建立并实施了（）。","opts":["A. 社会福利制度","B. 计划经济制度","C. 国有化制度","D. 自由市场经济制度"],"ans":0,"explain":"第二次世界大战后，发达资本主义国家为缓和矛盾建立并实施了普及化、全民化的社会福利制度。"},{"id":"mk15044-pl-P4803465","type":"sc","tier":"基础","conf":"adapt","chap":"第5-7章","q":"当代资本主义社会阶层和阶级结构变化中，大公司经营活动的实际控制者是（）。","opts":["A. 资本家","B. 高级职业经理","C. 普通工人","D. 政府官员"],"ans":1,"explain":"当代资本主义社会中，高级职业经理成为大公司经营活动的实际控制者。"},{"id":"mk15044-pl-P4803466","type":"sc","tier":"基础","conf":"adapt","chap":"第5-7章","q":"第二次世界大战后，资本主义国家经济调节机制的变化是（）。","opts":["A. 完全由市场机制主导","B. 开始对经济进行全面干预","C. 放弃政府干预","D. 只进行微观规制"],"ans":1,"explain":"第二次世界大战后，资本主义国家在继续发挥市场机制主导性作用的同时，开始对经济进行全面干预。"},{"id":"mk15044-pl-P4803467","type":"sc","tier":"基础","conf":"adapt","chap":"第5-7章","q":"第二次世界大战后，资本主义政治制度出现的变化是（）。","opts":["A. 政治制度单一化","B. 公民权利缩小","C. 加强法治建设","D. 取消政党制度"],"ans":2,"explain":"第二次世界大战后，资本主义国家普遍加强了法治建设。"},{"id":"mk15044-pl-P4803468","type":"sc","tier":"基础","conf":"adapt","chap":"第5-7章","q":"第二次世界大战后，资本主义发生变化的根本推动力量是（）。","opts":["A. 工人阶级争取自身权利和利益的斗争","B. 社会主义制度初步显示的优越性","C. 科学技术革命和生产力的发展","D. 主张改良主义的政党对资本主义制度的改革"],"ans":2,"explain":"科学技术革命和生产力的发展是资本主义发生变化的根本推动力量。"},{"id":"mk15044-pl-P4803469","type":"sc","tier":"基础","conf":"adapt","chap":"第5-7章","q":"当代资本主义变化的新特征不包括（）。","opts":["A. 科技创新加速资本主义生产方式变化","B. 国际金融垄断资本主义影响日益显现","C. 社会阶级层级结构呈现简单化","D. 发达资本主义国家推行霸权主义和强权政治"],"ans":2,"explain":"当代资本主义变化的新特征包括科技创新加速资本主义生产方式变化、国际金融垄断资本主义影响日益显现、社会阶级层级结构呈现复杂性多样化、发达资本主义国家推行霸权主义和强权政治，不包括社会阶级层级结构呈现简单化。"},{"id":"mk15044-pl-P4803470","type":"sc","tier":"基础","conf":"adapt","chap":"第5-7章","q":"在当代资本主义社会，资产阶级内部层级结构中最高层是（）。","opts":["A. 一般资产阶级阶层","B. 产业垄断资本家阶层","C. 国际金融一产业垄断寡头阶层","D. 国际金融垄断寡头阶层"],"ans":3,"explain":"当代资本主义社会中，资产阶级内部层级结构最高层是极少数国际金融垄断寡头阶层。"},{"id":"mk15044-pl-P4803471","type":"sc","tier":"基础","conf":"adapt","chap":"第5-7章","q":"21世纪以来，发达资本主义国家利用知识产权和信息技术垄断，构建（）。","opts":["A. 文化帝国主义","B. 信息帝国主义和数字帝国主义","C. 经济帝国主义","D. 军事帝国主义"],"ans":1,"explain":"21世纪以来，发达资本主义国家利用知识产权和信息技术垄断，构建“信息帝国主义”和“数字帝国主义”。"},{"id":"mk15044-pl-P4803472","type":"sc","tier":"基础","conf":"adapt","chap":"第5-7章","q":"资本主义显示巨大历史进步性的原因不包括（）。","opts":["A. 将科学技术转变为强大的生产力","B. 资本追求剩余价值的内在动力和竞争的外在压力推动社会生产力发展","C. 资本主义的意识形态和政治制度促进社会生产力发展","D. 资本主义没有基本矛盾"],"ans":3,"explain":"资本主义有基本矛盾，即生产社会化与生产资料资本主义私人占有之间的矛盾，这是其局限性的体现，不是显示历史进步性的原因。A、B、C选项均是资本主义显示巨大历史进步性的原因。"},{"id":"mk15044-pl-P4803473","type":"sc","tier":"基础","conf":"adapt","chap":"第5-7章","q":"资本主义的基本矛盾是（）。","opts":["A. 无产阶级和资产阶级的矛盾","B. 生产无限扩大的趋势与劳动人民有支付能力的需求相对缩小的矛盾","C. 生产社会化与生产资料资本主义私人占有之间的矛盾","D. 个别企业生产的有组织性和整个社会生产的无政府状态之间的矛盾"],"ans":2,"explain":"资本主义的基本矛盾是生产社会化与生产资料资本主义私人占有之间的矛盾。"},{"id":"mk15044-pl-P4803474","type":"sc","tier":"基础","conf":"adapt","chap":"第5-7章","q":"资本主义为社会主义所代替的历史必然性不包括（）。","opts":["A. 资本主义基本矛盾包含着现代的一切冲突的萌芽","B. 资本积累推动资本主义基本矛盾不断激化并最终否定资本主义自身","C. 国家垄断资本主义是资本社会化的更低形式","D. 资本主义社会存在着资产阶级和无产阶级两大阶级之间的矛盾和斗争"],"ans":2,"explain":"国家垄断资本主义是资本社会化的更高形式，将成为社会主义的前奏，C选项错误。A、B、D选项均是资本主义为社会主义所代替的历史必然性的体现。"},{"id":"mk15044-pl-P4803475","type":"sc","tier":"基础","conf":"adapt","chap":"第5-7章","q":"资本积累的客观历史趋势是（）。","opts":["A. 资本主义制度不断巩固","B. 资本主义基本矛盾得到解决","C. 公有制取代私有制、社会主义取代资本主义","D. 社会财富越来越集中在少数人手中"],"ans":2,"explain":"资本积累过程中，当资本主义基本矛盾及其派生的各种矛盾不断发展，资本主义生产关系不再适应生产力状况时，公有制取代私有制、社会主义取代资本主义就将成为不可避免的结果，这是资本积累的客观历史趋势。"},{"id":"mk15044-pl-P4803476","type":"sc","tier":"基础","conf":"adapt","chap":"第5-7章","q":"马克思认为，资本主义的股份企业（）。","opts":["A. 是纯粹的资本主义企业，没有任何进步意义","B. 应当被看做是由资本主义生产方式转化为联合的生产方式的过渡形式","C. 会阻碍生产力的发展","D. 与社会主义生产方式没有任何联系"],"ans":1,"explain":"马克思指出“资本主义的股份企业，也和合作工厂一样，应当被看做是由资本主义生产方式转化为联合的生产方式的过渡形式”。"},{"id":"mk15044-pl-P4803477","type":"sc","tier":"基础","conf":"adapt","chap":"第5-7章","q":"空想社会主义产生的时间是（）。","opts":["A. 16世纪初期","B. 18世纪中期","C. 19世纪初期","D. 20世纪初期"],"ans":0,"explain":"空想社会主义产生于16世纪初期，到19世纪上半叶达到顶峰。"},{"id":"mk15044-pl-P4803478","type":"sc","tier":"基础","conf":"adapt","chap":"第5-7章","q":"空想社会主义的开山之作是（）。","opts":["A. 《太阳城》","B. 《自然法典》","C. 《乌托邦》","D. 《论法制或法律的原则》"],"ans":2,"explain":"空想社会主义的开山之作是1516年英国人托马斯・莫尔所著的《乌托邦》一书。"},{"id":"mk15044-pl-P4803479","type":"sc","tier":"基础","conf":"adapt","chap":"第5-7章","q":"社会主义从空想到科学的飞跃，奠定理论基础的是（）。","opts":["A. 唯物史观和剩余价值学说","B. 辩证法和唯物论","C. 劳动价值论和剩余价值学说","D. 唯物史观和阶级斗争学说"],"ans":0,"explain":"马克思、恩格斯创立和发展的唯物史观和剩余价值学说，为实现社会主义从空想到科学的飞跃奠定了坚实的理论基础。"},{"id":"mk15044-pl-P4803480","type":"sc","tier":"基础","conf":"adapt","chap":"第5-7章","q":"标志着第一国际诞生的是（）。","opts":["A. 1848年欧洲革命","B. 1864年国际工人协会的成立","C. 1871年巴黎公社革命","D. 1889年国际社会主义者代表大会的召开"],"ans":1,"explain":"1864年，国际工人协会（第一国际）应运而生，标志着第一国际诞生。"},{"id":"mk15044-pl-P4803481","type":"sc","tier":"基础","conf":"adapt","chap":"第5-7章","q":"巴黎公社是（）。","opts":["A. 无产阶级夺取政权的第一次伟大尝试","B. 社会主义从理想到现实的飞跃","C. 第一个社会主义国家的建立标志","D. 国际工人运动的高潮"],"ans":0,"explain":"1871年爆发的巴黎公社革命，是无产阶级夺取政权的第一次伟大尝试。"},{"id":"mk15044-pl-P4803482","type":"sc","tier":"基础","conf":"adapt","chap":"第5-7章","q":"列宁认为社会主义可能首先在少数甚至在单独一个资本主义国家内获得胜利，其依据是（）。","opts":["A. 资本主义经济政治发展不平衡规律","B. 无产阶级革命的主观条件已经成熟","C. 社会主义在多国同时胜利的理论已经过时","D. 无产阶级与资产阶级的矛盾尖锐化"],"ans":0,"explain":"列宁根据资本主义经济和政治发展的不平衡规律，得出社会主义可能首先在少数甚至在单独一个资本主义国家内获得胜利的结论。"},{"id":"mk15044-pl-P4803483","type":"sc","tier":"基础","conf":"adapt","chap":"第5-7章","q":"俄国十月革命开辟了人类历史新纪元，主要是因为（）。","opts":["A. 建立了世界上第一个无产阶级政权","B. 推动了世界无产阶级革命运动","C. 推翻了沙皇专制统治","D. 建立了世界上第一个社会主义国家"],"ans":3,"explain":"十月革命建立起世界上第一个人民当家作主的社会主义国家，打破了资本主义的一统天下，开辟了人类历史新纪元。"},{"id":"mk15044-pl-P4803484","type":"sc","tier":"基础","conf":"adapt","chap":"第5-7章","q":"中国共产党诞生的时间是（）。","opts":["A. 1919年","B. 1921年","C. 1949年","D. 1956年"],"ans":1,"explain":"1921年7月，中国共产党应运而生。"},{"id":"mk15044-pl-P4803485","type":"sc","tier":"基础","conf":"adapt","chap":"第5-7章","q":"中国进入改革开放和社会主义现代化建设新时期的标志是（）。","opts":["A. 中华人民共和国的成立","B. 社会主义改造的完成","C. 党的十一届三中全会的召开","D. 党的十四大的召开"],"ans":2,"explain":"1978年12月，党的十一届三中全会召开，开启了改革开放和社会主义现代化建设新时期。"},{"id":"mk15044-pl-P4803486","type":"sc","tier":"基础","conf":"adapt","chap":"第5-7章","q":"科学社会主义诞生的标志是（）。","opts":["A. 《共产党宣言》的发表","B. 第一国际的成立","C. 巴黎公社的建立","D. 十月革命的胜利"],"ans":0,"explain":"《共产党宣言》的发表，标志着科学社会主义的诞生。"},{"id":"mk15044-pl-P4803487","type":"sc","tier":"基础","conf":"adapt","chap":"第5-7章","q":"科学社会主义的核心命题是（）。","opts":["A. 无产阶级是最先进最革命的阶级","B. 无产阶级革命是无产阶级进行斗争的最高形式","C. 资本主义必然灭亡，社会主义必然胜利","D. 要在生产资料公有制基础上组织生产"],"ans":2,"explain":"“资本主义必然灭亡，社会主义必然胜利”是科学社会主义的核心命题。"},{"id":"mk15044-pl-P4803488","type":"sc","tier":"基础","conf":"adapt","chap":"第5-7章","q":"社会主义经济制度的根基是（）。","opts":["A. 生产资料公有制","B. 按劳分配","C. 社会主义市场经济体制","D. 多种所有制经济共同发展"],"ans":0,"explain":"生产资料公有制是社会主义经济制度的根基。"},{"id":"mk15044-pl-P4803489","type":"sc","tier":"基础","conf":"adapt","chap":"第5-7章","q":"社会主义民主政治的本质特征是（）。","opts":["A. 人民当家作主","B. 无产阶级专政","C. 民主集中制","D. 政治协商制度"],"ans":0,"explain":"人民当家作主是社会主义民主政治的本质特征。"},{"id":"mk15044-pl-P4803490","type":"sc","tier":"基础","conf":"adapt","chap":"第5-7章","q":"社会主义社会生产的根本目的是（）。","opts":["A. 满足全体社会成员的需要","B. 实现共同富裕","C. 发展生产力","D. 消灭剥削"],"ans":0,"explain":"社会主义社会生产的根本目的是满足全体社会成员的需要。"},{"id":"mk15044-pl-P4803491","type":"sc","tier":"基础","conf":"adapt","chap":"第5-7章","q":"在社会主义国家，立党立国、兴党兴国的根本指导思想是（）。","opts":["A. 马克思主义","B. 毛泽东思想","C. 邓小平理论","D. 习近平新时代中国特色社会主义思想"],"ans":0,"explain":"在社会主义国家，马克思主义是立党立国、兴党兴国的根本指导思想。"},{"id":"mk15044-pl-P4803492","type":"sc","tier":"基础","conf":"adapt","chap":"第5-7章","q":"社会主义社会个人消费品分配的原则是（）。","opts":["A. 按需分配","B. 按劳分配","C. 按资分配","D. 平均分配"],"ans":1,"explain":"社会主义社会实行按劳分配的制度。"},{"id":"mk15044-pl-P4803493","type":"sc","tier":"基础","conf":"adapt","chap":"第5-7章","q":"社会主义社会要实现人与自然的（）。","opts":["A. 和谐共生","B. 征服与被征服关系","C. 相互对立","D. 互不干涉"],"ans":0,"explain":"社会主义社会要实现人与自然的和谐共生。"},{"id":"mk15044-pl-P4803494","type":"sc","tier":"基础","conf":"adapt","chap":"第5-7章","q":"无产阶级政党的组织原则是（）。","opts":["A. 民主制","B. 集中制","C. 民主集中制","D. 议会制"],"ans":2,"explain":"无产阶级政党实行民主集中制的组织原则。"},{"id":"mk15044-pl-P4803495","type":"sc","tier":"基础","conf":"adapt","chap":"第5-7章","q":"社会主义的本质特征和优越性的突出体现是（）。","opts":["A. 解放和发展生产力","B. 共同富裕","C. 消灭剥削","D. 消除两极分化"],"ans":1,"explain":"共同富裕是社会主义的一个本质特征，也是社会主义优越性的突出体现。"},{"id":"mk15044-pl-P4803496","type":"sc","tier":"基础","conf":"adapt","chap":"第5-7章","q":"共产主义社会的物质财富分配方式是（）。","opts":["A. 按劳分配","B. 按需分配","C. 按资分配","D. 平均分配"],"ans":1,"explain":"在共产主义社会，消费资料按需分配。"},{"id":"mk15044-pl-P4803497","type":"sc","tier":"基础","conf":"adapt","chap":"第5-7章","q":"经济文化相对落后的国家建设社会主义，具有历史长期性，其原因不包括（）。","opts":["A. 生产力发展状况的制约","B. 经济基础和上层建筑发展状况的制约","C. 国际环境的严峻挑战","D. 社会主义制度的优越性"],"ans":3,"explain":"社会主义制度的优越性不是经济文化相对落后国家建设社会主义具有历史长期性的原因。A、B、C选项都是其建设具有历史长期性的原因。"},{"id":"mk15044-pl-P4803498","type":"sc","tier":"基础","conf":"adapt","chap":"第5-7章","q":"造成社会主义发展道路多样性的现实原因是（）。","opts":["A. 各个国家的生产力发展状况和社会发展阶段不同","B. 历史文化传统的差异性","C. 时代和实践的不断发展","D. 无产阶级政党自身成熟程度的不同"],"ans":2,"explain":"时代和实践的不断发展，是造成社会主义发展道路多样性的现实原因。A、B、D选项也是社会主义发展道路多样性的原因，但不符合“现实原因”的要求。"},{"id":"mk15044-pl-P4803499","type":"sc","tier":"基础","conf":"adapt","chap":"第5-7章","q":"探索社会主义发展道路，必须坚持对待马克思主义的科学态度，最重要的是（）。","opts":["A. 背诵和重复马克思主义的具体结论和词句","B. 坚持马克思主义对于研究未来社会制度的科学方法","C. 坚持马克思主义的所有观点","D. 将马克思主义当作一成不变的教条"],"ans":1,"explain":"以科学的态度对待马克思主义，最重要的是坚持马克思主义对于研究未来社会制度的科学方法。A、C、D选项都是错误对待马克思主义的做法。"},{"id":"mk15044-pl-P4803545","type":"sa","tier":"创新","conf":"adapt","chap":"第5-7章","q":"论述垄断资本主义的实质，并结合实际案例说明垄断资本是如何获取高额垄断利润的。","opts":[],"ans":null,"explain":"垄断资本主义的实质是理解垄断资本主义的核心，结合实际案例能更直观地认识垄断资本获取高额垄断利润的手段和方式，这些在教材中有理论阐述，实际案例可帮助加深对理论的理解。\n垄断资本主义的实质是垄断资本凭借垄断地位，获取高额垄断利润。为了获取高额垄断利润，垄断资本对内通过“参与制”和同政府的“个人联合”谋求从经济到政治对整个国家的统治；对外运用经济、政治甚至战争的手段进行扩张，谋求对整个世界经济和政治的控制。例如，某大型跨国科技公司，在全球范围内拥有众多子公司和分支机构，通过掌握核心技术和大量专利，在行业内形成了垄断地位。它利用“参与制”，通过持有其他相关企业的股票，控制了产业链上下游的许多企业，实现对生产、销售等环节的把控。在国内，它与政府官员建立密切联系，影响政府的科技政策和产业政策，为自身发展创造有利条件。在国际上，它凭借技术优势，通过垄断高价销售产品，将产品价格定得远高于其价值，获取高额利润。同时，它还通过并购等手段，打压新兴竞争对手，巩固自己的垄断地位，进一步确保垄断利润的获取。从全球范围看，一些石油垄断企业，通过控制石油资源和国际石油市场，利用垄断高价和垄断低价，一方面以高价出售石油产品，另一方面以低价购买生产资料，从全球消费者和其他企业手中获取巨额垄断利润。它们还通过政治游说等手段，影响石油生产国和消费国的政策，保障自身的利益。这些都体现了垄断资本获取高额垄断利润的方式和垄断资本主义的扩张本性。"},{"id":"mk15044-pl-P4803546","type":"sa","tier":"创新","conf":"adapt","chap":"第5-7章","q":"论述当代资本主义新变化的表现、原因及实质，并分析这些变化对资本主义未来发展趋势的影响。","opts":[],"ans":null,"explain":"当代资本主义新变化是研究资本主义发展的重要内容，对其表现、原因、实质和影响的分析，有助于把握资本主义的发展脉络和未来走向，教材对这些方面有详细的分析和论述。\n当代资本主义新变化的表现：①生产资料所有制变化，国家资本所有制形成并发挥重要作用，法人资本所有制崛起并成为居主导地位的资本所有制形式；②劳资关系和分配关系变化，采取缓和劳资关系的激励制度，建立社会福利制度，劳动者工资水平有所提高；③社会阶层和阶级结构变化，资本家地位和作用改变，高级职业经理成为大公司经营活动的实际控制者，知识型和服务型劳动者数量增加，劳动方式发生变化；④经济调节机制和经济危机形态变化，国家对经济全面干预后又强化市场调节、弱化政府干预，经济危机呈现新特点；⑤政治制度变化，政治制度多元化，公民权利扩大，加强法治建设，改良主义政党影响扩大。变化的原因：①科学技术革命和生产力的发展是根本推动力量；②工人阶级争取自身权利和利益的斗争是重要力量；③社会主义制度初步显示的优越性对资本主义产生重要影响；④主张改良主义的政党对资本主义制度的改革起到重要作用。变化的实质：从根本上说是人类社会发展一般规律和资本主义经济规律作用的结果，是在资本主义制度基本框架内的变化，并不意味着资本主义生产关系的根本性质发生了变化。生产资料私有制依然是基本经济制度，雇佣劳动制度依然存在，资本追逐剩余价值的本性未变，社会福利制度未改变财富占有两极分化的制度基础，政治制度本质未变。对未来发展趋势的影响：这些变化在一定程度上缓解了资本主义的矛盾，为资本主义的发展提供了一定空间，但无法从根本上解决资本主义的基本矛盾。随着矛盾的积累，资本主义经济危机仍会爆发，社会矛盾会进一步激化。例如，经济调节机制的变化导致经济危机呈现新特点，贫富差距扩大等问题加剧社会矛盾。从长远看，资本主义必然走向灭亡，社会主义取代资本主义的历史趋势不会改变，只是这一过程会充满曲折。"},{"id":"mk15044-pl-P4803547","type":"sa","tier":"创新","conf":"adapt","chap":"第5-7章","q":"论述资本主义为社会主义所代替的历史必然性，并结合当前世界形势，谈谈你对这一趋势的认识。","opts":[],"ans":null,"explain":"资本主义为社会主义所代替的历史必然性是马克思主义政治经济学的重要观点，结合当前世界形势分析这一趋势，能更深刻地理解其科学性和现实意义，教材为这一论述提供了理论基础。\n资本主义为社会主义所代替具有历史必然性，原因如下：①资本主义基本矛盾“包含着现代的一切冲突的萌芽”，其表现在阶级关系上是无产阶级和资产阶级的对立，表现在生产上是个别企业生产的有组织性和整个社会生产的无政府状态之间的对立，经济危机的爆发就是基本矛盾发展的结果，只有用社会主义生产方式才能根本解决这一矛盾；②资本积累推动资本主义基本矛盾不断激化并最终否定资本主义自身，资本积累使生产规模扩大、生产社会化程度提高，客观上导致生产集中和资本集中，使资本的社会化占有成为可能，当资本主义生产关系不再适应生产力状况时，社会主义取代资本主义将不可避免；③国家垄断资本主义是资本社会化的更高形式，将成为社会主义的前奏，国家垄断资本主义使生产社会化、资本社会化和管理社会化达到更高程度，为全社会共同占有生产资料和共同组织社会化生产准备了充分的物质条件和社会条件；④资本主义社会存在着资产阶级和无产阶级两大阶级之间的矛盾和斗争，随着资本主义经济发展，无产阶级队伍壮大，在自己的政党领导下，必将推翻资本主义和资产阶级的统治。结合当前世界形势，虽然资本主义通过自我调节还能为生产力发展提供一定空间，但资本主义的基本矛盾依然存在且不断加深。例如，2008年国际金融危机暴露出资本主义金融体系的弊端，经济不平等、社会矛盾激化等问题日益严重。同时，社会主义国家在经济、社会发展方面取得了显著成就，展示了社会主义制度的优越性。这都表明资本主义为社会主义所代替是历史发展的必然趋势，尽管这一过程会面临诸多挑战和曲折，但从人类社会发展的长河看，社会主义取代资本主义的趋势不可阻挡。"},{"id":"mk15044-pl-P4803215","type":"sc","tier":"基础","conf":"adapt","chap":"第1章","q":"马克思主义是由马克思、恩格斯创立并为后继者所不断发展的科学理论体系，关于马克思主义，下列说法正确的是（）","opts":["A. 是关于自然、社会和人类思维发展特殊规律的学说","B. 是关于社会主义可能代替资本主义、最终实现共产主义的学说","C. 是关于无产阶级解放、全人类解放和每个人自由而全面发展的学说","D. 是关于未来社会具体制度构建的学说"],"ans":2,"explain":"马克思主义是关于自然、社会和人类思维发展一般规律的学说，是关于社会主义必然代替资本主义、最终实现共产主义的学说，是关于无产阶级解放、全人类解放和每个人自由而全面发展的学说，A、B、D选项错误，C选项正确。"},{"id":"mk15044-pl-P4803216","type":"sc","tier":"基础","conf":"adapt","chap":"第1章","q":"马克思主义的三个基本组成部分是（）","opts":["A. 马克思主义哲学、马克思主义政治学、马克思主义政治经济学","B. 马克思主义哲学、马克思主义政治经济学、科学社会主义","C. 马克思主义哲学、马克思主义社会学、科学社会主义","D. 马克思主义政治学、马克思主义政治经济学、科学社会主义"],"ans":1,"explain":"马克思主义哲学、马克思主义政治经济学和科学社会主义是其三个基本组成部分，它们共同构成马克思主义理论体系的主体内容，所以B选项正确。"},{"id":"mk15044-pl-P4803217","type":"sc","tier":"基础","conf":"adapt","chap":"第1章","q":"马克思主义基本原理是对马克思主义立场、观点、方法的集中概括，其中马克思主义观察、分析和解决问题的根本立足点和出发点是（）","opts":["A. 基本立场","B. 基本观点","C. 基本方法","D. 基本理论"],"ans":0,"explain":"马克思主义的基本立场是马克思主义观察、分析和解决问题的根本立足点和出发点，所以A选项正确。"},{"id":"mk15044-pl-P4803218","type":"sc","tier":"基础","conf":"adapt","chap":"第1章","q":"19世纪自然科学的三大发现为马克思主义的产生提供了自然科学前提，这三大发现不包括（）","opts":["A. 细胞学说","B. 能量守恒与转化定律","C. 量子学理论","D. 生物进化论"],"ans":2,"explain":"19世纪的三大科学发现是细胞学说、能量守恒与转化定律、生物进化论，不包括量子学理论，所以C选项正确。"},{"id":"mk15044-pl-P4803219","type":"sc","tier":"基础","conf":"adapt","chap":"第1章","q":"马克思主义产生于（）","opts":["A. 19世纪20年代","B. 19世纪40年代","C. 19世纪60年代","D. 19世纪80年代"],"ans":1,"explain":"马克思主义产生于19世纪40年代，所以B选项正确。"},{"id":"mk15044-pl-P4803220","type":"sc","tier":"基础","conf":"adapt","chap":"第1章","q":"马克思主义的创始人是（）","opts":["A. 马克思和李嘉图","B. 马克思和圣西门","C. 马克思和费尔巴哈","D. 马克思和恩格斯"],"ans":3,"explain":"马克思主义的创始人是马克思和恩格斯，所以D选项正确。"},{"id":"mk15044-pl-P4803221","type":"sc","tier":"基础","conf":"adapt","chap":"第1章","q":"作为马克思主义哲学直接理论来源的是（）","opts":["A. 古希腊罗马哲学","B. 英国近代哲学","C. 法国百科全书派哲学","D. 德国古典哲学"],"ans":3,"explain":"马克思主义的直接理论来源包括德国古典哲学、英国古典政治经济学、19世纪的英法两国的空想社会主义学说，其中德国古典哲学是马克思主义哲学的直接理论来源，所以D选项正确。"},{"id":"mk15044-pl-P4803222","type":"sc","tier":"基础","conf":"adapt","chap":"第1章","q":"英国古典经济学的代表人物是（）","opts":["A. 培根和洛克","B. 黑格尔和费尔巴哈","C. 斯密和李嘉图","D. 圣西门和傅立叶"],"ans":2,"explain":"英国古典经济学的代表人物有威廉・配第、亚当・斯密、大卫・李嘉图，C选项符合。"},{"id":"mk15044-pl-P4803223","type":"sc","tier":"基础","conf":"adapt","chap":"第1章","q":"19世纪初欧洲空想社会主义者不包括（）","opts":["A. 黑格尔","B. 圣西门","C. 傅立叶","D. 欧文"],"ans":0,"explain":"空想社会主义的代表人物是圣西门、傅立叶、欧文，黑格尔不属于空想社会主义者，所以A选项正确。"},{"id":"mk15044-pl-P4803224","type":"sc","tier":"基础","conf":"adapt","chap":"第1章","q":"马克思主义产生的阶级基础是（）","opts":["A. 19世纪30-40年代，法国、英国、德国工人运动的兴起","B. 19世纪70年代，资本主义从自由竞争阶段进入垄断阶段","C. 俄国十月革命的胜利","D. 中国新民主主义革命的胜利"],"ans":0,"explain":"19世纪30-40年代，法国、英国、德国接连爆发无产阶级反对资本主义制度的斗争，标志着现代无产阶级作为独立的政治力量登上历史舞台，这成为马克思主义产生的阶级基础，A选项正确。"},{"id":"mk15044-pl-P4803225","type":"sc","tier":"基础","conf":"adapt","chap":"第1章","q":"马克思主义具有鲜明的特征，其中作为马克思主义本质属性的是（）","opts":["A. 科学性","B. 人民性","C. 实践性","D. 发展性"],"ans":1,"explain":"人民性是马克思主义的本质属性，马克思主义植根人民之中，是来自人民、为了人民、造福人民的理论。"},{"id":"mk15044-pl-P4803226","type":"sc","tier":"基础","conf":"adapt","chap":"第1章","q":"马克思主义被称为科学的理论，其科学性体现在多个方面，其中马克思主义科学性的重要体现是（）","opts":["A. 以事实为依据","B. 以规律为对象","C. 具有科学的世界观和方法论基础","D. 以实践为检验标准"],"ans":2,"explain":"马克思主义具有科学的世界观和方法论基础，即辩证唯物主义和历史唯物主义，这是马克思主义科学性的重要体现。"},{"id":"mk15044-pl-P4803227","type":"sc","tier":"基础","conf":"adapt","chap":"第1章","q":"马克思主义认为，无产阶级解放和全人类解放是完全一致的，这体现了马克思主义的（）","opts":["A. 科学性","B. 人民性","C. 实践性","D. 发展性"],"ans":1,"explain":"马克思主义的人民性是以阶级性为深刻基础的，无产阶级解放和全人类解放的一致性体现了马克思主义的人民性，它代表了广大人民群众的根本利益。"},{"id":"mk15044-pl-P4803228","type":"sc","tier":"基础","conf":"adapt","chap":"第1章","q":"马克思指出“哲学家们只是用不同的方式解释世界，而问题在于改变世界”，这突出了马克思主义的（）","opts":["A. 科学性","B. 人民性","C. 实践性","D. 发展性"],"ans":2,"explain":"该句话强调马克思主义不是纯粹解释世界的学说，而是服务于改造世界的实践活动，突出了其实践性。"},{"id":"mk15044-pl-P4803229","type":"sc","tier":"基础","conf":"adapt","chap":"第1章","q":"马克思主义具有与时俱进的理论品质，这体现了马克思主义的（）","opts":["A. 科学性","B. 人民性","C. 实践性","D. 发展性"],"ans":3,"explain":"马克思主义随时代、实践和科学发展而不断发展，具有与时俱进的理论品质，这正是其发展性的体现。"},{"id":"mk15044-pl-P4803230","type":"sc","tier":"基础","conf":"adapt","chap":"第1章","q":"马克思主义在当今世界不但没有过时，而且日益焕发出旺盛的生命力，从根本上说，是因为它（）","opts":["A. 是科学的世界观和方法论","B. 能为人们提供解决问题的具体方法","C. 是马克思、恩格斯创立的","D. 具有鲜明的阶级性"],"ans":0,"explain":"马克思主义是科学的世界观和方法论，能够站在科学和时代的制高点上观察事物和现象，所以在当今世界仍具有强大生命力。"},{"id":"mk15044-pl-P4803231","type":"sc","tier":"基础","conf":"adapt","chap":"第1章","q":"学习马克思主义理论，有助于青年（）","opts":["A. 掌握具体的专业技能","B. 提高数学运算能力","C. 坚定理想信念，树立科学的世界观、人生观和价值观","D. 提升艺术鉴赏水平"],"ans":2,"explain":"学习马克思主义理论有助于青年坚定理想信念，树立科学的世界观、人生观和价值观，提高分析和解决问题的能力。"},{"id":"mk15044-pl-P4803232","type":"sc","tier":"基础","conf":"adapt","chap":"第1章","q":"哲学的基本问题是（）","opts":["A. 物质和运动的关系问题","B. 物质和意识的关系问题","C. 运动和静止的关系问题","D. 实践和理论的关系问题"],"ans":1,"explain":"明确提到“存在和思维的关系问题又称为物质和意识的关系问题，构成了全部哲学的基本问题”，所以答案选B。"},{"id":"mk15044-pl-P4803233","type":"sc","tier":"基础","conf":"adapt","chap":"第1章","q":"划分唯物主义和唯心主义的唯一标准是（）","opts":["A. 是否承认世界的统一性","B. 是否承认联系的普遍性","C. 是否承认物质第一性、意识第二性","D. 是否承认思维和存在具有同一性"],"ans":2,"explain":"、“对哲学基本问题中存在和思维、物质和意识谁为本原，即何者为第一性问题的不同回答，形成了唯物主义和唯心主义两种根本对立的哲学派别”，因此答案是C。"},{"id":"mk15044-pl-P4803234","type":"sc","tier":"基础","conf":"adapt","chap":"第1章","q":"认为水、火、土、气是世界的本源的哲学是（）","opts":["A. 朴素唯物主义","B. 形而上学唯物主义","C. 辩证唯物主义","D. 庸俗唯物主义"],"ans":0,"explain":"根据对古代朴素唯物主义的阐述，其用某一种或几种物质作为本原来解释世界，所以认为水、火、土、气是世界本源的哲学是朴素唯物主义，答案为A。"},{"id":"mk15044-pl-P4803235","type":"sc","tier":"基础","conf":"adapt","chap":"第1章","q":"形而上学唯物主义的局限性是（）","opts":["A. 简单性、机械性、教条性、僵化性","B. 片面性、直观性、表面性、庸俗性","C. 片面性、不彻底性、抽象性、外在性","D. 机械性、形而上学性、直观性、不彻底性"],"ans":3,"explain":"、近代形而上学唯物主义无法将唯物主义贯彻到历史领域，且存在机械、直观等问题，即具有机械性、形而上学性、直观性、不彻底性，答案选D。"},{"id":"mk15044-pl-P4803236","type":"sc","tier":"基础","conf":"adapt","chap":"第1章","q":"时间是物质运动的（）","opts":["A. 持续性和顺序性","B. 广延性和伸张性","C. 绝对性和无限性","D. 普遍性和特殊性"],"ans":0,"explain":"“时间是指物质运动的持续性、顺序性，特点是一维性”，所以答案是A。"},{"id":"mk15044-pl-P4803237","type":"sc","tier":"基础","conf":"adapt","chap":"第1章","q":"空间是物质运动的（）","opts":["A. 持续性和顺序性","B. 广延性和伸张性","C. 绝对性和无限性","D. 普遍性和特殊性"],"ans":1,"explain":"“空间是指物质运动的广延性、伸张性，特点是三维性”，故答案为B。"},{"id":"mk15044-pl-P4803238","type":"sc","tier":"基础","conf":"adapt","chap":"第1章","q":"唯物辩证法认为，发展的实质是（）","opts":["A. 新事物的产生和旧事物的灭亡","B. 事物的一切运动变化","C. 事物根本性质的变化","D. 事物存在范围的扩大"],"ans":0,"explain":"“发展的实质是新事物的产生和旧事物的灭亡”，所以答案选A。"},{"id":"mk15044-pl-P4803239","type":"sc","tier":"基础","conf":"adapt","chap":"第1章","q":"“乘舟侧畔千帆过，病树前头万木春”“芳林新叶催陈叶，流水前波让后波”这两句诗包含的哲学道理是（）","opts":["A. 矛盾是事物发展的动力","B. 一切事物都是发展变化的","C. 事物的发展是量变和质变的统一","D. 新事物代替旧事物是事物发展的基本趋势"],"ans":3,"explain":"从发展的实质及新事物旧事物相关内容可知，这两句诗体现新事物代替旧事物是发展基本趋势，答案为D。"},{"id":"mk15044-pl-P4803240","type":"sc","tier":"基础","conf":"adapt","chap":"第1章","q":"下列各项中表明事物处于相对静止状态的是（）","opts":["A. 事物的量没有发生任何变化","B. 事物的质发生变化","C. 事物的量发生巨大的变化","D. 事物的质没有发生根本变化"],"ans":3,"explain":"相对静止包括事物的质没有发生根本变化和空间相对位置暂时不变两种状态，所以答案是D。"},{"id":"mk15044-pl-P4803241","type":"sc","tier":"基础","conf":"adapt","chap":"第1章","q":"下列观点属于客观唯心主义的是（）","opts":["A. 天地万物皆在吾心中","B. 存在就是被感知","C. 物是感觉的集合","D. 万物是“绝对精神”的体现"],"ans":3,"explain":"指出客观唯心主义把客观精神看作世界本原，“绝对精神”属于客观精神，所以答案选D，A、B、C选项属于主观唯心主义。"},{"id":"mk15044-pl-P4803242","type":"sc","tier":"基础","conf":"adapt","chap":"第1章","q":"辩证唯物主义认为，物质的唯一特性是（）","opts":["A. 广延性","B. 持续性","C. 客观实在性","D. 可知性"],"ans":2,"explain":"“物质是标志客观实在的哲学范畴，这种客观实在是人通过感觉感知的，它不依赖于我们的感觉而存在……”，说明物质唯一特性是客观实在性，答案为C。"},{"id":"mk15044-pl-P4803243","type":"sc","tier":"基础","conf":"adapt","chap":"第1章","q":"“绝对运动中包含着相对静止，相对静止中包含着绝对运动”，这是一种（）","opts":["A. 相对主义诡辩论的观点","B. 唯物辩证法的观点","C. 形而上学的观点","D. 客观唯心主义的观点"],"ans":1,"explain":"唯物辩证法认为运动是绝对的，静止是相对的，二者相互依存，所以这是唯物辩证法的观点，答案选B。"},{"id":"mk15044-pl-P4803244","type":"sc","tier":"基础","conf":"adapt","chap":"第1章","q":"哲学上的二元论否认（）","opts":["A. 世界的统一性","B. 世界的物质性","C. 世界的可知性","D. 世界的多样性"],"ans":0,"explain":"一元论承认世界的统一性，二元论与之相反，否认世界的统一性，答案为A。"},{"id":"mk15044-pl-P4803245","type":"sc","tier":"基础","conf":"adapt","chap":"第1章","q":"列宁的物质定义表明，客观实在性是（）","opts":["A. 生命物质的共性","B. 自然物质的共性","C. 有形物质的共性","D. 一切物质的共性"],"ans":3,"explain":"列宁对物质的定义体现出客观实在性是从自然存在和社会存在中抽象出的共同特性，即一切物质的共性，答案选D。"},{"id":"mk15044-pl-P4803246","type":"sc","tier":"基础","conf":"adapt","chap":"第1章","q":"运动和静止的关系属于（）","opts":["A. 本质和现象的关系","B. 内容和形式的关系","C. 量变和质变的关系","D. 绝对和相对的关系"],"ans":3,"explain":"运动是绝对的，静止是相对的，所以运动和静止是绝对和相对的关系，答案为D。"},{"id":"mk15044-pl-P4803247","type":"sc","tier":"基础","conf":"adapt","chap":"第1章","q":"既肯定物质的绝对运动又承认事物的相对静止，这是一种（）","opts":["A. 机械唯物主义观点","B. 折衷主义观点","C. 辩证唯物主义观点","D. 相对主义观点"],"ans":2,"explain":"辩证唯物主义承认物质绝对运动的同时也承认相对静止，所以这是辩证唯物主义观点，答案选C。"},{"id":"mk15044-pl-P4803248","type":"sc","tier":"基础","conf":"adapt","chap":"第1章","q":"对世界存在状态问题的不同回答所区分的哲学派别是（）","opts":["A. 可知论和不可知论","B. 反映论和先验论","C. 辩证法和形而上学","D. 唯物主义和唯心主义"],"ans":2,"explain":"对世界上万事万物是以联系、发展还是孤立、静止的状态存在这一问题的不同回答，区分出了辩证法和形而上学，答案为C。"},{"id":"mk15044-pl-P4803249","type":"sc","tier":"基础","conf":"adapt","chap":"第1章","q":"世界观是（）","opts":["A. 人们对整个世界的根本看法和观点","B. 人们对精神世界的根本看法和观点","C. 人们对物质世界的根本看法和观点","D. 人们对外部世界的根本看法和观点"],"ans":0,"explain":"世界观是人们对包括自然、社会和人类思维在内的整个世界的根本看法和根本观点，答案选A。"},{"id":"mk15044-pl-P4803250","type":"sc","tier":"基础","conf":"adapt","chap":"第1章","q":"“盛年不再来，一日难再晨”，这个谚语说的是（）","opts":["A. 时间具有一维性","B. 物质运动具有持续性","C. 时间具有有限性","D. 物质运动具有顺序性"],"ans":0,"explain":"时间的特点是一维性，即时间的流逝一去不复返，“盛年不再来，一日难再晨”体现了这一特性，答案为A。"},{"id":"mk15044-pl-P4803251","type":"sc","tier":"基础","conf":"adapt","chap":"第1章","q":"辩证法和形而上学的区别在于如何回答（）","opts":["A. 世界的本质是什么的问题","B. 世界可否被认识的问题","C. 世界的存在是怎样的问题","D. 世界有否统一性的问题"],"ans":2,"explain":"辩证法和形而上学的区别在于对世界存在状态问题的回答不同，答案选C。"},{"id":"mk15044-pl-P4803252","type":"sc","tier":"基础","conf":"adapt","chap":"第1章","q":"时间和空间既是绝对的、无限的，又是相对的、有限的。这是一种（）","opts":["A. 诡辩论的观点","B. 辩证唯物主义的观点","C. 实用主义的观点","D. 形而上学的观点"],"ans":1,"explain":"辩证唯物主义认为时间和空间是绝对和相对、无限和有限的统一，所以这是辩证唯物主义观点，答案为B。"},{"id":"mk15044-pl-P4803253","type":"sc","tier":"基础","conf":"adapt","chap":"第1章","q":"唯物主义与唯心主义的区别在于如何回答（）","opts":["A. 世界的本质是什么的问题","B. 世界可否被认识的问题","C. 世界的存在是怎样的问题","D. 世界有否统一性的问题"],"ans":0,"explain":"对哲学基本问题中物质和意识谁为本原问题的不同回答，区分了唯物主义和唯心主义，即二者区别在于对世界本质问题的回答，答案选A。"},{"id":"mk15044-pl-P4803254","type":"sc","tier":"基础","conf":"adapt","chap":"第1章","q":"唯物主义哲学发展所经历的第二种基本形态是（）","opts":["A. 朴素唯物主义","B. 辩证唯物主义","C. 形而上学唯物主义","D. 历史唯物主义"],"ans":2,"explain":"唯物主义的发展形态，第二种基本形态是近代形而上学唯物主义，答案为C。"},{"id":"mk15044-pl-P4803255","type":"sc","tier":"基础","conf":"adapt","chap":"第1章","q":"哲学基本问题第二方面内容主要回答的是（）","opts":["A. 世界的本质是什么的问题","B. 世界可否被认识的问题","C. 世界的存在是怎样的问题","D. 世界有否统一性的问题"],"ans":1,"explain":"哲学基本问题第二方面是思维和存在是否具有同一性的问题，即世界可不可以认识的问题，答案选B。"},{"id":"mk15044-pl-P4803256","type":"sc","tier":"基础","conf":"adapt","chap":"第1章","q":"下列各项属于一元论哲学思想的是（）","opts":["A. 世界万物是普遍联系的","B. 世界万物有一个共同的本质","C. 世界万物是可以认识的","D. 世界万物有多种多样的形态"],"ans":1,"explain":"一元论承认世界的统一性，即认为世界万物有一个共同的本质或本原，答案为B。"},{"id":"mk15044-pl-P4803257","type":"sc","tier":"基础","conf":"adapt","chap":"第1章","q":"可知论与不可知论的对立在于是否承认（）","opts":["A. 人的认识是先于经验而获得的","B. 思维能够正确地认识现实世界","C. 人的认识是从外部世界得来的","D. 思维能够能动地认识现实世界"],"ans":1,"explain":"对哲学基本问题第二方面思维能否正确认识存在问题的不同回答，区分了可知论和不可知论，答案选B。"},{"id":"mk15044-pl-P4803258","type":"sc","tier":"基础","conf":"adapt","chap":"第1章","q":"承认世界具有统一性的哲学就是（）","opts":["A. 唯物论","B. 辩证法","C. 一元论","D. 可知论"],"ans":2,"explain":"一元论承认世界的统一性，答案为C。"},{"id":"mk15044-pl-P4803259","type":"sc","tier":"基础","conf":"adapt","chap":"第1章","q":"世界上的一切事物都是运动的，一切运动都是物质的运动。这表明物质和运动（）","opts":["A. 不可分割","B. 不易区别","C. 完全对立","D. 绝对同一"],"ans":0,"explain":"物质和运动不可分割，运动是物质的固有属性，物质是运动的承担者，答案选A。"},{"id":"mk15044-pl-P4803260","type":"sc","tier":"基础","conf":"adapt","chap":"第1章","q":"下列观点中表述唯物辩证法总特征的是（）","opts":["A. 量变和质变的观点","B. 对立统一的观点","C. 联系和发展的观点","D. 辩证否定的观点"],"ans":2,"explain":"唯物辩证法的总特征是联系的观点和发展的观点，答案为C。"},{"id":"mk15044-pl-P4803261","type":"sc","tier":"基础","conf":"adapt","chap":"第1章","q":"质量互变规律揭示了（）","opts":["A. 事物发展的原因和结果","B. 事物发展的状态和形式","C. 事物发展的趋势和道路","D. 事物发展的源泉和动力"],"ans":1,"explain":"明确提到“量变质变规律揭示了事物发展的状态和形式”，事物的发展是量变与质变的统一，量变体现事物发展的渐进性，质变体现事物发展的飞跃性，二者相互转化、相互渗透，共同构成事物发展的状态和形式，所以答案选B。"},{"id":"mk15044-pl-P4803262","type":"sc","tier":"基础","conf":"adapt","chap":"第1章","q":"唯物辩证法提供的最根本的认识方法是（）","opts":["A. 逻辑分析法","B. 阶级分析法","C. 矛盾分析法","D. 精神分析法"],"ans":2,"explain":"“对立统一规律是事物发展的根本规律……矛盾分析法是最根本的认识方法”，因为矛盾是事物发展的动力和源泉，通过分析矛盾能深入理解事物本质和发展规律，所以答案是C。"},{"id":"mk15044-pl-P4803263","type":"sc","tier":"基础","conf":"adapt","chap":"第1章","q":"判断一个事物是新事物还是旧事物，主要看它（）","opts":["A. 是否形式新奇","B. 是否满足大多数人的主观愿望","C. 是否新近出现","D. 是否符合事物发展的必然趋势"],"ans":3,"explain":"新事物和旧事物的定义进行了阐述，新事物是符合客观规律、具有强大生命力和远大前途的事物，旧事物是丧失其存在的必然性、日趋灭亡的事物，所以判断依据是是否符合事物发展的必然趋势，答案为D。"},{"id":"mk15044-pl-P4803264","type":"sc","tier":"基础","conf":"adapt","chap":"第1章","q":"在唯物辩证法的理论体系中，作为实质和核心的是（）","opts":["A. 对立统一规律","B. 普遍联系的观点","C. 质量互变规律","D. 辩证否定的观点"],"ans":0,"explain":"“对立统一规律是事物发展的根本规律，是唯物辩证法的实质和核心”，其揭示了事物联系的根本内容和发展的内在动力，贯穿唯物辩证法其他规律和范畴，所以答案选A。"},{"id":"mk15044-pl-P4803265","type":"sc","tier":"基础","conf":"adapt","chap":"第1章","q":"对立统一规律揭示了（）","opts":["A. 事物发展的方向和道路","B. 事物发展的源泉和动力","C. 事物发展的状态和过程","D. 事物发展的趋向和走势"],"ans":1,"explain":"“对立统一规律揭示了事物发展的动力和源泉”，矛盾双方既对立又统一推动事物的运动、变化和发展，所以答案是B。"},{"id":"mk15044-pl-P4803266","type":"sc","tier":"基础","conf":"adapt","chap":"第1章","q":"在我国战国时期，公孙龙提出“白马非马”的命题。这个命题的错误在于它割裂了（）","opts":["A. 矛盾的普遍性和特殊性的统一","B. 矛盾的同一性和斗争性的统一","C. 事物发展的量变和质变的统一","D. 事物发展的内因和外因的统一"],"ans":0,"explain":"从矛盾普遍性和特殊性的关系可知，“白马”是矛盾的特殊性，“马”是矛盾的普遍性，“白马非马”割裂了二者的统一，答案选A。"},{"id":"mk15044-pl-P4803267","type":"sc","tier":"基础","conf":"adapt","chap":"第1章","q":"在唯物辩证法看来，粮食同玉米、高粱、小麦之间的关系属于（）","opts":["A. 一般和个别的关系","B. 整体和局部的关系","C. 本质和现象的关系","D. 内容和形式的关系"],"ans":0,"explain":"矛盾普遍性和特殊性相关内容，粮食是普遍性、一般，玉米、高粱、小麦是特殊性、个别，它们是一般和个别的关系，答案为A。"},{"id":"mk15044-pl-P4803268","type":"sc","tier":"基础","conf":"adapt","chap":"第1章","q":"认识我国改革开放和社会主义现代化建设的形势，首先要分清主流和支流，看到取得的成绩是主流，同时又不忽略支流。这是在哲学上坚持了（）","opts":["A. 事物普遍联系和永恒运动的观点","B. 矛盾的普遍性和特殊性相统一的观点","C. 两点论和重点论相统一的观点","D. 矛盾的同一性和斗争性相统一的观点"],"ans":2,"explain":"坚持两点论和重点论的统一，在认识复杂事物时既要看到主要矛盾和矛盾的主要方面，又要看到次要矛盾和矛盾的次要方面，且着重把握主要矛盾和矛盾的主要方面，这与题干描述相符，答案选C。"},{"id":"mk15044-pl-P4803269","type":"sc","tier":"基础","conf":"adapt","chap":"第1章","q":"循环论的错误在于（）","opts":["A. 夸大了事物发展的普遍性，否认了事物发展的特殊性","B. 夸大了事物运动的绝对性，否认了事物的相对静止","C. 夸大了事物发展的曲折性，否认了事物的前进性","D. 夸大新旧事物之间的连续性，否认新旧事物之间的间断性"],"ans":2,"explain":"循环论片面夸大事物发展的曲折性、回复性，忽视了事物发展的前进性，所以答案是C。"},{"id":"mk15044-pl-P4803270","type":"sc","tier":"基础","conf":"adapt","chap":"第1章","q":"唯物辩证法的总特征有两个，一个是联系的观点，另一个是（）","opts":["A. 发展的观点","B. 对立统一的观点","C. 实践的观点","D. 辩证否定的观点"],"ans":0,"explain":"唯物辩证法的总特征是联系的观点和发展的观点，所以答案选A。"},{"id":"mk15044-pl-P4803271","type":"sc","tier":"基础","conf":"adapt","chap":"第1章","q":"唯物辩证法与形而上学根本对立和斗争的焦点在于，是否承认（）","opts":["A. 联系具有复杂多样性","B. 新事物必然战胜旧事物","C. 质变是量变的必然结果","D. 矛盾是事物发展的动力"],"ans":3,"explain":"“是否承认对立统一规律以及矛盾是事物发展的动力，是唯物辩证法与形而上学的斗争焦点和根本分歧”，所以答案为D。"},{"id":"mk15044-pl-P4803272","type":"sc","tier":"基础","conf":"adapt","chap":"第1章","q":"联系的观点和发展的观点是（）","opts":["A. 马克思主义的理论品质","B. 唯物辩证法的总特征","C. 马克思主义的活的灵魂","D. 唯物辩证法的实质和核心"],"ans":1,"explain":"联系的观点和发展的观点是唯物辩证法的总特征，答案选B。"},{"id":"mk15044-pl-P4803273","type":"sc","tier":"基础","conf":"adapt","chap":"第1章","q":"事物之间的相互联系是事物本身固有的，是不以人的主观意志为转移的。这就是说（）","opts":["A. 联系具有客观性","B. 联系具有普遍性","C. 联系具有复杂性","D. 联系具有多样性"],"ans":0,"explain":"联系的客观性定义为事物之间的相互联系是事物本身固有的，不以人的主观意志为转移，所以答案是A。"},{"id":"mk15044-pl-P4803274","type":"sc","tier":"基础","conf":"adapt","chap":"第1章","q":"坚持马克思主义普遍真理与中国的具体实际相结合，走自己的路，建设中国特色社会主义。其理论依据是（）","opts":["A. 矛盾的同一性和斗争相结合的原理","B. 矛盾的普遍性和特殊性相统一的原理","C. 事物的发展是量变和质变统一的原理","D. 事物的发展是前进性和曲折性统一的原理"],"ans":1,"explain":"矛盾的普遍性和特殊性相统一的原理是马克思主义普遍真理与中国具体实际相结合的理论基础，所以答案选B。"},{"id":"mk15044-pl-P4803275","type":"sc","tier":"基础","conf":"adapt","chap":"第1章","q":"矛盾的两种基本属性是（）","opts":["A. 同一性和斗争性","B. 统一性和多样性","C. 普遍性和特殊性","D. 一般性和个别性"],"ans":0,"explain":"矛盾的同一性和斗争性是矛盾的基本属性，答案为A。"},{"id":"mk15044-pl-P4803276","type":"sc","tier":"基础","conf":"adapt","chap":"第1章","q":"“一把钥匙开一把锁”。这句话强调的是（）","opts":["A. 要注重分析矛盾的同一性","B. 要注重分析矛盾的斗争性","C. 要注重分析矛盾的特殊性","D. 要注重分析矛盾的普遍性"],"ans":2,"explain":"“一把钥匙开一把锁”体现了不同事物有不同的特点，需要具体问题具体分析，这符合矛盾特殊性原理，答案选C。"},{"id":"mk15044-pl-P4803277","type":"sc","tier":"基础","conf":"adapt","chap":"第1章","q":"我们党制定和执行独立自主、自力更生以及对外开放方针的理论基础是（）","opts":["A. 矛盾的同一性和斗争性辩证关系的原理","B. 事物发展的内因和外因辩证关系的原理","C. 矛盾的普遍性和特殊性辩证关系的原理","D. 事物发展的量变和质变辩证关系的原理"],"ans":1,"explain":"阐述事物发展的内因和外因辩证关系原理是党制定和执行相关方针的理论基础，内因是事物发展的根据，外因是事物发展的条件，所以答案是B。"},{"id":"mk15044-pl-P4803278","type":"sc","tier":"基础","conf":"adapt","chap":"第1章","q":"矛盾是事物发展的动力，这说明事物发展的根本原因是（）","opts":["A. 事物的内部矛盾","B. 事物的特殊矛盾","C. 事物的外部矛盾","D. 事物的主要矛盾"],"ans":0,"explain":"矛盾是事物发展的动力，事物发展的根本原因是事物的内部矛盾，内部矛盾是事物发展的根据，所以答案选A。"},{"id":"mk15044-pl-P4803279","type":"sc","tier":"基础","conf":"adapt","chap":"第1章","q":"否定之否定规律揭示了（）","opts":["A. 事物发展的动力和源泉","B. 事物发展的状态和形式","C. 事物发展的趋势和道路","D. 事物发展的内因和外因"],"ans":2,"explain":"否定之否定规律揭示了事物发展的趋势和道路，事物发展是前进性与曲折性的统一，答案为C。"},{"id":"mk15044-pl-P4803280","type":"sc","tier":"基础","conf":"adapt","chap":"第1章","q":"假象同真象一样，也是客观存在的，这是一种（）","opts":["A. 唯物辩证法的观点","B. 形而上学的观点","C. 折中主义的观点","D. 诡辩论的观点"],"ans":0,"explain":"唯物辩证法认为假象和真象都是客观存在的，假象是从反面歪曲地表现本质，所以答案选A。"},{"id":"mk15044-pl-P4803281","type":"sc","tier":"基础","conf":"adapt","chap":"第1章","q":"区分量变和质变的根本标志是（）","opts":["A. 事物的变化是否迅速","B. 事物的变化是否突破度","C. 事物的变化是否显著","D. 事物的变化是否有根据"],"ans":1,"explain":"量变与质变的根本标志是事物的变化是否超出度的范围，所以答案是B。"},{"id":"mk15044-pl-P4803282","type":"sc","tier":"基础","conf":"adapt","chap":"第1章","q":"对传统文化的批判继承态度依据的是（）","opts":["A. 辩证的否定的原理","B. 现象表现本质的原理","C. 量变和质变的原理","D. 内容决定形式的原理"],"ans":0,"explain":"辩证的否定是扬弃，即既克服又保留，对传统文化批判继承就是取其精华、去其糟粕，符合辩证否定原理，答案选A。"},{"id":"mk15044-pl-P4803283","type":"sc","tier":"基础","conf":"adapt","chap":"第1章","q":"拒腐防变就要防微杜渐，从哲学上看，是因为（）","opts":["A. 外因通过内因而起作用","B. 量变积累到一定程度会引起质变","C. 多种原因引起一个结果","D. 矛盾双方在一定条件下相互转化"],"ans":1,"explain":"量变和质变的辩证关系，量变是质变的必要准备，量变积累到一定程度会引起质变，“防微杜渐”就是防止小的不良量变积累引发质变，答案为B。"},{"id":"mk15044-pl-P4803284","type":"sc","tier":"基础","conf":"adapt","chap":"第1章","q":"下列选项中，表示要坚持适度原则的是（）","opts":["A. 因地制宜","B. 对症下药","C. 注意分寸","D. 实事求是"],"ans":2,"explain":"实践中坚持适度原则的表现如“注意分寸”“掌握火候”等，所以答案选C。"},{"id":"mk15044-pl-P4803285","type":"sc","tier":"基础","conf":"adapt","chap":"第1章","q":"“注意分寸”“掌握火候”“适可而止”等说法，都是要求在实践中坚持（）","opts":["A. 适度原则","B. 辩证否定观","C. 实事求是","D. 科学发展观"],"ans":0,"explain":"这些说法都体现了在实践中要把握好度，坚持适度原则，答案为A。"},{"id":"mk15044-pl-P4803286","type":"sc","tier":"基础","conf":"adapt","chap":"第1章","q":"在唯物辩证法的基本范畴中，内容和形式反映了（）","opts":["A. 事物之间引起和被引起的关系","B. 事物的内在要素和结构方式间的关系","C. 事物过去、现在和将来的关系","D. 事物的根本性质和表面特征间的关系"],"ans":1,"explain":"内容和形式反映了事物的内在要素和结构方式间的关系，内容是事物存在的基础，形式是事物存在和表现的方式，答案选B。"},{"id":"mk15044-pl-P4803287","type":"sc","tier":"基础","conf":"adapt","chap":"第1章","q":"在唯物辩证法的基本范畴中，本质和现象反映了（）","opts":["A. 事物之间引起和被引起的关系","B. 事物的内在要素和结构方式间的关系","C. 事物过去、现在和将来的关系","D. 事物的根本性质和表面特征间的关系"],"ans":3,"explain":"本质和现象反映了事物的根本性质和表面特征间的关系，本质是事物的内在联系和根本性质，现象是事物的外部联系和表面特征，答案为D。"},{"id":"mk15044-pl-P4803288","type":"sc","tier":"基础","conf":"adapt","chap":"第1章","q":"唯物辩证法的规律作用的范围和领域是（）","opts":["A. 自然界和人类社会","B. 人类社会和思维领域","C. 思维领域和自然界","D. 自然、社会和思维等所有领域"],"ans":3,"explain":"唯物辩证法的规律是在自然、社会和人类思维等所有领域都起作用的普遍规律，答案选D。"},{"id":"mk15044-pl-P4803289","type":"sc","tier":"基础","conf":"adapt","chap":"第1章","q":"现象可以分为真相和假象，假象是指（）","opts":["A. 歪曲地表现本质的现象","B. 与本质一致的现象","C. 直接表现本质的现象","D. 不表现本质的现象"],"ans":0,"explain":"“真相：正面直接地表现本质；假象：从反面歪曲地表现本质”，所以答案是A。"},{"id":"mk15044-pl-P4803290","type":"sc","tier":"基础","conf":"adapt","chap":"第1章","q":"正确发挥人的主观能动性的前提是（）","opts":["A. 形成明确的目的","B. 正确认识事物的规律","C. 制定周密的计划","D. 具有坚持的意志"],"ans":1,"explain":"“尊重客观规律是正确发挥主观能动性的前提。人们只有在认识和掌握客观规律的基础上，才能正确地认识世界，有效地改造世界”，所以答案选B。"},{"id":"mk15044-pl-P4803291","type":"sc","tier":"基础","conf":"adapt","chap":"第1章","q":"实现意识能动作用的根本途径是（）","opts":["A. 学习科学理论","B. 投身社会实践","C. 了解实际情况","D. 制定周密计划"],"ans":1,"explain":"提到“实践是正确发挥人的主观能动性的根本途径。正确的认识要变为现实的物质力量，只能通过物质的活动即实践才能达到”，所以答案为B。"},{"id":"mk15044-pl-P4803292","type":"sc","tier":"基础","conf":"adapt","chap":"第1章","q":"意识的能动性最突出的表现是，意识能够（）","opts":["A. 通过指导实践改造客观世界","B. 通过指导实践改造客观规律","C. 通过改造规律反映客观世界","D. 通过改造世界消灭客观规律"],"ans":0,"explain":"“意识能通过指导实践改造客观物质世界（最突出的表现）”，规律是客观的，不能被改造或消灭，所以答案选A。"},{"id":"mk15044-pl-P4803293","type":"sc","tier":"基础","conf":"adapt","chap":"第1章","q":"规律的两个特点是（）","opts":["A. 客观性和普遍性","B. 客观性和历史性","C. 普遍性和持久性","D. 普遍性和自觉性"],"ans":0,"explain":"明确规律的特点包括客观性和普遍性，客观性指规律不以人的意志为转移，普遍性指规律在一定范围内普遍起作用，所以答案是A。"},{"id":"mk15044-pl-P4803294","type":"sc","tier":"基础","conf":"adapt","chap":"第1章","q":"意识对于人的生理活动具有一定影响作用，这表明（）","opts":["A. 意识对物质具有能动性","B. 意识是客观事物本身","C. 意识对物质共有决定性","D. 意识是人脑的机能"],"ans":0,"explain":"意识能动性的表现之一是“意识对于人的生理活动具有一定影响作用”，这体现了意识对物质具有能动性，所以答案选A。"},{"id":"mk15044-pl-P4803295","type":"sc","tier":"基础","conf":"adapt","chap":"第1章","q":"“天行有常，不为尧存，不为舜亡。”这是说（）","opts":["A. 规律仅仅存在于自然界","B. 规律是无法认识和把握的","C. 规律不具有客观普遍性","D. 规律不以人的意志为转移"],"ans":3,"explain":"对规律客观性的解释为不以人的意志为转移，“天行有常，不为尧存，不为舜亡”体现了这一点，所以答案是D。"},{"id":"mk15044-pl-P4803296","type":"sc","tier":"基础","conf":"adapt","chap":"第1章","q":"下列关于意识起源的正确说法是（）","opts":["A. 意识是主观自生的","B. 意识是自然界长期发展的产物","C. 意识是人脑的机能","D. 意识是客观世界的主观映像"],"ans":1,"explain":"“从意识的起源来看，一方面，意识是自然界长期发展的产物。另一方面，意识也是社会历史发展的产物”，所以答案选B。"},{"id":"mk15044-pl-P4803297","type":"sc","tier":"基础","conf":"adapt","chap":"第1章","q":"在意识问题上，唯心主义的错误在于（）","opts":["A. 忽视意识的主观特征","B. 抹杀意识的主观特征","C. 夸大意识的能动作用","D. 否认意识的能动作用"],"ans":2,"explain":"“唯心主义片面夸大意识的能动作用，否认物质对意识决定作用”，所以答案是C。"},{"id":"mk15044-pl-P4803298","type":"sc","tier":"基础","conf":"adapt","chap":"第1章","q":"“揠苗助长”的寓言说明的哲学道理是（）","opts":["A. 意识的能动作用都是积极的","B. 发挥主观能动性可以改变规律","C. 意识的能动作用总是巨大的","D. 发挥主观能动性不能违背规律"],"ans":3,"explain":"尊重客观规律是发挥主观能动性的前提，“揠苗助长”违背了植物生长规律，所以答案选D。"},{"id":"mk15044-pl-P4803299","type":"sc","tier":"基础","conf":"adapt","chap":"第1章","q":"意识是人脑的机能，这说的是（）","opts":["A. 人脑是意识的唯一源泉","B. 意识不具有客观性","C. 人脑是意识的物质器官","D. 意识不具有主观性"],"ans":2,"explain":"“意识是人脑的机能和属性，是客观世界的主观映象”，人脑是产生意识的物质器官，所以答案是C。"},{"id":"mk15044-pl-P4803300","type":"sc","tier":"基础","conf":"adapt","chap":"第1章","q":"与自然规律相比，社会规律（）","opts":["A. 不具有客观性","B. 是通过各种盲目力量实现的","C. 不具有主观性","D. 是通过人的自觉活动实现的"],"ans":3,"explain":"“社会规律：与自然规律相比，社会规律是通过人的自觉活动实现的，说明社会规律不是盲目自发起作用的”，所以答案选D。"},{"id":"mk15044-pl-P4803301","type":"sc","tier":"基础","conf":"adapt","chap":"第1章","q":"社会规律是通过人们的自觉活动实现的，这说明社会规律（）","opts":["A. 不具有客观性","B. 不是盲目自发起作用的","C. 不具有普遍性","D. 不是事物发展的必然性"],"ans":1,"explain":"社会规律通过人的自觉活动实现，意味着它不是盲目自发起作用的，所以答案是B。"},{"id":"mk15044-pl-P4803302","type":"sc","tier":"基础","conf":"adapt","chap":"第1章","q":"把意识说成是人脑的分泌物，这是一种（）","opts":["A. 庸俗唯物主义的观点","B. 朴素唯物主义的观点","C. 形而上学唯物主义的观点","D. 辩证唯物主义的观点"],"ans":0,"explain":"“抹杀意识的主观特征，把意识等同于物质或客观事物，把意识说成是人脑的分泌物，就是一种庸俗唯物主义观点”，所以答案选A。"},{"id":"mk15044-pl-P4803303","type":"sc","tier":"基础","conf":"adapt","chap":"第1章","q":"抹杀意识的客观性，把意识说成是纯粹主观自生的，这是一种（）","opts":["A. 唯心主义的观点","B. 庸俗唯物主义的观点","C. 形而上学的观点","D. 不可知论的观点"],"ans":0,"explain":"“抹杀意识客观性，把意识说成纯粹是主观自生的，就是一种唯心主义观点”，所以答案是A。"},{"id":"mk15044-pl-P4803304","type":"sc","tier":"基础","conf":"adapt","chap":"第1章","q":"规律的客观性是指（）","opts":["A. 规律是无法认识的","B. 规律是不以任何人的意志为转移的","C. 规律是无法利用的","D. 规律是不在人类思维领域起作用的"],"ans":1,"explain":"规律客观性的定义为不以人的意志为转移，所以答案选B。"},{"id":"mk15044-pl-P4803305","type":"sc","tier":"基础","conf":"adapt","chap":"第1章","q":"“狼孩”没有意识，这一事实说明（）","opts":["A. 意识是自然界长期发展的产物","B. 意识是人脑的机能","C. 意识是社会的产物","D. 意识是大脑对客观事物的反映"],"ans":2,"explain":"意识是社会历史发展的产物，“狼孩”脱离人类社会，没有形成意识，说明了意识是社会的产物，所以答案是C。"},{"id":"mk15044-pl-P4803554","type":"sa","tier":"创新","conf":"adapt","chap":"第1章","q":"简述马克思主义的科学内涵。","opts":[],"ans":null,"explain":"马克思主义从创立者、研究对象、社会发展规律、阶级使命以及实践指导作用等多方面构成其科学内涵。马克思、恩格斯创立后经后继者发展，研究涵盖自然、社会和人类思维领域，揭示社会主义代替资本主义等规律，致力于无产阶级和全人类解放，为无产阶级政党和社会主义国家提供指导。\n马克思主义是由马克思、恩格斯创立并为后继者所不断发展的科学理论体系；是关于自然、社会和人类思维发展一般规律的学说；是关于社会主义必然代替资本主义、最终实现共产主义的学说；是关于无产阶级解放、全人类解放和每个人自由而全面发展的学说；是无产阶级政党和社会主义国家的指导思想，是指引人民创造美好生活的行动指南。"},{"id":"mk15044-pl-P4803555","type":"sa","tier":"创新","conf":"adapt","chap":"第1章","q":"简述马克思主义的三个基本组成部分及直接理论来源。","opts":[],"ans":null,"explain":"马克思主义哲学为认识世界和改造世界提供世界观和方法论；马克思主义政治经济学剖析资本主义经济内在规律；科学社会主义基于前两者，描绘未来社会蓝图。其直接理论来源中，德国古典哲学提供了辩证法和唯物主义思想；英国古典政治经济学对资本主义生产关系的分析有重要意义；英法空想社会主义则为未来社会的构想提供了启发。\n三个基本组成部分：马克思主义哲学、马克思主义政治经济学和科学社会主义。直接理论来源：德国古典哲学、英国古典政治经济学、19世纪的英法两国的空想社会主义学说。"},{"id":"mk15044-pl-P4803556","type":"sa","tier":"创新","conf":"adapt","chap":"第1章","q":"简述马克思主义对德国古典哲学的继承与创新。","opts":[],"ans":null,"explain":"黑格尔的辩证法强调事物的运动、变化和发展，费尔巴哈的唯物主义坚持物质第一性。马克思主义继承这些合理内核，摒弃其唯心主义和形而上学的部分，将辩证法与唯物主义有机结合，创立唯物辩证法；同时从社会历史领域出发，创立历史唯物主义，揭示人类社会发展的一般规律。\n继承：吸取黑格尔的辩证法的合理思想和费尔巴哈的唯物主义基本思想。创新：创立唯物辩证法和历史唯物主义。"},{"id":"mk15044-pl-P4803557","type":"sa","tier":"创新","conf":"adapt","chap":"第1章","q":"简述马克思主义的基本特征。","opts":[],"ans":null,"explain":"马克思主义的科学性确保其对世界的认识正确；人民性决定其价值取向；实践性是其理论来源和应用的关键；发展性使其能适应时代变化。这些特征相互关联，共同构成马克思主义的独特理论形象。\n马克思主义具有鲜明的科学性、人民性、实践性、发展性。科学性体现在它是对自然、社会和人类思维发展本质和规律的正确反映，具有科学的世界观和方法论基础等；人民性是其本质属性，它来自人民、为了人民、造福人民，以阶级性为深刻基础；实践性表现为从实践中来、到实践中去、在实践中接受检验并随实践发展，实践观点是首要和基本的观点；发展性指它是不断发展的开放的学说，具有与时俱进的理论品质，随时代、实践和科学发展而不断发展。"},{"id":"mk15044-pl-P4803558","type":"sa","tier":"创新","conf":"adapt","chap":"第1章","q":"简述马克思主义的当代价值。","opts":[],"ans":null,"explain":"从对世界、中国以及人类社会的作用三个层面来理解马克思主义当代价值。在世界层面帮助人们认识世界；在中国层面助力国家发展；在人类社会层面为社会进步提供方向。\n马克思主义的当代价值体现在：一是观察当代世界变化的认识工具，给予我们宏大视野、锐利目光以及长远眼光和战略定力；二是指引当代中国发展的行动指南，是指引当代中国发展的精神旗帜、推动当代中国发展的精神动力、引领当代中国实践的行动指南；三是引领人类社会进步的科学真理，其揭示的社会发展规律和历史趋势依然存在并发挥作用，人类未来仍需其指引。"},{"id":"mk15044-pl-P4803559","type":"sa","tier":"创新","conf":"adapt","chap":"第1章","q":"简述大学生学习马克思主义理论应采取的正确态度和科学方法。","opts":[],"ans":null,"explain":"从学习内容、学习方法以及实践运用等方面，全面阐述大学生学习马克思主义理论的正确路径，确保能真正掌握并运用马克思主义。\n大学生学习马克思主义理论应采取以下态度和方法：努力学习和掌握马克思主义的基本立场观点方法，领会其精髓要义；努力学习和掌握马克思主义中国化时代化的理论成果，尤其是习近平新时代中国特色社会主义思想；坚持理论联系实际的马克思主义学风，联系社会和自身实际；自觉将马克思主义内化于心、外化于行，树立科学理想信念，增强服务社会本领。"},{"id":"mk15044-pl-P1526284","type":"sc","tier":"基础","conf":"adapt","chap":"第1章","q":"作为马克思、恩格斯一生最重要的理论发现，使社会主义从空想变成科学的是（）。","opts":["A. 唯物论和辩证法学说","B. 唯物论和劳动价值学说","C. 唯物史观和剩余价值学说","D. 唯物史观和阶级斗争学说"],"ans":2,"explain":"马克思、恩格斯以唯物史观和剩余价值学说为基础，深入研究资本主义制度的内在矛盾和发展趋势，总结工人阶级斗争的实践经验，批判地吸收了空想社会主义学说的积极成果，对未来社会主义和共产主义社会的基本特征做了科学的预测和设想，创立了科学社会主义理论，实现了社会主义理论的变革。也因此把社会主义从空想变成科学。"},{"id":"mk15044-pl-P1526285","type":"sc","tier":"基础","conf":"adapt","chap":"第1章","q":"下列科学发现中，为马克思主义的产生提供了坚实的自然科学基础的不包括（）。","opts":["A. 细胞学说","B. 狭义相对论","C. 生物进化论","D. 能量守恒和转化定律"],"ans":1,"explain":"马克思主义的产生与当时自然科学的巨大进步密切相关，特别是细胞学说、能量守恒和转化定律与生物进化论这自然科学的三大发现，对马克思主义产生的影响尤为巨大。"},{"id":"mk15044-pl-P1526286","type":"sc","tier":"基础","conf":"adapt","chap":"第1章","q":"马克思主义的创始人是（）。","opts":["A. 马克思和李嘉图","B. 马克思和圣西门","C. 马克思和费尔巴哈","D. 马克思和恩格斯"],"ans":3,"explain":"马克思主义作为工人阶级和人类解放的科学，是包括马克思主义哲学、政治经济学和科学社会主义在内的统一整体。马克思、恩格斯是马克思主义的创始人。"},{"id":"mk15044-pl-P1526287","type":"sc","tier":"基础","conf":"adapt","chap":"第1章","q":"标志着马克思主义公开问世的著作除了《共产党宣言》，还有（）。","opts":["A. 《关于费尔巴哈的提纲》","B. 《德意志意识形态》","C. 《资本论》","D. 《哲学的贫困》"],"ans":3,"explain":"马克思、恩格斯不仅是马克思主义的创立者，而且是马克思主义的发展者。1847年7月发表的马克思的《哲学的贫困》和1848年2月发表的马克思、恩格斯合写的《共产党宣言》，标志着马克思主义的公开问世。"},{"id":"mk15044-pl-P1526288","type":"sc","tier":"基础","conf":"adapt","chap":"第1章","q":"列宁在《论欧洲联邦口号》和《无产阶级革命的军事纲领》两篇论文中，提出了（）。","opts":["A. 在特定的历史条件下，社会主义革命有可能在一国或几国首先取得胜利的思想","B. 落后的国家通过国家资本主义形式向社会主义过渡的思想","C. 新经济政策","D. 战时共产主义政策"],"ans":0,"explain":"列宁的《论欧洲联邦口号》和《无产阶级革命的军事纲领》两篇论文，提出了在特定的历史条件下，社会主义革命有可能在一国或几国首先取得胜利的思想。"},{"id":"mk15044-pl-P1526289","type":"sc","tier":"基础","conf":"adapt","chap":"第1章","q":"中国特色社会主义理论体系不包括（）。","opts":["A. 毛泽东思想","B. 邓小平理论","C. “三个代表”重要思想","D. 科学发展观"],"ans":0,"explain":"改革开放以来，我们党开辟了中国特色社会主义道路，形成了中国特色社会主义理论体系。这个理论体系就是包括邓小平理论、“三个代表”重要思想、科学发展观等重大战略思想在内的科学理论体系。"},{"id":"mk15044-pl-P1526290","type":"sc","tier":"基础","conf":"adapt","chap":"第1章","q":"马克思主义是（）。","opts":["A. 关于工人阶级和人类解放的科学","B. 人类全部优秀文化成果的总汇","C. 自然知识和社会知识的总和","D. 关于未来社会具体设想的学说"],"ans":0,"explain":"马克思主义是由马克思、恩格斯创立的，为他们的后继者所发展的，以反对资本主义、建设社会主义和共产主义为目标的科学的理论体系，或者简要地说，它是关于工人阶级和人类解放的科学。"},{"id":"mk15044-pl-P1526291","type":"sc","tier":"基础","conf":"adapt","chap":"第1章","q":"马克思主义体系中，通向实际生活的中介是（）。","opts":["A. 马克思主义哲学","B. 马克思主义政治经济学","C. 科学社会主义学说","D. 阶级和阶级斗争学说"],"ans":1,"explain":"在马克思主义体系中哲学是世界观和方法论的指导原则，政治经济学是通向实际生活的中介，科学社会主义则是运用哲学分析经济事实引出的结论。"},{"id":"mk15044-pl-P1526292","type":"sc","tier":"基础","conf":"adapt","chap":"第1章","q":"马克思主义的根本理论特征是以实践为基础的（）。","opts":["A. 科学性和革命性的统一","B. 革命性和批判性的统一","C. 先进性和科学性的统一","D. 创新性与革命性的统一"],"ans":0,"explain":"马克思主义的根本理论特征是以实践为基础的科学性和革命性的统一。"},{"id":"mk15044-pl-P1526293","type":"sc","tier":"基础","conf":"adapt","chap":"第1章","q":"马克思主义各个组成部分中处于核心地位的是（）。","opts":["A. 政治经济学","B. 马克思主义哲学","C. 科学社会主义理论","D. 历史唯物论"],"ans":2,"explain":"政治经济学是马克思主义的理论基础，处于核心地位的则是科学社会主义理论。"},{"id":"mk15044-pl-P1526294","type":"sc","tier":"基础","conf":"adapt","chap":"第1章","q":"马克思主义的科学性和革命性统一于它的（）。","opts":["A. 实践性","B. 阶级性","C. 深刻性","D. 批判性"],"ans":0,"explain":"马克思主义的根本理论特征是以实践为基础的科学性和革命性的统一。"},{"id":"mk15044-pl-P1526295","type":"sc","tier":"基础","conf":"adapt","chap":"第1章","q":"马克思主义的革命性集中表现为它的彻底的（）。","opts":["A. 批判精神","B. 革命精神","C. 创造精神","D. 实践精神"],"ans":0,"explain":"马克思主义的革命性，集中表现为它的彻底的批判精神。"},{"id":"mk15044-pl-P1526296","type":"sc","tier":"基础","conf":"adapt","chap":"第1章","q":"既是马克思主义的基本观点，又是马克思主义的出发点和归宿的是（）。","opts":["A. 实践的观点","B. 发展的观点","C. 矛盾的观点","D. 辩证的否定观"],"ans":0,"explain":"马克思主义的科学性和革命性都是以实践性为基础的。实践的观点是马克思主义的基本观点，是马克思主义的出发点和归宿。"},{"id":"mk15044-pl-P1526297","type":"sc","tier":"基础","conf":"adapt","chap":"第1章","q":"马克思主义的理论品质是（）。","opts":["A. 自我批判","B. 与时俱进","C. 不迷信权威","D. 批判与继承的统一"],"ans":1,"explain":"与时俱进是马克思主义的理论品质。"},{"id":"mk15044-pl-P1526298","type":"sc","tier":"基础","conf":"adapt","chap":"第1章","q":"中国各族人的共同理想是（）。","opts":["A. 倡导社会主义的民主精神","B. 高扬社会主义的平等思想","C. 提倡诚实守信的伦理道德","D. 把我国建设成为富强、民主、文明、和谐的社会主义现代化国家"],"ans":3,"explain":"走中国特色社会主义道路，把我国建设成为富强、民主、文明、和谐的社会主义现代化国家，相对于最高理想来说，就是近期的具体理想，即全国各族人民的共同理想。"},{"id":"mk15044-pl-P1526299","type":"sc","tier":"基础","conf":"adapt","chap":"第1章","q":"就理想的内容来划分，有生活理想、职业理想、道德理想、社会理想等。其中全部理想的核心是（）。","opts":["A. 社会理想","B. 道德理想","C. 职业理想","D. 生活理想"],"ans":0,"explain":"就理想的内容来划分，有生活理想、职业理想、道德理想、社会理想等。其中社会理想是最根本的，是全部理想的核心，它贯穿于生活理想、职业理想、道德理想之中，决定和制约着它们的发展和实现程度。"},{"id":"mk15044-pl-P1526300","type":"sc","tier":"基础","conf":"adapt","chap":"第1章","q":"实现共同理想，必须坚持以（）为根本方向。","opts":["A. 阶段理想","B. 共同理想","C. 最高理想","D. 社会主义理想"],"ans":2,"explain":"实现共同理想，必须坚持以最高理想为根本方向。"},{"id":"mk15044-pl-P1526301","type":"sc","tier":"基础","conf":"adapt","chap":"第1章","q":"下列关于学习马克思主义目的的表述，正确的是（）。","opts":["A. 掌握具体的自然科学知识","B. 掌握具体的社会科学知识","C. 学会认识和改造世界的具体方法","D. 树立正确的世界观、人生观、价值观"],"ans":3,"explain":"学习马克思主义的目的主要包括：(1)树立正确的世界观、人生观、价值观。(2)掌握认识世界和改造世界的伟大工具。(3)全面提高人的素质。"},{"id":"mk15044-pl-P1526302","type":"sc","tier":"基础","conf":"adapt","chap":"第1章","q":"学习马克思主义的根本方法是（）。","opts":["A. 理论联系实际","B. 矛盾分析法","C. 阶级斗争分析法","D. 主客观相结合分析法"],"ans":0,"explain":"理论联系实际是学习马克思主义的根本方法。"},{"id":"mk15044-pl-P1526303","type":"sc","tier":"基础","conf":"adapt","chap":"第1章","q":"理论联系实际是学习马克思主义的根本方法。坚持理论联系实际必须反对的两种倾向是经验主义和（）。","opts":["A. 相对主义","B. 教条主义","C. 绝对主义","D. 折衷主义"],"ans":1,"explain":"理论联系实际是学习马克思主义的根本方法。所谓理论联系实际，就是把马克思主义的基本原理作为指导，去观察和分析社会实际、工作实际和思想实际。要做到理论联系实际，在实际工作中必须反对经验主义和教条主义两种倾向。"},{"id":"mk15044-pl-P1526304","type":"sc","tier":"基础","conf":"adapt","chap":"第1章","q":"属于马克思主义科学的世界观和方法论的是（）。","opts":["A. 马克思主义哲学","B. 科学社会主义","C. 政治经济学","D. 科学发展观"],"ans":0,"explain":"在马克思主义体系中，马克思主义哲学是科学的世界观和方法论，政治经济学揭示了资本主义的发展规律，处于核心地位的则是科学社会主义理论。"},{"id":"mk15044-pl-P1526305","type":"sc","tier":"基础","conf":"adapt","chap":"第1章","q":"下列不属于学习马克思主义目的的是（）。","opts":["A. 树立正确的世界观、人生观、价值观","B. 掌握认识世界和改造世界的伟大工具","C. 全面提高人的素质","D. 理论联系实际"],"ans":3,"explain":"学习马克思主义的目的有以下四个方面：第一，树立正确的世界观、人生观、价值观。第二，掌握认识世界和改造世界的伟大工具。第三，全面提高人的素质。第四，指导中国特色社会主义伟大实践。"},{"id":"mk15044-pl-P1526306","type":"sc","tier":"基础","conf":"adapt","chap":"第1章","q":"马克思主义在（）传入中国。","opts":["A. 19世纪中期","B. 18世纪末19世纪初","C. 19世纪末20世纪初","D. 20世纪中期"],"ans":2,"explain":"马克思主义19世纪末20世纪初在传入中国。"},{"id":"mk15044-pl-P1526307","type":"sc","tier":"基础","conf":"adapt","chap":"第1章","q":"资本主义基本矛盾的激化，在阶级关系上表现为（）。","opts":["A. 工人阶级和地主阶级之间的矛盾的尖锐化","B. 工人阶级和干部阶级之间的矛盾的尖锐化","C. 工人阶级和农民阶级之间的矛盾的尖锐化","D. 工人阶级和资产阶级之间的矛盾的尖锐化"],"ans":3,"explain":"资本主义基本矛盾的激化，在阶级关系上表现为工人阶级和资产阶级之间的矛盾的尖锐化。"},{"id":"mk15044-pl-P1526308","type":"sc","tier":"基础","conf":"adapt","chap":"第1章","q":"下列哪个人物与英国古典政治经济学无关（）。","opts":["A. 威廉·配第","B. 黑格尔","C. 亚当·斯密","D. 大卫·李嘉图"],"ans":1,"explain":"英国古典政治经济学产生于17世纪后半期即英国资产阶级革命时期，完成于英国工业革命后的19世纪初，创始人是威廉·配第，中间经过亚当·斯密的发展，发展到大卫·李嘉图结束。B项黑格尔属于德国古典哲学的代表人物。"},{"id":"mk15044-pl-P1526309","type":"sc","tier":"基础","conf":"adapt","chap":"第1章","q":"否认思维和存在的同一性是（）。","opts":["A. 唯心主义","B. 相对主义","C. 不可知论","D. 反映论"],"ans":2,"explain":"否认思维与存在的同一性，认为世界是不可能认识的，属于不可知论。"},{"id":"mk15044-pl-P1526310","type":"sc","tier":"基础","conf":"adapt","chap":"第1章","q":"对哲学基本问题第二个方面内容的不同回答是划分（）。","opts":["A. 唯物主义和唯心主义的标准","B. 辩证法和形而上学的标准","C. 可知论和不可知论的标准","D. 辩证唯物主义和形而上学唯物主义的标准"],"ans":2,"explain":"哲学的基本问题包括两方面的内容：第一方面是物质和意识哪个是本原、哪个是第一性的问题；第二方面是思维和存在的同一性问题。其中，对第二个方面内容的不同回答，是区分可知论与不可知论的标准。"},{"id":"mk15044-pl-P1526311","type":"sc","tier":"基础","conf":"adapt","chap":"第1章","q":"哲学上的二元论就是否认（）。","opts":["A. 世界的本原是物质","B. 世界的本原是精神","C. 世界是发展变化的","D. 世界的统一性"],"ans":3,"explain":"一元论承认世界的统一性，认为世界上的万事万物有一个共同的本质或本原；二元论否认世界的统一性，认为世界上的万事万物有物质和精神这两个相互平行、各自独立的本原。"},{"id":"mk15044-pl-P1526312","type":"sc","tier":"基础","conf":"adapt","chap":"第1章","q":"把世界的本质或本原归结为某一种或某几种具体的物质形态的观点，属于（）。","opts":["A. 古代的朴素唯物主义","B. 形而上学唯物主义","C. 辩证唯物主义","D. 庸俗唯物主义"],"ans":0,"explain":"古代朴素唯物主义把世界的本质或本原归结为某一种或某几种具体的物质形态。"},{"id":"mk15044-pl-P1526313","type":"sc","tier":"基础","conf":"adapt","chap":"第1章","q":"我国哲学家王守仁提出“心外无物”，英国哲学家贝克莱提出“存在就是被感知”。这两种观点（）。","opts":["A. 前者是主观唯心主义，后者是客观唯心主义","B. 前者是客观唯心主义，后者是主观唯心主义","C. 都是主观唯心主义","D. 都是客观唯心主义"],"ans":2,"explain":"主观唯心主义把人的主观精神（人的感觉、经验、“心”等）夸大为唯一的实在，认为人的主观精神是第一性的，整个世界都是这种主观精神的产物。如18世纪英国哲学家贝克莱提出的“存在就是被感知”、“物是感觉的集合”，明代哲学家王守仁提出的“心外无物”、“天地万物皆在吾心中”等，都是主观唯心主义的观点。"},{"id":"mk15044-pl-P1526314","type":"sc","tier":"基础","conf":"adapt","chap":"第1章","q":"设想没有运动的物质会导致（）。","opts":["A. 唯心主义","B. 形而上学","C. 二元论","D. 不可知论"],"ans":1,"explain":"形而上学和唯心主义的运动观，都是把物质和运动相割裂，前者主张没有运动的物质，后者主张没有物质的运动。"},{"id":"mk15044-pl-P1526315","type":"sc","tier":"基础","conf":"adapt","chap":"第1章","q":"从哲学上看，运动和静止的关系属于（）。","opts":["A. 现象和本质的关系","B. 一般和个别的关系","C. 绝对和相对的关系","D. 抽象和具体的关系"],"ans":2,"explain":"世界上的事物都是绝对运动和相对静止的统一，是动中有静，静中有动。因此，可以说运动和静止的关系属于绝对和相对的关系。"},{"id":"mk15044-pl-P1526316","type":"sc","tier":"基础","conf":"adapt","chap":"第1章","q":"只承认绝对运动，不承认相对静止的观点是（）。","opts":["A. 主观唯心主义","B. 相对主义诡辩论","C. 形而上学","D. 客观唯心主义"],"ans":1,"explain":"世界上的事物都是绝对运动和相对静止的统一，是动中有静，静中有动。形而上学把静止绝对化，否认运动；相对主义诡辩论则只承认运动，否认相对静止。"},{"id":"mk15044-pl-P1526317","type":"sc","tier":"基础","conf":"adapt","chap":"第1章","q":"下列活动中，属于最基本的实践活动的是（）。","opts":["A. 处理人际关系的伦理活动","B. 处理社会关系的实践活动","C. 物质生产实践活动","D. 科学实验活动"],"ans":2,"explain":"物质生产实践是处理人与自然关系的活动。它是最基本的实践活动，是决定其他一切实践活动产生和发展的前提。"},{"id":"mk15044-pl-P1526318","type":"sc","tier":"基础","conf":"adapt","chap":"第1章","q":"对立统一规律揭示了（）。","opts":["A. 事物发展的方向和道路","B. 事物发展的动力和源泉","C. 事物发展的状态和过程","D. 事物发展的趋向和走势"],"ans":1,"explain":"联系和发展是有规律的。唯物辩证法就是关于自然、社会和思维联系与发展一般规律的科学。它是由对立统一规律、质量互变规律、否定之否定规律和一系列其他范畴构成的科学体系。对立统一规律揭示了事物发展的动力和源泉，质量互变规律揭示了事物发展的状态和形式，否定之否定规律揭示了事物发展的趋势和道路。唯物辩证法的其他范畴则揭示了事物联系和发展的基本环节。"},{"id":"mk15044-pl-P1526319","type":"sc","tier":"基础","conf":"adapt","chap":"第1章","q":"唯物辩证法的实质与核心是（）。","opts":["A. 对立统一规律","B. 质量互变规律","C. 否定之否定规律","D. 联系和发展的规律"],"ans":0,"explain":"对立统一规律是唯物辩证法的实质与核心，是宇宙的根本规律。"},{"id":"mk15044-pl-P1526320","type":"sc","tier":"基础","conf":"adapt","chap":"第1章","q":"质量互变规律揭示了（）。","opts":["A. 事物发展的基本趋势","B. 事物发展的状态和形式","C. 事物发展的方向和道路","D. 事物发展的源泉和动力"],"ans":1,"explain":"唯物辩证法中质量互变规律揭示了事物发展的状态和形式；否定之否定规律揭示了事物发展的趋势和道路；唯物辩证法的其他范畴则揭示了事物的联系和发展的基本环节。"},{"id":"mk15044-pl-P1526321","type":"sc","tier":"基础","conf":"adapt","chap":"第1章","q":"矛盾问题的精髓是（）。","opts":["A. 矛盾的同一性和斗争性的关系问题","B. 主要矛盾和次要矛盾的关系问题","C. 矛盾的普遍性和特殊性辩证关系问题","D. 矛盾的主要方面和次要方面的关系问题"],"ans":2,"explain":"矛盾的普遍性与特殊性辩证关系的原理，是矛盾问题的精髓。这一原理要求我们在普遍原理的指导下，对具体问题进行具体分析，通过对具体问题分析和解决，补充和丰富普遍原理。"},{"id":"mk15044-pl-P1526322","type":"sc","tier":"基础","conf":"adapt","chap":"第1章","q":"揭示事物发展是前进性和曲折性统一的规律是（）。","opts":["A. 联系和发展的规律","B. 对立统一规律","C. 质量互变规律","D. 否定之否定规律"],"ans":3,"explain":"否定之否定规律的基本内容是：事物的发展经过两次辩证的否定，由肯定阶段到否定阶段，再到否定之否定阶段，从而使事物的发展表现为螺旋式上升和波浪式前进的过程。否定之否定规律揭示了事物的发展是前进性和曲折性的统一。"},{"id":"mk15044-pl-P1526323","type":"sc","tier":"基础","conf":"adapt","chap":"第1章","q":"价值规律是通过商品交换中价格围绕价值上下波动表现出来的。这说明（）。","opts":["A. 必然趋势通过大量偶然现象为自己开辟道路","B. 必然性可以转化为偶然性","C. 事物的发展是由量变向质变转化的过程","D. 事物的发展是由可能性向现实性转化的过程"],"ans":0,"explain":"必然性通过大量的偶然性表现出来，由此为自己开辟道路，没有脱离偶然性的纯粹必然性。客观事物的每一过程都是由根本矛盾的作用决定的，都是遵循必然规律发展的，但在发展过程中还受到内部非根本矛盾和外部条件的种种影响。事物的发展不能排除偶然因素的影响，总是在无数的偶然变动中贯彻自己必然的发展趋势。社会发展的必然趋势是通过大量偶然现象为自己开辟道路的。"},{"id":"mk15044-pl-P1526324","type":"sc","tier":"基础","conf":"adapt","chap":"第1章","q":"真相和假象的区别在于（）。","opts":["A. 真相是客观的，假象是主观的","B. 真相是确定的，假象是不确定的","C. 真相是稳定的，假象是变动不居的","D. 真相从正面直接地表现本质，假象从反面歪曲地表现本质"],"ans":3,"explain":"任何现象都从一定的方面表现着本质，真相从正面直接地表现本质，假象从反面歪曲地表现本质。不表现本质的纯粹现象是不存在的。"},{"id":"mk15044-pl-P1526325","type":"sc","tier":"基础","conf":"adapt","chap":"第1章","q":"正确发挥意识能动作用的前提是（）。","opts":["A. 尊重客观规律","B. 充分调动个人积极性","C. 彻底克服保守思想","D. 充分发挥集体智慧"],"ans":0,"explain":"尊重客观规律是正确发挥主观能动性的前提。"},{"id":"mk15044-pl-P1526326","type":"sc","tier":"基础","conf":"adapt","chap":"第1章","q":"党的思想路线是：一切从实际出发，理论联系实际，实事求是，在实践中检验和发展真理。其核心是（）。","opts":["A. 一切从实际出发","B. 理论联系实际","C. 实事求是","D. 在实践中检验和发展真理"],"ans":2,"explain":"党的思想路线有着丰富的内涵，这就是：一切从实际出发，理论联系实际，实事求是，在实践中检验和发展真理。这条思想路线的核心是实事求是。"},{"id":"mk15044-pl-P1526327","type":"sc","tier":"基础","conf":"adapt","chap":"第1章","q":"解放思想的目的是（）。","opts":["A. 一切从实际出发","B. 开动脑筋","C. 实事求是","D. 团结一致向前看"],"ans":2,"explain":"实事求是是解放思想的目的，解放思想就是为了更好地做到实事求是。"},{"id":"mk15044-pl-P1526328","type":"sc","tier":"基础","conf":"adapt","chap":"第1章","q":"坚持实事求是的前提是（）。","opts":["A. 解放思想","B. 尊重客观规律","C. 联系群众密切","D. 团结一致向前看"],"ans":0,"explain":"解放思想是坚持实事求是的前提，只有解放思想，才能切实做到实事求是。"},{"id":"mk15044-pl-P1526329","type":"sc","tier":"基础","conf":"adapt","chap":"第1章","q":"在物质和运动的关系问题上，唯心主义的错误在于（）。","opts":["A. 否认物质的绝对运动","B. 夸大相对静止的存在","C. 否认物质是运动的主体","D. 主张没有运动的物质"],"ans":2,"explain":"世界上也不存在没有物质的运动。物质是运动的承担者，是运动的主体，一切运动都是物质的运动。否认物质是运动的承担者或主体，必然导致唯心主义。"},{"id":"mk15044-pl-P1526330","type":"sc","tier":"基础","conf":"adapt","chap":"第1章","q":"马克思主义认为，实践是（）。","opts":["A. 主体能动地改造和探索客体的客观物质活动","B. 主观的精神活动","C. 人为应付环境所采取的生物性活动","D. 个人的日常生活活动"],"ans":0,"explain":"实践是主体能动地改造和探索客体的社会性的客观物质活动。"},{"id":"mk15044-pl-P1526331","type":"sc","tier":"基础","conf":"adapt","chap":"第1章","q":"唯物辩证法有两个总特征，一个是普遍联系的观点，另一个是（）。","opts":["A. 质量互变的观点","B. 永恒发展的观点","C. 对立统一的观点","D. 辩证否定的观点"],"ans":1,"explain":"唯物辨证法认为，物质世界是普遍联系和永恒发展的。唯物辩证法有两个总特征，一个是联系的观点，另一个是发展的观点。"},{"id":"mk15044-pl-P1526332","type":"sc","tier":"基础","conf":"adapt","chap":"第1章","q":"新事物之所以必然战胜旧事物，从根本上说是由于（）。","opts":["A. 新事物是在旧事物之后产生的","B. 新事物具有旧事物所没有的新形式","C. 新事物具有旧事物所没有的新内容","D. 新事物较旧事物更符合事物发展的必然趋势"],"ans":3,"explain":"区分新旧事物的根本标志在于它是否符合事物发展的必然趋势，是否具有强大的生命力和发展前途。因此，新事物之所以必然战胜旧事物，从根本上说是由于新事物较旧事物更符合事物发展的必然趋势。"},{"id":"mk15044-pl-P1526333","type":"sc","tier":"基础","conf":"adapt","chap":"第1章","q":"马克思主义哲学的精髓是（）。","opts":["A. 解放思想","B. 实事求是","C. 与时俱进","D. 联系群众"],"ans":1,"explain":"实事求是是马克思主义哲学的精髓，是马克思主义中国化所形成的重大理论成果。"},{"id":"mk15044-pl-P1527748","type":"sc","tier":"基础","conf":"adapt","chap":"第1章","q":"“注意分寸”“掌握火候”“适可而止”等说法，都是要在实践中坚持（ ）。","opts":["A. 适度原则","B. 辩证否定观","C. 实事求是","D. 科学发展观"],"ans":0,"explain":"“注意分寸”“掌握火候”“适可而止”等说法，都是要在实践中坚持适度原则。"},{"id":"mk15044-pl-P1527749","type":"sc","tier":"基础","conf":"adapt","chap":"第1章","q":"下列选项中，表示要坚持适度原则的是（ ）。","opts":["A. 因地制宜","B. 对症下药","C. 注意分寸","D. 实事求是"],"ans":2,"explain":"“注意分寸”“掌握火候”“适可而止”等说法，都是要在实践中坚持适度原则。选项中的“注意分寸”是坚持适度原则。"},{"id":"mk15044-pl-P1527750","type":"sc","tier":"基础","conf":"adapt","chap":"第1章","q":"面对消极腐败的东西，我们一定要提高警惕，做到见微知著，防微杜渐。因为（）","opts":["A. 量变积累到一定程度必然引起质变","B. 原因必然引起结果","C. 外因通过内因而起作用","D. 矛盾双方在一定条件下相互转化"],"ans":0,"explain":"单纯的量变不会永远持续下去，量变达到一定的程度必然引起质变。"},{"id":"mk15044-pl-P1527754","type":"sc","tier":"基础","conf":"adapt","chap":"第1章","q":"辩证的否定是事物发展的环节，因为辩证的否定（ ）","opts":["A. 把旧事物完全抛弃","B. 使旧事物发生量变","C. 是新事物的产生、旧事物的灭亡","D. 是从外部强加给事物的"],"ans":2,"explain":"否定是事物发展的环节。事物的发展，是新事物的产生和旧事物的灭亡，是事物根本性质的变化。没有新事物对旧事物的否定，就没有事物的发展。"},{"id":"mk15044-pl-P1527755","type":"sc","tier":"基础","conf":"adapt","chap":"第1章","q":"矛盾的两种基本属性是（ ）。","opts":["A. 同一性和斗争性","B. 统一性和多样性","C. 普遍性和特殊性","D. 一般性和个别性"],"ans":0,"explain":"矛盾的两种基本属性是同一性和斗争性。"},{"id":"mk15044-pl-P1527757","type":"sc","tier":"基础","conf":"adapt","chap":"第1章","q":"矛盾普遍性的完整含义是（）","opts":["A. 矛盾存在于质变和量变的过程中","B. 矛盾存在于一切运动中的事物中","C. 矛盾存在于一切现象的一定阶段中","D. 矛盾存在于一切事物及其发展过程的始终"],"ans":3,"explain":"矛盾的普遍性是指矛盾存在于一切事物的发展过程中，存在于一切事物发展过程的始终。"},{"id":"mk15044-pl-P1527758","type":"sc","tier":"基础","conf":"adapt","chap":"第1章","q":"矛盾的同一性和斗争性的关系是（）","opts":["A. 部分和整体的关系","B. 形势和内容的关系","C. 相对和绝对的关系","D. 次要和主要的关系"],"ans":2,"explain":"矛盾的同一性是相对的，矛盾的斗争性是绝对的。"},{"id":"mk15044-pl-P1527759","type":"sc","tier":"基础","conf":"adapt","chap":"第1章","q":"矛盾斗争的无条件性是指（）","opts":["A. 不需要任何条件","B. 脱离同一性的纯粹斗争性","C. 不被任何条件所限制","D. 能打破特定条件的限制"],"ans":2,"explain":"矛盾斗争性的无条件性不是指斗争性的存在可以脱离任何具体条件，而是指无论在任何条件下，矛盾双方都会有斗争。矛盾的斗争性既存在于事物的相对稳定状态中，也存在于事物的显著变动状态中。矛盾的斗争及其所体现的事物的运动变化，都是无条件的、绝对的。"},{"id":"mk15044-pl-P1527761","type":"sc","tier":"基础","conf":"adapt","chap":"第1章","q":"矛盾的两个基本属性，一个是斗争性，另一个是（）","opts":["A. 同一性","B. 客观性","C. 普遍性","D. 特殊性"],"ans":0,"explain":"矛盾双方的对立和统一这两重关系决定了矛盾具有两种基本属性，即同一性和斗争性。"},{"id":"mk15044-pl-P1527763","type":"sc","tier":"基础","conf":"adapt","chap":"第1章","q":"在自然界，没有上，就无所谓下；在社会中，没有先进，就无所谓落后；在认识中，没有正确，就无所谓错误。这说明（ ）","opts":["A. 矛盾双方是相互排斥的","B. 矛盾双方是相互渗透的","C. 矛盾双方是相互依存的","D. 矛盾双方是相互转化的"],"ans":2,"explain":"矛盾双方相互依存。矛盾双方互为存在的前提，矛盾的一方必须以另一方的存在作为自己存在的条件，双方共处于一个统一体中。"},{"id":"mk15044-pl-P1527764","type":"sc","tier":"基础","conf":"adapt","chap":"第1章","q":"唯物辩证法认为，矛盾双方在一定条件下的转化是（）","opts":["A. 向任何一个方向转化","B. 向着自己的对立面转化","C. 由坏向好的转化","D. 由低级向高级的转化"],"ans":1,"explain":"矛盾双方在一定条件下相互转化的趋势，即矛盾双方在一定条件下向自己的对立面转化的趋势。"},{"id":"mk15044-pl-P1527765","type":"sc","tier":"基础","conf":"adapt","chap":"第1章","q":"矛盾是事物发展的动力，这说明事物发展的根本原因是（ ）。","opts":["A. 事物的内部矛盾","B. 事物的特殊矛盾","C. 事物的外部矛盾","D. 事物的主要矛盾"],"ans":0,"explain":"内因是事物发展变化的根据，是第一位的原因，事物发展变化的根本原因不在事物外部，而在事物的内部。"},{"id":"mk15044-pl-P1527766","type":"sc","tier":"基础","conf":"adapt","chap":"第1章","q":"区分量变和质变的根本标志是（ ）。","opts":["A. 事物的变化是否迅速","B. 事物的变化是否超出度的范围","C. 事物的变化是否彻底","D. 事物的变化是否具有必然性"],"ans":1,"explain":"区分量变和质变的根本标志是事物的变化是否超出度的范围。"},{"id":"mk15044-pl-P1527767","type":"sc","tier":"基础","conf":"adapt","chap":"第1章","q":"认识我国改革开放和社会主义现代化建设的形势，我们要分清主流和支流，要看主流，同时又不忽略支流。这里依据的哲学道理是（ ）。","opts":["A. 矛盾的普遍性和特殊性辩证关系的原理","B. 主要矛盾和次要矛盾辩证关系的原理","C. 矛盾的主要方面和次要方面辩证关系的原理","D. 事物变化的内因和外因辩证关系的原理"],"ans":2,"explain":"认识我国改革开放和社会主义现代化建设的形势，我们要分清主流和支流，要看主流（主要方面），同时又不忽略支流（次要方面）。这里依据的哲学道理是矛盾的主要方面和次要方面辩证关系的原理。"},{"id":"mk15044-pl-P1527769","type":"sc","tier":"基础","conf":"adapt","chap":"第1章","q":"我们党制定和执行独立自主、自力更生以及对外开放方针的理论基础是（ ）。","opts":["A. 矛盾的同一性和斗争性辩证关系的原理","B. 事物发展的内因和外因辩证关系的原理","C. 矛盾的普遍性和特殊性辩证关系的原理","D. 事物发展的量变和质变辩证关系的原理"],"ans":1,"explain":"事物发展的内因和外因辩证关系的原理是我们党制定和执行独立自主、自力更生以及对外开放方针的理论基础。"},{"id":"mk15044-pl-P1527770","type":"sc","tier":"基础","conf":"adapt","chap":"第1章","q":"唯物辩证法认为，外部矛盾是事物发展变化的（）","opts":["A. 根本原因","B. 决定性因素","C. 不可缺少的条件","D. 动力和源泉"],"ans":2,"explain":"外因是事物发展变化不可缺少的条件。"},{"id":"mk15044-pl-P1527772","type":"sc","tier":"基础","conf":"adapt","chap":"第1章","q":"要开一张包治百病的药方是很荒谬的，因为它违背了（ ）。","opts":["A. 任何事物都包含着矛盾的原理","B. 事物的矛盾各有其特点的原理","C. 普遍性存在于特殊性之中的原理","D. 事物之间普遍联系的原理"],"ans":1,"explain":"要开一张包治百病的药方是很荒谬的，因为它违背了事物的矛盾各有其特点的原理，矛盾的特殊性要求我们具体问题具体分析。"},{"id":"mk15044-pl-P1527773","type":"sc","tier":"基础","conf":"adapt","chap":"第1章","q":"在唯物辩证法看来，粮食同玉米、高粱、小麦之间的关系属于（ ）。","opts":["A. 一般和个别的关系","B. 整体和局部的关系","C. 本质和现象的关系","D. 内容和形式的关系"],"ans":0,"explain":"在唯物辩证法看来，粮食属于一般（普遍），玉米、高粱、小麦属于个别（特殊）。"},{"id":"mk15044-pl-P1527775","type":"sc","tier":"基础","conf":"adapt","chap":"第1章","q":"假象同真相一样，也是客观存在的。这是一种（ ）。","opts":["A. 辩证法的观点","B. 唯物辩证法的观点","C. 形而上学的观点","D. 主观唯心主义的观点"],"ans":1,"explain":"“假象同真相一样，也是客观存在的”这是一种唯物辩证法的观点。"},{"id":"mk15044-pl-P1527776","type":"sc","tier":"基础","conf":"adapt","chap":"第1章","q":"“在自然界中没有原因也没有结果，因果律的一切形式都是从主观意向当中产生的”，这种观点（）","opts":["A. 形而上学机械决定论","B. 否认因果区别的诡辩论","C. 唯心主义非决定论","D. 唯物主义决定论"],"ans":2,"explain":"“在自然界中没有原因也没有结果，因果律的一切形式都是从主观意向当中产生的”，这种观点属于唯心主义非决定论"},{"id":"mk15044-pl-P1527777","type":"sc","tier":"基础","conf":"adapt","chap":"第1章","q":"在唯物辩证法的基本范畴中，本质和现象反映了（ ）。","opts":["A. 事物之间引起和被引起的关系","B. 事物的内在要素和结构方式的关系","C. 事物过去、现在和将来的关系","D. 事物的根本性质和表面特征的关系"],"ans":3,"explain":"本质是指事物的根本性质以及组成事物基本要素的内在联系，现象是指事物的表面特征以及这些特征的外部联系。所以本质和现象反映的是事物的根本性质和表面特征的关系。"},{"id":"mk15044-pl-P1527778","type":"sc","tier":"基础","conf":"adapt","chap":"第1章","q":"在唯物辩证法的基本范畴中，内容和形式反映了（ ）。","opts":["A. 事物之间引起和被引起的关系","B. 事物的内在要素和结构方式间的关系","C. 事物过去、现在和将来的关系","D. 事物的根本性质和表面特征间的关系"],"ans":1,"explain":"内容是指构成事物一切要素的总和，即事物的各种内在矛盾以及由这些矛盾所决定的事物的特性、成分、运动过程和发展的趋势等的总和，形式是指把内容诸要素统一起来的结构或表现内容的方式。所以内容和形式是反映事物的内在要素和结构方式间的关系。"},{"id":"mk15044-pl-P1527780","type":"sc","tier":"基础","conf":"adapt","chap":"第1章","q":"“沉舟侧畔千帆过，病树前头万木春”这句诗包含的哲学道理是（）","opts":["A. 矛盾是事物发展的动力","B. 事物是本质和现象的统一","C. 事物的发展是量变和质变的统一","D. 新事物代替旧事物是事物发展的总趋势"],"ans":3,"explain":"“沉舟侧畔千帆过，病树前头万木春”这句诗包含的哲学道理是新事物代替旧事物是事物发展的总趋势。"},{"id":"mk15044-pl-P1527781","type":"sc","tier":"基础","conf":"adapt","chap":"第1章","q":"1958年，我们只看到麻雀吃粮食，而没有看到麻雀大量捕食害虫能保护庄稼和树木，于是大规模捕杀麻雀，造成了一些地方虫灾泛滥，（）","opts":["A. 只看到事物的客观性，没有看到人们的主观能动性","B. 只看到事物的绝对运动，没有看到事物的相对静止","C. 只看到眼前的直接联系，没有看到长远的间接联系","D. 只看到物与物的联系，没有看到人与物的联系"],"ans":2,"explain":"把握联系的复杂多样性，要特别注意避免只看到直接联系而忽视间接联系的片面性倾向。人们为了追求眼前的经济利益，从事一些破坏生态环境的活动，往往是因为只看到直接联系，忽视了间接联系。比如，1958年，我们只看到麻雀吃粮食，而没有看到麻雀大量捕食害虫能保护庄稼和树木，于是大规模捕杀麻雀，造成一些地方虫灾泛滥。又如，人们为了获得经济利益，或为了保护自己的家畜家禽，大量捕杀蛇、鹰、狐狸、黄鼠狼等，这些动物被消灭殆尽，结果鼠患成灾。这种只见直接联系不见间接联系的急功近利的狭隘功利主义，给人类带来巨大的灾难，应当引起我们的警觉。"},{"id":"mk15044-pl-P1527782","type":"sc","tier":"基础","conf":"adapt","chap":"第1章","q":"辩证法和形而上学的区别在于如何回答（ ）。","opts":["A. 世界的本质是什么的问题","B. 世界可否被认识的问题","C. 世界的存在是怎样的问题","D. 世界有否统一性的问题"],"ans":2,"explain":"辩证法和形而上学这两种根本对立的发展观，是关于世界如何存在的两种根本不同的观点。辩证法认为这个世界的存在方式是绝对运动和相对静止的统一，形而上学则认为这个世界是绝对静止的、不变的。"},{"id":"mk15044-pl-P1527784","type":"sc","tier":"基础","conf":"adapt","chap":"第1章","q":"唯物辩证法的实质和核心是（）","opts":["A. 内容决定形式的规律","B. 否定之否定规律","C. 质量互变规律","D. 对立统一规律"],"ans":3,"explain":"对立统一规律是唯物辩证法的实质与核心，是宇宙的根本规律。"},{"id":"mk15044-pl-P1527785","type":"sc","tier":"基础","conf":"adapt","chap":"第1章","q":"事物发展的实质是（）","opts":["A. 事物数量的增加和减少","B. 事物简单的重复和循环","C. 新事物的产生和旧事物的灭亡","D. 物体的位置变动和场所变更"],"ans":2,"explain":"发展的实质是新事物的产生和旧事物的灭亡。"},{"id":"mk15044-pl-P1527786","type":"sc","tier":"基础","conf":"adapt","chap":"第1章","q":"否定之否定规律揭示了（ ）。","opts":["A. 事物发展的动力和源泉","B. 事物发展的状态和形式","C. 事物发展的趋势和道路","D. 事物发展的内因和外因"],"ans":2,"explain":"否定之否定规律揭示了事物发展的趋势和道路。"},{"id":"mk15044-pl-P1527787","type":"sc","tier":"基础","conf":"adapt","chap":"第1章","q":"揭示了事物发展的趋势和道路的是（）","opts":["A. 矛盾对立统一规律","B. 质量互变规律","C. 否定之否定规律","D. 其他范畴"],"ans":2,"explain":"揭示了事物发展的趋势和道路的是否定之否定规律"},{"id":"mk15044-pl-P1527788","type":"sc","tier":"基础","conf":"adapt","chap":"第1章","q":"联系的观点和发展的观点是（ ）。","opts":["A. 马克思主义的理论品质","B. 唯物辩证法的总特征","C. 马克思主义的活的灵魂","D. 唯物辩证法的实质和核心"],"ans":1,"explain":"联系的观点和发展的观点是唯物辩证法的总特征（2大特征）。"},{"id":"mk15044-pl-P1527789","type":"sc","tier":"基础","conf":"adapt","chap":"第1章","q":"唯物辩证法的总特征是（）","opts":["A. 量变和质变的观点","B. 辩证否定的观点","C. 联系和发展的观点","D. 对立统一的观点"],"ans":2,"explain":"联系的观点和发展的观点是唯物辩证法的总特征。"},{"id":"mk15044-pl-P1527790","type":"sc","tier":"基础","conf":"adapt","chap":"第1章","q":"联系的客观性和普遍性原理的方法论意义在于（ ）","opts":["A. 要求我们用联系的观点看世界","B. 它是认识事物本质的基础","C. 它是科学分门别类的客观依据","D. 它是正确区分不同事物的基础"],"ans":0,"explain":"联系的客观性和普遍性原理的方法论意义在于要求我们用联系的观点看世界"},{"id":"mk15044-pl-P1527791","type":"sc","tier":"基础","conf":"adapt","chap":"第1章","q":"下列不属于联系的特征是（）","opts":["A. 客观性","B. 普遍性","C. 心理性","D. 多样性"],"ans":2,"explain":"联系的特点：①客观性；②普遍性；③多样性。"},{"id":"mk15044-pl-P1527792","type":"sc","tier":"基础","conf":"adapt","chap":"第1章","q":"下列观点中表述唯物辩证法总特征的是（ ）。","opts":["A. 量变和质变的观点","B. 对立统一的观点","C. 联系和发展的观点","D. 辩证否定的观点"],"ans":2,"explain":"联系和发展的观点是唯物辩证法总特征。"},{"id":"mk15044-pl-P1527793","type":"sc","tier":"基础","conf":"adapt","chap":"第1章","q":"唯物辩证法认为，联系是指事物之间以及事物内部诸要素之间的（）","opts":["A. 主要和次要的联系","B. 本质的和必然的联系","C. 相互对立、排斥和否定的关系","D. 相互影响、作用、制约的关系"],"ans":3,"explain":"联系是指事物之间以及事物内部诸要素之间的相互影响、相互作用和相互制约。"},{"id":"mk15044-pl-P1527794","type":"sc","tier":"基础","conf":"adapt","chap":"第1章","q":"判断一个事物是否是新事物还是旧事物，根据（）","opts":["A. 时间上出现的先后","B. 形式是否新奇","C. 力量是否强大","D. 是否符合事物发展的趋势"],"ans":3,"explain":"判断一个事物是否是新事物还是旧事物，根据是否符合事物发展的趋势"},{"id":"mk15044-pl-P1527795","type":"sc","tier":"基础","conf":"adapt","chap":"第1章","q":"新生事物是不可战胜的，区分新旧事物的根本标志在于它是否（）","opts":["A. 在新的历史条件下出现","B. 具有新的形式和新的特点","C. 得到绝大多数人的承认","D. 符合事物发展的必然趋势，具有强大的生命力"],"ans":3,"explain":"区分新旧事物的根本标志在于它是否符合事物发展的必然趋势，是否具有强大的生命力和远大的发展前途。"},{"id":"mk15044-pl-P1527796","type":"sc","tier":"基础","conf":"adapt","chap":"第1章","q":"下列各项属于主观臆想联系的是（ ）。","opts":["A. 汽车尾气的大量排放造成空气严重污染","B. 过度毁林开荒导致严重水土流失","C. 人的生辰八字决定其一生命运","D. 人的社会环境影响其一生命运"],"ans":2,"explain":"人的生辰八字决定其一生命运属于主观臆想。"},{"id":"mk15044-pl-P1527797","type":"sc","tier":"基础","conf":"adapt","chap":"第1章","q":"事物联系与发展的基本环节是（）","opts":["A. 矛盾对立统一规律","B. 质量互变规律","C. 否定之否定规律","D. 其他范畴"],"ans":3,"explain":"唯物辩证法的其他范畴揭示了事物联系和发展的基本环节。"},{"id":"mk15044-pl-P1527798","type":"sc","tier":"基础","conf":"adapt","chap":"第1章","q":"唯物辩证法的总特征有两个，一个是联系的观点，另一个是（ ）。","opts":["A. 发展的观点","B. 对立统一的观点","C. 实践的观点","D. 辩证否定的观点"],"ans":0,"explain":"唯物辩证法的总特征有两个：联系的观点和发展的观点。"},{"id":"mk15044-pl-P1527799","type":"sc","tier":"基础","conf":"adapt","chap":"第1章","q":"“世界不是即成的事物的集合体，而是过程的集合体”，这是一种（）","opts":["A. 唯物辩证法的观点","B. 唯心主义的观点","C. 形而上学的观点","D. 相对主义的观点"],"ans":0,"explain":"唯物辩证法认为，事物之间既相互联系又相互区别，事物的相互联系与相互区别是互为前提的。任何事物都有它不同于其他事物的特殊本质，因而是与其他事物相区别的；同时，任何事物都不是孤立存在的，总是同其他事物联系在一起的。"},{"id":"mk15044-pl-P1527801","type":"sc","tier":"基础","conf":"adapt","chap":"第1章","q":"唯物辩证法提供的最根本的认识方法是（ ）。","opts":["A. 逻辑分析法","B. 阶级分析法","C. 矛盾分析法","D. 精神分析法"],"ans":2,"explain":"唯物辩证法提供的最根本的认识方法是矛盾分析法。"},{"id":"mk15044-pl-P1527803","type":"sc","tier":"基础","conf":"adapt","chap":"第1章","q":"唯物辩证法与形而上学根本对立和斗争的焦点在于，是否承认（ ）。","opts":["A. 联系具有复杂多样性","B. 新事物必然战胜旧事物","C. 质变是量变的必然结果","D. 矛盾是事物发展的动力"],"ans":3,"explain":"唯物辩证法与形而上学根本对立和斗争的焦点在于，是否承认矛盾是事物发展的动力。"},{"id":"mk15044-pl-P1527804","type":"sc","tier":"基础","conf":"adapt","chap":"第1章","q":"从小脱离社会、在狼群中生存的“狼孩”没有意识，这一事实说明（ ）。","opts":["A. 意识是生物长期进化的结果","B. 意识是社会的产物","C. 意识是人脑的机能","D. 意识是人脑对客观世界的反映"],"ans":1,"explain":"“狼孩”说明意识是社会的产物，从起源上来说，人类意识是社会性的劳动创造。"},{"id":"mk15044-pl-P1527805","type":"sc","tier":"基础","conf":"adapt","chap":"第1章","q":"下列说法中，属于正确发挥人的主观能动性的是（ ）。","opts":["A. 人有多大胆，地有多大产","B. 不怕做不到，就怕想不到","C. 纸上谈兵，画饼充饥","D. 量力而行，尽力而为"],"ans":3,"explain":"“量力而行，尽力而为”是正确发挥人的主观能动性的表现。"},{"id":"mk15044-pl-P1527806","type":"sc","tier":"基础","conf":"adapt","chap":"第1章","q":"划分唯物主义和唯心主义的唯一标准是，是否承认（ ）。","opts":["A. 世界的统一性和多样性","B. 联系的客观性和普遍性","C. 物质第一性意识第二性","D. 思维和存在具有同一性"],"ans":2,"explain":"划分唯物主义和唯心主义的唯一标准是，是否承认物质第一性意识第二性。"},{"id":"mk15044-pl-P1527807","type":"sc","tier":"基础","conf":"adapt","chap":"第1章","q":"下列关于意识起源的正确说法是（ ）。","opts":["A. 意识是主观自生的","B. 意识是自然界长期发展的产物","C. 意识是人脑的机能","D. 意识是客观世界的主观映像"],"ans":1,"explain":"马克是主义认为意识是自然界长期发展的产物。"},{"id":"mk15044-pl-P1527808","type":"sc","tier":"基础","conf":"adapt","chap":"第1章","q":"马克思主义认为，正像个人的成长史再现着整个人类的成长史一样，个人的认识史也再现着整个人类的认识史，意识的起源和认识的起源是（）","opts":["A. 相似的","B. 一致的","C. 同一的","D. 复杂的"],"ans":1,"explain":"马克思主义认为，正像个人的成长史再现着整个人类的成长史一样，个人的认识史也再现着整个人类的认识史，意识的起源和认识的起源是一致的"},{"id":"mk15044-pl-P1527809","type":"sc","tier":"基础","conf":"adapt","chap":"第1章","q":"能够坚持彻底唯物主义一元论的是（）","opts":["A. 庸俗唯物主义","B. 辩证唯物主义","C. 机械唯物主义","D. 朴素唯物主义"],"ans":1,"explain":"能够坚持彻底唯物主义一元论的是辩证唯物主义。"},{"id":"mk15044-pl-P1527810","type":"sc","tier":"基础","conf":"adapt","chap":"第1章","q":"在客观规律面前，人的主观能动性表现在（ ）","opts":["A. 人可以改变规律","B. 人可以创造规律","C. 人可以消灭规律","D. 人可以认识和利用规律"],"ans":3,"explain":"认识和利用客观规律必须充分发挥人的主观能动性"},{"id":"mk15044-pl-P1527811","type":"sc","tier":"基础","conf":"adapt","chap":"第1章","q":"实现意识对物质反作用的根本途径是（ ）","opts":["A. 研究历史资料","B. 参加社会实践","C. 学习书本知识","D. 进行社会调查"],"ans":1,"explain":"实现意识能动作用的根本途径是人的社会实践。"},{"id":"mk15044-pl-P1527812","type":"sc","tier":"基础","conf":"adapt","chap":"第1章","q":"实现意识能动作用的根本途径是（ ）。","opts":["A. 学习科学理论","B. 投身社会实践","C. 了解实际情况","D. 制定周密计划"],"ans":1,"explain":"实现意识能动作用的根本途径是实践。"},{"id":"mk15044-pl-P1527814","type":"sc","tier":"基础","conf":"adapt","chap":"第1章","q":"在意识的问题上，唯心主义的错误在于（ ）。","opts":["A. 忽视意识的主观特征","B. 抹煞意识的主观特征","C. 夸大意识的能动作用","D. 否认意识的能动作用"],"ans":2,"explain":"唯心主义认为意识决定物质，夸大了意识的能动作用。"},{"id":"mk15044-pl-P1527815","type":"sc","tier":"基础","conf":"adapt","chap":"第1章","q":"意识的能动性最突出的表现是，意识活动（ ）。","opts":["A. 具有目的性和计划性","B. 能通过指导实践改造世界","C. 具有主动性和创造性","D. 能影响人的生理活动"],"ans":1,"explain":"选项中ABCD都属于意识的能动性的表现，而意识的能动性的最突出表现是在于意识能够通过指导实践改造世界。"},{"id":"mk15044-pl-P1527816","type":"sc","tier":"基础","conf":"adapt","chap":"第1章","q":"意识对于人的生理活动具有一定影响作用，这表明（ ）。","opts":["A. 意识对物质具有能动性","B. 意识是客观事物本身","C. 意识对物质具有决定性","D. 意识是人脑的机能"],"ans":0,"explain":"意识的能动性表现在四个方面：（1）具有目的性和计划性；（2）具有主动性、创造性；（3）对人的生理活动有一定的影响；（4）通过指导实践改造客观物质世界。"},{"id":"mk15044-pl-P1527817","type":"sc","tier":"基础","conf":"adapt","chap":"第1章","q":"马克思主义认为实践是（）","opts":["A. 纯主观、纯精神的活动","B. 日常生活的活动","C. 主观见之于客观的活动","D. 利己主义的活动"],"ans":2,"explain":"实践是人们改造客观世界的物质活动，是主观见之于客观的活动。"},{"id":"mk15044-pl-P1527821","type":"sc","tier":"基础","conf":"adapt","chap":"第1章","q":"作为认识和实践活动的承担者，认识主体所具有的突出特点（ ）。","opts":["A. 能动性","B. 社会性","C. 历史性","D. 客观性"],"ans":0,"explain":"作为认识和实践活动的承担者，认识主体所具有的突出特点是能动性。"},{"id":"mk15044-pl-P1527822","type":"sc","tier":"基础","conf":"adapt","chap":"第1章","q":"规律的两个特点是（ ）。","opts":["A. 客观性和普遍性","B. 客观性和历史性","C. 普遍性和持久性","D. 普遍性和自觉性"],"ans":0,"explain":"规律的两个特点是客观性和普遍性。"},{"id":"mk15044-pl-P1527823","type":"sc","tier":"基础","conf":"adapt","chap":"第1章","q":"“天行有常，不为尧存，不为桀亡。”这是说（ ）。","opts":["A. 规律仅仅存在于自然界","B. 规律是无法认识和把握的","C. 规律不具有客观普遍性","D. 规律不以人的意志为转移"],"ans":3,"explain":"规律是事物发展过程中本质的、必然的、稳定的、不以人的意志为转移的。选项中其他说法都是错误的。"},{"id":"mk15044-pl-P1527824","type":"sc","tier":"基础","conf":"adapt","chap":"第1章","q":"在客观规律面前，人的主观能动性的表现是（ ）。","opts":["A. 人可以创造规律","B. 人可以消灭规律","C. 人可以改变规律","D. 人可以认识和利用规律"],"ans":3,"explain":"人的主观能动性的表现在人可以认识和利用规律改造世界。"},{"id":"mk15044-pl-P1527825","type":"sc","tier":"基础","conf":"adapt","chap":"第1章","q":"（ ）是我们党的根本思想方法、工作方法和领导方法，是党带领人民推动中国革命、建设和改革事业不断取得胜利的重要法宝。","opts":["A. 解放思想","B. 理论联系实际","C. 求真务实","D. 实事求是"],"ans":3,"explain":"实事求是是中国共产党人认识世界和改造世界的根本要求，是我们党的根本思想方法、工作方法和领导方法，是党带领人民推动中国革命、建设和改革事业不断取得胜利的重要法宝。"},{"id":"mk15044-pl-P1527826","type":"sc","tier":"基础","conf":"adapt","chap":"第1章","q":"实践作为一种感性物质活动，强调的是（ ）。","opts":["A. 实践具有客观物质性","B. 实践具有主观性","C. 实践具有能动性","D. 实践具有历史性"],"ans":0,"explain":"客观性、主观能动性和社会历史性是实践的三个基本特点，其中客观性表明实践是客观的感性物质活动。"},{"id":"mk15044-pl-P1527828","type":"sc","tier":"基础","conf":"adapt","chap":"第1章","q":"下列选项中，属于最基本的实践活动是（）","opts":["A. 农民科学种田，为人们提供丰富的食品","B. 医生医治人们的疾病","C. 教师向学生传授知识","D. 科学家对大气环境进行检测"],"ans":0,"explain":"物质生产实践是处理人与自然关系的活动，是最基本的实践活动。物质生产实践解决人类生存和发展所必需的衣、食、住、行的问题，是决定其他一切实践活动产生和发展的前提。"},{"id":"mk15044-pl-P1527829","type":"sc","tier":"基础","conf":"adapt","chap":"第1章","q":"与辩证唯物主义认识论相比较，旧唯物主义认识论有两个缺陷，一个是缺乏辩证法的观点，另一个是（ ）。","opts":["A. 缺乏实践的观点","B. 缺乏反映论的观点","C. 缺乏一元论的观点","D. 缺乏可知论的观点"],"ans":0,"explain":"与辩证唯物主义认识论相比较，旧唯物主义认识论有两个缺陷，一个是缺乏辩证法的观点，另一个是缺乏实践的观点。"},{"id":"mk15044-pl-P1527830","type":"sc","tier":"基础","conf":"adapt","chap":"第1章","q":"马克思主义认为，实践是人类社会产生、存在和发展的基础，社会生活在本质上是（）","opts":["A. 客观的","B. 现实的","C. 物质的","D. 实践的"],"ans":3,"explain":"“社会生活在本质上是实践的”这一思想的确立，使马克思主义哲学克服了旧唯物主义不彻底性的缺陷，把唯物主义贯彻到社会历史领域，科学地说明了社会的物质性。"},{"id":"mk15044-pl-P1527831","type":"sc","tier":"基础","conf":"adapt","chap":"第1章","q":"马克思主义认为，社会生活在本质上是（ ）。","opts":["A. 丰富的","B. 发展的","C. 精神的","D. 实践的"],"ans":3,"explain":"马克思主义认为，社会生活在本质上是实践的，实践是人类社会产生、存在、发展的基础。"},{"id":"mk15044-pl-P1527832","type":"sc","tier":"基础","conf":"adapt","chap":"第1章","q":"马克思主义认为，一切社会历史的第一个前提是（）","opts":["A. 地理环境的存在","B. 一定数量人口的存在","C. 生产精神生活资料的实践","D. 生产物质生活资料的实践"],"ans":3,"explain":"马克思主义认为，生产物质生活资料的实践是一切社会历史的第一个前提。"},{"id":"mk15044-pl-P1527833","type":"sc","tier":"基础","conf":"adapt","chap":"第1章","q":"马克思主义认为社会生活在本质上是实践的，这是因为（ ）","opts":["A. 实践主体处于一定的社会关系中","B. 实践具有客观性、能动性和社会历史性","C. 实践是个人日常生活的活动","D. 实践是人类社会产生、存在和发展的基础"],"ans":3,"explain":"马克思主义认为，实践是人类社会产生、存在和发展的基础，是社会生活的本质。"},{"id":"mk15044-pl-P1527835","type":"sc","tier":"基础","conf":"adapt","chap":"第1章","q":"“白马非马”这一诡辩命题的错误在于割裂了（ ）。","opts":["A. 现象和本质的联系","B. 局部和整体的联系","C. 个别和一般的联系","D. 量变和质变的联系"],"ans":2,"explain":"“白马非马”这一诡辩命题的错误在于割裂了个别和一般的联系。"},{"id":"mk15044-pl-P1527836","type":"sc","tier":"基础","conf":"adapt","chap":"第1章","q":"“存在就是被感知”的观点属于（）","opts":["A. 主观唯心主义","B. 客观唯心主义","C. 形而上学唯物主义","D. 辩证唯物主义"],"ans":0,"explain":"“存在就是被感知”的观点属于主观唯心主义。"},{"id":"mk15044-pl-P1527837","type":"sc","tier":"基础","conf":"adapt","chap":"第1章","q":"“人有多大胆，地有多大产；不怕办不到，就怕想不到。”这体现的是（ ）。","opts":["A. 辩证唯物主义思想","B. 机械唯物主义思想","C. 主观唯心主义思想","D. 客观唯心主义思想"],"ans":2,"explain":"“人有多大胆，地有多大产；不怕办不到，就怕想不到。”这体现的是主观唯心主义思想，夸大了思维的主观能动作用。"},{"id":"mk15044-pl-P1527839","type":"sc","tier":"基础","conf":"adapt","chap":"第1章","q":"时间和空间既是绝对的、无限的，也是相对的、有限的。这是一种（ ）。","opts":["A. 诡辩论的观点","B. 辩证唯物主义的观点","C. 实用至受的观点","D. 形而上学的观点"],"ans":1,"explain":"“时间和空间既是绝对的、无限的，也是相对的、有限的。”是辩证唯物主义的观点。"},{"id":"mk15044-pl-P1527840","type":"sc","tier":"基础","conf":"adapt","chap":"第1章","q":"对世界存在状态问题的不同回答所区分的哲学派别是（ ）。","opts":["A. 可知论和不可知论","B. 反映论和先验论","C. 辩证法和形而上学","D. 唯物主义和唯心主义"],"ans":2,"explain":"辩证法和形而上学这两种根本对立的发展观，是关于世界如何存在的两种根本不同的观点。"},{"id":"mk15044-pl-P1527841","type":"sc","tier":"基础","conf":"adapt","chap":"第1章","q":"划分唯物主义和唯心主义的标准是看他是否承认（）","opts":["A. 世界是普遍联系的","B. 世界是运动发展的","C. 世界是物质的","D. 世界是统一的"],"ans":2,"explain":"辩证唯物主义和历史唯物主义不仅肯定世界是物质的，而且认为物质是运动、变化、发展的。"},{"id":"mk15044-pl-P1527842","type":"sc","tier":"基础","conf":"adapt","chap":"第1章","q":"辩证唯物主义认为，物质的唯一特性是（ ）。","opts":["A. 广延性","B. 持续性","C. 客观实在性","D. 可知性"],"ans":2,"explain":"辩证唯物主义认为，物质的唯一特性是客观实在性。"},{"id":"mk15044-pl-P1527843","type":"sc","tier":"基础","conf":"adapt","chap":"第1章","q":"承认世界的统一性的哲学都属于（ ）。","opts":["A. 一元论","B. 二元论","C. 唯物论","D. 唯心论"],"ans":0,"explain":"承认世界的统一性，认为世界上的万事万物有一个共同的本质或本原，这种哲学就是一元论。"},{"id":"mk15044-pl-P1527844","type":"sc","tier":"基础","conf":"adapt","chap":"第1章","q":"对思维与存在的同一性问题的不同回答区分了（ ）。","opts":["A. 唯物主义和唯心主义","B. 辩证法和形而上学","C. 可知论和不可知论","D. 反映论和先验论"],"ans":2,"explain":"对思维与存在的同一性问题的不同回答区分了可知论和不可知论。"},{"id":"mk15044-pl-P1527845","type":"sc","tier":"基础","conf":"adapt","chap":"第1章","q":"把世界的本源归结为某一种或某几种具体的物质形态，这种观点属于（）","opts":["A. 朴素唯物主义观点","B. 庸俗唯物主义观点","C. 机械唯物主义观点","D. 辩证唯物主义观点"],"ans":0,"explain":"古代朴素唯物主义把世界的本质或本原归结为某一种或某几种具体的物质形态。"},{"id":"mk15044-pl-P1527846","type":"sc","tier":"基础","conf":"adapt","chap":"第1章","q":"认为水、火、土、气是世界的本原的哲学是（ ）。","opts":["A. 朴素唯物主义","B. 形而上学唯物主义","C. 辩证唯物主义","D. 庸俗唯物主义"],"ans":0,"explain":"古代朴素唯物主义认为水、火、土、气是世界的本原。"},{"id":"mk15044-pl-P1527847","type":"sc","tier":"基础","conf":"adapt","chap":"第1章","q":"金、银、铜、铁、铝等同金属的关系属于（ ）。","opts":["A. 部分与整体的关系","B. 个别与一般的关系","C. 现象与本质的关系","D. 形式与内容的关系"],"ans":1,"explain":"金、银、铜、铁、铝（个别）同金属（一般）的关系属于个别与一般的关系。"},{"id":"mk15044-pl-P1527848","type":"sc","tier":"基础","conf":"adapt","chap":"第1章","q":"肯定思维和存在具有同一性，这种观点属于（）","opts":["A. 辩证法","B. 形而上学","C. 唯心主义","D. 可知论"],"ans":3,"explain":"可知论：承认思维与存在的同一性，认为世界是可以认识的；"},{"id":"mk15044-pl-P1527850","type":"sc","tier":"基础","conf":"adapt","chap":"第1章","q":"客观实在性是（ ）。","opts":["A. 自然物质的个性","B. 一切物质的共性","C. 物质的具体形态","D. 物质的存在形式"],"ans":1,"explain":"客观实在性是一切物质的共性，是物质的唯一特性。"},{"id":"mk15044-pl-P1527852","type":"sc","tier":"基础","conf":"adapt","chap":"第1章","q":"设想没有运动的物质的观点是（）","opts":["A. 形而上学唯物主义","B. 庸俗唯物主义","C. 主观唯心主义","D. 客观唯心主义"],"ans":0,"explain":"设想没有运动的物质的观点是形而上学唯物主义。"},{"id":"mk15044-pl-P1527853","type":"sc","tier":"基础","conf":"adapt","chap":"第1章","q":"社会历史观的基本问题是（）","opts":["A. 生产力和生产关系的关系问题","B. 社会存在和社会意识的关系问题","C. 经济基础和上层建筑的关系问题","D. 唯物史观和唯心史观的关系问题"],"ans":1,"explain":"社会存在与社会意识的关系问题是社会历史观的基本问题。"},{"id":"mk15044-pl-P1527854","type":"sc","tier":"基础","conf":"adapt","chap":"第1章","q":"尽管主观唯心主义和客观唯心主义有这样那样的差别，但在本质上是一样，都主张（）","opts":["A. 世界是不可认识的","B. 物是感觉的集合","C. 物是“绝对精神”的体现","D. 世界统一于精神"],"ans":3,"explain":"神学唯心主义也是一种客观唯心主义。尽管主观唯心主义和客观唯心主义有这样那样的差别，但在本质上是一样的，都主张世界统一于精神。"},{"id":"mk15044-pl-P1527855","type":"sc","tier":"基础","conf":"adapt","chap":"第1章","q":"下列范畴中，反映人与人之间经济关系的是（ ）。","opts":["A. 生产力","B. 生产关系","C. 生产方式","D. 生产资料"],"ans":1,"explain":"生产关系反映的是人与人之间的经济关系。"},{"id":"mk15044-pl-P1527857","type":"sc","tier":"基础","conf":"adapt","chap":"第1章","q":"时间和空间既是绝对的、无限的，又是相对的、有限的。这是一种（ ）。","opts":["A. 诡辩论的观点","B. 辩证唯物主义的观点","C. 实用主义的观点","D. 形而上学的观点"],"ans":1,"explain":"时间和空间既是绝对的、无限的，又是相对的、有限的。这是一种辩证唯物主义的观点"},{"id":"mk15044-pl-P1527858","type":"sc","tier":"基础","conf":"adapt","chap":"第1章","q":"马克思主义哲学认为时间和空间是运动的物质的（）","opts":["A. 唯一属性","B. 整理认识材料的主观工具","C. 存在方式","D. 根本属性"],"ans":2,"explain":"时间和空间是物质运动的存在方式"},{"id":"mk15044-pl-P1527859","type":"sc","tier":"基础","conf":"adapt","chap":"第1章","q":"世界的本质问题，实质上是世界的（）","opts":["A. 物质性问题","B. 可知性问题","C. 统一性问题","D. 客观性问题"],"ans":2,"explain":"世界的本质问题实质上是世界的统一性问题。"},{"id":"mk15044-pl-P1527861","type":"sc","tier":"基础","conf":"adapt","chap":"第1章","q":"下列对世界观的定义正确的是（）","opts":["A. 世界观是人们对社会历史问题的总的看法","B. 世界观是人们对自然界的总的看法","C. 世界观是对人类生存和发展的总的看法","D. 世界观是人们对整个世界的根本观点和看法"],"ans":3,"explain":"世界观就是人们对包括自然、社会和人类思维在内的整个世界的根本看法和根本观点。"},{"id":"mk15044-pl-P1527862","type":"sc","tier":"基础","conf":"adapt","chap":"第1章","q":"世界观是（ ）。","opts":["A. 人们对整个世界的根本看法和观点","B. 人们对精神世界的根本看法和观点","C. 人们对物质世界的根本看法和观点","D. 人们对外部世界的根本看法和观点"],"ans":0,"explain":"世界观就是人们对包括自然、社会和人类思维在内的整个世界的根本看法和观点。"},{"id":"mk15044-pl-P1527863","type":"sc","tier":"基础","conf":"adapt","chap":"第1章","q":"动中有静，静中有动说的是（）","opts":["A. 前进行和曲折性的统一","B. 绝对运动和相对静止的统一","C. 物质和运动的统一","D. 连续性和非连续性的统一"],"ans":1,"explain":"世界上的事物都是绝对运动和相对静止的统一，是动中有静，静中有动。"},{"id":"mk15044-pl-P1527864","type":"sc","tier":"基础","conf":"adapt","chap":"第1章","q":"“绝对运动中包含着相对静止，相对静止中包含着绝对运动”，这是一种（ ）。","opts":["A. 相对主义诡辩论的观点","B. 唯物辩证法的观点","C. 形而上学的观点","D. 客观唯心主义的观点"],"ans":1,"explain":"唯物辩证法的观点认为“动中有静，静中有动”。"},{"id":"mk15044-pl-P1527865","type":"sc","tier":"基础","conf":"adapt","chap":"第1章","q":"唯物主义与唯心主义的区别在于如何回答（ ）。","opts":["A. 世界的本质是什么的问题","B. 世界可否被认识的问题","C. 世界的存在是怎样的问题","D. 世界统一性的问题"],"ans":0,"explain":"唯物主义和唯心主义的区别在于认为物质和意识何为世界本原，哪个是第一性的问题，其实就是世界的本质是什么的问题。"},{"id":"mk15044-pl-P1527866","type":"sc","tier":"基础","conf":"adapt","chap":"第1章","q":"物质的唯一特性是（）","opts":["A. 运动变化性","B. 客观实在性","C. 可知性","D. 广延性"],"ans":1,"explain":"物质的唯一特性是客观实在性。"},{"id":"mk15044-pl-P1527867","type":"sc","tier":"基础","conf":"adapt","chap":"第1章","q":"以下哪个是哲学的基本问题（）。","opts":["A. 物质和意识的关系问题","B. 物质和运动的关系问题","C. 物质和时间的关系问题","D. 物质和空间的关系问题"],"ans":0,"explain":"物质和意识的关系问题主要是回答世界的本质是什么以及世界可不可以认识的问题，它是哲学的基本问题，但不是哲学要研究的全部问题。"},{"id":"mk15044-pl-P1527868","type":"sc","tier":"基础","conf":"adapt","chap":"第1章","q":"物质资料的生产方式是（ ）。","opts":["A. 生产资料与消费资料的统一","B. 劳动资料与劳动对象的统一","C. 生产力与生产关系的统一","D. 劳动者与劳动工具的统一"],"ans":2,"explain":"物质资料的生产方式是生产力与生产关系的统一。"},{"id":"mk15044-pl-P1527869","type":"sc","tier":"基础","conf":"adapt","chap":"第1章","q":"哲学上的一元论就是承认（）","opts":["A. 世界是物质的","B. 世界在本质上是精神的","C. 世界是发展的","D. 世界是统一的"],"ans":3,"explain":"一元论是承认世界的统一性，认为世界上的万事万物有一个共同的本质或本原的哲学"},{"id":"mk15044-pl-P1527870","type":"sc","tier":"基础","conf":"adapt","chap":"第1章","q":"运动和静止的关系属于（ ）。","opts":["A. 必然和偶然的关系","B. 本质和现象的关系","C. 共性和个性的关系","D. 绝对和相对的关系"],"ans":3,"explain":"运动和静止的关系属于绝对和相对的关系。绝对运动和相对静止。"},{"id":"mk15044-pl-P1527871","type":"sc","tier":"基础","conf":"adapt","chap":"第1章","q":"哲学的基本问题是（ ）。","opts":["A. 物质和运动的关系问题","B. 物质和意识的关系问题","C. 运动和静止的关系问题","D. 实践和理论的关系问题"],"ans":1,"explain":"哲学的基本问题是物质和意识的关系问题，即物质和意识何为第一性问题。"},{"id":"mk15044-pl-P1527872","type":"sc","tier":"基础","conf":"adapt","chap":"第1章","q":"哲学基本问题第二方面内容主要回答的是（ ）。","opts":["A. 世界的本质是什么的问题","B. 世界可否被认识的问题","C. 世界的存在是怎样的问题","D. 世界有否统一性的问题"],"ans":1,"explain":"哲学基本问题第二方面内容主要回答的是世界可否被认识的问题"},{"id":"mk15044-pl-P1527873","type":"sc","tier":"基础","conf":"adapt","chap":"第1章","q":"哲学上的二元论否认（ ）。","opts":["A. 世界的统一性","B. 世界的物质性","C. 世界的可知性","D. 世界的多样性"],"ans":0,"explain":"哲学上的二元论否认世界的统一性。"},{"id":"mk15044-pl-P1527874","type":"sc","tier":"基础","conf":"adapt","chap":"第1章","q":"哲学上的一元论与二元论的区别在于是否承认（ ）。","opts":["A. 世界的物质性","B. 世界的统一性","C. 世界的可知性","D. 世界的多样性"],"ans":1,"explain":"哲学上的一元论与二元论的区别在于是否承认世界的统一性。"},{"id":"mk15044-pl-P1527875","type":"sc","tier":"基础","conf":"adapt","chap":"第1章","q":"马克思主义认为哲学是（）","opts":["A. 关于自然界和社会一般规律的科学","B. 科学的世界观和方法论","C. 系统化理论化的世界观","D. 革命化科学化的世界观"],"ans":2,"explain":"马克思主义认为哲学是系统化、理论化的世界观。"},{"id":"mk15044-pl-P1527876","type":"sc","tier":"基础","conf":"adapt","chap":"第1章","q":"“盛年不重来，一日难再晨”，这个谚语说的是（ ）。","opts":["A. 时间具有一维性","B. 物质运动具有持续性","C. 时间具有有限性","D. 物质运动具有顺序性"],"ans":0,"explain":"这句诗讲的是时间过去就不会再倒回，说明时间具有一维性，总是朝着一个方向发展，具有不可逆性。"},{"id":"mk15044-pl-P1527877","type":"sc","tier":"基础","conf":"adapt","chap":"第1章","q":"真理具有客观性，被称为客观真理，是因为（ ）。","opts":["A. 真理是事物发展的客观规律","B. 真理是对事物及其规律的正确反映","C. 真理是不依赖于意识的客观实在","D. 真理是大多数人承认的客观事实"],"ans":2,"explain":"真理具有客观性，被称为客观真理，是因为真理是不依赖于意识的客观实在。"},{"id":"mk15044-pl-P1527878","type":"sc","tier":"基础","conf":"adapt","chap":"第1章","q":"马克思主义的革命性既表现为它具有彻底的批判精神，又表现为它具有（ ）。","opts":["A. 完整的理论体系","B. 严密的逻辑结构","C. 鲜明的政治立场","D. 崇高的社会理想"],"ans":2,"explain":"马克思主义的革命性既表现为它具有彻底的批判精神，又表现为它具有鲜明的政治立场"},{"id":"mk15044-pl-P1527879","type":"sc","tier":"基础","conf":"adapt","chap":"第1章","q":"实践为基础的科学性和革命性的统一是马克主义的（）","opts":["A. 根本方法","B. 理论品质","C. 阶级基础","D. 理论特征"],"ans":3,"explain":"马克思主义的根本理论特征是以实践为基础的科学性和革命性的统一。"},{"id":"mk15044-pl-P1527881","type":"sc","tier":"基础","conf":"adapt","chap":"第1章","q":"马克思主义的根本理论特征是（ ）。","opts":["A. 科学性和革命性的统一","B. 逻辑性和历史性的统一","C. 自然观和历史观的统一","D. 世界观和方法论的统一"],"ans":0,"explain":"马克思主义的根本理论特征是以实践为基础的科学性和革命性的统一。"},{"id":"mk15044-pl-P1527882","type":"sc","tier":"基础","conf":"adapt","chap":"第1章","q":"“哲学家们只是用不同的方式解释世界，问题在于改变世界”的提出者（ ）","opts":["A. 黑格尔","B. 费尔巴哈","C. 马克思","D. 恩格斯"],"ans":2,"explain":"马克思主义具有鲜明的实践品格，不仅致力于科学‘解释世界’，而且致力于积极‘改变世界’。"},{"id":"mk15044-pl-P1527883","type":"sc","tier":"基础","conf":"adapt","chap":"第1章","q":"马克思主义是关于（）","opts":["A. 工人阶级和人类解放的学说","B. 无产阶级专政的学说","C. 反对资本主义的学说","D. 未来社会设想的学说"],"ans":0,"explain":"马克思主义是关于工人阶级和人类解放的科学这一对马克思主义的内涵的界定，就鲜明地体现了它的革命性与科学性相统一的基本特征。"},{"id":"mk15044-pl-P1527884","type":"sc","tier":"基础","conf":"adapt","chap":"第1章","q":"作为马克思主义出发点和归宿的基本观点是（）","opts":["A. 实践的观点","B. 唯物论的观点","C. 辩证法的观点","D. 可知论的观点"],"ans":0,"explain":"实践的观点是马克思主义的基本观点，是马克思主义的出发点和归宿。"},{"id":"mk15044-pl-P1527886","type":"sc","tier":"基础","conf":"adapt","chap":"第1章","q":"与时俱进是马克思主义的（ ）。","opts":["A. 理论特征","B. 理论核心","C. 理论品质","D. 理论前提"],"ans":2,"explain":"与时俱进是马克思主义的理论品质。"},{"id":"mk15044-pl-P1527887","type":"sc","tier":"基础","conf":"adapt","chap":"第1章","q":"1999年秋，英国广播公司（BBC）用几周时间在国际互联网评选千年“最伟大、最有影响的思想家”，经过反复斟酌，最后选定排在第一位的是（）","opts":["A. 牛顿","B. 达尔文","C. 马克思","D. 爱因斯坦"],"ans":2,"explain":"1999年秋，英国广播公司（BBC）用几周时间在国际互联网评选千年“最伟大、最有影响的思想家”，经过反复斟酌，最后选定排在第一位的是马克思。"},{"id":"mk15044-pl-P1527888","type":"sc","tier":"基础","conf":"adapt","chap":"第1章","q":"马克思主义是马克思，恩格斯共同创立的，之所以称马克思主义，是因为（）","opts":["A. 马克思比一般人站得高，看得远","B. 马克思是位天才人物","C. 马克思对马克思主义的创立起了主导作用","D. 马克思完成了全部理论的最后阐发"],"ans":2,"explain":"马克思对马克思主义的创立起了主导作用，但恩格斯对马克思主义的创立也做出了不可磨灭的贡献。"},{"id":"mk15044-pl-P1527889","type":"sc","tier":"基础","conf":"adapt","chap":"第1章","q":"马克思主义是一个具有内在逻辑联系的科学体系，其中处于核心地位的是（ ）。","opts":["A. 辩证唯物主义","B. 历史唯物主义","C. 政治经济学","D. 科学社会主义"],"ans":3,"explain":"马克思主义是一个具有内在逻辑联系的科学体系，其中处于核心地位的是科学社会主义，起到指引方向的道路的作用。"},{"id":"mk15044-pl-P1527890","type":"sc","tier":"基础","conf":"adapt","chap":"第1章","q":"在马克思主义科学体系中，作为世界观和方法论的是（ ）。","opts":["A. 马克思主义哲学","B. 马克思主义政治学","C. 马克思主义政治经济学","D. 科学社会主义"],"ans":0,"explain":"在马克思主义科学体系中，作为世界观和方法论的是马克思主义哲学。"},{"id":"mk15044-pl-P1527891","type":"sc","tier":"基础","conf":"adapt","chap":"第1章","q":"把马克思主义作为行动的指南，就是要（ ）。","opts":["A. 用马克思主义的立场、观点和方法研究解决实际问题","B. 从马克思主义经典著作中寻找解决现实问题的直接答案","C. 把马克思主义当作现成的公式裁剪历史事实","D. 一切从马克思主义的一般原理出发"],"ans":0,"explain":"把马克思主义作为行动的指南，就是要用马克思主义的立场、观点和方法研究解决实际问题（理论联系实际）。"},{"id":"mk15044-pl-P1527892","type":"sc","tier":"基础","conf":"adapt","chap":"第1章","q":"理论联系实际是（ ）。","opts":["A. 马克思主义理论特征","B. 学习马克思主义的目的","C. 马克思主义活的灵魂","D. 学习马克思主义的方法"],"ans":3,"explain":"理论联系实际是学习马克思主义的根本方法。"},{"id":"mk15044-pl-P1527893","type":"sc","tier":"基础","conf":"adapt","chap":"第1章","q":"理论联系实际是学习马克思主义的根本方法，这是由它的（）决定的","opts":["A. 实践性","B. 阶级性","C. 深刻性","D. 批判性"],"ans":0,"explain":"实践是马克思主义的基础，马克思主义源于实践并随着实践的发展而发展，它的科学性和旺盛的生命力的根源就在于它同实际紧密结合。"},{"id":"mk15044-pl-P1527894","type":"sc","tier":"基础","conf":"adapt","chap":"第1章","q":"树立正确的三观，掌握认识改造世界的方法和工具，全面提高人的素质是学习马克思主义的（）","opts":["A. 马克思主义理论特征","B. 学习马克思主义的目的","C. 马克思主义活的灵魂","D. 学习马克思主义的方法"],"ans":1,"explain":"树立正确的三观，掌握认识改造世界的方法和工具，全面提高人的素质是学习马克思主义的学习马克思主义的目的"},{"id":"mk15044-pl-P1527897","type":"sc","tier":"基础","conf":"adapt","chap":"第1章","q":"德国古典哲学是马克思主义的直接理论来源之一，其代表人物是（）","opts":["A. 培根、洛克","B. 圣西门、欧文","C. 黑格尔、费尔巴哈","D. 斯密、李嘉图"],"ans":2,"explain":"德国古典哲学代表人物是黑格尔和费尔巴哈。"},{"id":"mk15044-pl-P1527898","type":"sc","tier":"基础","conf":"adapt","chap":"第1章","q":"德国古典哲学是马克思主义哲学的直接理论来源。马克思恩格斯批判地吸取了黑格尔哲学的（）","opts":["A. 唯物主义思想","B. 辩证法思想","C. 可知论思想","D. 决定论思想"],"ans":1,"explain":"德国古典哲学是马克思主义哲学的直接理论来源。马克思恩格斯批判地吸取了黑格尔哲学的辩证法思想。"},{"id":"mk15044-pl-P1527899","type":"sc","tier":"基础","conf":"adapt","chap":"第1章","q":"马克思主义哲学的直接理论来源是（）","opts":["A. 古希腊罗马哲学","B. 德国古典哲学","C. 17世纪英国哲学","D. 18世纪法国唯物主义"],"ans":1,"explain":"对马克思主义的形成产生最直接、最重大影响的，是德国古典哲学、英国古典政治经济学和19世纪英法两国的空想社会主义学说，它们代表了到19世纪上半叶为止的人类思想的最高成就，是马克思主义的直接理论来源。"},{"id":"mk15044-pl-P1527900","type":"sc","tier":"基础","conf":"adapt","chap":"第1章","q":"在19世纪英法两国的空想社会主义学说中，把设想的未来社会称为“和谐制度”的是（）","opts":["A. 圣西门","B. 傅里叶","C. 欧文","D. 大卫李嘉图"],"ans":1,"explain":"傅里叶把设想的未来社会称为“和谐制度”，在这个制度下，人们和睦相处，全体社会成员的情欲都得到了充分的满足。"},{"id":"mk15044-pl-P1527902","type":"sc","tier":"基础","conf":"adapt","chap":"第1章","q":"马克思恩格斯所处的历史时代及其提出的各项任务，为马克思主义的产生提供了（ ）。","opts":["A. 主观条件","B. 客观条件","C. 理论基础","D. 理论前提"],"ans":1,"explain":"马克思恩格斯所处的历史时代及其提出的各项任务，为马克思主义的产生提供了客观条件。"},{"id":"mk15044-pl-P1527903","type":"sc","tier":"基础","conf":"adapt","chap":"第1章","q":"马克思主义是时代的产物。马克思、恩格斯所处的历史时代及其提出的各项任务，为马克思主义的产生提供了（ ）。","opts":["A. 主观条件","B. 客观条件","C. 理论基础","D. 理论前提"],"ans":1,"explain":"马克思主义产生的客观条件：马克思、恩格斯所处的历史时代及其提出的各项任务。"},{"id":"mk15044-pl-P1527905","type":"sc","tier":"基础","conf":"adapt","chap":"第1章","q":"马克思主义哲学以前欧洲哲学的全部积极内容，都是马克思主义哲学的理论来源，其中作为马克思主义哲学直接理论来源的是（ ）。","opts":["A. 古希腊罗马哲学","B. 德国古典哲学","C. 近代英国哲学","D. 近代法国哲学"],"ans":1,"explain":"马克思主义哲学的直接理论来源是德国古典哲学。"},{"id":"mk15044-pl-P1527906","type":"sc","tier":"基础","conf":"adapt","chap":"第1章","q":"英国古典经济学的代表人物是（ ）。","opts":["A. 培根和洛克","B. 黑格尔和费尔巴哈","C. 斯密和李嘉图","D. 圣西门和傅立叶"],"ans":2,"explain":"英国古典经济学的代表人物是亚当·斯密和大卫·李嘉图。"},{"id":"mk15044-pl-P1527907","type":"sc","tier":"基础","conf":"adapt","chap":"第1章","q":"下列哪项不属于对马克思主义产生影响的19世纪自然科学的三大发现（）","opts":["A. “细胞学说”","B. “能量守恒和转化定律”","C. “生物进化论”","D. “上帝神创论”"],"ans":3,"explain":"自然科学的三大发现：细胞学说、能量守恒和转化定律与生物进化论。"},{"id":"mk15044-pl-P1527908","type":"sc","tier":"基础","conf":"adapt","chap":"第1章","q":"作为马克思恩格斯一生最重要的理论发现，使社会主义从空想变成科学的是（ ）。","opts":["A. 唯物论和辩证法学说","B. 唯物论和劳动价值学说","C. 唯物史观和剩余价值学说","D. 唯物史观和阶级斗争学说"],"ans":2,"explain":"作为马克思恩格斯一生最重要的理论发现，使社会主义从空想变成科学的是唯物史观和剩余价值学说。"},{"id":"mk15044-pl-P1527909","type":"sc","tier":"基础","conf":"adapt","chap":"第1章","q":"作为马克思主义哲学直接理论来源是（ ）","opts":["A. 古希腊罗马哲学","B. 英国近代哲学","C. 法国百科全书派哲学","D. 德国古典哲学"],"ans":3,"explain":"作为马克思主义哲学直接理论来源是德国古典哲学"},{"id":"mk15044-pl-P1527910","type":"sc","tier":"基础","conf":"adapt","chap":"第1章","q":"《共产党宣言》的作者是（ ）。","opts":["A. 马克思、恩格斯","B. 列宁、斯大林","C. 卢森堡、拉法格","D. 毛泽东、朱德"],"ans":0,"explain":"《共产党宣言》的作者是马克思、恩格斯。"},{"id":"mk15044-pl-P1527911","type":"sc","tier":"基础","conf":"adapt","chap":"第1章","q":"关于马克思主义的产生，下列说法错误的是（ ）。","opts":["A. 马克思主义是历史时代的产物","B. 马克思主义是实践经验的总结","C. 马克思主义是科学成果的升华","D. 马克思主义是先天智慧的结晶"],"ans":3,"explain":"马克思主义既然是时代的产物、实践经验的总结、科学成果的升华，就必然会随着时代的变化、实践的扩展、科学的进步而不断丰富和发展其自身。"},{"id":"mk15044-pl-P1526503","type":"sa","tier":"创新","conf":"adapt","chap":"第1章","q":"简要回答马克思主义科学体系的三个组成部分及其直接理论来源。","opts":[],"ans":null,"explain":"(1)马克思主义哲学、马克思主义政治经济学和科学社会主义是马克思主义科学体系的主要组成部分。<br/>(2)德国古典哲学、英国古典政治经济学和19世纪英法两国的空想社会主义学说是马克思主义的直接理论来源。"},{"id":"mk15044-pl-P1526504","type":"sa","tier":"创新","conf":"adapt","chap":"第1章","q":"如何理解马克思主义的科学性和革命性是以实践性为基础的？","opts":[],"ans":null,"explain":"马克思主义的科学性和革命性都是以实践性为基础的。实践的观点是马克思主义的基本观点，是马克思主义的出发点和归宿。马克思主义来源于实践，是实践经验的概括和总结，又反过来指导工人阶级和广大人民群众改造世界的实践活动，为实践服务，并在实践中得到检验和发展。离开了无产阶级和广大人民群众的实践活动，马克思主义就成了无源之水、无本之木，就丧失了认识世界和改造世界的功能，就失去了存在的意义。"},{"id":"mk15044-pl-P1526505","type":"sa","tier":"创新","conf":"adapt","chap":"第1章","q":"简述马克思主义的社会理想与全国各族人民的共同理想的关系。","opts":[],"ans":null,"explain":"马克思主义的社会理想是推翻资本主义、实现社会主义和共产主义。走中国特色社会主义道路，把我国建设成为富强、民主、文明、和谐的社会主义现代化国家即全国各族人民的共同理想。二者既相互区别又相互联系，是辩证统一的关系。<br/>(1)共同理想是实现最高理想的必经阶段和必要基础。<br/>(2)实现共同理想，必须坚持以最高理想为根本方向。"},{"id":"mk15044-pl-P1526506","type":"sa","tier":"创新","conf":"adapt","chap":"第1章","q":"简述马克思主义是时代的产物的内涵。","opts":[],"ans":null,"explain":"马克思主义是时代的产物。马克思主义产生于资本主义社会化大生产已经成为主导趋势，资本主义社会内部各种社会矛盾和阶级矛盾充分显露，无产阶级以独立的政治力量登上历史舞台争取自身和人类解放的斗争的历史时代。<br/>(1)客观条件：工业革命的深入推动了资本主义的迅速发展，导致其内部矛盾的尖锐化，为马克思主义的诞生提供了客观条件。<br/>(2)阶级基础：工人阶级作为一支独立的政治力量登上历史舞台，进行反对资本主义制度和资产阶级统治的斗争，为马克思主义的诞生准备了阶级基础。总之，马克思主义是时代的产物，时代孕育了马克思主义，同时马克思主义的兴起和发展也开辟了新时代。"},{"id":"mk15044-pl-P1526507","type":"sa","tier":"创新","conf":"adapt","chap":"第1章","q":"简述学习马克思主义的目的。","opts":[],"ans":null,"explain":"人们的学习都是有目的的。学科的性质不同，学习的目的也不同。我们学习马克思主义的目的主要有以下几个方面：<br/>第一，树立正确的世界观、人生观、价值观。<br/>第二，掌握认识世界和改造世界的伟大工具。<br/>第三，全面提高人的素质。<br/>第四，指导中国特色社会主义伟大实践。"},{"id":"mk15044-pl-P1526508","type":"sa","tier":"创新","conf":"adapt","chap":"第1章","q":"简述联系的复杂多样性。","opts":[],"ans":null,"explain":"(1)事物内部或事物之间的具体联系是复杂多样的。事物联系的主要形式有：直接联系与间接联系，内部联系与外部联系，本质联系与非本质联系，必然联系与偶然联系等等。不同的联系对事物的存在和发展所起的作用是不同的。<br/>(2)认识事物联系的复杂多样性，对于我们观察和处理问题具有重要意义。<br/>①必须坚持全面的观点，尽可能地从各个方面把握事物的各种联系。<br/>②必须抓住事物中本质的、必然的联系，避免对不同的联系不分主次、甚至本末倒置的倾向。"},{"id":"mk15044-pl-P1526509","type":"sa","tier":"创新","conf":"adapt","chap":"第1章","q":"简述矛盾的特殊性的含义及其方法论意义。","opts":[],"ans":null,"explain":"(1)矛盾的特殊性有三种情况：<br/>①不同事物的矛盾各有其特点；<br/>②同一事物的矛盾在不同发展过程和发展阶段各有不同的特点；<br/>③构成事物的诸多矛盾以及每一矛盾的不同方面各有不同的性质、地位和作用。<br/>(2)矛盾的特殊性原理具有重要的方法论意义。分析矛盾的特殊性就是坚持具体问题具体分析。一方面，分析矛盾的特殊性是正确认识事物的基础。另一方面，分析矛盾的特殊性是正确解决矛盾的关键。"},{"id":"mk15044-pl-P1526510","type":"sa","tier":"创新","conf":"adapt","chap":"第1章","q":"简述新事物必将代替旧事物的原因。","opts":[],"ans":null,"explain":"新事物必然战胜旧事物，是由新旧事物的本质特点和事物发展的辩证本性决定的：<br/>(1)新事物符合事物发展的必然趋势，具有强大的生命力和远大的发展前途，而旧事物则不符合事物发展的必然趋势，丧失了其存在的必然性。<br/>(2)新事物优越于旧事物。<br/>(3)在社会历史领域内，新事物是社会上先进的、富有创造力的人们创造性活动的产物，它从根本上符合广大人民群众的利益和要求，因而能够得到广大人民群众的拥护和支持，它必然战胜旧事物。"},{"id":"mk15044-pl-P1526511","type":"sa","tier":"创新","conf":"adapt","chap":"第1章","q":"简述意识能动性的主要表现。","opts":[],"ans":null,"explain":"(1)意识活动具有目的性和计划性。<br/>(2)意识活动具有主动性、创造性。<br/>(3)意识对于人的生理活动具有一定影响作用。<br/>(4)意识能通过指导实践改造客观物质世界。"},{"id":"mk15044-pl-P1526512","type":"sa","tier":"创新","conf":"adapt","chap":"第1章","q":"简述事物的发展是前进性和曲折性的统一。","opts":[],"ans":null,"explain":"(1)否定之否定规律揭示了事物发展的总趋势是前进的、上升的。事物发展到否定之否定阶段，克服了前两个阶段（即肯定阶段和否定阶段）的局限性和片面性，保留了前两个阶段的积极因素，使事物得到充分发展和完善，因而事物发展的总趋势是前进的、上升的。<br/>(2)否定之否定规律揭示了事物发展的道路是曲折的。<br/>①否定之否定规律使事物的发展呈现出周期性，表现为螺旋式上升或波浪式前进的过程；<br/>②新事物战胜旧事物是一个反复斗争的过程。由于某些偶然原因的出现，事物的发展还可能有暂时的倒退。<br/>(3)事物的发展是前进性和曲折性的统一，如果割裂二者的统一，会导致循环论或直线论的错误。"},{"id":"mk15044-pl-P1527971","type":"sa","tier":"创新","conf":"adapt","chap":"第1章","q":"试述量变和质变辩证关系的原理及其现实意义。","opts":[],"ans":null,"explain":"量变是事物数量的增减和场所的变更，以及事物构成成分在空间上排列组合的变化；质变是事物由一种质态向另一种质态的飞跃。事物的变化是否超出度的范围，是区分质变和量变的根本标志。<br/>（1）量变和质变的辩证关系：量变是质变的必要准备；质变是量变的必然结果；质变和量变相互渗透的。<br/>（2）现实意义：我们在社会主义建设和改革开放过程中，既要有远大理想和奋斗目标，又要有步骤、分阶段地踏实苦干，稳步前进。急躁冒进、急于求成的结果，只能是事与愿违，欲速则不达。"},{"id":"mk15044-pl-P1527972","type":"sa","tier":"创新","conf":"adapt","chap":"第1章","q":"试述尊重客观规律和发挥主观能动性的辩证统一原理及其现实意义。","opts":[],"ans":null,"explain":"（1）原理：①尊重客观规律是正确发挥主动能动性的前提。只有正确认识了客观规律，并按规律办事，才能正确发挥人的主观能动性，有效地改造世界。无视或违背规律，盲目蛮干，必然受到规律的惩罚。<br/>②认识和利用客观规律又必须充分发挥人的主观能动性。只有充分发挥人的主观能动性，反复实践，深入研究，才能揭示隐藏在事物内部的规律，才能顺利实现理论与实践的指导。<br/>（2）现实意义：改革开放和现代化建设中，既要充分发挥人民群众的积极性和创造性，又要踏踏实实地按客观规律办事；既要实事求是，从实际出发，又要解放思想，开拓创新。"},{"id":"mk15044-pl-P1527973","type":"sa","tier":"创新","conf":"adapt","chap":"第1章","q":"试述矛盾的普遍性和特殊性辩证关系的原理，并说明这一原理对社会主义建设的重要意义。","opts":[],"ans":null,"explain":"（1）矛盾的普遍性和特殊性的关系，也就是共性与个性，一般与个别的关系，它们是辩证统一的。表现在：<br/>①矛盾普遍性与特殊性是互相联结的；<br/>②矛盾的普遍性与特殊性是互相区别的；<br/>③矛盾的普遍性与特殊性在一定条件下可以互相转化。<br/>（2）矛盾的普遍性与特殊性辩证关系的原理，是矛盾问题的精髓。这一原理要求我们在普遍原理的指导下，对具体问题进行具体分析，通过对具体问题的分析和解决，补充和丰富普遍原理。这一原理对我们有重要意义：<br/>①矛盾的普遍性和特殊性辩证关系的原理，是我们坚持马克思主义普遍真理同中国具体实际相结合，建设中国特色社会主义的理论基础。<br/>②在中国这样一个人口众多、经济文化落后的大国建设社会主义，是前无古人的崭新事业。我们面对的情况，既不是马克思主义创始人设想的在资本主义高度发展的基础上建设社会主义，也不完全相同于其他社会主义国家。照抄书本不行，照搬外国也不行，必须从中国的国情出发，把科学社会主义的一般原理同中国具体实际结合起来，在实践中开辟建设中国特色的社会主义道路。"},{"id":"mk15044-pl-P1527974","type":"sa","tier":"创新","conf":"adapt","chap":"第1章","q":"用内因和外因关系的原理说明我国坚持独立自主、自力更生和对外开放的重要意义。","opts":[],"ans":null,"explain":"<p>（1）内因就是事物的内部矛盾。外因是一事物与他事物的相互影响和相互作用，即外部矛盾。内因和外因的关系是：内因是事物发展变化的根据，外因是事物发展变化的条件，外因通过内因而起作用。这一原理是我国坚持独立自主、自力更生和对外开放方针的基础。</p><p>（2）我国的现代化建设，首先必须依靠本国人民，独立自主，自力更生，艰苦奋斗，只有这样才能建立起繁荣昌盛的社会主义强国。</p><p>（3）中国的发展离不开世界，对外开放是我国的一项基本国策。闭关自守只能导致愚昧落后。</p><p>（4）我国的对外开放是以独立自主、自力更生为基础的。</p>"},{"id":"mk15044-pl-P1527975","type":"sa","tier":"创新","conf":"adapt","chap":"第1章","q":"简述内容和形式的辩证关系。","opts":[],"ans":null,"explain":"任何现实事物都是内容和形式的统一体。内容与形式的关系是对立统一、相互作用的关系。<br/>（1）内容与形式是对立的统一。内容和形式是事物的内在要素和结构方式这两个不同方面，二者是有区别的，对立的。同时，内容与形式相互依存、密不可分。任何事物的内容都有一定的形式，任何形式都表现一定的内容。另外，内容和形式的区别和对立是相对的，在一定条件下，内容和形式可以相互转化。在某一种联系中是形式的东西，在另一种联系中可能成为内容，反过来也是一样。<br/>（2）内容和形式又是相互作用的。<br/>第一，内容决定形式，形式依赖于内容。有什么样的内容，就要求有什么样的形式与之相适应；内容发生了变化，形式或迟或早总要发生相应的变化。<br/>第二，形式对内容又有巨大的反作用。形式对内容的反作用有两种情形：当形式适合于内容时，对内容的发展起积极的促进作用；当形式不适合于内容时，对内容的发展起消极的阻碍作用。<br/>第三，内容和形式的相互作用构成两者的矛盾运动。"},{"id":"mk15044-pl-P1527976","type":"sa","tier":"创新","conf":"adapt","chap":"第1章","q":"简述必然性和偶然性的辩证关系。","opts":[],"ans":null,"explain":"（1）必然性是指事物联系和发展中一定要发生的、不可避免的趋势。偶然性是指事物联系和发展中不确定的趋势。必然性和偶然性是对立统一的关系。<br/>（2）二者是对立的它们是事物发展的两种不同趋势产生的原因以及在事物发展中的地位和作用不同。<br/>（3）二者是统一的其表现是：<br/>第一，必然性总是通过大量的偶然性表现出来由此为自己开辟道路没有脱离偶然性和纯粹必然性；<br/>第二，偶然性是必然性的表现形式和必要补充，偶然性背后隐藏着必然性，并受其制约，没有脱离必然性的纯粹偶然性；<br/>第三，必然性和偶然性可以在一定条件下互相转化。"},{"id":"mk15044-pl-P1527977","type":"sa","tier":"创新","conf":"adapt","chap":"第1章","q":"简述本质和现象的辩证关系","opts":[],"ans":null,"explain":"本质和现象之间的关系是对立统一关系。<br/>（1）本质和现象是相互区别相互对立的。<br/>（2）本质和现象又是相互联系、相互依存的。"},{"id":"mk15044-pl-P1527978","type":"sa","tier":"创新","conf":"adapt","chap":"第1章","q":"主要矛盾和次要矛盾，矛盾的主要方面和次要方面关系的原理，要求我们在实践工作中坚持两点论和重心论统一的原理及其现实意义。","opts":[],"ans":null,"explain":"<p>（1）坚持两点论，就是在认识复杂事物的发展过程时，既要看到主要矛盾，又不忽略矛盾的次要方面。</p><p>（2）坚持重点论，就是在认识复杂事物的发展过程时，要着重抓住主要矛盾；在研究某一矛盾时，要注重把握矛盾的主要方面。</p><p>（3）坚持两点论和重点论的统一，就是看问题、办事情既要全面，又要抓住重点。我国坚持以经济建设为中心和一系列“两手抓”的方针，就是坚持两点论和重点论统一的具体表现。认识我国改革开放和现代化建设的形式要分清主流和支流，既要抓住主流，坚定信心，又不忽略支流，认真解决存在的问题。</p>"},{"id":"mk15044-pl-P1527979","type":"sa","tier":"创新","conf":"adapt","chap":"第1章","q":"简述唯物辩证法与形而上学对立的主要表现。","opts":[],"ans":null,"explain":"唯物辩证法与形而上学对立的主要表现：<br/>（1）联系观点和孤立观点的对立。唯物辩证法认为世界上的一切事物都是相互联系的，主张用联系的观点看世界。形而上学认为世界上的事物都是彼此孤立的，它用孤立的观点看世界。<br/>（2）发展变化观点和静止不变观点的对立。唯物辩证法认为，一切事物都处于不停的运动、变化、发展过程中，主张用发展的观点看世界。形而上学认为世界上的事物在本质上是不变的，它用静止不变的观点看世界。<br/>（3）承认事物内部矛盾和否认事物内部矛盾的对立。唯物辩证法认为一切事物内部都包含着矛盾，矛盾是事物变化发展的根本原因。形而上学否认事物内部矛盾的存在，认为事物的变化是外力推动的结果。"},{"id":"mk15044-pl-P1527980","type":"sa","tier":"创新","conf":"adapt","chap":"第1章","q":"简述发挥主观能动性与尊重客观规律的关系。","opts":[],"ans":null,"explain":"意识的能动性和客观规律是在实践的基础上统一起来的。主观能动性的实现途径是人们的社会实践。要正确发挥人的主观能动性，必须充分认识二者的辩证统一关系：<br/>（1）尊重客观规律是正确发挥主观能动性的前提；<br/>（2）认识和利用客观规律又必须充分发挥人的主观能动性。"},{"id":"mk15044-pl-P1527981","type":"sa","tier":"创新","conf":"adapt","chap":"第1章","q":"简述意识的本质。","opts":[],"ans":null,"explain":"意识的本质：<br/>（1）意识是人脑的机能，人脑是意识的物质器官；<br/>（2）意识是客观世界的主观映象，是人脑对客观世界的反映；<br/>（3）意识是社会的产物。"},{"id":"mk15044-pl-P1527982","type":"sa","tier":"创新","conf":"adapt","chap":"第1章","q":"简述物质和意识的辩证关系以及唯心主义、形而上学唯物主义在这个问题上的错误。","opts":[],"ans":null,"explain":"（1）物质和意识的关系是：物质决定意识，物质是第一性，意识是第二性，意识对物质又有能动的反作用。<br/>（2）在物质和意识的关系问题上，唯心主义片面夸大意识的能动作用，否认物质对意识的决定作用；形而上学唯物主义肯定物质对意识的决定作用，但却忽视意识对物质的能动作用。"},{"id":"mk15044-pl-P1527983","type":"sa","tier":"创新","conf":"adapt","chap":"第1章","q":"试述意识的能动性及其主要表现。在实际工作中如何正确发挥人的主观能动性？","opts":[],"ans":null,"explain":"（1）意识的能动作用具体表现在：其一，意识活动具有创造性；其二，意识活动具有目的性和计划性；其三，意识活动对客观世界的改造作用，这是意识能动作用的最重要的表现；其四，意识对人的生理活动具有调节作用。<br/>（2）正确发挥意识的能动作用是有条件的，这种条件性的根本点在于要科学把握物质和意识的辩证关系，把意识的能动作用基于物质决定论的理论基础之上。具体为：<br/>其一，社会实践是发挥意识能动作用的唯一正确有效的途径；<br/>其二，要遵循客观规律。正确认识客观规律，按客观规律办事，是正确实践的前提，因而也是发挥意识能动性的前提；<br/>其三，发挥意识的能动性需要具备一定的物质技术条件。在任何工作、学习中，都必须以意识的能动性原理为依据，充分发挥主观能动性，这样才能深入解决工作、学习中的各种矛盾。在任何时候，发挥人的主观能动性必须注意客观物质条件的制约。"},{"id":"mk15044-pl-P1527984","type":"sa","tier":"创新","conf":"adapt","chap":"第1章","q":"简述规律的含义和特点。","opts":[],"ans":null,"explain":"规律就是物质运动发展过程中本质的、必然的、稳定的联系。规律的特点包栝：<br/>（1）客观性：指规律是运动着的事物本身所固有的，是不以任何人的意志为转移的。<br/>（2）普遍性：指规律不是只在个别的、特殊的事物和现象里起作用，而是在较大的范围和领域起作用。"},{"id":"mk15044-pl-P1527985","type":"sa","tier":"创新","conf":"adapt","chap":"第1章","q":"如何理解社会生活在本质上是实践的？","opts":[],"ans":null,"explain":"马克思主义认为，实践是人类社会产生、存在和发展的基础，是社会生活的本质。表现为：<br/>（1）劳动实践是人类和人类社会产生的决定性环节。<br/>（2）物质生产实践是人类社会得以存在的基础。<br/>（3）实践活动是推动社会发展的动力。"},{"id":"mk15044-pl-P1527986","type":"sa","tier":"创新","conf":"adapt","chap":"第1章","q":"什么是哲学基本问题？简述其内容和意义。","opts":[],"ans":null,"explain":"（1）思维和存在的关系问题或意识和物质的关系问题是哲学基本问题。它包括两方面的内容。第一方面是物质和意识何者为第一性的问题，即世界的本原是什么的问题。第二方面是思维和存在有无同一性的问题，即思维能不能认识存在、世界能不能被认识的问题。<br/>（2）掌握哲学基本问题具有重要的理论意义。如何正确回答哲学基本问题内容的第一方面，是划分唯物主义和唯心主义的标准。如何回答哲学基本问题的第二方面，是划分可知论和不可知论的标准。"},{"id":"mk15044-pl-P1527987","type":"sa","tier":"创新","conf":"adapt","chap":"第1章","q":"简述列宁的物质定义及其意义。","opts":[],"ans":null,"explain":"（1）列宁的物质定义是：“物质是标志客观实在的哲学范畴，这种客观实在是人通过感觉感知的，它不依赖于我们的感觉而存在，为我们的感觉所复写、摄影、反映。”简言之，物质是不依赖于意识并能为意识所反映的客观实在，物质的唯一特性是客观实在性。<br/>（2）意义：<br/>第一，它指出物质是不依赖于意识的客观实在，将辩证唯物主义同唯心主义划清了界限；<br/>第二，它指出物质是可以被人们认识的，将辩证唯物主义（可知论）同不可知论划清了界限；<br/>第三，它是指客观实在性是一切物质的共性，克服了旧唯物主义物质观的局限性。"},{"id":"mk15044-pl-P1527988","type":"sa","tier":"创新","conf":"adapt","chap":"第1章","q":"简述马克思主义的理论特征。","opts":[],"ans":null,"explain":"马克思主义的根本理论特征是以实践为基础的科学性和革命性的统一。（1）马克思主义的革命性；（2）马克思主义的科学性；（3）马克思主义的革命性和严格的科学性是紧密联系在一起的；（4）马克思主义的科学性和革命性都是以实践性为基础的。"},{"id":"mk15044-pl-P1527989","type":"sa","tier":"创新","conf":"adapt","chap":"第1章","q":"简述马克思主义的科学性与革命性的关系。","opts":[],"ans":null,"explain":"马克思主义哲学是以实践为基础的科学性和革命性的统一：<br/>（1）其科学性是指它既是建立在科学基础之上的，又是关于自然、社会和思维发展普遍规律的科学；<br/>（2）其革命性是指它是批判革命的，它把变革旧世界作为自己的任务和目的；<br/>（3）它在实践基础上实现了科学性和革命性的统一，科学性是革命性的必要前提和保证，革命性是科学性的必然结论和归宿。"},{"id":"mk15044-pl-P1527990","type":"sa","tier":"创新","conf":"adapt","chap":"第1章","q":"简述马克思主义的根本理论特征。","opts":[],"ans":null,"explain":"（1）马克思主义的根本理论特征是以实践为基础的科学性和革命性的统一。<br/>（2）马克思主义的革命性集中表现为它的彻底的批判精神。<br/>（3）马克思主义的科学性表现为它力求按照世界的本来面目如实的认识世界不带任何偏见，马克思主义的科学性还在于它的深刻性，对任何一个领域都不是浅尝辄止。<br/>（4）马克思主义的科学性和革命性都是以实践性为基础的实践的观点是马克思主义的基本观点，是马克思主义的出发点和归属。"},{"id":"mk15044-pl-P1527991","type":"sa","tier":"创新","conf":"adapt","chap":"第1章","q":"简述马克思主义的理论品质及其含义。","opts":[],"ans":null,"explain":"与时俱进是马克思主义的理论品质。与时俱进的含义：党的全部理论和工作要体现时代性，把握规律性，富于创造性。首先，与时俱进要求人们高瞻远瞩站在时代前列，使我们思想理论体现时代特点时代精神。其次，与时俱进要求我们以马克思主义的立场观点方法为指导，弘扬求真务实开拓进取的精神，不断深化对共产党执政规律，建设规律的认识为我们实际工作提供规律性指导。再次，与时俱进要求我们富有创造精神，适应新形势新任务要求，提出新理论开拓各项工作新局面。"},{"id":"mk15044-pl-P1527992","type":"sa","tier":"创新","conf":"adapt","chap":"第1章","q":"简述马克思主义科学体系的主要组成部分及其内在联系。","opts":[],"ans":null,"explain":"（1）马克思主义理论体系的三个主要组成部门是马克思主义哲学、马克思主义政治经济学、科学社会主义。<br/>（2）马克思主义的各个组成部分，是一个具有内在逻辑联系的科学体系，其中马克思主义哲学是科学的世界观和方法论，政治经济学是马克思主义的理论基础，处于核心地位的则是科学社会主义理论。"},{"id":"mk15044-pl-P1527993","type":"sa","tier":"创新","conf":"adapt","chap":"第1章","q":"简述马克思主义的科学内涵和理论品质。","opts":[],"ans":null,"explain":"（1）科学内涵：马克思主义是由马克思、恩格斯创立的，为他们的后继者所发展的，以反对资本主义、建设社会主义和共产主义为目标的科学的理论体系，或者简要地说，它是关于工人阶级和人类解放的科学。<br/>（2）理论品质：与时俱进"},{"id":"mk15044-pl-P1527994","type":"sa","tier":"创新","conf":"adapt","chap":"第1章","q":"简述学习马克思主义的根本方法。","opts":[],"ans":null,"explain":"<p>理论联系实际是学习马克思主义的根本方法</p><p>①首先，这是由马克思主义的实践性决定的。实践是马克思主义的基础，马克思主义源于实践并随着实践的发展而发展，它的科学性和旺盛的生命力的根源就在于它同实际紧密结合。</p><p>②其次，这是由我们学习马克思主义的目的决定的。我们学习马克思主义的目的全在于应用，不论是树立正确的世界观、人生观、价值观，还是掌握认识世界和改造世界的伟大工具，全面提高人的素质，或是指导中国特色社会主义伟大实践，都是为了在实践中更好地运用马克思主义。</p>"},{"id":"mk15044-pl-P1527995","type":"sa","tier":"创新","conf":"adapt","chap":"第1章","q":"简述马克思主义的科学内涵以及学习马克思主义的根本方法。","opts":[],"ans":null,"explain":"（1）科学内涵：马克思主义是由马克思、恩格斯创立的，为他们的后继者所发展的，以反对资本主义、建设社会主义和共产主义为目标的科学的理论体系，或者简要地说，它是关于工人阶级和人类解放的科学。<br/>（2）根本方法：理论联系实际，就是把马克思主义的基本原理作为指导，去观察和分析社会实际、工作实际和思想实际。要做到理论联系实际，在实际工作中必须反对经验主义和教条主义两种倾向。"},{"id":"mk15044-pl-P1527996","type":"sa","tier":"创新","conf":"adapt","chap":"第1章","q":"简述学习马克思主义的目的和根本方法。","opts":[],"ans":null,"explain":"我们学习马克思主义的目的主要有以下几个方面：<br/>（1）树立正确的世界观、人生观、价值观。<br/>（2）掌握认识世界和改造世界的伟大工具。<br/>（3）全面提高人的素质。<br/>（4）指导中国特色社会主义实践。理论联系实际是学习马克思主义的根本方法。"},{"id":"mk15044-pl-P1527997","type":"sa","tier":"创新","conf":"adapt","chap":"第1章","q":"新的历史条件下丰富和发展马克思主义的必要性。","opts":[],"ans":null,"explain":"（1）现实社会主义的变化向马克思主义提出的研究课题；（2）当代资本主义的新变化向马克思主义提出的研究课题；（3）经济全球化向马克思主义提出的研究课题；（4）世界新技术革命向马克思主义提出的研究课题；（5）我国的改革开放和现代化建设向马克思主义提出的研究课题。"},{"id":"mk15044-pl-P1527998","type":"sa","tier":"创新","conf":"adapt","chap":"第1章","q":"什么是马克思主义？简述马克思主义对德国古典哲学的继承与创新。","opts":[],"ans":null,"explain":"<p>（1）马克思主义是由马克思恩格斯创立并为后继者所发展的，以反对资本主义、建设社会主义和共产主义为目标的科学理论体系，或者简要地说，它是关于工人阶级和人类解放的科学。</p><p>（2）马克思主义哲学的直接理论来源是德国古典哲学，它吸收了黑格尔辩证法中的合理思想和费尔巴哈唯物主义的基本思想，创立了辩证唯物主义和历史唯物主义。马克思彻底批判了黑格尔的唯心主义和神秘主义，对它进行了根本改造，同时吸收了费尔巴哈的唯物主义基本思想，摒弃了他理论中的形而上学的思想，创立了唯物辩证法。</p>"},{"id":"mk15044-pl-P1527999","type":"sa","tier":"创新","conf":"adapt","chap":"第1章","q":"简述马克思主义的直接理论来源。","opts":[],"ans":null,"explain":"马克思主义的理论来源：德国古典哲学、英国古典政治经济学和英法空想社会主义。"},{"id":"mk15044-pl-P1528000","type":"sa","tier":"创新","conf":"adapt","chap":"第1章","q":"简述马克思主义科学体系的三个组成部分及其直接理论来源。","opts":[],"ans":null,"explain":"（1）马克思主义理论体系的三个主要组成部分：马克思主义哲学，马克思主义政治经济学、科学社会主义。<br/>（2）直接理论来源：德国古典哲学、英国古典政治经济学和19世纪英法两国的空想社会主义。"},{"id":"mk15044-pl-P1528001","type":"sa","tier":"创新","conf":"adapt","chap":"第1章","q":"简述马克思主义对德国古典哲学、英国古典经济学和英法两国的空想社会主义学说的继承与创新。","opts":[],"ans":null,"explain":"（1）马克思、恩格斯吸取黑格尔辩证法中的合理思想和费尔巴哈唯物主义的基本思想，创立了辩证唯物主义和历史唯物主义。<br/>（2）马克思、恩格斯吸取了英国古典经济学家的劳动价值论等合理思想，创立了剩余价值学说。<br/>（3）马克思、恩格斯批判地吸收了空想社会主义学说的积极成果，创立了科学社会主义理论。"},{"id":"mk15044-pl-P1528002","type":"sa","tier":"创新","conf":"adapt","chap":"第1章","q":"为什么说马克思主义是不断发展的理论。","opts":[],"ans":null,"explain":"<p>（一）马克思主义的理论本性决定了它是发展着的理论</p><p>（1）首先，马克思主义不是脱离实际的抽象的思辨体系，它永远面对现实世界，面对实际生活，关注和研究时代提出的最迫切的问题，总结新的实践经验，提出新的理论观点。</p><p>（2）其次，马克思主义不是宗派主义体系，它能正确地对待各种非马克思主义，甚至反马克思主义的学说，对它们进行批判地研究，剔除其中错误的观点，吸收其积极合理的内容。</p><p>（3）再次，马克思主义不是故步自封的体系，它具有自我批评意识，它能根据时代的变化、实践的发展和科学的进步，发现自身的历史局限性和不完善的地方，把自身提高到与时代和实践的需要更加适应的水平。</p><p>（二）马克思主义的生命力就存在于它的不断发展和创新的过程之中</p><p>在马克思主义产生170多年来的历史过程中，它的创始人和后继者总是根据变化了的实际情况，不断推进马克思主义的理论创新，使其获得新的生命，采取新的形态，从而形成了一部内容丰富并持续向前的马克思主义发展史。可以说，马克思主义的生命力，就存在于它的不断发展和创新的过程之中。</p>"},{"id":"mk15044-pl-P1528003","type":"sa","tier":"创新","conf":"adapt","chap":"第1章","q":"为什么说在当代中国坚持中国特色社会主义理论体系就是真正坚持马克思主义?","opts":[],"ans":null,"explain":"（1）中国特色社会主义理论体系包括邓小平理论、“三个代表”重要思想以及科学发展观等。<br/>（2）改革开放以后，中国共产党人把马克思主义的普遍真理与中国具体实践相结合，开辟了中国特色社会主义道路，形成了中国特色社会主义理论体系。这个理论体系坚持和发展了马克思列宁主义、毛泽东思想，是马克思主义中国化的最新成果。因此，在当代中国坚持中国特色社会主义理论体系，就是真正坚持马克思主义。"},{"id":"mk15044-pl-P1528004","type":"sa","tier":"创新","conf":"adapt","chap":"第1章","q":"简述马克思主义是时代的产物。","opts":[],"ans":null,"explain":"（1）马克思主义产生的客观条件：资本主义的发展及其内在矛盾的尖锐化，为马克思主义的产生提供了客观条件。<br/>（2）马克思主义产生的阶级基础：工人阶级作为一支独立的政治力量登上历史舞台，进行反对资本主义制度和资产阶级统治的斗争，为马克思主义的产生准备了阶级基础。<br/>（3）马克思主义产生的必然性：从马克思主义科学体系的内容来看，资本主义的发展及其内在矛盾的尖锐化，工人阶级以独立的政治力量登上历史舞台，不仅提出了在哲学、政治经济学和社会主义学说方面实行变革的必要性，而且提供了把哲学、政治经济学和社会主义理论结合为一个完整而严密的科学体系的统一的马克思主义学说的可能性：<br/>①正是资本主义生产方式及其内在矛盾的暴露以及生产力和科学技术的发展，为科学地揭示自然、社会和人类思维发展的一般规律，创立科学的哲学世界观和历史观创造了条件；②正是资本主义生产方式及其内在矛盾的发展，使得从理论上揭示资本主义生产方式的本质、发现剩余价值理论成为可能；③马克思、恩格斯正是在科学的世界观和历史观以及剩余价值理论的基础上，解决了空想社会主义学说所不能解决的理论课题，使社会主义从空想变成了科学。"},{"id":"mk15044-pl-P1526482","type":"sa","tier":"创新","conf":"adapt","chap":"第1章","q":"论述学习马克思主义的根本方法。","opts":[],"ans":null,"explain":"理论联系实际是学习马克思主义的根本方法。<br/>首先，这是由马克思主义的实践性决定的。实践是马克思主义的基础，马克思主义源于实践并随着实践的发展而发展，它的科学性和旺盛的生命力的根源就在于它同实际紧密结合。<br/>其次，这是由我们学习马克思主义的目的决定的。我们学习马克思主义的目的全在于应用，不论是树立正确的世界观、人生观、价值观，还是掌握认识世界和改造世界的伟大工具，全面提高人的素质，或是指导中国特色社会主义伟大实践，都是为了在实践中更好地运用马克思主义。<br/>所谓理论联系实际，就是把马克思主义的基本原理作为指导，去观察和分析社会实践、工作实际和思想实际。我国今天所面临的最大的社会实际，就是我国正处于并将长期处于社会主义初级阶段。社会主义初级阶段的基本国情，是我们党制定路线、纲领、方针、政策的基本依据，是我们分析、认识和解决当今中国一切社会问题的基础。工作实际和思想实际虽然因人而异，但任何人在工作中都会遇到矛盾和困难，在思想上都会产生困惑和冲突。学习马克思主义基本原理，具体地分析这些矛盾、困难、困惑和冲突，有助于搞好各项工作和提高思想水平。<br/>要做到理论联系实际，在实际工作中必须反对经验主义和教条主义两种倾向。实际工作中的经验主义片面夸大感性经验的作用，轻视理论，把局部经验当做普遍真理，到处搬用。教条主义片面夸大理论和书本知识的作用，轻视感性经验，一切从本本出发，把理论当成万古不变的教条，生搬硬套。这两种倾向都是主观主义的，都曾经给中国革命和建设带来重大损失。理论与实际的结合或联系是双向的，不是单向的。理论联系实际，分析和解决实际问题，一定要在弄清理论的基础上联系实际，不要离开理论只分析实际问题。学了理论，把它束之高阁，不去分析解决实际问题，再好的理论也是无用的；但是离开理论，只对实际问题作经验性的描述，就事论事，也不能算是理论联系实际。只讲理论，不讲实际，是理论脱离实际的一种表现；只讲实际，不讲理论，则是理论脱离实际的另一种表现。这两种倾向我们都要防止和反对。"},{"id":"mk15044-pl-P1526483","type":"sa","tier":"创新","conf":"adapt","chap":"第1章","q":"简要说明马克思主义对人类文明成果的继承与创新。","opts":[],"ans":null,"explain":"<p>(1)对马克思主义的形成产生最直接、最重大影响的人类文明成果，是德国古典哲学、英国古典政治经济学和19世纪英法两国的空想社会主义学说。</p><p>①马克思、恩格斯吸取了黑格尔辩证法中的合理思想，彻底批判了它的唯心主义和神秘主义，创立了唯物辩证法；把唯物主义和辩证法、唯物主义自然观和唯物主义历史观结合起来，创立了唯物主义哲学。</p><p>②马克思、恩格斯批判地继承了古典经济学的研究成果，严密论证了劳动价值论，在此基础上创立了剩余价值学说，从而创立了马克思主义政治经济学。</p><p>③马克思，恩格斯以唯物史观和剩余价值学说为基础，批判地吸收了空想社会主义学说的积极成果，创立了科学社会主义理论。</p><p>(2)细胞学说、能量守恒和转化定律、达尔文的生物进化论这自然科学的三大发现以及其他成果，为马克思、恩格斯揭示了自然界的本质和发展规律以及自然界与人类社会的相互作用规律，从而为整个马克思主义的形成提供了坚实的自然科学基础。</p>"},{"id":"mk15044-pl-P1526484","type":"sa","tier":"创新","conf":"adapt","chap":"第1章","q":"为什么说马克思主义是发展着的理论？","opts":[],"ans":null,"explain":"马克思主义之所以是发展着的理论，是由它的理论本性决定的。<br/>首先，马克思主义不是脱离实际的抽象的思辨体，它永远面对现实世界，面对实际生活，关注和研究时代提出的最迫切的问题，总结新的践经验，提出新的理论观点。<br/>其次，马克思主义不是宗派主义体系，它能正确地对待各种非马克思主义、甚至反马克思主义的学说，对它们进行批判地研究，剔除其中错误的观点，吸收其积极合理的内容。<br/>再次，马克思主义不是故步自封的体系，它具有自我批评意识，它能根据时代的变化、实践的发展和科学的进步，发现自身的历史局限性和不完善的地方，把自身提高到与时代和实践的需要更加适应的水平。事实上，在马克思主义产生170年来的历史过程中，它的创始人和后继者总是根据变化了的实际情况，不断推进马克思主义的理论创新，使其获得新的生命，采取新的形态，从而形成了一部内容丰富并持续向前的马克思主义发展史。可以说，马克思主义的生命力，就存在于它的不断发展和创新的过程之中。"},{"id":"mk15044-pl-P1526485","type":"sa","tier":"创新","conf":"adapt","chap":"第1章","q":"简述矛盾的主要方面和次要方面的关系及其方法论意义。","opts":[],"ans":null,"explain":"(1)矛盾双方的力量是不平衡的，其中居于支配地位、起着主导作用的方面是矛盾的主要方面，处于被支配地位的方面是矛盾的次要方面。<br/>(2)矛盾的主要方面和次要方面的关系是：<br/>①矛盾的主要方面和次要方面是相互制约、相互作用的。<br/>②矛盾的主要方面和次要方面的地位不是固定不变的，在一定条件可以相互转化，随着矛盾双方主次地位的的变化，事物的性质也就发生了变化。<br/>(3)矛盾的主要方面和次要方面的关系的原理具有重要的方法论意义。我们在分析问题，特别是分析形势时，要分清主流和支流，抓住主流，正确认识事物的性质，同时也不能忽视支流，并且注意主流和支流的相互转化。"},{"id":"mk15044-pl-P1526486","type":"sa","tier":"创新","conf":"adapt","chap":"第1章","q":"论述形而上学唯物主义的局限性。","opts":[],"ans":null,"explain":"形而上学唯物主义有四个明显的局限性:<br/>(1)机械性，它把一切运动都归结为机械运动，企图用力学原理解释一切现象，甚至把人和动物都看成受力学规律支配的机器，因此形而上学唯物主义也称机械唯物主义。<br/>(2)形而上学性，它把一切事物都看做是彼此孤立的、在本质上是不发展变化的。<br/>(3)直观性，它对待世界、认识，都缺乏实践的观点。<br/>(4)不彻底性，它只在自然观上坚持唯物主义，在历史观上则陷入唯心主义，把精神看成是社会发展的决定力量。"},{"id":"mk15044-pl-P1526487","type":"sa","tier":"创新","conf":"adapt","chap":"第1章","q":"试述内因和外因的辩证关系及其现实意义。","opts":[],"ans":null,"explain":"(1)内因和外因的辩证关系是：<br/>①内因是事物发展的根据，是第一位的原因；<br/>②外因是事物发展变化的条件，是第二位的原因；<br/>③外因通过内因而起作用。<br/>(2)内因和外因辨证关系的原理，是我们党制定和执行独立自主、自力更生以及对外开放方针的重要理论基础。<br/>(3)我国的对外开放是以独立自主、自力更生为基础的，必须从我国的实际出发，积极地借鉴和吸收世界各国一切文明成果，为我所用，增强我国自力更生的能力，加快我国社会主义现代化建设步伐。"},{"id":"mk15044-pl-P1526334","type":"sc","tier":"基础","conf":"adapt","chap":"第2-3章","q":"辩证唯物主义认识论首要的和基本的观点是（）。","opts":["A. 唯物论的观点","B. 辩证法的观点","C. 实践的观点","D. 可知论的观点论"],"ans":2,"explain":"列宁指出：“生活、实践的观点，应该是认识论的首要的和基本的观点。”马克思主义哲学认为实践的观点是辨证唯物主义认识论之第一的基本的观点，实践是认识的基础，从而引起了认识论的革命。"},{"id":"mk15044-pl-P1526335","type":"sc","tier":"基础","conf":"adapt","chap":"第2-3章","q":"沟通主体和客体的桥梁是（）。","opts":["A. 真理","B. 社会","C. 实践","D. 认识"],"ans":2,"explain":"实践是沟通主体和客体的桥梁，认识作为主体对客体的反映，只有在主体和客体相互接触、相互作用的情况下才能发生，而能使主体和客体相互接触、相互作用的唯一途径就是实践。"},{"id":"mk15044-pl-P1526336","type":"sc","tier":"基础","conf":"adapt","chap":"第2-3章","q":"“社会一旦有技术上的需要，这种需要就会比十所大学更能把科学推向前进。”这句话包含的认识论道理是（）。","opts":["A. 实践是检验认识正确与否的标准","B. 实践是认识发展的动力","C. 实践是认识的来源","D. 实践是认识的目的"],"ans":1,"explain":"实践是认识发展的动力。正如恩格斯指出的：“社会一旦有技术上的需要，这种需要就会比十所大学更能把科学推向前进。”"},{"id":"mk15044-pl-P1526337","type":"sc","tier":"基础","conf":"adapt","chap":"第2-3章","q":"认识的源泉、动力、标准和最终目的是（）。","opts":["A. 实践","B. 理想","C. 真理","D. 经验"],"ans":0,"explain":"实践是认识的源泉、动力、标准和最终目的，这些都是实践对认识决定作用的具体表现。正是由于这种决定作用，所以，马克思主义哲学认为，人的认识一点也不能脱离实践。"},{"id":"mk15044-pl-P1526338","type":"sc","tier":"基础","conf":"adapt","chap":"第2-3章","q":"认识的主体不包括（）。","opts":["A. 个体","B. 群体","C. 企业主体","D. 人类群体"],"ans":2,"explain":"认识主体是指认识和实践活动的承担者，是处于一定社会关系中从事实践活动和认识活动的现实的、具体的人。马克思主义哲学继承以前唯物主义的优秀传统，提出认识的主体是现实的人。认识主体只能是人，不能是人以外的其他事物。一切认识现象都是属于人的，离开了人和人的实践根本就谈不上认识。"},{"id":"mk15044-pl-P1526339","type":"sc","tier":"基础","conf":"adapt","chap":"第2-3章","q":"认识的客体是（）。","opts":["A. 人的实践活动和认识活动所指向的对象","B. 人的主观创造物","C. 整个物质世界","D. 现代科学知识尚未达到的领域"],"ans":0,"explain":"认识客体是指人的实践活动和认识活动所指向的对象。构成认识客体的内容主要有自然客体、社会客体和精神客体。"},{"id":"mk15044-pl-P1526340","type":"sc","tier":"基础","conf":"adapt","chap":"第2-3章","q":"认识主体和认识客体之间最基本的关系是（）。","opts":["A. 改造与被改造的实践关系","B. 反映与被反映的认识关系","C. 相互依存的关系","D. 相互作用的关系"],"ans":0,"explain":"认识的主体和客体的关系之一就是主体和客体的实践关系。它是指主体与客体之间改造和被改造的关系，主体作用于客体，就是对客体的改造，也就是实践。"},{"id":"mk15044-pl-P1526341","type":"sc","tier":"基础","conf":"adapt","chap":"第2-3章","q":"认识客体的属性有（）。","opts":["A. 客观性和对象性","B. 客观性和主观性","C. 主观性和对象性","D. 对象性和相对性"],"ans":0,"explain":"(1)认识客体具有客观性。自然客体和社会客体都是物质性的客观存在和客观过程，当然具有客观性。(2)认识客体具有对象性。认识客体必须具有客观实在性，但并不是所有具有客观实在性的事物都自然而然地成为认识客体，只有那些与主体活动发生关系、成为主体活动对象的外部事物，才构成认识客体。"},{"id":"mk15044-pl-P1526342","type":"sc","tier":"基础","conf":"adapt","chap":"第2-3章","q":"唯物主义认识论和唯心主义认识论的根本区别是（）。","opts":["A. 前者是可知论，后者是不可知论","B. 前者是能动反映论，后者是机械反映论","C. 前者是反映论，后者是先验论","D. 前者是唯理论，后者是经验论"],"ans":2,"explain":"在哲学史上形成了不同的认识论派别，主要有唯物论的反映论、唯心论的先验论以及可知论和不可知论。"},{"id":"mk15044-pl-P1526343","type":"sc","tier":"基础","conf":"adapt","chap":"第2-3章","q":"下列各项中，属于辩证唯物主义认识论区别于旧唯物主义认识论的观点是（）。","opts":["A. 认识客体具有客观性的观点","B. 认识是主体对客体的反映的观点","C. 物质世界可以认识的观点","D. 实践是认识的基础的观点"],"ans":3,"explain":"辩证唯物主义是对旧唯物主义的发展和超越，它把实践观引进到认识论中来。辩证唯物主义的认识论认为，实践是认识的基础。"},{"id":"mk15044-pl-P1526344","type":"sc","tier":"基础","conf":"adapt","chap":"第2-3章","q":"一个完整的认识过程是（）。","opts":["A. 感觉一知觉一表象","B. 概念一判断一推理","C. 认识一实践一认识","D. 实践一认识一实践"],"ans":3,"explain":"人的认识就是从实践到认识、再从认识到实践这样一个不断反复、无限发展的过程。"},{"id":"mk15044-pl-P1526345","type":"sc","tier":"基础","conf":"adapt","chap":"第2-3章","q":"与理性认识相比较，感性认识有两个特点，一个是形象性，另一个是（）。","opts":["A. 能动性","B. 间接性","C. 客观性","D. 直接性"],"ans":3,"explain":"感性认识是对事物表面的、直接的、具体的、个别特性的反映，是具体的、丰富的、生动的；理性认识是对事物本质的、全体的、间接的、概括的反映，是抽象的、间接的、相对稳定的。"},{"id":"mk15044-pl-P1526346","type":"sc","tier":"基础","conf":"adapt","chap":"第2-3章","q":"理性认识的三种形式是（）。","opts":["A. 概念、判断、推理","B. 感觉、知觉、表象","C. 抽象、具体、再抽象","D. 分析、归纳、综合"],"ans":0,"explain":"理性认识包括概念、判断和推理三种形式。感性认识分为感觉、知觉和表象三种形式。"},{"id":"mk15044-pl-P1526347","type":"sc","tier":"基础","conf":"adapt","chap":"第2-3章","q":"有人把个别的、局部的经验当做普遍真理，到处搬用，否认科学理论的指导意义。这在认识论上犯了类似于（）。","opts":["A. 唯理论的错误","B. 经验论的错误","C. 唯心主义先验论的错误","D. 直观被动反映论的错误"],"ans":1,"explain":"在实际工作中，经验论和唯理论是经验主义和教条主义的认识论根源。经验主义夸大个别的、局部的经验的作用，把它当做普遍真理，到处搬用，否认科学理论的指导意义。"},{"id":"mk15044-pl-P1526348","type":"sc","tier":"基础","conf":"adapt","chap":"第2-3章","q":"“感觉到了的东西，我们不能立刻理解它，只有理解了的东西才能更深刻地感觉它”，这句话表明（）。","opts":["A. 感性认识是微不足道的","B. 感性认识是认识的高级阶段","C. 理性认识是唯一可靠的","D. 理性认识是认识的高级阶段"],"ans":3,"explain":"理性认识是认识的高级阶段，它是对事物本质的、全体的、间接的、概括的反映，因而是深刻的、全面的、相对稳定的认识。题干中的引言体现了理性认识是认识的高级阶段这一哲理。"},{"id":"mk15044-pl-P1526349","type":"sc","tier":"基础","conf":"adapt","chap":"第2-3章","q":"感性认识和理性认识的区别在于（）。","opts":["A. 前者源于书本，后者源于实践","B. 前者是可靠的，后者是不可靠的","C. 前者反映事物的现象，后者反映事物的本质","D. 前者来源于直接经验，后者来源于间接经验"],"ans":2,"explain":"感性认识分为感觉、知觉和表象三种形式。感觉是在实践中反映客观事物的开始，是对认识对象最直接的反映。理性认识是认识的高级阶段，它是对事物的全体、本质和内部联系的反映，是抽象的、间接的、相对稳定的，理性认识是深刻的，它反映的是事物的全体和本质。"},{"id":"mk15044-pl-P1526350","type":"sc","tier":"基础","conf":"adapt","chap":"第2-3章","q":"一个完整的认识过程，需要经过两次飞跃。下列选项中属于第二次飞跃的是（）。","opts":["A. 调查研究，了解情况","B. 深入思考，形成理论","C. 精心安排，制定策略","D. 执行计划，付诸实践"],"ans":3,"explain":"认识过程包括两次飞跃，从感性认识上升到理性认识，是认识过程的第一次飞跃；从理性认识到实践，即用理性认识去指导实践，并接受实践的检验，是认识过程的第二次飞跃。题中D项体现了认识的第二次飞跃。"},{"id":"mk15044-pl-P1526351","type":"sc","tier":"基础","conf":"adapt","chap":"第2-3章","q":"一个正确的认识需要多次反复才能完成，并且认识是永无止境的发展过程。这说明人类的认识是（）。","opts":["A. 感性和理性的统一","B. 理论和实践的统一","C. 正确和错误的统一","D. 有限和无限的统一"],"ans":3,"explain":"一个正确的认识需要经过多次反复才能完成，整个人类的认识是有限与无限的统一。"},{"id":"mk15044-pl-P1526352","type":"sc","tier":"基础","conf":"adapt","chap":"第2-3章","q":"下列选项中，正确表述认识发展总规律的是（）。","opts":["A. 认识是不断由感性认识上升到理性认识的过程","B. 认识是由实践到认识，再由认识到实践的过程","C. 实践、认识、再实践、再认识，循环往复，无限发展的过程","D. 认识、实践、再认识、再实践，循环往复，无限发展的过程"],"ans":2,"explain":"毛泽东指出：“实践、认识、再实践、再认识，这种形式，循环往复以至无穷，而实践和认识之每一循环的内容，都比较地进到高一级的程度。”这里讲的循环不是封闭式的循环，人的认识运动既不是简单的循环，也不是直线式的前进，而是螺旋式的上升运动。这就是认识运动发展的总规律。"},{"id":"mk15044-pl-P1526353","type":"sc","tier":"基础","conf":"adapt","chap":"第2-3章","q":"“真理在一定条件下可以转化为谬误。”这是（）。","opts":["A. 唯心主义观点","B. 辩证唯物主义观点","C. 一切唯物主义共有的主张","D. 诡辩论观点"],"ans":1,"explain":"辩证唯物主义认为真理和谬误不仅相互依存，而且在一定条件下可以相互转化。"},{"id":"mk15044-pl-P1526354","type":"sc","tier":"基础","conf":"adapt","chap":"第2-3章","q":"阶级斗争是阶级社会发展的（）。","opts":["A. 基本动力","B. 最终动力","C. 直接动力","D. 唯一动力"],"ans":2,"explain":"马克思主义认为阶级斗争是阶级社会发展的直接动力。"},{"id":"mk15044-pl-P1526355","type":"sc","tier":"基础","conf":"adapt","chap":"第2-3章","q":"辩证法与形而上学在真理观上的对立在于是否承认（）。","opts":["A. 真理具有相对性","B. 真理具有客观性","C. 真理具有主观性","D. 真理具有绝对性"],"ans":0,"explain":"本题考查的是辩证法与形而上学的区别，属于需要识记的内容，请考生熟记此知识点。"},{"id":"mk15044-pl-P1526356","type":"sc","tier":"基础","conf":"adapt","chap":"第2-3章","q":"“有用即真理”是（）哲学提出的观点。","opts":["A. 实用主义","B. 唯心主义和唯物主义","C. 唯物主义","D. 马克思主义"],"ans":0,"explain":"实用主义哲学主张“有用即真理”的观点。美国哲学家詹姆斯说：“凡是有利于我们的工作，并使我们得到效果的东西就是真理，这也是真理的唯一的标准。”我国的实用主义哲学家胡适也主张这种观点。"},{"id":"mk15044-pl-P1526358","type":"sc","tier":"基础","conf":"adapt","chap":"第2-3章","q":"在真理标准问题上坚持辩证法，就是要坚持（）。","opts":["A. 实践标准是确定性和不确定性统一的观点","B. 实践标准是主观性和客观性统一的观点","C. 实践是检验真理唯一标准的观点","D. 具体的实践能对一切认识做出确定检验的的观点"],"ans":0,"explain":"坚持实践是检验真理的唯一标准，就是坚持了检验标准的客观性，也就是在真理标准问题上坚持了唯物论。然而，这个标准既是确定的、绝对的，又是不确定的、相对的，是确定性与不确定性、绝对性与相对性的统一。这就是在真理标准问题上坚持了辩证法。"},{"id":"mk15044-pl-P1526359","type":"sc","tier":"基础","conf":"adapt","chap":"第2-3章","q":"社会存在是指（）。","opts":["A. 生产力各要素的总和","B. 生产关系各方面的总和","C. 生产力和生产关系的总和","D. 社会物质生活条件的总和"],"ans":3,"explain":"社会存在是指社会物质生活条件的总和，包括地理环境、人口因素和物质生活资料的生产方式。"},{"id":"mk15044-pl-P1526360","type":"sc","tier":"基础","conf":"adapt","chap":"第2-3章","q":"地理环境在社会发展中的作用是（）。","opts":["A. 影响社会结构的划分","B. 影响社会发展的速度","C. 决定社会制度的性质","D. 决定社会形态的更替"],"ans":1,"explain":"地理环境通过对生产的影响，加速或延缓社会的发展。地理环境影响劳动生产率的高低和生产部门的分布，在一定程度上决定不同国家经济发展的特点，制约一个国家经济发展的潜力和前景。"},{"id":"mk15044-pl-P1526361","type":"sc","tier":"基础","conf":"adapt","chap":"第2-3章","q":"社会关系是一个复杂的体系，其中最基础的关系是（）。","opts":["A. 政治关系","B. 生产关系","C. 阶级关系","D. 思想关系"],"ans":1,"explain":"生产活动是形成人类一切社会关系的基础。生产活动不仅创造了人类生存所必需的物质资料，而且创造了人与人之间的生产关系。在生产关系的基础上，又形成了人与人之间的政治关系和思想关系等其他社会关系，从而形成了整个人类社会。"},{"id":"mk15044-pl-P1526362","type":"sc","tier":"基础","conf":"adapt","chap":"第2-3章","q":"下列关于社会心理和思想体系之间的区别说法正确的是（）。","opts":["A. 前者属于高级层次，后者属于低级层次","B. 前者系统，后者不系统","C. 前者是日常生活中自发形成的，后者以相对稳定的形式反映社会存在","D. 前者定型，后者抽象"],"ans":2,"explain":"社会心理是社会意识的低级层次，它是特定阶级、民族、社会集团或个人，在日常生活和交往中自发形成的、不定型、不系统的社会意识，表现在人们的情感、情绪、愿望、要求、风俗、习惯、传统、自发倾向和社会风气等等之中。思想体系是社会意识的高级层次，亦称社会意识形式，它以相对稳定的形式反映社会存在，具有抽象化、系统化的特性。"},{"id":"mk15044-pl-P1526363","type":"sc","tier":"基础","conf":"adapt","chap":"第2-3章","q":"生产力范畴反映的是（）。","opts":["A. 人与人之间的经济关系","B. 人与人之间的政治关系","C. 人与自然之间的关系","D. 人与人之间的思想关系"],"ans":2,"explain":"生产力是人类利用自然、改造自然、从自然界获取物质资料的能力，生产力范畴反映的是人与自然界的关系。生产力的要素或成分，按照一定的比例和形式结合起来，形成生产力的整体功能，就构成生产力系统。"},{"id":"mk15044-pl-P1526364","type":"sc","tier":"基础","conf":"adapt","chap":"第2-3章","q":"人类社会发展最基本的规律是（）。","opts":["A. 社会存在决定社会意识的规律","B. 阶级斗争推动社会发展的规律","C. 生产关系必须适合生产力性质的规律","D. 社会形态由低级到高级依次更替的规律"],"ans":2,"explain":"生产力决定生产关系，生产关系反作用于生产力，生产力和生产关系之系之间的矛盾运动，这三项内容构成生产关系必须适合生产力性质的规律。这是人类社会发展最基本、最普遍的规律。"},{"id":"mk15044-pl-P1526365","type":"sc","tier":"基础","conf":"adapt","chap":"第2-3章","q":"判断一种生产关系是否先进的根本标志在于它是（）。","opts":["A. 促进生产力发展还是阻碍生产力发展","B. 生产资料公有制还是生产资料私有制","C. 社会化的大生产还是个体小生产","D. 封闭的自然经济还是开放的市场经济"],"ans":0,"explain":"本题考查的是生产力与生产关系之间关系的相关知识点，属于需要识记的内容，请考生熟记此知识点。"},{"id":"mk15044-pl-P1526366","type":"sc","tier":"基础","conf":"adapt","chap":"第2-3章","q":"经济基础和生产关系是两个术语，但内容相同，相对于上层建筑而言，占统治地位的生产关系叫（）。","opts":["A. 经济基础","B. 生产力","C. 经济命脉","D. 科学技术"],"ans":0,"explain":"经济基础和生产关系是两个术语，但内容相同。相对于生产力而言，叫生产关系；相对于上层建筑而言，占统治地位的生产关系叫经济基础。"},{"id":"mk15044-pl-P1526367","type":"sc","tier":"基础","conf":"adapt","chap":"第2-3章","q":"无产阶级政党制定正确路线、方针、政策的理论依据（）。","opts":["A. 上层建筑必须适合经济基础发展要求的规律","B. 生产力必须适合生产关系性质的规律","C. 经济基础决定上层建筑的规律","D. 普遍联系和矛盾对立统一规律"],"ans":0,"explain":"上层建筑必须适合经济基础发展要求的规律，是无产阶级政党制定正确的路线、方针、政策的理论依据。"},{"id":"mk15044-pl-P1526368","type":"sc","tier":"基础","conf":"adapt","chap":"第2-3章","q":"社会形态最基本的划分法之一是（）。","opts":["A. 意识形态划分法","B. 经济社会形态划分法","C. 文化形态划分法","D. 政治形态划分法"],"ans":1,"explain":"人类社会是一个内容丰富、结构复杂的巨系统。我们可以根据研究问题的不同需要，运用不同标准划分社会形态。最基本的划分法有两种，一种是经济社会形态划分法，另一种是技术社会形态划分法。"},{"id":"mk15044-pl-P1526369","type":"sc","tier":"基础","conf":"adapt","chap":"第2-3章","q":"划分阶级的唯一标准是（）。","opts":["A. 政治标准","B. 思想标准","C. 经济标准","D. 文化标准"],"ans":2,"explain":"阶级的定义表明，阶级首先是一个经济范畴，是一些经济集团，划分阶级的唯一标准是经济标准，不能用政治标准和思想标准划分阶级。"},{"id":"mk15044-pl-P1526370","type":"sc","tier":"基础","conf":"adapt","chap":"第2-3章","q":"我国社会主义现代化建设的重要支点不包括（）。","opts":["A. 革命","B. 发展","C. 稳定","D. 改革"],"ans":0,"explain":"当前中国的改革是和发展、稳定相统一的过程。改革、发展、稳定是我国社会主义现代化建设的三个重要支点。稳定是前提；改革是动力；发展是关键。"},{"id":"mk15044-pl-P1526371","type":"sc","tier":"基础","conf":"adapt","chap":"第2-3章","q":"唯物史观和唯心史观在历史创造者问题上的根本对立在于是否承认（）。","opts":["A. 个人在历史发展中的作用","B. 思想动机在社会发展中的作用","C. 人民群众是推动历史发展的决定力量","D. 剥削阶级代表人物在历史发展中的作用"],"ans":2,"explain":"是广大人民群众还是个别英雄人物是历史的创造者，即推动历史发展的决定力量，历史唯物主义和历史唯心主义在对这个问题的看法上，存在着根本分歧。"},{"id":"mk15044-pl-P1526372","type":"sc","tier":"基础","conf":"adapt","chap":"第2-3章","q":"群众路线的基本出发点和最终归宿是（）。","opts":["A. “一切为了群众”","B. “一切依靠群众”","C. “从群众中来”","D. “到群众中去”"],"ans":0,"explain":"无产阶级政党的性质决定了群众路线的基本出发点和最终归宿是“一切为了群众”；群众路线的根本要求是“一切依靠群众”。"},{"id":"mk15044-pl-P1526373","type":"sc","tier":"基础","conf":"adapt","chap":"第2-3章","q":"推进党的作风建设，核心是（）。","opts":["A. 保持党同人民群众的血肉联系","B. 保持党的先进性","C. 保持党的群众性","D. 保持党的先锋队性"],"ans":0,"explain":"在改革开放和现代化建设的新形势下，坚持党的群众路线，具有十分重大的意义。推进党的作风建设，其核心是保持党同人民群众的血肉联系。我们党的最大政治优势是密切联系群众，党执政后的最大危险是脱离群众。"},{"id":"mk15044-pl-P1526374","type":"sc","tier":"基础","conf":"adapt","chap":"第2-3章","q":"按照技术社会形态的划分标准，我们可以把人类历史划分为（）。","opts":["A. 人的依赖性社会、物的依赖性社会、个人全面发展的社会","B. 渔猎社会、农业社会、工业社会、信息社会","C. 自然经济社会、商品经济社会、产品经济社会","D. 古代社会、近代社会、现代社会"],"ans":1,"explain":"技术社会形态就是以生产力和技术发展水平以及与此相适应的产业结构为标准划分的社会形态。人类历史的技术社会形态序列为：渔猎社会——农业社会——工业社会——信息社会。"},{"id":"mk15044-pl-P1526375","type":"sc","tier":"基础","conf":"adapt","chap":"第2-3章","q":"社会意识对社会存在的反作用，必须通过（）。","opts":["A. 思想斗争和说理斗争","B. 先进思想战胜落后思想","C. 社会意识诸形式之间的相互作用","D. 人民群众的实践活动"],"ans":3,"explain":"社会意识对社会存在的反作用，是指社会意识这种精神力量，在一定条件下可以反作用于社会存在，转化为物质力量，影响社会发展的进程。社会意识对社会存在的反作用，必须通过人民群众的实践活动。"},{"id":"mk15044-pl-P1526376","type":"sc","tier":"基础","conf":"adapt","chap":"第2-3章","q":"衡量生产力水平的客观尺度是（）。","opts":["A. 劳动工具的状况","B. 劳动对象的广度","C. 劳动者的素质","D. 劳动产品的质量"],"ans":0,"explain":"现代生产力系统独立的实体性要素包括劳动者、劳动资料和劳动对象。生产工具是劳动资料的主要内容，是生产力发展水平的主要标志。"},{"id":"mk15044-pl-P1526377","type":"sc","tier":"基础","conf":"adapt","chap":"第2-3章","q":"劳动对象是指（）。","opts":["A. 人类活动所遇到的一切客观事物","B. 整个自然界","C. 劳动半成品","D. 劳动过程中被加工的东西"],"ans":3,"explain":"劳动对象是劳动过程中被加工的东西。劳动对象分为两大类：一类是天然存在的劳动对象，如矿藏、原始森林、江河湖海里非人工养的鱼、空气等等；另一类是经过劳动加工的劳动对象，如做衣服用的布、织布用的棉纱、纺纱用的棉花、炼油厂用的原油、炼钢用的铁，等等。经过劳动加工的劳动对象叫原料。劳动资料和劳动对象合称生产资料。"},{"id":"mk15044-pl-P1526378","type":"sc","tier":"基础","conf":"adapt","chap":"第2-3章","q":"现代生产力系统要素中的渗透性因素主要是（）。","opts":["A. 劳动对象","B. 生产工具","C. 自然科学","D. 科学技术"],"ans":2,"explain":"现代生产力系统的渗透性因素，主要指自然科学。"},{"id":"mk15044-pl-P1526379","type":"sc","tier":"基础","conf":"adapt","chap":"第2-3章","q":"生产关系范畴反映的是人与人之间的（）。","opts":["A. 经济关系","B. 政治关系","C. 思想关系","D. 血缘关系"],"ans":0,"explain":"生产关系是指人们在物质生产过程中结成的经济关系。它包括三项内容：(1)生产资料的所有制形式；(2)人们在生产中的地位及其相互关系（包括交换）；(3)产品的分配方式。"},{"id":"mk15044-pl-P1526380","type":"sc","tier":"基础","conf":"adapt","chap":"第2-3章","q":"经济基础是一定社会中（）。","opts":["A. 生产力系统各要素的总和","B. 生产力和生产关系的总和","C. 占统治地位的生产关系各个方面的总和","D. 占统治地位的各种社会关系的总和"],"ans":2,"explain":"经济基础是指一个社会中占统治地位的生产关系各个方面的总和，即生产资料所有制形式、各种不同的社会集团在生产中的地位及其相互关系、产品分配方式三个方面的总和。"},{"id":"mk15044-pl-P1526381","type":"sc","tier":"基础","conf":"adapt","chap":"第2-3章","q":"下列选项中属于上层建筑两大组成部分的是（）。","opts":["A. 政治思想和法律思想","B. 政治制度和法律制度","C. 政治法律思想和道德观念","D. 政治上层建筑和观念上层建筑"],"ans":3,"explain":"上层建筑可分为政治上层建筑和观念上层建筑两部分。其中，政治上层建筑亦称实体性上层建筑，指政治法律制度以及军队、警察、法院、监狱、政府机关等设施，以及与之相适应的一套组织。观念上层建筑又称思想上层建筑，包括政治、法律、艺术、道德、宗教、哲学等各种服务于统治阶级的意识形态。"},{"id":"mk15044-pl-P1526382","type":"sc","tier":"基础","conf":"adapt","chap":"第2-3章","q":"人类社会的三个基本层次不包括（）。","opts":["A. 生产力","B. 生产关系","C. 上层建筑","D. 生产资料"],"ans":3,"explain":"人类社会有三个基本层次：生产力，生产关系（经济基础），上层建筑。生产力和生产关系构成一对矛盾，占统治地位的生产关系作为社会的经济基础，又和上层建筑构成一对矛盾。"},{"id":"mk15044-pl-P1527273","type":"sc","tier":"基础","conf":"adapt","chap":"第2-3章","q":"毛泽东指出：“如果有了正确的理论，只是把它空谈一阵，束之高阁，并不实行，那么，这种理论再好也是没有意义的。”从认识和实践的关系看，这句话强调的是（）","opts":["A. 感性认识和理性认识的统一","B. 认识世界和改造世界的统一","C. 真理的绝对性和相对性的统一","D. 实践标准的确定性和不确定性的统一"],"ans":1,"explain":"毛泽东指出：“如果有了正确的理论，只是把它空谈一阵，束之高阁，并不实行，那么，这种理论再好也是没有意义的。”从认识和实践的关系看，这句话强调的是认识世界和改造世界的统一"},{"id":"mk15044-pl-P1527274","type":"sc","tier":"基础","conf":"adapt","chap":"第2-3章","q":"一个完整的认识过程需要经历两次飞跃，下列属于第二次飞跃的是（）","opts":["A. 调查研究了解情况","B. 深入思考形成理论","C. 精心安排制定计划","D. 执行计划付诸实施"],"ans":3,"explain":"只有经过第二次飞跃，使理性认识再回到实践中去，才能使之得到检验，得到丰富和发展。"},{"id":"mk15044-pl-P1527275","type":"sc","tier":"基础","conf":"adapt","chap":"第2-3章","q":"“实践、认识、再实践、再认识，这种形式，循环往复以至无穷，而实践和认识每一循环的内容，都比较地进到了高一级的程度。”这段话揭示了认识运动发展的（）","opts":["A. 总过程","B. 总规律","C. 总方向","D. 总趋势"],"ans":1,"explain":"毛泽东指出：“实践、认识、再实践、再认识，这种形式，循环往复以至无穷，而实践和认识之每一循环的内容，都比较地进到了高一级的程度。”这里讲的循环不是封闭式的循环，人的认识运动既不是简单的循环，也不是直线式的前进，而是螺旋式的上升运动。这就是认识运动发雇的总规律。"},{"id":"mk15044-pl-P1527276","type":"sc","tier":"基础","conf":"adapt","chap":"第2-3章","q":"“实践、认识、再实践、再认识，这种形式，循环往复以至无穷，而实践和认识之每一循环的内容都比较地进到高一级的程度。”这里讲的“循环”是指（）","opts":["A. 封闭式的循环","B. 周而复始的运动","C. 直线式的前进","D. 螺旋式的上升"],"ans":3,"explain":"毛泽东指出：“实践、认识、再实践、再认识，这种形式，循环往复以至无穷，而实践和认识之每一循环的内容，都比较地进到了高一级的程度。”这里讲的循环不是封闭式的循环，人的认识运动既不是简单的循环，也不是直线式的前进，而是螺旋式的上升运动。这就是认识运动发雇的总规律。"},{"id":"mk15044-pl-P1527278","type":"sc","tier":"基础","conf":"adapt","chap":"第2-3章","q":"一个正确的认识往往需要经过（ ）","opts":["A. 由实践到认识.由认识到实践的过程","B. 由感性认识到理性认识，由理性认识到实践的过程","C. 由实践到认识.由认识到实践的多次反复才能完成","D. 由物质到精神，由精神到物质的过程"],"ans":2,"explain":"一个正确的认识常常不是通过实践——认识——再实践一次反复就能完成的，而是要经过多次反复才能完成"},{"id":"mk15044-pl-P1527279","type":"sc","tier":"基础","conf":"adapt","chap":"第2-3章","q":"“感觉只解决现象问题，理论才解决本质问题”，这句话说明（ ）。","opts":["A. 感性认识是微不足道的","B. 感性认识有待于发展到理性认识","C. 理性认识是唯一可靠的","D. 理性认识有待于深化为感性认识"],"ans":1,"explain":"“感觉只解决现象问题，理论才解决本质问题”，这句话说明的是感性认识有待于发展到理性认识。"},{"id":"mk15044-pl-P1527280","type":"sc","tier":"基础","conf":"adapt","chap":"第2-3章","q":"感觉、知觉、表象是（ ）。","opts":["A. 社会心理的三种形式","B. 社会意识形态的三种形式","C. 感性认识的三种形式","D. 理性认识的三种形式"],"ans":2,"explain":"感觉、知觉、表象是感性认识的三种形式。"},{"id":"mk15044-pl-P1527281","type":"sc","tier":"基础","conf":"adapt","chap":"第2-3章","q":"感性认识不同于理性认识的特点在于，它具有（）","opts":["A. 直接性和形象性","B. 间接性和抽象性","C. 社会性和历史性","D. 主观性和能动性"],"ans":0,"explain":"感性认识不同于理性认识的特点在于，它具有直接性和形象性"},{"id":"mk15044-pl-P1527282","type":"sc","tier":"基础","conf":"adapt","chap":"第2-3章","q":"作为认识的初级阶段，感性认识的三种形式是（ ）。","opts":["A. 概念、判断、推理","B. 感觉、知觉、表象","C. 分析、归纳、综合","D. 识记、联想、假说"],"ans":1,"explain":"感性认识的三种形式是感觉、知觉、表象（感知表）。"},{"id":"mk15044-pl-P1527283","type":"sc","tier":"基础","conf":"adapt","chap":"第2-3章","q":"感觉知觉表象是（）","opts":["A. 感性认识的三种形式","B. 理性认识的三种形式","C. 社会意识的三种形态","D. 社会心理的三种形式"],"ans":0,"explain":"感性认识分为感觉、知觉和表象三种形式。"},{"id":"mk15044-pl-P1527284","type":"sc","tier":"基础","conf":"adapt","chap":"第2-3章","q":"下列各项正确说明感性认识和理性认识联系的是（ ）。","opts":["A. 理性认识依赖于感性认识","B. 感性认识可以自动上升到理性认识","C. 感性认识依赖于理性认识","D. 理性认识可以自动回归到感性认识"],"ans":0,"explain":"感性认识和理性认识的联系是理性认识依赖于感性认识，感性认识有待于上升为理性认识。"},{"id":"mk15044-pl-P1527285","type":"sc","tier":"基础","conf":"adapt","chap":"第2-3章","q":"教条主义夸大理论和书本知识的作用，轻视实际经验，把理论当做万古不变的公式，生搬硬套。这在认识论上犯了()","opts":["A. 经验论的错误","B. 唯理论的错误","C. 相对主义的错误","D. 绝对主义的错误"],"ans":1,"explain":"教条主义夸大理论和书本知识的作用，轻视实际经验，不是从实际出发，而是从书本出发，把理论当作万古不变的公式，生搬硬套。"},{"id":"mk15044-pl-P1527286","type":"sc","tier":"基础","conf":"adapt","chap":"第2-3章","q":"认为只有感性经验才是可靠的，抽象的理论是不可靠的，这在认识论上犯了（ ）","opts":["A. 主观唯心主义的错误","B. 唯理论的错误","C. 经验论的错误","D. 形而上学的错误"],"ans":2,"explain":"经验论者片面强调感性经验的重要性，认为只有感性经验才是可靠的，而抽象的理性认识是不可靠的"},{"id":"mk15044-pl-P1527287","type":"sc","tier":"基础","conf":"adapt","chap":"第2-3章","q":"概念.判断.推理是（ ）","opts":["A. 感性认识的三种形式","B. 理性认识的三种形式","C. 社会意识形态的三种形式","D. 社会心理的三种形式"],"ans":1,"explain":"理性认识包括概念、判断和推理三种形式。"},{"id":"mk15044-pl-P1527288","type":"sc","tier":"基础","conf":"adapt","chap":"第2-3章","q":"理性认识由低级到高级的发展过程是（ ）。","opts":["A. 实践-认识-实践","B. 认识-实践-认识","C. 感觉-知觉-表象","D. 概念-判断-推理"],"ans":3,"explain":"理性认识由低级到高级的发展过程是概念-判断-推理。"},{"id":"mk15044-pl-P1527289","type":"sc","tier":"基础","conf":"adapt","chap":"第2-3章","q":"认识过程的第一次飞跃是（ ）","opts":["A. 由实践到感性认识","B. 由理性认识到实践","C. 由实践到认识，再由认识到实践","D. 由感性认识到理性认识"],"ans":3,"explain":"认识过程的第一次飞跃是由感性认识到理性认识"},{"id":"mk15044-pl-P1527290","type":"sc","tier":"基础","conf":"adapt","chap":"第2-3章","q":"通过实践和调查，获得十分丰富的感性材料，然后运用科学的思维方法对感性材料进行加工制作，透过现象抓住本质，从认识发展过程看，这是（）","opts":["A. 从感性认识到理性认识的飞跃","B. 从感觉到知觉的飞跃","C. 从意识到物质的飞跃","D. 从认识到实践的飞跃"],"ans":0,"explain":"通过实践和调查，获得十分丰富的感性材料，然后运用科学的思维方法对感性材料进行加工制作，透过现象抓住本质，从认识发展过程看，这是从感性认识到理性认识的飞跃"},{"id":"mk15044-pl-P1527291","type":"sc","tier":"基础","conf":"adapt","chap":"第2-3章","q":"有人认为只有写到书本上的理论才是真实可靠的，从而不顾实际情况，死搬书本上的教条。这在认识论上犯了类似于（ ）。","opts":["A. 唯心主义先验论的错误","B. 旧唯物主义认识论的错误","C. 经验论的错误","D. 唯理论的错误"],"ans":3,"explain":"有人认为只有写到书本上的理论才是真实可靠的，从而不顾实际情况，死搬书本上的教条。这在认识论上犯了类似于唯理论的错误（教条主义）。"},{"id":"mk15044-pl-P1527292","type":"sc","tier":"基础","conf":"adapt","chap":"第2-3章","q":"在实际工作中，有的人夸大个别、局部的经验作用，把他当成普遍真理，到处搬用，否认科学理论的指导作用，这在认识论上犯了（）","opts":["A. 经验论的错误","B. 唯理论的错误","C. 相对主义的错误","D. 绝对主义的错误"],"ans":0,"explain":"在实际工作中，有的人夸大个别、局部的经验作用，把他当成普遍真理，到处搬用，否认科学理论的指导作用，这在认识论上犯了经验论的错误"},{"id":"mk15044-pl-P1527293","type":"sc","tier":"基础","conf":"adapt","chap":"第2-3章","q":"16世纪末，伽利略通过在比萨斜塔所做的自由落体实验，推翻了亚里士多德关于物体的降落速度与物体的重量成正比的说法。这件事说明（）","opts":["A. 真理是对事物及其规律的正确反映","B. 真理是由相对真理走向绝对真理的过程","C. 实践是认识发展的动力","D. 实践是检验认识是否正确的唯一标准"],"ans":3,"explain":"坚持实践是检验真理的唯一标准，并不否认逻辑证明在认识和探索真理中的作用。"},{"id":"mk15044-pl-P1527294","type":"sc","tier":"基础","conf":"adapt","chap":"第2-3章","q":"实践是检验真理的唯一标准，这是因为实践具有（）","opts":["A. 普遍性的品格","B. 直接现实性的品格","C. 社会历史性的品格","D. 自觉能动性的品格"],"ans":1,"explain":"实践具有直接现实性的品格。"},{"id":"mk15044-pl-P1527295","type":"sc","tier":"基础","conf":"adapt","chap":"第2-3章","q":"实践是检验真理的唯一标准，这主要是因为（ ）。","opts":["A. 实践是人类生存和发展的基础","B. 实践是认识的来源和目的","C. 实践具有把主观和客观联系起来的特性","D. 实践具有社会历史性"],"ans":2,"explain":"实践是检验真理的唯一标准，这主要是因为实践具有把主观和客观联系起来的特性。"},{"id":"mk15044-pl-P1527296","type":"sc","tier":"基础","conf":"adapt","chap":"第2-3章","q":"下列关于真理的表述正确的是（）","opts":["A. 真理是客观事物及其规律","B. 真理是对人们有用，能够满足人们需要的理论","C. 真理是人们对客观事物及其规律的正确反映","D. 真理是大多数人认同的思维模式"],"ans":2,"explain":"由于真理是对客观事物及其规律的正确反映，因而具有客观性。"},{"id":"mk15044-pl-P1527297","type":"sc","tier":"基础","conf":"adapt","chap":"第2-3章","q":"在生活和工作中，人们的认识都需要通过实践来验证。这句话说明（ ）","opts":["A. 实践是认识的来源","B. 实践是认识的目的","C. 实践是认识发展的动力","D. 实践是检验认识正确与否的标准"],"ans":3,"explain":"在生活和工作中，人们的认识都需要通过实践来验证。这句话说明实践是检验认识正确与否的标准，注意题干关键词“通过实践来验证”。"},{"id":"mk15044-pl-P1527298","type":"sc","tier":"基础","conf":"adapt","chap":"第2-3章","q":"人们常说“真理在手所向披靡”这是因为（）","opts":["A. 真理具有客观性","B. 真理具有绝对性","C. 真理具有教育和激励的功能","D. 真理具有再认识的功能"],"ans":2,"explain":"人们常说“真理在手所向披靡”这是因为真理具有教育和激励的功能"},{"id":"mk15044-pl-P1527299","type":"sc","tier":"基础","conf":"adapt","chap":"第2-3章","q":"正确的价值观一定是（）","opts":["A. 建立在唯物论的基础上","B. 建立在真理的基础上","C. 建立在辩证法的基础上","D. 建立在认识的基础上"],"ans":1,"explain":"只有建立在真理基础上的价值观才是正确的价值观。"},{"id":"mk15044-pl-P1527300","type":"sc","tier":"基础","conf":"adapt","chap":"第2-3章","q":"社会主义核心价值观兼顾了国家、社会、个人三者的价值愿望与追求，其中从个人层面对社会主义核心价值观基本理念的凝练表达是（ ）。","opts":["A. 富强、民主、文明、和谐","B. 自由、平等、公正、法治","C. 爱国、敬业、诚信、友善","D. 厚德、包容、求是、创新"],"ans":2,"explain":"“爱国、敬业、诚信、友善”是从个人层面对社会主义核心价值观基本理念的凝练表达。"},{"id":"mk15044-pl-P1527301","type":"sc","tier":"基础","conf":"adapt","chap":"第2-3章","q":"党的十八大报告提出要积极培育和践行社会主义核心价值观，其中从社会层面对社会主义核心基本理念的凝练表达是（ ）","opts":["A. 富强.民主.文明.和谐","B. 自由.平等.公正.法治","C. 爱国.敬业.诚信.友善","D. 创新.包容.开放.进取"],"ans":1,"explain":"“自由、平等、公正、法治”可以说是从社会层面对社会主义核心价值观基本理念的凝练，反映了社会主义社会的基本要求，是我们党矢志不渝、长期实践的价值理念。"},{"id":"mk15044-pl-P1527302","type":"sc","tier":"基础","conf":"adapt","chap":"第2-3章","q":"党的十八大报告提出要积极培育和践行社会主义核心价值观，其中从社会层面对社会主义核心价值观基本理念的凝练表达是（ ）。","opts":["A. 富强、民主、文明、和谐","B. 自由、平等、公正、法治","C. 爱国、敬业、诚信、友善","D. 创新、包容、开放、进取"],"ans":1,"explain":"“自由、平等、公正、法治”是从社会层面对社会主义核心价值观基本理念的凝练表达。"},{"id":"mk15044-pl-P1527303","type":"sc","tier":"基础","conf":"adapt","chap":"第2-3章","q":"“没有理性，眼睛是最坏的见证人”。这句话强调的是（ ）。","opts":["A. 仅同事物的现象相符合的不一定是真相","B. 只要同事物的现象相符合的就是真理","C. 只要观察事物的外部联系就能获得真理","D. 只要观察事物的偶然联系就能获得真理"],"ans":0,"explain":"“没有理性，眼睛是最坏的见证人”这句话强调的是仅同事物的现象相符合的不一定是真相。"},{"id":"mk15044-pl-P1527304","type":"sc","tier":"基础","conf":"adapt","chap":"第2-3章","q":"绝对真理和相对真理是（ ）。","opts":["A. 两种性质不同的真理","B. 真理发展的两个不同阶段","C. 两种各自独立的真理","D. 客观真理的两种不同属性"],"ans":3,"explain":"绝对真理和相对真理是客观真理的两种不同属性。"},{"id":"mk15044-pl-P1527305","type":"sc","tier":"基础","conf":"adapt","chap":"第2-3章","q":"绝对真理与相对真理是（ ）","opts":["A. 两种完全不同的真理","B. 同一个真理的两种不同属性","C. 两种完全相同的真理","D. 两者有着固定不变的界限"],"ans":1,"explain":"绝对真理与相对真理是同一个真理的两种不同属性"},{"id":"mk15044-pl-P1527306","type":"sc","tier":"基础","conf":"adapt","chap":"第2-3章","q":"马克思主义认识论认为，真理的发展是一个（ ）。","opts":["A. 从主观真理走向客观真理的过程","B. 从局部真理走向全面真理的过程","C. 从相对真理走向绝对真理的过程","D. 从具体真理走向抽象真理的过程"],"ans":2,"explain":"马克思主义认识论认为，真理的发展是一个从相对真理走向绝对真理的过程。"},{"id":"mk15044-pl-P1527307","type":"sc","tier":"基础","conf":"adapt","chap":"第2-3章","q":"任何科学理论都不能穷尽真理，只能在实践中不断开辟认识真理的道路。这说明（ ）","opts":["A. 真理具有客观性","B. 真理具有绝对性","C. 真理具有相对性","D. 真理具有全面性"],"ans":2,"explain":"任何科学理论都不能穷尽真理，只能在实践中不断开辟认识真理的道路。这说明真理具有相对性"},{"id":"mk15044-pl-P1527308","type":"sc","tier":"基础","conf":"adapt","chap":"第2-3章","q":"真理是没有阶级性的，在真理面前人人平等。这是因为（ ）","opts":["A. 真理是绝对性和相对性的统一，真理是不断发展的","B. 真理是具体的，任何真理都有其适用的条件和范围","C. 真理就是客观规律，真理与人的阶级地位无关","D. 真理具有客观性，真理中包含着不依赖于人类的客观内容"],"ans":3,"explain":"任何真理都包含不依赖于主体、不依赖于人类的客观内容，也就是说，真理的客观性就是承认认识的内容来自客观实际又符合客观实际。"},{"id":"mk15044-pl-P1527309","type":"sc","tier":"基础","conf":"adapt","chap":"第2-3章","q":"任何真理都是具体的，包罗万象的真理是不存在的。这是因为真理具有（ ）。","opts":["A. 绝对性","B. 相对性","C. 全面性","D. 片面性"],"ans":1,"explain":"任何真理都是具体的，包罗万象的真理是不存在的。这是因为真理具有相对性。"},{"id":"mk15044-pl-P1527310","type":"sc","tier":"基础","conf":"adapt","chap":"第2-3章","q":"唯物辩证法与形而上学在真理观上的对立，表现在是否承认（ ）。","opts":["A. 真理具有客观性","B. 真理具有相对性","C. 真理中包含着错误","D. 真理来源于主观创造"],"ans":1,"explain":"唯物辩证法与形而上学在真理观上的对立，表现在是否承认真理具有相对性。"},{"id":"mk15044-pl-P1527311","type":"sc","tier":"基础","conf":"adapt","chap":"第2-3章","q":"在真理标准问题上坚持辩证法，就是要承认实践标准（ ）。","opts":["A. 既是抽象的又是具体的","B. 既是必然的又是偶然的","C. 既是普遍的又是特殊的","D. 既是绝对的又是相对的"],"ans":3,"explain":"在真理标准问题上坚持辩证法，就是要承认实践标准既是绝对的又是相对的。"},{"id":"mk15044-pl-P1527312","type":"sc","tier":"基础","conf":"adapt","chap":"第2-3章","q":"在真理问题上坚持辩证法，就是要承认任何真理都是（ ）。","opts":["A. 客观性和主观性的统一","B. 主观性和相对性的统一","C. 客观性和绝对性的统一","D. 绝对性和相对性的统一"],"ans":3,"explain":"在真理问题上坚持辩证法，就是要承认任何真理都是绝对性和相对性的统一。"},{"id":"mk15044-pl-P1527315","type":"sc","tier":"基础","conf":"adapt","chap":"第2-3章","q":"真理都是具体的，包罗万象的真理是不存在的。这说明任何真理都具有（ ）。","opts":["A. 全面性","B. 相对性","C. 绝对性","D. 客观性"],"ans":1,"explain":"真理都是具体的，包罗万象的真理是不存在的。这说明任何真理都具有相对性。"},{"id":"mk15044-pl-P1527316","type":"sc","tier":"基础","conf":"adapt","chap":"第2-3章","q":"真理和谬误的区别在于（ ）","opts":["A. 真理是对外部世界的反映，谬误是主观自生的","B. 真理是对事物的正确反映，谬误是对事物的歪曲反映","C. 真理是绝对的，谬误是相对的","D. 真理是不变的，谬误是可变的"],"ans":1,"explain":"真理是对事物的正确反映，谬误是对事物的歪曲反映"},{"id":"mk15044-pl-P1527317","type":"sc","tier":"基础","conf":"adapt","chap":"第2-3章","q":"任何科学理论都不能穷尽真理，只能在实践中不断开辟认识真理的道路，这说明真理具有（）","opts":["A. 客观性","B. 绝对性","C. 相对性","D. 全面性"],"ans":2,"explain":"真理是绝对的，同时又是相对的，具有相对性，通常用“相对真理”这个概念表明真理具有相对性。"},{"id":"mk15044-pl-P1527318","type":"sc","tier":"基础","conf":"adapt","chap":"第2-3章","q":"作为真理的马克思主义是发展的，与时俱进的，这是因为真理具有（ ）。","opts":["A. 相对性","B. 能动性","C. 绝对性","D. 普遍性"],"ans":0,"explain":"作为真理的马克思主义是发展的，与时俱进的，这是因为真理具有相对性。"},{"id":"mk15044-pl-P1527320","type":"sc","tier":"基础","conf":"adapt","chap":"第2-3章","q":"中国共产党的认识路线可以概括为（）","opts":["A. 马克思主义哲学和科学社会主义","B. 唯物论辩证法和认识论","C. 解放思想实事求是","D. 无产阶级的世界观和价值观"],"ans":2,"explain":"党的思想路线是一个整体，是指导我们党各项工作的认识路线。是否坚持这条思想路线，关系到党和国家的前途和命运。邓小平指出：“只有解放思想，坚持实事求是，一切从实际出发，理论联系实际，我们的社会主义现代化建设才能顺利进行，我们党的马列主义、毛泽东思想的理论也才能顺利发展。”"},{"id":"mk15044-pl-P1527321","type":"sc","tier":"基础","conf":"adapt","chap":"第2-3章","q":"坚持马克思主义哲学的认识路线，就必须在工作中坚持（ ）。","opts":["A. 一切从实际出发","B. 一切从主观的愿望出发","C. 一切从理论出发","D. 一切从臆造的规律出发"],"ans":0,"explain":"坚持马克思主义哲学的认识路线，就必须在工作中坚持一切从实际出发。"},{"id":"mk15044-pl-P1527322","type":"sc","tier":"基础","conf":"adapt","chap":"第2-3章","q":"下列选项中，符合马克思主义检验真理标准观点的是（）","opts":["A. 以孔子的是非为是非","B. 以马克思主义理论为准绳","C. 以有用作为检验真理的标准","D. 以社会实践作为检验真理的标准"],"ans":3,"explain":"马克思主义哲学认识论认为，实践是检验真理的唯一标准"},{"id":"mk15044-pl-P1527323","type":"sc","tier":"基础","conf":"adapt","chap":"第2-3章","q":"马克思主义哲学认为，人追求符合客观实际的科学认识，归根到底是为了（ ）","opts":["A. 把握事物现象","B. 揭示事物本质","C. 追求自我实现","D. 改造客观世界"],"ans":3,"explain":"马克思主义哲学认为，人们之所以追求符合客观实际的科学认识，归根到底是为了用这种科学的认识去指导人们的实践，达到改变世界的目的。"},{"id":"mk15044-pl-P1527324","type":"sc","tier":"基础","conf":"adapt","chap":"第2-3章","q":"马克思主义哲学认为，人们追求符合客观实际的认识，归根到底是为了（ ）。","opts":["A. 把握事物现象","B. 揭示事物本质","C. 追求自我实现","D. 改造客观世界"],"ans":3,"explain":"马克思主义哲学认为，人们追求符合客观实际的认识，归根到底是为了改造客观世界（认识的目的全为了实践）。"},{"id":"mk15044-pl-P1527325","type":"sc","tier":"基础","conf":"adapt","chap":"第2-3章","q":"党的思想路线的核心是（ ）。","opts":["A. 一切从实际出发","B. 理论联系实际","C. 实事求是","D. 实践是检验真理的唯一标"],"ans":2,"explain":"实事求是是党的思想路线的核心。"},{"id":"mk15044-pl-P1527326","type":"sc","tier":"基础","conf":"adapt","chap":"第2-3章","q":"脱离实践的理论是空洞的理论；没有理论指导的实践是盲目的实践。这句话强调的是（ ）。","opts":["A. 认识过程中摹写与创造的统一","B. 认识过程中感性与理性的统一","C. 认识过程中真理与价值的统一","D. 认识过程中理论与实践的统一"],"ans":3,"explain":"这句话强调的是认识过程中理论与实践的统一，理论联系实践。"},{"id":"mk15044-pl-P1527327","type":"sc","tier":"基础","conf":"adapt","chap":"第2-3章","q":"认识的目的在于（）","opts":["A. 总结理论","B. 概括理论","C. 归纳理论","D. 运用"],"ans":3,"explain":"认识的目的全在于运用。"},{"id":"mk15044-pl-P1527328","type":"sc","tier":"基础","conf":"adapt","chap":"第2-3章","q":"“圣人不行而知”，这种观点属于（ ）。","opts":["A. 唯物主义反映论","B. 旧唯物主义直观反映论","C. 唯心主义先验论","D. 辩证唯物主义能动反映论"],"ans":2,"explain":"“圣人不行而知”，这种观点属于唯心主义先验论。"},{"id":"mk15044-pl-P1527329","type":"sc","tier":"基础","conf":"adapt","chap":"第2-3章","q":"德国古典哲学家康德认为，人们所能认识的只是客观世界的外在形象，对于现象后的本质，人的认识是无法达到的这种观点属于（）","opts":["A. 经验论","B. 反映论","C. 不可知论","D. 唯物论"],"ans":2,"explain":"德国古典哲学家康德认为，人们所能认识的只是客观世界的外在形象，对于现象后的本质，人的认识是无法达到的这种观点属于不可知论"},{"id":"mk15044-pl-P1527330","type":"sc","tier":"基础","conf":"adapt","chap":"第2-3章","q":"对不可知论最有力的驳斥是指出（ ）。","opts":["A. 外部世界是可以被人感知的","B. 人们能够透过现象揭示本质","C. 实践的成功能够证明认识正确","D. 感性认识可以上升到理性认识"],"ans":2,"explain":"对不可知论最有力的驳斥是指出实践的成功能够证明认识正确。"},{"id":"mk15044-pl-P1527331","type":"sc","tier":"基础","conf":"adapt","chap":"第2-3章","q":"可知论与不可知论的对立在于是否承认（ ）。","opts":["A. 人的认识是先于经验而获得的","B. 思维能够正确地认识现实世界","C. 人的认识是从外部世界得来的","D. 思维能够能动地认识现实世界"],"ans":1,"explain":"可知论与不可知论的对立在于是否承认思维能够正确地认识现实世界。"},{"id":"mk15044-pl-P1527332","type":"sc","tier":"基础","conf":"adapt","chap":"第2-3章","q":"马克思主义认识论认为，认识的本质是（ ）。","opts":["A. 主体对客体的直观反映","B. 主体对客体的自由创造","C. 主体对客体的能动反映","D. 主体对客体的简单摹写"],"ans":2,"explain":"马克思主义认识论认为，认识的本质是主体对客体的能动反映。"},{"id":"mk15044-pl-P1527333","type":"sc","tier":"基础","conf":"adapt","chap":"第2-3章","q":"能动反映论区别于机械反映论的根本标志是（ ）。","opts":["A. 肯定思维能正确地反映存在","B. 认为认识过程是纯粹的观念创造","C. 肯定思维对存在的决定作用","D. 认为认识过程是反映和创造的统一"],"ans":3,"explain":"能动反映论区别于机械反映论的根本标志是能动反映论认为认识过程是反映和创造的统一。"},{"id":"mk15044-pl-P1527334","type":"sc","tier":"基础","conf":"adapt","chap":"第2-3章","q":"认识主体的突出特点是（）","opts":["A. 社会历史性","B. 客观存在性","C. 能动性","D. 自然性"],"ans":2,"explain":"能动性是认识主体的突出特点。"},{"id":"mk15044-pl-P1527335","type":"sc","tier":"基础","conf":"adapt","chap":"第2-3章","q":"认识的本质是（）","opts":["A. 主体主观意识的创造","B. 主体对“客观精神”的体验","C. 主体对客观的直观反映","D. 主体对客体的能动反映"],"ans":3,"explain":"认识的本质是主体对客体的能动反映"},{"id":"mk15044-pl-P1527336","type":"sc","tier":"基础","conf":"adapt","chap":"第2-3章","q":"辩证唯物主义认识论认为，认识的本质是（）","opts":["A. 主体对客体的被动反映","B. 主体对客体的能动反映","C. 主体对客体的主观创造","D. 主体对客体的自由选择"],"ans":1,"explain":"认识的本质是主体对客体的能动反映"},{"id":"mk15044-pl-P1527337","type":"sc","tier":"基础","conf":"adapt","chap":"第2-3章","q":"辩证唯物主义反映论的能动性的突出表现是，认识过程是（）","opts":["A. 现象与本质的统一","B. 反映与创造的统一","C. 先验论与反映论的统一","D. 可知论和不可知论的统一"],"ans":1,"explain":"认识的过程是反映与创造的统一，这是辩证唯物论的反映论的能动性的突出表现，也是区别于机械唯物论反映论的根本标志。"},{"id":"mk15044-pl-P1527338","type":"sc","tier":"基础","conf":"adapt","chap":"第2-3章","q":"认识主体和认识客体的基本关系是（）","opts":["A. 反映与被反映的关系","B. 改造与被改造的关系","C. 相互依存的关系","D. 相互作用的关系"],"ans":1,"explain":"认识主体和认识客体的基本关系是改造与被改造的关系"},{"id":"mk15044-pl-P1527339","type":"sc","tier":"基础","conf":"adapt","chap":"第2-3章","q":"认识主体与认识客体之间最基本的关系是（ ）。","opts":["A. 改造与被改造的关系","B. 相互依存的关系","C. 反映与被反映的关系","D. 相互作用的关系"],"ans":0,"explain":"认识主体与认识客体之间最基本的关系是改造与被改造的关系，认识主体改造认识客体。"},{"id":"mk15044-pl-P1527340","type":"sc","tier":"基础","conf":"adapt","chap":"第2-3章","q":"有一种观点认为，认识只是人的一种内心体验或者精神的作用，不与外部世界发生任何关系。这种观点属于（）","opts":["A. 主观唯心主义","B. 客观唯心主义","C. 朴素唯物主义","D. 形而上学唯物主义"],"ans":0,"explain":"主观唯心主义把认识客体说成是主观意识或感觉，认为认识就是认识人的主观意识或感觉"},{"id":"mk15044-pl-P1527341","type":"sc","tier":"基础","conf":"adapt","chap":"第2-3章","q":"下列各项中，强调认识来源于实践的是（ ）。","opts":["A. 不积跬步，无以至千里","B. 蝉噪林愈静，鸟鸣山更幽","C. 不积小流，无以成江海","D. 近水知鱼性，近山识鸟音"],"ans":3,"explain":"“近水知鱼性，近山识鸟音”是强调认识来源于实践的。"},{"id":"mk15044-pl-P1527342","type":"sc","tier":"基础","conf":"adapt","chap":"第2-3章","q":"那种主张“天赋的才能”“天生的心灵禀赋”的观点属于（ ）。","opts":["A. 唯心主义先验论","B. 旧唯物论的直观反映论","C. 唯物主义反映论","D. 辩证唯物主义的能动反映论"],"ans":0,"explain":"“天赋的才能”“天生的心灵禀赋”属于唯心主义先验论的观点。"},{"id":"mk15044-pl-P1527343","type":"sc","tier":"基础","conf":"adapt","chap":"第2-3章","q":"下列选项中，反映实践对意识具有决定作用的是（ ）。","opts":["A. 芳林新叶催陈叶，流水前波让后波","B. 沉舟侧畔千帆过，病树前头万木春","C. 勿以善小而不为，勿以恶小而为之","D. 纸上得来终觉浅，绝知此事要躬行"],"ans":3,"explain":"“纸上得来终觉浅，绝知此事要躬行”反映了实践对意识具有决定作用，实践是认识的基础。"},{"id":"mk15044-pl-P1527344","type":"sc","tier":"基础","conf":"adapt","chap":"第2-3章","q":"辩证唯物主义认识论区别于旧唯物主义认识论的基本观点是（ ）。","opts":["A. 实践是认识的基础","B. 认识是主体对客体的反映","C. 世界是可以认识的","D. 认识是一个发展过程"],"ans":0,"explain":"辩证唯物主义认识论区别于旧唯物主义认识论的基本观点是实践是认识的基础。"},{"id":"mk15044-pl-P1527345","type":"sc","tier":"基础","conf":"adapt","chap":"第2-3章","q":"恩格斯指出：“社会一旦有技术上的需要，这种需要就会比十所大学更能把科学推向前进。”这表明（）","opts":["A. 实践是认识的来源","B. 实践是认识发展的动力","C. 实践是认识的目的","D. 实践的主体是人"],"ans":1,"explain":"恩格斯指出：“社会一旦有技术上的需要，这种需要就会比十所大学更能把科学推向前进。”这表明实践是认识发展的动力"},{"id":"mk15044-pl-P1527346","type":"sc","tier":"基础","conf":"adapt","chap":"第2-3章","q":"下列各项中，反映实践对认识具有决定作用的是（ ）","opts":["A. 芳林新叶催陈叶，流水前波让后波","B. 沉舟侧畔千帆过，病树前头万木春","C. 勿以恶小而为之，勿以善小而不为","D. 纸上得来终觉浅，绝知此事要躬行"],"ans":3,"explain":"反映实践对认识具有决定作用的是纸上得来终觉浅，绝知此事要躬行"},{"id":"mk15044-pl-P1527347","type":"sc","tier":"基础","conf":"adapt","chap":"第2-3章","q":"辩证唯物主义认识论第一的和基本的观点是（ ）","opts":["A. 认识是主体对客体的反映","B. 实践是认识的基础","C. 认识是一个辩证发展过程","D. 认识是从物到感觉和思想的过程"],"ans":1,"explain":"马克思主义哲学把实践观引入认识论中来，克服了以往唯物论在认识论上的局限性，认为实践的观点是辩证唯物主义认识论第一的和基本的观点，实践是认识的基础，从而引起了认识论的革命。"},{"id":"mk15044-pl-P1527349","type":"sc","tier":"基础","conf":"adapt","chap":"第2-3章","q":"人们认识世界的目的在于（ ）。","opts":["A. 发展个人的兴趣爱好","B. 实现对自身能力的改造","C. 满足人类的求知欲望","D. 实现对客观世界的改造"],"ans":3,"explain":"人们认识世界的目的在于实现对客观世界的改造（实践）。"},{"id":"mk15044-pl-P1527350","type":"sc","tier":"基础","conf":"adapt","chap":"第2-3章","q":"实践观是马克思主义的（）观点","opts":["A. 一般的","B. 特殊的","C. 基本的","D. 个别的"],"ans":2,"explain":"认为实践的观点是辩证唯物主义认识论第一的和基本的观点"},{"id":"mk15044-pl-P1527351","type":"sc","tier":"基础","conf":"adapt","chap":"第2-3章","q":"实践是认识的来源，这表明（）","opts":["A. 只要参加实践活动就能获得正确的认识","B. 一切认识都要直接参与社会实践才能获得","C. 一切认识归根到底都是从实践中获得的","D. 只有直接经验才是最可靠的"],"ans":2,"explain":"实践是认识的来源，这表明一切认识归根到底都是从实践中获得的"},{"id":"mk15044-pl-P1527352","type":"sc","tier":"基础","conf":"adapt","chap":"第2-3章","q":"宋代诗人陆游在诗中写道“纸上得来终觉浅，绝知此事要躬行”是强调（）","opts":["A. 读书不能获得知识","B. 实践是认识发展的动力","C. 实践是认识的来源","D. 实践是认识的目的"],"ans":2,"explain":"宋代诗人陆游在诗中写道“纸上得来终觉浅，绝知此事要躬行”是强调实践是认识的来源"},{"id":"mk15044-pl-P1527353","type":"sc","tier":"基础","conf":"adapt","chap":"第2-3章","q":"只有通过实践，客观事物才会成为认识的对象，才会有人对客观事物的认识，这表明（）","opts":["A. 实践是认识的来源","B. 实践是认识发展的动力","C. 实践是认识的目的","D. 实践是检验认识正确与否的标准"],"ans":0,"explain":"只有通过实践，客观事物才会成为认识的对象，才会有人对客观事物的认识，这表明实践是认识的来源"},{"id":"mk15044-pl-P1527477","type":"sc","tier":"基础","conf":"adapt","chap":"第2-3章","q":"阶级斗争的根源在于两个阶级之间（ ）。","opts":["A. 物质利益对立","B. 政治立场的不同","C. 思想观念的对立","D. 社会分工的不同"],"ans":0,"explain":"阶级斗争的根源在于两个阶级之间物质利益对立。"},{"id":"mk15044-pl-P1527478","type":"sc","tier":"基础","conf":"adapt","chap":"第2-3章","q":"阶级斗争归根到底是（ ）。","opts":["A. 由物质利益的对立引起的","B. 由思想观念的分歧引起的","C. 由政治主张的差异引起的","D. 由宗教信仰的不同引起的"],"ans":0,"explain":"阶级斗争归根到底是由物质利益的对立引起的。"},{"id":"mk15044-pl-P1527479","type":"sc","tier":"基础","conf":"adapt","chap":"第2-3章","q":"阶级斗争归根结底是由（ ）。","opts":["A. 物质利益的对立引起的","B. 思想观念的分歧引起的","C. 政治理念的差异引起的","D. 宗教信仰的不同引起的"],"ans":0,"explain":"阶级斗争归根结底是由物质利益的对立引起的。"},{"id":"mk15044-pl-P1527481","type":"sc","tier":"基础","conf":"adapt","chap":"第2-3章","q":"马克思主义认为划分阶级的唯一标准是（）","opts":["A. 经济标准","B. 政治标准","C. 思想标准","D. 社会标准"],"ans":0,"explain":"阶级首先是一个经济范畴，是一些经济集团，划分阶级的唯一标准是经济标准，不能用政治标准和思想标准划分阶级。"},{"id":"mk15044-pl-P1527482","type":"sc","tier":"基础","conf":"adapt","chap":"第2-3章","q":"阶级作为一种社会现象首先是一个（ ）。","opts":["A. 经济范畴","B. 政治范畴","C. 文化范畴","D. 交往范畴"],"ans":0,"explain":"阶级作为一种社会现象首先是一个经济范畴。"},{"id":"mk15044-pl-P1527483","type":"sc","tier":"基础","conf":"adapt","chap":"第2-3章","q":"阶级斗争的根源在于（）","opts":["A. 社会政治格局的改变","B. 各种政治主张的对立","C. 各阶级之间物质利益的对立","D. 思想和道德观念的根本对立"],"ans":2,"explain":"物质利益的对立是阶级斗争的根源"},{"id":"mk15044-pl-P1527484","type":"sc","tier":"基础","conf":"adapt","chap":"第2-3章","q":"“革命是解放生产力，改革也是解放生产力”，这一论断的提出者是（ ）。","opts":["A. 马克思","B. 恩格斯","C. 邓小平","D. 江泽民"],"ans":2,"explain":"“革命是解放生产力，改革也是解放生产力”，这一论断的提出者是邓小平。"},{"id":"mk15044-pl-P1527485","type":"sc","tier":"基础","conf":"adapt","chap":"第2-3章","q":"从历史上看，暴力革命是社会革命的（ ）。","opts":["A. 唯一形式","B. 基本形式","C. 辅助形式","D. 补充形式"],"ans":1,"explain":"从历史上看，暴力革命是社会革命的基本形式。"},{"id":"mk15044-pl-P1527486","type":"sc","tier":"基础","conf":"adapt","chap":"第2-3章","q":"马克思说：“革命是历史的火车头”。这句话形象而深刻地说明了（）","opts":["A. 生产力和生产关系矛盾的激化是社会革命的根源","B. 暴力革命是社会革命的基本形式","C. 革命对推动社会发展的重大作用","D. 革命是实现社会变革的唯一形式"],"ans":2,"explain":"马克思说“革命是历史的火车头”，这句话形象而深刻地说明了社会革命在社会发展中的重大作用。"},{"id":"mk15044-pl-P1527487","type":"sc","tier":"基础","conf":"adapt","chap":"第2-3章","q":"在社会存在与社会意识的关系问题上，两种根本对立的观点是（ ）。","opts":["A. 机械唯物主义和辩证唯物主义","B. 可知论和不可知论","C. 历史唯物主义和历史唯心主义","D. 辩证法与形而上学"],"ans":2,"explain":"在社会存在与社会意识的关系问题上，两种根本对立的观点是历史唯物主义和历史唯心主义。"},{"id":"mk15044-pl-P1527489","type":"sc","tier":"基础","conf":"adapt","chap":"第2-3章","q":"在奴隶社会，封建社会和资本主义社会中，社会发展的直接动力是（）","opts":["A. 生产力和生产关系的矛盾","B. 经济体制和政治体制的矛盾","C. 阶级矛盾和阶级斗争","D. 进步社会势力和保守社会势力的斗争"],"ans":2,"explain":"阶级斗争是阶级社会发展的直接动力，但是，阶级矛盾和阶级斗争是社会基本矛盾的表现，社会基本矛盾决定着阶级矛盾和阶级斗争的发展阶段和发展状况，制约着阶级矛盾和阶级斗争的特点及其解决方式。"},{"id":"mk15044-pl-P1527490","type":"sc","tier":"基础","conf":"adapt","chap":"第2-3章","q":"人类社会的基本矛盾是作为推动社会历史发展的（）","opts":["A. 基本动力","B. 基本形式","C. 重要动力","D. 补充形式"],"ans":0,"explain":"社会基本矛盾是社会发展的基本动力。"},{"id":"mk15044-pl-P1527491","type":"sc","tier":"基础","conf":"adapt","chap":"第2-3章","q":"人类社会的基本矛盾是（）","opts":["A. 人与自然界之间的矛盾","B. 社会存在和社会意识之间的矛盾","C. 社会物质生产和社会精神生产之间的矛盾","D. 生产力与生产关系经济基础和上层建筑之间的矛盾"],"ans":3,"explain":"生产力和生产关系之间的矛盾、经济基础和上层建筑之间的矛盾，存在于一切社会形态之中，贯穿于每一个社会形态的始终。这两对矛盾制约和决定着其他各种社会矛盾，决定着整个社会的面貌，决定着社会发展的必然阶段和客观趋势，决定社会形态由低级到高级的演进。所以社会基本矛盾是社会发展的基本动力。"},{"id":"mk15044-pl-P1527494","type":"sc","tier":"基础","conf":"adapt","chap":"第2-3章","q":"唯心史观在历史创造者问题上的根本错误在于（ ）。","opts":["A. 否认个人在历史发展中的作用","B. 否认思想动机在历史发展中的作用","C. 否认少数英雄人物是推动历史发展的决定力量","D. 否认广大人民群众是推动历史发展的决定力量"],"ans":3,"explain":"唯心史观在历史创造者问题上的根本错误在于否认广大人民群众是推动历史发展的决定力量。"},{"id":"mk15044-pl-P1527495","type":"sc","tier":"基础","conf":"adapt","chap":"第2-3章","q":"在历史创造者问题上，两种根本对立的观点是（ ）。","opts":["A. 群众史观和英雄史观","B. 一元论和二元论","C. 宿命论和唯意志论","D. 唯理论和经验论"],"ans":0,"explain":"在历史创造者问题上，两种根本对立的观点是群众史观和英雄史观"},{"id":"mk15044-pl-P1527497","type":"sc","tier":"基础","conf":"adapt","chap":"第2-3章","q":"在人类社会发展中起决定作用的是（ ）。","opts":["A. 差异多样的地理环境","B. 丰腴富饶的自然资源","C. 协调合理的人口结构","D. 物质资料的生产方式"],"ans":3,"explain":"在人类社会发展中起决定作用的是物质资料的生产方式。"},{"id":"mk15044-pl-P1527498","type":"sc","tier":"基础","conf":"adapt","chap":"第2-3章","q":"在历史发展的决定性和历史主体的选择性的关系问题上，历史唯物主义的观点是（）","opts":["A. 主体选择作用与历史发展的决定性是矛盾的","B. 主体选择作用与历史发展的决定性是一致的","C. 主体的选择可以摆脱历史发展的规律","D. 历史决定论是根本错误的"],"ans":1,"explain":"承认历史决定论和承认主体选择的作用是一致的，人们对社会历史发展的客观规律的揭示，正是为探寻作为历史主体的人的选择活动开辟广阔的天地，使人的主体特性能得以更自由、更充分地发挥，从而能以日益合乎客观规律的活动，更加自觉地创造自己的历史。"},{"id":"mk15044-pl-P1527502","type":"sc","tier":"基础","conf":"adapt","chap":"第2-3章","q":"唯物史观认为，杰出人物的出现是（ ）。","opts":["A. 历史命运的安排","B. 纯粹的历史必然","C. 时代发展的需要","D. 纯粹的历史偶然"],"ans":2,"explain":"唯物史观认为，杰出人物的出现是时代发展的需要。"},{"id":"mk15044-pl-P1527503","type":"sc","tier":"基础","conf":"adapt","chap":"第2-3章","q":"下列关于人的本质的说法中不正确的是（ ）。","opts":["A. 人的本质是发展变化的","B. 人的本质是现实具体的","C. 人的本质是后天形成的","D. 人的本质是人人相同的"],"ans":3,"explain":"马克思指出人的本质是社会属性，每个人都受到不同的影响，所以并不是人人相同的。"},{"id":"mk15044-pl-P1527504","type":"sc","tier":"基础","conf":"adapt","chap":"第2-3章","q":"人的本质在于（ ）。","opts":["A. 人的自然属性","B. 人的道德素质","C. 人的社会属性","D. 人的文化素质"],"ans":2,"explain":"马克思主义认为，人有自然属性和社会属性两种属性。人的本质不是由人的自然属性决定的，而是由人的社会属性决定的。"},{"id":"mk15044-pl-P1527505","type":"sc","tier":"基础","conf":"adapt","chap":"第2-3章","q":"下列关于人的本质的表述中，正确的是（ ）。","opts":["A. 人的本质不是后天的而是先天的","B. 人的本质不是具体的而是抽象的","C. 人的本质不是变化的而是永恒的","D. 在阶级社会里人的本质是有阶级性的"],"ans":3,"explain":"由于人的具体本质在其现实性上是一切社会关系的总和，即它是由社会关系决定的，所以它就不是先天的，而是后天的；不是抽象的，而是具体的；不是不变的，而是随着社会关系的变化发生相应变化的；在阶级社会里不是超阶级的，而是有阶级性的。本题选D。"},{"id":"mk15044-pl-P1527507","type":"sc","tier":"基础","conf":"adapt","chap":"第2-3章","q":"人的本质在其现实性上是（ ）。","opts":["A. 人的道德品性","B. 人的经济地位","C. 人的价值追求","D. 一切社会关系的总和"],"ans":3,"explain":"人的本质在其现实性上是一切社会关系的总和。"},{"id":"mk15044-pl-P1527509","type":"sc","tier":"基础","conf":"adapt","chap":"第2-3章","q":"唯物史观认为，人的本质在其现实性上是（ ）。","opts":["A. 人的价值追求","B. 人的政治立场","C. 人的情感态度","D. 人的一切社会关系的总和"],"ans":3,"explain":"唯物史观认为，人的本质在其现实性上是人的一切社会关系的总和。"},{"id":"mk15044-pl-P1527510","type":"sc","tier":"基础","conf":"adapt","chap":"第2-3章","q":"下列关于人的本质的表述正确的是（ ）","opts":["A. 人的本质不是后天的而是先天的","B. 人的本质不是具体的而是抽象的","C. 人的本质不是变化的而是永恒的","D. 在阶级社会里人的本质是有阶级性的"],"ans":3,"explain":"在阶级社会里不是超阶级的，而是有阶级性的。"},{"id":"mk15044-pl-P1527511","type":"sc","tier":"基础","conf":"adapt","chap":"第2-3章","q":"在马克思主义看来，人的本质（ ）。","opts":["A. 是由人的文化素质决定的","B. 是由人的心理素质决定的","C. 是由人的社会属性决定的","D. 是由人的自然属性决定的"],"ans":2,"explain":"在马克思主义看来，人的本质是由人的社会属性决定的。"},{"id":"mk15044-pl-P1527513","type":"sc","tier":"基础","conf":"adapt","chap":"第2-3章","q":"社会改革和社会革命都根源于（ ）。","opts":["A. 生产力和生产关系的矛盾","B. 社会存在和社会意识的矛盾","C. 人口增长和资源匮乏的矛盾","D. 创新意识和传统观念的矛盾"],"ans":0,"explain":"社会改革和社会革命都根源于生产力和生产关系的矛盾。"},{"id":"mk15044-pl-P1527514","type":"sc","tier":"基础","conf":"adapt","chap":"第2-3章","q":"在劳动资料中，最能标志生产力发展水平的因素是()","opts":["A. 运输设备","B. 仓储设备","C. 生产工具","D. 维修工具"],"ans":2,"explain":"生产工具是劳动资料的主要内容，是生产力发展水平的主要标志。"},{"id":"mk15044-pl-P1527515","type":"sc","tier":"基础","conf":"adapt","chap":"第2-3章","q":"在生产力系统独立的实体性要素中，标志生产力发展水平的是（）","opts":["A. 劳动者的技能","B. 劳动对象的优劣","C. 生产工具的状况","D. 劳动产品的质量"],"ans":2,"explain":"生产工具是劳动资料的主要内容，是生产力发展水平的主要标志。"},{"id":"mk15044-pl-P1527516","type":"sc","tier":"基础","conf":"adapt","chap":"第2-3章","q":"衡量生产力发展水平的主要标志是（）","opts":["A. 生产工具","B. 管理手段","C. 劳动对象","D. 科学技术"],"ans":0,"explain":"生产工具是劳动资料的主要内容，是生产力发展水平的主要标志。"},{"id":"mk15044-pl-P1527517","type":"sc","tier":"基础","conf":"adapt","chap":"第2-3章","q":"我国社会主义初级阶段实行以公有制为主体.多种所有制经济共同发展的基本经济制度，促进了生产力的发展，说明实行这种制度遵循了（）","opts":["A. 生产力决定生产关系的原理","B. 经济基础决定上层建筑的原理","C. 社会存在决定社会意识的原理","D. 经济制度决定生产力状况的原理"],"ans":0,"explain":"生产关系必须适合生产力性质的规律，是无产阶级政党制定正确的路线、方针、政策的理论依据。正确理解和运用这个规律，对于我国正在进行的改革开放和社会主义现代化建设，具有重大的指导意义。我国社会主义初级阶段实行以公有制为主体、多种所有制经济共同发展的基本经济制度，就是以这一规律为理论依据的。"},{"id":"mk15044-pl-P1527518","type":"sc","tier":"基础","conf":"adapt","chap":"第2-3章","q":"下列关于生产力和生产关系的表述中，不正确的是（ ）。","opts":["A. 生产力的性质决定生产关系的性质","B. 生产力的发展决定生产关系的改变","C. 生产关系对生产力具有巨大的反作用","D. 生产关系总是适应生产力的发展要求"],"ans":3,"explain":"生产关系并不总是适应生产力的发展要求，可能会比生产力更先进，或者又比生产力落后。"},{"id":"mk15044-pl-P1527519","type":"sc","tier":"基础","conf":"adapt","chap":"第2-3章","q":"生产力发展水平的主要标志是（ ）。","opts":["A. 生产工具","B. 运输工具","C. 通讯设备","D. 包装设备"],"ans":0,"explain":"生产力发展水平的主要标志是生产工具。"},{"id":"mk15044-pl-P1527520","type":"sc","tier":"基础","conf":"adapt","chap":"第2-3章","q":"历史唯物主义的生产力范畴反映的是（）","opts":["A. 人与自然界的关系","B. 人与社会的关系","C. 人与劳动产品的关系","D. 人与劳动资料的关系"],"ans":0,"explain":"生产力范畴反映的是人与自然界的关系。"},{"id":"mk15044-pl-P1527522","type":"sc","tier":"基础","conf":"adapt","chap":"第2-3章","q":"自然科学属于生产力范畴，这是因为（）","opts":["A. 它是对自然界的现象及其发展规律的正确认识","B. 它渗透到生产力诸要素中并转化为现实生产力","C. 它能把生产力系统中的各要素组合成统一整体","D. 它是构成现代生产力系统的最重要的独立因素"],"ans":1,"explain":"生产力是人类利用自然、改造自然、从自然界获取物质资料的能力，生产力范畴反映的是人与自然界的关系。"},{"id":"mk15044-pl-P1527523","type":"sc","tier":"基础","conf":"adapt","chap":"第2-3章","q":"在整个生产关系体系中，决定该体系的性质是（）","opts":["A. 生产资料所有制","B. 产品分配方式","C. 人们在生产中的地位和关系","D. 生产过程中人与人的关系"],"ans":0,"explain":"生产资料所有制形式在生产关系体系里起着决定作用，它是整个生产关系的基础"},{"id":"mk15044-pl-P1527524","type":"sc","tier":"基础","conf":"adapt","chap":"第2-3章","q":"在生产关系的构成要素中，起决定作用的是（）","opts":["A. 产品分配方式","B. 人们在生产中的地位","C. 人们在生产中的相互关系","D. 生产资料所有制形式"],"ans":3,"explain":"生产资料所有制形式在生产关系体系里起着决定作用，它是整个生产关系的基础"},{"id":"mk15044-pl-P1527525","type":"sc","tier":"基础","conf":"adapt","chap":"第2-3章","q":"现代生产力系统的渗透性因素是指（ ）。","opts":["A. 教育","B. 管理","C. 生产资料","D. 自然科学"],"ans":3,"explain":"现代生产力系统的渗透性因素是指自然科学。"},{"id":"mk15044-pl-P1527527","type":"sc","tier":"基础","conf":"adapt","chap":"第2-3章","q":"在劳动资料这一复杂系统中，最能标志生产力发展水平的是（ ）。","opts":["A. 运输设备","B. 传动装置","C. 动力系统","D. 生产工具"],"ans":3,"explain":"在劳动资料这一复杂系统中，最能标志生产力发展水平的是生产工具。"},{"id":"mk15044-pl-P1527528","type":"sc","tier":"基础","conf":"adapt","chap":"第2-3章","q":"在生产关系的各项内容中，起决定作用的是（ ）。","opts":["A. 人们在生产中的地位","B. 人们在生产中的相互关系","C. 产品的分配方式","D. 生产资料的所有制形式"],"ans":3,"explain":"在生产关系的各项内容中，起决定作用的是生产资料的所有制形式。"},{"id":"mk15044-pl-P1527529","type":"sc","tier":"基础","conf":"adapt","chap":"第2-3章","q":"在生产关系的诸要素中起决定作用的是（ ）。","opts":["A. 产品的分配方式","B. 人们在生产中的地位","C. 产品的交换方式","D. 生产资料的所有制形式"],"ans":3,"explain":"在生产关系的诸要素中起决定作用的是生产资料的所有制形式。"},{"id":"mk15044-pl-P1527530","type":"sc","tier":"基础","conf":"adapt","chap":"第2-3章","q":"在现代生产力系统中，教育属于（ ）。","opts":["A. 实体性因素","B. 运筹性因素","C. 准备性因素","D. 渗透性因素"],"ans":2,"explain":"在现代生产力系统中，教育属于准备性因素。"},{"id":"mk15044-pl-P1527531","type":"sc","tier":"基础","conf":"adapt","chap":"第2-3章","q":"在现代生产力系统中，生产工具属于（ ）。","opts":["A. 实体性因素","B. 运筹性因素","C. 渗透性因素","D. 准备性因素"],"ans":0,"explain":"在现代生产力系统中，生产工具属于实体性因素。"},{"id":"mk15044-pl-P1527532","type":"sc","tier":"基础","conf":"adapt","chap":"第2-3章","q":"在现代生产力系统中，自然科学属于（ ）。","opts":["A. 实体性因素","B. 运筹性因素","C. 渗透性因素","D. 准备性因素"],"ans":2,"explain":"在现代生产力系统中，自然科学属于渗透性因素。"},{"id":"mk15044-pl-P1527533","type":"sc","tier":"基础","conf":"adapt","chap":"第2-3章","q":"生产力系统中独立的实体要素包括（）","opts":["A. 运输设备决策管理预测决策","B. 仓储设备科学技术灌溉设备","C. 劳动者劳动资料劳动对象","D. 劳动者科学技术生产工具"],"ans":2,"explain":"这是以物质实体形式相对独立存在的因素，包括劳动者、劳动资料和劳动对象。"},{"id":"mk15044-pl-P1527534","type":"sc","tier":"基础","conf":"adapt","chap":"第2-3章","q":"经济基础决定上层建筑，这就是说（ ）。","opts":["A. 任何上层建筑都产生于经济基础之后","B. 任何上层建筑都根源于经济基础","C. 上层建筑任何部分的变化都与经济基础的变化同步","D. 上层建筑整体的变化与经济基础的变化同步"],"ans":1,"explain":"经济基础决定上层建筑，这就是说任何上层建筑都根源于经济基础。"},{"id":"mk15044-pl-P1527535","type":"sc","tier":"基础","conf":"adapt","chap":"第2-3章","q":"马克思主义认为，经济基础是一定社会中（）","opts":["A. 生产力系统各要素的总和","B. 生产力和生产关系各方面的总和","C. 占统治地位的各种生产关系的总和","D. 占统治地位的生产关系各方面的总和"],"ans":3,"explain":"经济基础是指一个社会中占统治地位的生产关系各个方面的总和"},{"id":"mk15044-pl-P1527536","type":"sc","tier":"基础","conf":"adapt","chap":"第2-3章","q":"除了生产力与生产关系的矛盾，另一对社会基本矛盾是（ ）。","opts":["A. 社会存在与社会意识的矛盾","B. 社会生产和社会消费的矛盾","C. 经济基础和上层建筑的矛盾","D. 先进意识和落后意识的矛盾"],"ans":2,"explain":"社会基本矛盾有两对，分别是生产力与生产关系的矛盾、经济基础和上层建筑的矛盾。"},{"id":"mk15044-pl-P1527537","type":"sc","tier":"基础","conf":"adapt","chap":"第2-3章","q":"在上层建筑的各种要素中，居于主导地位的是（ ）。","opts":["A. 艺术","B. 宗教","C. 政治","D. 哲学"],"ans":2,"explain":"在上层建筑的各种要素中，居于主导地位的是政治因素。"},{"id":"mk15044-pl-P1527539","type":"sc","tier":"基础","conf":"adapt","chap":"第2-3章","q":"划分经济社会形态所依据的标准是（ ）。","opts":["A. 生产力的水平","B. 生产关系的性质","C. 社会意识的内容","D. 政治制度的状况"],"ans":1,"explain":"划分经济社会形态所依据的标准是生产关系的性质。"},{"id":"mk15044-pl-P1527540","type":"sc","tier":"基础","conf":"adapt","chap":"第2-3章","q":"下列各项中，属于技术社会形态序列的是（ ）。","opts":["A. 原始社会","B. 封建社会","C. 工业社会","D. 个人全面发展的社会"],"ans":2,"explain":"技术社会形态序列包括：渔猎社会--农业社会--工业社会--信息社会。"},{"id":"mk15044-pl-P1527541","type":"sc","tier":"基础","conf":"adapt","chap":"第2-3章","q":"既承认历史发展的决定性又承认历史发展的选择性，这属于（ ）。","opts":["A. 历史唯物论观点","B. 相对主义观点","C. 历史循环论","D. 折衷主义"],"ans":0,"explain":"既承认历史发展的决定性又承认历史发展的选择性，这属于历史唯物论观点。"},{"id":"mk15044-pl-P1527542","type":"sc","tier":"基础","conf":"adapt","chap":"第2-3章","q":"既坚持历史决定论又承认主体选择的作用，这属于（ ）。","opts":["A. 历史唯物论观点","B. 相对主义观点","C. 诡辩论观点","D. 折衷主义观点"],"ans":0,"explain":"既坚持历史决定论又承认主体选择的作用，这属于历史唯物论观点。"},{"id":"mk15044-pl-P1527543","type":"sc","tier":"基础","conf":"adapt","chap":"第2-3章","q":"将社会形态细分原始社会、奴隶社会、封建社会、资本主义社会、共产主义社会是属于（）","opts":["A. 经济社会形态划分法","B. 技术社会形态划分法","C. 三种社会形态划分法","D. 七种社会形态划分法"],"ans":0,"explain":"将社会形态细分原始社会、奴隶社会、封建社会、资本主义社会、共产主义社会是属于经济社会形态划分法"},{"id":"mk15044-pl-P1527544","type":"sc","tier":"基础","conf":"adapt","chap":"第2-3章","q":"人类社会是一个内容丰富结构复杂的系统，我们可以根据研究问题的不同需要，运用不同标准划分社会形态，“经济社会形态”的划分标准是（）","opts":["A. 生产关系的性质","B. 生产力的性质","C. 产品的分配方式","D. 人们在生产中的地位及相互关系"],"ans":0,"explain":"经济社会形态是直接或间接以生产关系的性质为标准划分的社会形态。"},{"id":"mk15044-pl-P1527545","type":"sc","tier":"基础","conf":"adapt","chap":"第2-3章","q":"在马克思主义哲学中，划分“经济社会形态”的标准是（）","opts":["A. 产品的分配方式","B. 生产关系的性质","C. 人们收入的差别","D. 人们社会关系的差别"],"ans":1,"explain":"经济社会形态是直接或间接以生产关系的性质为标准划分的社会形态。"},{"id":"mk15044-pl-P1527546","type":"sc","tier":"基础","conf":"adapt","chap":"第2-3章","q":"社会意识形态最基本的划分方法之一是（）","opts":["A. 意识形态划分法","B. 经济社会形态划分法","C. 文化形态划分法","D. 政治形态划分法"],"ans":1,"explain":"经济社会形态是直接或间接以生产关系的性质为标准划分的社会形态。"},{"id":"mk15044-pl-P1527547","type":"sc","tier":"基础","conf":"adapt","chap":"第2-3章","q":"建国初期，我国在特定历史条件下，选择了高度集中的计划经济体制，后来由于这种体制弊端的日益暴露，我们进行了体制改革，1992年以来我们逐步建立和完善了社会主义市场经济体制。这说明（）","opts":["A. 社会历史发展是没有规律的","B. 马克思主义的历史决定论是错误的","C. 历史是人们主观选择的结果","D. 历史规律面前，人们对具体模式的选择有巨大的能动性"],"ans":3,"explain":"每一种可能性的实现，又会有多种多样的形式，即各种具体的模式和途径。人们对具体模式和途径的选择，可以表现出巨大的能动性。"},{"id":"mk15044-pl-P1527548","type":"sc","tier":"基础","conf":"adapt","chap":"第2-3章","q":"下列选项属于经济社会形态的是（ ）。","opts":["A. 农业社会","B. 工业社会","C. 信息社会","D. 奴隶社会"],"ans":3,"explain":"农业社会、工业社会、信息社会都属于技术社会形态序列，选项中只有奴隶社会属于经济社会形态序列。"},{"id":"mk15044-pl-P1527549","type":"sc","tier":"基础","conf":"adapt","chap":"第2-3章","q":"“社会形态的发展是一个自然历史过程”这句话说的是（）","opts":["A. 社会规律与自然规律完全相同","B. 社会发展是纯粹自发过程","C. 社会发展不受人的思维动机的影响","D. 社会发展具有不以人的意志为转移的客观规律性"],"ans":3,"explain":"人类社会的发展或者说社会形态的演变像自然界一样，是客观的、物质的、辩证的过程，具有不依人的意志为转移的客观规律性。同时又应看到，人类的活动是有意识、有目的的。"},{"id":"mk15044-pl-P1527551","type":"sc","tier":"基础","conf":"adapt","chap":"第2-3章","q":"下列各项中，属于经济社会形态序列的是（ ）。","opts":["A. 渔猎社会","B. 封建社会","C. 工业社会","D. 信息社会"],"ans":1,"explain":"渔猎社会、工业社会、信息社会都属于技术社会形态序列，选项中只有封建社会属于经济社会形态序列。"},{"id":"mk15044-pl-P1527552","type":"sc","tier":"基础","conf":"adapt","chap":"第2-3章","q":"“作为观念形态的文艺作品，都是一定的社会生活在人类头脑中的反映的产物”，这句话强调的是（）","opts":["A. 社会意识根源于社会存在","B. 社会意识具有历史继承性","C. 社会存在根源于社会意识","D. 社会意识具有相对独立性"],"ans":0,"explain":"“作为观念形态的文艺作品，都是一定的社会生活在人类头脑中的反映的产物”，这句话强调的是社会意识根源于社会存在"},{"id":"mk15044-pl-P1527554","type":"sc","tier":"基础","conf":"adapt","chap":"第2-3章","q":"在历史唯物主义看来，决定社会制度的性质和更替的是（）","opts":["A. 精神生产","B. 生产方式","C. 政治活动","D. 文化活动"],"ans":1,"explain":"地理环境虽然对社会发展起制约和影响作用，但对社会发展不起主要的决定作用。这是因为地理环境不能决定社会制度的性质和社会形态的更替，地理环境在社会发展中的作用受社会因素，主要受生产力和生产关系的制约。"},{"id":"mk15044-pl-P1527555","type":"sc","tier":"基础","conf":"adapt","chap":"第2-3章","q":"地理环境对社会发展的作用主要通过（）","opts":["A. 对人的生理结构的影响来实现","B. 对人的心理素质的影响来实现","C. 对民族风俗的影响来实现","D. 对生产的影响来实现"],"ans":3,"explain":"地理环境通过对生产的影响，加速或延缓社会的发展。"},{"id":"mk15044-pl-P1527556","type":"sc","tier":"基础","conf":"adapt","chap":"第2-3章","q":"地理环境在社会发展中的作用主要通过（ ）。","opts":["A. 对个体心理素质的影响实现","B. 对物质生产的影响实现","C. 对个体生理结构的影响实现","D. 对民族气质的影响实现"],"ans":1,"explain":"地理环境在社会发展中的作用主要通过对物质生产的影响实现。"},{"id":"mk15044-pl-P1527559","type":"sc","tier":"基础","conf":"adapt","chap":"第2-3章","q":"划分历史唯物主义和历史唯心主义唯一标准是看它是否承认（）","opts":["A. 社会历史是变化发展的","B. 社会存在决定社会意识","C. 人们的思想对社会发展有重要作用","D. 社会历史是人们的自觉活动的结果"],"ans":1,"explain":"社会存在和社会意识的关系问题，是划分历史唯物主义和历史唯心主义的根本标准。"},{"id":"mk15044-pl-P1527560","type":"sc","tier":"基础","conf":"adapt","chap":"第2-3章","q":"社会物质生活条件的总和包括（ ）","opts":["A. 地理环境","B. 人口因素","C. 物质生活资料的生产方式","D. 地理环境、人口因素和物质生活资料的生产方式"],"ans":3,"explain":"社会存在是指社会物质生活条件的总和，包括地理环境、人口因素和物质生活资料的生产方式。"},{"id":"mk15044-pl-P1527564","type":"sc","tier":"基础","conf":"adapt","chap":"第2-3章","q":"下列各项中属于社会心理的是（ ）。","opts":["A. 政治与法律","B. 哲学与宗教","C. 科学与艺术","D. 风俗与习惯"],"ans":3,"explain":"社会心理是社会意识的低级层次，它是特定阶级、民族、社会集团或个人，在日常生活和交往中自发形成的、不定型、不系统的社会意识，表现在人们的情感、情绪、愿望、要求、风俗、习惯、传统、自发倾向和社会风气等之中。"},{"id":"mk15044-pl-P1527565","type":"sc","tier":"基础","conf":"adapt","chap":"第2-3章","q":"社会意识相对独立性最突出的表现是（）","opts":["A. 社会意识的发展具有历史继承性","B. 社会意识的发展与社会经济发展水平的不平衡性","C. 社会意识对社会存在的能动反作用","D. 社会意识诸形式之间的相互作用"],"ans":2,"explain":"社会意识对社会存在具有反作用或称能动性，这是社会意识相对独立性的重要表现。"},{"id":"mk15044-pl-P1527566","type":"sc","tier":"基础","conf":"adapt","chap":"第2-3章","q":"先进的社会意识一旦被群众掌握变成群众的自觉行动，就会成为改造世界，推动世界进步的巨大物质力量。这说明社会意识（）","opts":["A. 与社会存在的发展变化不具有同步性","B. 决定社会存在","C. 对社会存在具有反作用","D. 具有历史继承性"],"ans":2,"explain":"社会意识对社会存在具有反作用或称能动性，这是社会意识相对独立性的重要表现。"},{"id":"mk15044-pl-P1527567","type":"sc","tier":"基础","conf":"adapt","chap":"第2-3章","q":"社会意识的相对独立性最突出地表现为（ ）","opts":["A. 与社会存在发展变化的不完全同步性","B. 同经济发展的不平衡性","C. 具有历史的继承性","D. 对社会存在有能动的反作用"],"ans":3,"explain":"社会意识对社会存在具有反作用或称能动性，这是社会意识相对独立性的重要表现。"},{"id":"mk15044-pl-P1527568","type":"sc","tier":"基础","conf":"adapt","chap":"第2-3章","q":"社会意识具有复杂的结构，从其主体的角度看可分为（ ）。","opts":["A. 社会心理和思想体系","B. 意识形态和非意识形态","C. 个体意识和群体意识","D. 先进意识和落后意识"],"ans":2,"explain":"社会意识具有复杂的结构，从其主体的角度看可分为个体意识和群体意识。"},{"id":"mk15044-pl-P1527569","type":"sc","tier":"基础","conf":"adapt","chap":"第2-3章","q":"历史唯物主义认为，社会意识具有相对独立性这是指（）","opts":["A. 社会意识可以决定社会存在","B. 社会意识可以脱离社会存在而独立发展","C. 社会意识和社会存在的发展总是保持一致和平衡","D. 社会意识的发展与社会存在的发展并不总是保持一致和平衡"],"ans":3,"explain":"社会意识与社会经济发展水平具有不平衡性。社会经济发展水平较高的国家，某些社会意识形式的发展水平可能较低；社会经济发展水平较低的国家，某些社会意识形式的发展水平可能较高。"},{"id":"mk15044-pl-P1527570","type":"sc","tier":"基础","conf":"adapt","chap":"第2-3章","q":"生产方式包括（ ）。","opts":["A. 劳动者和劳动工具两个方面","B. 地理环境和人口因素两个方面","C. 生产力和生产关系两个方面","D. 经济基础和上层建筑两个方面"],"ans":2,"explain":"生产方式包括生产力和生产关系两个方面。"},{"id":"mk15044-pl-P1527571","type":"sc","tier":"基础","conf":"adapt","chap":"第2-3章","q":"在社会发展中起决定作用的因素是（）","opts":["A. 地理环境的优劣","B. 人口增长的快慢","C. 社会风气的好坏","D. 物质生活资料的生产方式"],"ans":3,"explain":"生产方式在社会发展中起决定作用"},{"id":"mk15044-pl-P1527572","type":"sc","tier":"基础","conf":"adapt","chap":"第2-3章","q":"下列选项中，属于非意识形态范围的思想体系的是（）","opts":["A. 政治思想语言学道德","B. 技术科学哲学艺术","C. 自然科学逻辑学语言学","D. 法律思想逻辑学宗教"],"ans":2,"explain":"属于非意识形态范围的思想体系，包括自然科学、语言学、逻辑学等，它们不是特定经济基础的反映，其自身没有阶级性，可以一视同仁地为各个阶级和各种经济基础服务。"},{"id":"mk15044-pl-P1527573","type":"sc","tier":"基础","conf":"adapt","chap":"第2-3章","q":"下列各组社会意识形式中，全部属于意识形态领域的是（）","opts":["A. 自然科学道德宗教","B. 法律思想逻辑学宗教","C. 政治思想语言学艺术","D. 法律思想哲学宗教"],"ans":3,"explain":"属于意识形态范围的思想体系，包括政治思想、法律思想、道德、宗教、艺术、哲学和绝大部分社会科学，它们是上层建筑的重要组成部分，反映特定的经济基础并为之服务，在阶级社会里具有一定的阶级性。"},{"id":"mk15044-pl-P1527574","type":"sc","tier":"基础","conf":"adapt","chap":"第2-3章","q":"唯物史观认为，地理环境是（ ）。","opts":["A. 社会物质生活的必要条件","B. 经济社会形态的划分依据","C. 社会形态更替的决定力量","D. 技术社会形态的划分依据"],"ans":0,"explain":"唯物史观认为，地理环境是社会物质生活的必要条件。"},{"id":"mk15044-pl-P1527575","type":"sc","tier":"基础","conf":"adapt","chap":"第2-3章","q":"决定人口生产的发展方向和基本趋势的是（ ）。","opts":["A. 地理环境","B. 物质生产","C. 风俗习惯","D. 人伦道德"],"ans":1,"explain":"物质生产对人口生产的发展方向和基本趋势起决定作用。"},{"id":"mk15044-pl-P1527576","type":"sc","tier":"基础","conf":"adapt","chap":"第2-3章","q":"下列各项属于意识形态的是（ ）。","opts":["A. 哲学","B. 物理学","C. 数学","D. 语言学"],"ans":0,"explain":"意识形态是具有阶级性的，自然科学并不具阶级性，而哲学具有阶级性。"},{"id":"mk15044-pl-P1527577","type":"sc","tier":"基础","conf":"adapt","chap":"第2-3章","q":"最有利于社会发展的人口状况是（）","opts":["A. 人口多，密度大","B. 人口少，质量高","C. 与地理环境相吻合","D. 与物质生产相适应"],"ans":3,"explain":"只有与物质生产相适应的人口状况，才最有利于促进社会的发展。"},{"id":"mk15044-pl-P1526514","type":"sa","tier":"创新","conf":"adapt","chap":"第2-3章","q":"简述认识客体的含义、构成和性质。","opts":[],"ans":null,"explain":"(1)认识客体的含义：认识客体是指人的实践活动和认识活动所指向的对象。<br/>(2)认识客体的构成：认识客体由自然客体、社会客体和精神客体构成。<br/>(3)认识客体的性质：<br/>①认识客体具有客观性。<br/>②认识客体具有对象性。"},{"id":"mk15044-pl-P1526515","type":"sa","tier":"创新","conf":"adapt","chap":"第2-3章","q":"简述可知论与不可知论的对立。","opts":[],"ans":null,"explain":"(1)可知论和不可知论是由对思维能不能认识存在、能不能正确认识现实世界这个问题的不同回答而划分出来的。<br/>(2)唯物主义哲学都是可知论，认为人的思维能认识和正确认识现实世界，即认为现实世界是可知的。有些唯心主义哲学家，如黑格尔，也是可知论者，他认为客观世界是绝对精神的产物，精神认识世界就是精神认识自己和自己的产物。<br/>(3)不可知论是指那些认为世界不可认识或不能彻底认识的认识论。<br/>(4)马克思主义把实践观引入认识论，认为人在实践中能够认识、并能够正确认识客观世界，实践的观点彻底驳倒了不可知论和哲学上的其他一切怪论。"},{"id":"mk15044-pl-P1526516","type":"sa","tier":"创新","conf":"adapt","chap":"第2-3章","q":"简述欧洲近代哲学中两位典型代表人物及其基本观点。","opts":[],"ans":null,"explain":"在欧洲近代哲学中有两位典型代表人物。一位是英国的休谟，他认为人能知道的只是自己的感觉经验，而这种感觉经验同外部世界的关系，即这种感觉经验是不是对外部世界的反映，人是无法知道的。这就是说，外部世界本身是否存在、是否可以认识，我们是无法知道的。另一位是德国哲学家康德。康德并不否认外部世界的存在，也不否认感觉是从外部世界得来的；但他认为人们所能认识的只是客观世界的外在现象，至于现象背后的本质人的认识是无法达到的。他把事物的本质叫做“自在之物”，“自在之物”的现象可以引起人的感觉，由于在现象与本质之间有一条不可逾越的“鸿沟”，所以，认识无法达到事物的本质，即无法达到“自在之物”。"},{"id":"mk15044-pl-P1526517","type":"sa","tier":"创新","conf":"adapt","chap":"第2-3章","q":"简要说明整个人类的认识是有限与无限的统一。","opts":[],"ans":null,"explain":"(1)认识的有限性是指每个时代的人每一次具体的认识是有限的，认识的无限性是指整个人类无止境的世代更替的认识是无限的。<br/>(2)认识的有限性和无限性是辩证统一的。整个人类认识的无限性，存在于每个时代的人的认识的有限性中，并通过无数有限性的认识而得以实现。<br/>(3)认识的有限性和无限性的矛盾，只有在无限的前进过程中，在至少对我们来说实际上是无止境的世代更迭中才能得到解决。"},{"id":"mk15044-pl-P1526518","type":"sa","tier":"创新","conf":"adapt","chap":"第2-3章","q":"简述生产关系包括的内容。","opts":[],"ans":null,"explain":"生产关系是指人们在物质生产过程中结成的经济关系。它包括三项内容：<br/>(1)生产资料的所有制形式。<br/>(2)人们在生产中的地位及其相互关系（包括交换）。<br/>(3)产品的分配方式。"},{"id":"mk15044-pl-P1526519","type":"sa","tier":"创新","conf":"adapt","chap":"第2-3章","q":"为什么说社会存在和社会意识的关系问题是历史观的基本问题？","opts":[],"ans":null,"explain":"(1)社会存在和社会意识这对范畴，是高度概括、高度抽象的范畴，是任何一种历史观都无法回避的首要问题。<br/>(2)社会存在和社会意识的关系问题，是划分历史唯物主义和历史唯心主义的根本标准。<br/>(3)社会存在和社会意识的关系问题，也是人们在实践中的重大问题。"},{"id":"mk15044-pl-P1526520","type":"sa","tier":"创新","conf":"adapt","chap":"第2-3章","q":"简述三种社会形态划分法与五种社会形态划分法的关系。","opts":[],"ans":null,"explain":"（1）三种社会形态划分法和五种社会形态划分法，都是马克思提出来的，它们各自从不同的角度和不同的侧面说明了人类历史发展的进程和社会发展阶段的划分，共同揭示了人类社会发展的一般规律。<br/>（2）二者在马克思主义体系中的作用是互补的，而不是互相排斥的，而且这两种划分法本质上是统一的。人的依赖性社会或自然经济社会包括原始社会、奴隶社会、封建社会三种社会形态；物的依赖性社会或商品经济社会在马克思、恩格斯那里指的就是资本主义社会，中国的社会主义初级阶段也属于商品经济社会；个人全面发展的社会或产品经济社会，则指的是未来的社会主义社会和共产主义社会。<br/>（3）我们既不能只讲五种社会形态划分法、不讲三种社会形态划分法，也不能用三种社会形态划分法否定或取代五种社会形态划分法。"},{"id":"mk15044-pl-P1526521","type":"sa","tier":"创新","conf":"adapt","chap":"第2-3章","q":"简述阶级斗争在社会发展中的作用。","opts":[],"ans":null,"explain":"阶级斗争在阶级社会的发展中起着重要作用，它是阶级社会发展的直接动力。这主要表现在两个方面：<br/>(1)阶级斗争推动社会发展的作用，最明显地表现在社会形态更替的过程中。在阶级社会里，当生产关系阻碍生产力发展、上层建筑阻碍经济基础变革时，必然引起革命阶级和反动统治阶级之间的矛盾尖锐化，直至爆发以推翻旧政权、建立新政权为目标的政治革命，而政治革命一旦成功，就实现了社会形态的更替，把人类社会从一个较低的社会形态推进到一个较高的社会形态。<br/>(2)阶级斗争推动社会发展的作用，还表现在同一个社会形态的量变过程中。在以生产资料私有制为基础的阶级社会里，剥削阶级出于它的本性，总是残酷地剥削和压迫劳动群众，无偿地占有他们的剩余劳动，有时甚至侵吞他们的必要劳动。在这种情况下，被剥削阶级只有起来进行反抗，才能迫使剥削阶级做些让步、减轻一点剥削程度，以保证社会再生产正常进行，从而推动社会在各种不同程度上向前发展。"},{"id":"mk15044-pl-P1527912","type":"sa","tier":"创新","conf":"adapt","chap":"第2-3章","q":"简述认识的本质和认识发展的总规律。","opts":[],"ans":null,"explain":"认识的本质是主体对客体的能动反映，这是马克思主义哲学对认识本质的科学揭示。认识是在实践中主体对客体的能动的反映。这个过程是一个辩证的发展过程。<br/>（1）在实践中，人们先是产生感性认识，在感性认识积累的基础上，产生了理性认识，然后在理性认识的指导下去进行新的实践；在新的实践中又产生新的认识。<br/>（2）人的认识就是从实践到认识、再从认识到实践这样一个不断反复、无限发展的过程。"},{"id":"mk15044-pl-P1527914","type":"sa","tier":"创新","conf":"adapt","chap":"第2-3章","q":"试述感性认识和理性认识辩证关系的原理，并说明这一原理的理论和实践意义。","opts":[],"ans":null,"explain":"感性认识和理性认识是认识的两个阶段，它们既相互区别、又相互联系，它们之间存在着对立统一的关系。<br/>（1）感性认识与理性认识的区别。感性认识是对事物表面的、直接的、具体的、个别特性的反映，因而是不深刻、片面的认识；理性认识是对事物本质的、全面的、间接的、概括的反映，因而是深刻的、全面的、相对稳定的认识。<br/>（2）感性认识与理性认识的联系。理性认识依赖于感性认识。感性认识有待于发展到理性认识。<br/>（3）感性认识和理性认识相互渗透。由此可见，在认识过程中，感性认识和理性认识是不可分割的，如果将二者割裂开，就会犯经验论或唯理论的错误。由于实践的继续，感性认识积累的多了，就会由量变发生质变，出现认识的飞跃，由感性认识上升到理性认识，认识的这次飞跃非常重要，它是认识任务的真正完成。从实践中，认识由感性上升到理性的辩证运动，也就是人们的认识从现象到本质，从不深刻的本质到更深刻的本质的过程。"},{"id":"mk15044-pl-P1527915","type":"sa","tier":"创新","conf":"adapt","chap":"第2-3章","q":"简要说明逻辑证明与实践检验的关系。","opts":[],"ans":null,"explain":"（1）坚持实践是检验真理的唯一标准，并不否认逻辑证明在认识和探索真理中的作用，逻辑证明是指用已有的真理认识，通过合乎逻辑规则的推理，去证实或证伪另一种认识。一种认识、一种科学假说，一个重大的理论不能贸然直接付诸实践。在付诸实践之前，先要经过逻辑证明对之进行筛选，对被证伪的认识、假设、理论就不必付诸实践，这样可以减少损失。<br/>（2）承认逻辑证明的作用，并不是说逻辑证是检验真理的标准，不能用逻辑证明代替实践标准，这是因为逻辑证明不具有最终性。首先，逻辑证明所依赖的前提是否正常，它自身不能保证，需要经过实践的检验。其次，被逻辑证明证实或证伪了的东西，最终还要靠实践检验，实践才具有最后的权威。"},{"id":"mk15044-pl-P1527916","type":"sa","tier":"创新","conf":"adapt","chap":"第2-3章","q":"简述真理与价值对立统一关系。","opts":[],"ans":null,"explain":"（1）真理与价值相互对立、相互别区别：真理体现的是认识与对象的相符合；价值体现的是外物对人需要的满足，表示某物具有对人有用或者使人愉快的属性。<br/>（2）真理与价值又是不可分的，又有统一的一面，表现在：第一真理能够指导社会实践，成功改造世界，以实践的成果满足人们的需要，这就是真理所表现出来的价值属性。第二真理与正确的价值观相一致，正确的价值是在真理指导下形成的。"},{"id":"mk15044-pl-P1527917","type":"sa","tier":"创新","conf":"adapt","chap":"第2-3章","q":"试析认识主客体的含义、特点及关系。","opts":[],"ans":null,"explain":"认识主体的含义：认识主体是指认识和实践活动的承担者，是处于一定社会关系中从事实践活动和认识活动的现实的、具体的人。唯心主义哲学把这个承担者说成是“精神”“灵魂”“自我意识”等，马克思主义哲学继承以前唯物主义的优秀传统，提出认识的主体是现实的人。认识主体只能是人，不能是人以外的其他事物。一切认识现象都是属于人的，离开了人和人的实践根本就谈不上认识。<br/>（2）认识主体的性质和特点：①认识主体具有自然的物质基础；②认识主体具有社会性；③认识主体具有历史性；④认识主体具有能动性。<br/>（三）认识主体和认识客体的关系：（1）认识的主体和客体的实践关系<br/>；（2）认识的主体和客体的认识关系；（3）认识的主体和客体的相互作用"},{"id":"mk15044-pl-P1527918","type":"sa","tier":"创新","conf":"adapt","chap":"第2-3章","q":"简述认识主体与认识客体的含义及二者间的关系。","opts":[],"ans":null,"explain":"认识主体是指认识和实践活动的承担者，是处于一定社会关系中从事实践活动和认识活动的现实的、具体的人。认识客体是指人的实践活动和认识活动所指向的对象。认识的主体和客体是一对矛盾的两个方面它们之间存在着既对立又统一的辩证关系。<br/>具体说来，它们的关系表现如下：<br/>主体和客体的实践关系；<br/>主体和客体的认识关系；<br/>主体和客体的相互作用。"},{"id":"mk15044-pl-P1527919","type":"sa","tier":"创新","conf":"adapt","chap":"第2-3章","q":"简述实践是认识的基础。","opts":[],"ans":null,"explain":"（1）实践的观点是辩证唯物主义的首要观点。实践是认识的基础，对认识具有决定作用。<br/>（2）实践对认识的决定作用表现在：实践是认识的来源；实践是认识发展的动力；实践是检验认识真理性的唯一标准；实践是认识的目的。"},{"id":"mk15044-pl-P1527920","type":"sa","tier":"创新","conf":"adapt","chap":"第2-3章","q":"简述实践是认识发展的动力。","opts":[],"ans":null,"explain":"实践是认识发展的动力表现在：<br/>（1）实践不断提出新的认识课题，推动认识发展；<br/>（2）实践不断为认识提供经验材料和认识工具，使认识不断发展；<br/>（3）实践锻炼和提高人的认识能力。"},{"id":"mk15044-pl-P1527936","type":"sa","tier":"创新","conf":"adapt","chap":"第2-3章","q":"简述社会革命和社会改革的区别。","opts":[],"ans":null,"explain":"（1）社会革命是人类社会的根本质变，是新的社会制度代替旧的社会制度；社会改革则是同一社会制度总的量变过程中的部分质变，不改变社会制度的根本性质。<br/>（2）社会革命是由被统治阶级发动的，目的是推翻反动统治阶级的国家政权，建立新的革命阶级的国家政权；社会改革则是由统治阶级发动的，目的是维护和巩固自己的统治地位。<br/>（3）社会革命往往采取暴力革命的形式；社会改革一般不发生激烈的外部冲突。"},{"id":"mk15044-pl-P1527937","type":"sa","tier":"创新","conf":"adapt","chap":"第2-3章","q":"简述改革、发展、稳定的关系。","opts":[],"ans":null,"explain":"改革、发展和稳定三者之间相互依存，互为条件。<br/>第一，发展是目的。是硬道理.中国解决所有问题的关键要靠自己的发展.<br/>第二，改革是动力。改革是经济和社会发展的强大动力，是社会主义制度的自我完善和发展，它的决定性作用不仅在于解决当前经济和社会发展中的一些重大问题，推进社会生产力的解放和发展，还要为我国经济的持续发展和国家的长治久安打下坚实的基础。<br/>第三，稳定是前提。无论改革还是发展都需要有一个稳定的社会环境作保证。稳定是发展和改革和发展的前提，发展和改革和发展必须要有稳定的政治和社会环境.没有稳定的政治和社会环境，一切无从谈起。<br/>实践表明，改革、发展、稳定三者关系处理得当，就能总揽全局，保证经济社会的顺利发展；处理不当，就会吃苦头，付出代价。"},{"id":"mk15044-pl-P1527938","type":"sa","tier":"创新","conf":"adapt","chap":"第2-3章","q":"简述社会基本矛盾的内容以及它们之间的关系。","opts":[],"ans":null,"explain":"社会基本矛盾指生产力和生产关系之间的矛盾、经济基础和上层建筑之间的矛盾。生产力和生产关系之间的矛盾、经济基础和上层建筑之间的矛盾这两对矛盾，不是互相孤立、互相平行的，而是相互制约、有主次之分的。<br/>（1）由于生产力决定生产关系、生产关系作为社会的经济基础又决定社会的上层建筑，所以生产力与生产关系之间的矛盾对于经济基础与上层建筑之间的矛盾起着主导作用。<br/>（2）由于生产关系对生产力有反作用，上层建筑对经济基础有反作用，经济基础是联系上层建筑和生产力的中间环节，所以生产力和生产关系之间的矛盾的解决，又有赖于经济基础和上层建筑之间的矛盾的解决。"},{"id":"mk15044-pl-P1527940","type":"sa","tier":"创新","conf":"adapt","chap":"第2-3章","q":"根据人民群众是历史创造者的原理，谈谈坚持党的群众路线的现实意义。","opts":[],"ans":null,"explain":"（1）历史唯物主义认为人民是历史的创造者，是社会物资生产资料的创造主体，是社会得以存在与发展的决定性力量，党必须联系群众，依靠群众，推进中国社会主义现代化建设事业。<br/>（2）人民是社会精神财富的创造者，是推进社会发展和进步的根本性力量。党必须联系群众，依靠群众，推进社会主义精神文明的发展。（3）人民是推进社会变革的主力党必须走群众路线依靠群众。<br/>（4）从群众中来到群众中去，不断推进中国现代化的改革事业的发展，中国共产党的一切工作的根本路线，一方面要求在一切工作或斗争中，必须相信群众用自己的力量去解决自己的问题，另一方面要求领导贯彻从群众中来到群众中去的原则，即在集中群众意见的基础上制定方针。政策交给群众讨论执行过程中，不断根据群众意见进行修改，使之逐渐完善。"},{"id":"mk15044-pl-P1527941","type":"sa","tier":"创新","conf":"adapt","chap":"第2-3章","q":"试述如何正确分析和评价杰出人物在历史中的作用？","opts":[],"ans":null,"explain":"（1）杰出人物是一定历史条件下的产物，要正确认识杰出人物的历史作用，需要坚持历史主义原则，任何一个杰出人物的出现，都是时代的需要。<br/>（2）在阶级社会里，杰出人物多是一定阶级的代表，要正确认识杰出人物的历史作用，必须对他们作阶级分析。<br/>（3）杰出人物的出现及其历史作用都是必然性与偶然性的辩证统一，必须用辩证统一的观点来分析杰出人物的历史作用。<br/>（4）任何杰出人物都有巨大的历史功绩，也必然会有缺点或错误，因此对他们的历史作用要做全面的分析，不能肯定一切，也不能否定一切。"},{"id":"mk15044-pl-P1527942","type":"sa","tier":"创新","conf":"adapt","chap":"第2-3章","q":"简述上层建筑必须适合经济基础发展要求规律的内容。","opts":[],"ans":null,"explain":"经济基础决定上层建筑，上层建筑反作用于经济基础，经济基础和上层建筑之间的矛盾运动，这三项内容构成上层建筑必须适合经济基础发展要求的规律。具体表现在：<br/>（1）经济基础决定上层建筑。经济基础决定上层建筑的产生和性质，经济基础的变化决定上层建筑的改变；<br/>（2）上层建筑反作用于经济基础。这种反作用集中表现在它是为经济基础服务的；<br/>（3）经济基础和上层建筑之间的矛盾运动，使上层建筑和经济基础的发展要求之间呈现出由基本适合到基本不适合，再到新的基础上的基本适合这样一个发展过程。"},{"id":"mk15044-pl-P1527945","type":"sa","tier":"创新","conf":"adapt","chap":"第2-3章","q":"什么是生产方式？为什么说生产方式在社会发展中起决定作用。","opts":[],"ans":null,"explain":"生产方式：生产方式是人类借以向自然界谋取必要的生活资料的方式，包括了生产力和生产关系两个方面，是特定的生产力和生产关系的统一。<br/>生产方式在社会发展中起决定作用，主要表现：<br/>（1）生产方式或生产活动是人类从动物界分离出来的根本动力和人类区别动物的根本标志（如制造和使用工具）。<br/>（2）生产方式或生产活动是人类和人类社会得以生存和发展的基础。<br/>（3）生产活动是形成人类一切社会关系的基础。<br/>（4）生产方式决定社会制度的性质和社会制度的更替。"},{"id":"mk15044-pl-P1527946","type":"sa","tier":"创新","conf":"adapt","chap":"第2-3章","q":"用社会存在和社会意识辩证关系的原理，说明大力发展社会主义先进文化的意义。","opts":[],"ans":null,"explain":"（1）社会存在和社会意识的辩证关系：社会存在决定社会意识，社会意识反作用于社会存在。先进的社会意识对社会存在的发展起积极推动作用，落后的社会意识对社会存在的发展起消极作用。<br/>（2）观念形态的文化包括一切社会意识形式。在当代中国，发展现今文化，就是发展面向现代化、面向世界、面向未来的，民族的科学的大众的社会主义文化。<br/>（3）社会主义先进文化能够培育民族精神，加强思想道德建设、推动教育和科学的发展、大力发展社会主义先进文化，对全面建设小康社会，实现中华民族伟大复兴具有十分重要的作用。"},{"id":"mk15044-pl-P1526488","type":"sa","tier":"创新","conf":"adapt","chap":"第2-3章","q":"试述真理的价值的具体表现。","opts":[],"ans":null,"explain":"(1)真理具有指导实践的功能。真理的价值突出地表现为它具有指导实践的功能。这个功能表现在两个方面：一方面，由于真理是一种正确的认识，在实践之前人们可以根据真理制定出正确的计划、方案，甚至制成实践模型，成为人们行动的依据，以保证实践活动取得成功。另一方面，真理渗透于实践活动的全过程，能随时校正实践活动中出现的偏差。真理指导实践的功能是真理最突出的价值，因为真理指导下的实践是最能获得成功的，这种成功能使人的需要得到满足。<br/>(2)真理具有再认识的功能。虽然认识的源泉和动力在于实践，但每一个真理性的认识都为以后的认识提供了思想资料和理论指导，为认识的发展和达到新的真理开辟道路。所以，追求和把握真理是推动认识发展不可缺少的条件。<br/>(3)真理具有教育和激励的功能。由于真理是对客观事物及其规律的正确反映，因而具有客观性。在真理面前人人平等，任何人都必须服从真理；真理对人们具有巨大的说服力，真理的力量是不可抗拒的。人们常说：“真理在手，所向披靡”。正是这个原因，使得真理对人们具有无可比拟的教育作用。掌握真理就是离开了谬误，科学是真理的系统，通过学习和掌握科学，使人们通晓自然规律和社会规律，减少盲目性，增加自觉性，从而获得更大的自由。真理具有强大的激励功能。满足人们追求真理的需要，能提高人的精神境界，给人以善和美的享受，给人以力量和鼓舞，这是真理自身价值的重要体现。人类总是把追求真理看作是崇高而伟大的事业。所以，从古到今，世界各国都有无数为真理而献身的人，而这些人在任何时候都会受到人们的尊敬。"},{"id":"mk15044-pl-P1526489","type":"sa","tier":"创新","conf":"adapt","chap":"第2-3章","q":"试述主观和客观、认识和实践的统一。","opts":[],"ans":null,"explain":"(1)主观和客观、认识和实践的统一是具体的。这是指特定的主体在具体的实践中的主观认识与特定的客观实际的相一致、相符合。实践是人的具体的物质活动，认识是产生于实践，因此，有什么样的实践就会产生什么样的认识。在革命和战争年代，产生了许多革命的理论和战争的学说，这些理论和学说就是对革命斗争实践和战争实践的认识。今天，我们关于改革开放和建立社会主义市场经济体制的理论，就是对我国现在进行的改革开放和社会主义建设的实践的认识。<br/>(2)主观和客观、认识和实践的统一是历史的。这是指认识与实践的统一是变动的，随着实践的发展，认识也应跟着实践的发展而发展。客观世界和人们改造客观世界的实践都是不断发展的，旧的过程结束了，新的过程又开始，从而决定了认识与实践、主观与客观的矛盾是一个不断产生——不断解决——又不断产生的过程。我们要坚持与时俱进，在新的历史条件下达到新的认识与实践的统一。<br/>总之，实践——认识——实践的循环往复体现了认识和实践的统一是具体的、历史的。经验主义和教条主义这两种错误倾向，虽然表现形式不同，但在认识论上都是以主观和客观相分裂、认识和实践相分离为特征的，违背了认识和实践具体的、历史的统一的原理。教条主义者和经验主义者或者超越客观过程的一定发展阶段搞冒险主义，犯“左”的错误；或者思想僵化、停滞不前搞保守主义，犯右的错误。认识和实践的具体的历史的统一，要求我们在实际工作中必须坚持一切从实际出发，实事求是，开拓创新，把马克思主义普遍原理同我国的具体实际情况相结合，坚持真理，修正错误，走中国特色社会主义道路。"},{"id":"mk15044-pl-P1526490","type":"sa","tier":"创新","conf":"adapt","chap":"第2-3章","q":"试述马克思主义认识与党的群众路线的一致性以及坚持群众路线的重要意义。","opts":[],"ans":null,"explain":"(1)马克思主义认为，人的认识是从实践到认识，再从认识到实践的不断反复、无限发展的过程。<br/>(2)党的群众路线的内容是：一切为了群众，一切依靠群众，从群众中来，到群众中去。从群众中来，到群众中去，是无产阶级政党的领导方法，也是群众路线的基本工作方法。<br/>(3)从群众中来，在认识论上就是从实践到认识；到群众中去，就是从认识到实践。从群众中来、到群众中去的循环往复，就是从实践到认识、从认识到实践的循环往复。<br/>(4)坚持党的群众路线，对于党在新形势下保持同人民群众的血肉联系，巩固执政地位，坚持为人民服务的根本宗旨具有重大意义。"},{"id":"mk15044-pl-P1526491","type":"sa","tier":"创新","conf":"adapt","chap":"第2-3章","q":"试述经济基础和上层建筑的矛盾运动的规律及其对我国经济体制改革和政治体制改革的指导意义。","opts":[],"ans":null,"explain":"(1)经济基础决定上层建筑，上层建筑反作用于经济基础，经济基础和上层建筑之间的矛盾运动，这三项内容构成上层建筑必须适合经济基础发展要求的规律。<br/>(2)上层建筑必须适合经济基础发展要求的规律，是无产阶级政党制定正确的路线、方针、政策的理论依据。正确理解和运用这个规律，对于我国正在进行的经济体制改革和政治体制改革以及其他方面的改革，具有重大的指导意义。"},{"id":"mk15044-pl-P1526492","type":"sa","tier":"创新","conf":"adapt","chap":"第2-3章","q":"试述生产力和生产关系之间的辩证关系原理及其现实意义。","opts":[],"ans":null,"explain":"(1)生产力与生产关系之间的辩证关系原理为：<br/>①生产力决定生产关系。<br/>其一，生产力的性质决定生产关系的性质。<br/>其二，生产力的发展决定生产关系的改变。<br/>②生产关系反作用于生产力。<br/>其一，适合生产力性质和发展要求的先进的生产关系，促进生产力的发展.<br/>其二，不适合生产力性质和发展要求的落后的生产关系，阻碍生产力的发展。<br/>③生产力和生产关系之间存在矛盾运动。生产关系和生产力性质与发展要求之间这种由基本适合到基本不适合，再到新的基础上的基本适合，是一个川流不息、万古常新的循环过程，每一次这样的循环，都把人类社会提高到一个新的阶段。<br/>(2)生产关系必须适合生产力性质的规律，是无产阶级政党制定正确的路线、方针、政策的理论依据。正确理解和运用这个规律，对于我国正在进行的改革开放和社会主义现代化建设，具有重大的指导意义。我国社会主义初级阶段实行以公有制为主体、多种所有制经济共同发展的基本经济制度，就是以这一规律为理论依据的。"},{"id":"mk15044-pl-P1526493","type":"sa","tier":"创新","conf":"adapt","chap":"第2-3章","q":"为什么说社会革命是社会基本矛盾的必然产物？","opts":[],"ans":null,"explain":"（1）马克思指出：“社会的物质生产力发展到一定阶段，便同它们一直在其中运动的生产关系……发生矛盾。于是这些关系便由生产力的发展形式变成生产力的桎梏。那时社会革命的时代就到来了。随着经济基础的变更，全部庞大的上层建筑也或慢或快地发生变革。”这就是说，社会革命的最深刻的根源，就在于生产力和生产关系之间的矛盾以及经济基础和上层建筑之间的矛盾。<br/>（2）当生产关系成为生产力发展的桎梏时，生产力的发展就要求革命的进步的阶级消灭过时的旧生产关系，建立适合生产力发展的新生产关系，以解放被束缚的生产力。但旧的上层建筑，特别是国家政权，总是要维护旧的生产关系。要解决生产力和生产关系之间的矛盾，就必须首先解决经济基础和上层建筑之间的矛盾，即改变旧的上层建筑，最主要的是消灭旧的国家政权，建立新的国家政权。"},{"id":"mk15044-pl-P1526383","type":"sc","tier":"基础","conf":"adapt","chap":"第4-5章","q":"商品经济的主要内容是（）。","opts":["A. 商品流通","B. 商品存储","C. 商品生产和商品交换","D. 商品消费"],"ans":2,"explain":"商品经济是以商品生产和商品交换为内容，直接以交换为目的而进行生产的经济形式。所以商品经济是商品生产和商品交换的总称。"},{"id":"mk15044-pl-P1526385","type":"sc","tier":"基础","conf":"adapt","chap":"第4-5章","q":"价值是商品的（）。","opts":["A. 自然属性","B. 社会属性","C. 自然属性和社会属性的统一体","D. 存在形式"],"ans":1,"explain":"价值反映的是商品生产者之间的关系，它是商品的社会属性。"},{"id":"mk15044-pl-P1526386","type":"sc","tier":"基础","conf":"adapt","chap":"第4-5章","q":"马克思的科学劳动价值论的核心在于揭示了（）。","opts":["A. 价值是商品的社会属性","B. 价值的唯一源泉是剩余劳动","C. 价值是商品的本质属性","D. 价值的唯一源泉是活的抽象劳动"],"ans":3,"explain":"马克思的科学劳动价值论的核心就在于揭示了在商品生产过程中价值的创造是由活劳动实现的，价值的唯一源泉是活劳动，即活的抽象劳动。"},{"id":"mk15044-pl-P1526387","type":"sc","tier":"基础","conf":"adapt","chap":"第4-5章","q":"商品生产者要获得更多收益必须使生产商品的（）。","opts":["A. 个别劳动时间等于社会必要劳动时间","B. 个别劳动时间低于社会必要劳动时间","C. 个别劳动时间高于社会必要劳动时间","D. 个别劳动时间大大高于社会必要劳动时间"],"ans":1,"explain":"商品生产者生产单位商品的个别劳动时间少于社会必要劳动时间，也即商品的个别价值小于社会价值，但仍能按其社会价值进行交换，该商品生产者也就可以获得较多盈利，并在市场竞争中处于有利地位。"},{"id":"mk15044-pl-P1526388","type":"sc","tier":"基础","conf":"adapt","chap":"第4-5章","q":"单位商品价值量与劳动生产率的关系是（）。","opts":["A. 二者成正比","B. 二者成反比","C. 二者总按相同比例变化","D. 二者总按不同比例变化"],"ans":1,"explain":"单位商品的价值量，与包含在商品中的社会必要劳动量成正比，而与生产该商品的劳动生产率成反比。这是商品价值量同劳动生产率之间的基本关系。"},{"id":"mk15044-pl-P1526389","type":"sc","tier":"基础","conf":"adapt","chap":"第4-5章","q":"使资本主义制度取得完全胜利和最终确立的是（）。","opts":["A. 阶级斗争","B. 原始积累","C. 产业革命","D. 民主法治"],"ans":2,"explain":"产业革命使资本主义制度取得完全胜利和最终确立。"},{"id":"mk15044-pl-P1526391","type":"sc","tier":"基础","conf":"adapt","chap":"第4-5章","q":"资本主义生产过程是（）。","opts":["A. 劳动过程和价值形成过程的统一","B. 劳动过程和价值增殖过程的统一","C. 劳动过程和劳动力价值创造过程的统一","D. 劳动过程和旧价值转移过程的统一"],"ans":1,"explain":"在资本主义生产方式下，资本家在购买了劳动力之后，就离开流通领域，进入生产过程。资本主义生产过程是劳动过程和价值增殖过程的统一。"},{"id":"mk15044-pl-P1526392","type":"sc","tier":"基础","conf":"adapt","chap":"第4-5章","q":"准确地表明资本主义剥削程度的指标是（）。","opts":["A. 利润率","B. 利息率","C. 剩余价值率","D. 平均利润率"],"ans":2,"explain":"剩余价值是可变资本产生的，为准确地表明资本家对工人的剥削程度，应该用剩余价值同可变资本相比，即剩余价值率。"},{"id":"mk15044-pl-P1526393","type":"sc","tier":"基础","conf":"adapt","chap":"第4-5章","q":"资本主义的基本经济规律是（）。","opts":["A. 价值规律","B. 剩余价值规律","C. 资本积累规律","D. 平均利润规律"],"ans":1,"explain":"资本主义的基本经济规律是剩余价值规律。剩余价值规律的內容，就是资本通过组织雇佣劳动进行生产，占有工人的剩余劳动，不断提高对雇佣劳动力的剥削程度来达到获取剩余价值的目的。"},{"id":"mk15044-pl-P1526394","type":"sc","tier":"基础","conf":"adapt","chap":"第4-5章","q":"资本积累的实质是（）。","opts":["A. 资本家用榨取的剩余价值来榨取更多的剩余价值","B. 增加社会财富总量","C. 扩大生产规模，增强竞争能力","D. 推动社会进步"],"ans":0,"explain":"资本家用无偿占有工人所创造的剩余价值，进行资本积累来增大资本的规模，以便继续占有更多的剩余价值，从而占有不断增大的资本来扩大对工人的剥削和统治。这就是资本积累的实质。"},{"id":"mk15044-pl-P1526395","type":"sc","tier":"基础","conf":"adapt","chap":"第4-5章","q":"产业资本循环中为生产剩余价值准备条件的阶段是（）。","opts":["A. 生产阶段","B. 流通阶段","C. 购买阶段","D. 销售阶段"],"ans":2,"explain":"在产业资本循环的购买阶段，产业资本家为了从事生产经营活动，首先须到市场上用货币购买劳动力和生产资料，为剩余价值的生产准备条件。"},{"id":"mk15044-pl-P1526396","type":"sc","tier":"基础","conf":"adapt","chap":"第4-5章","q":"产业资本的职能形式不包括（）。","opts":["A. 货币资本","B. 生产资本","C. 商品资本","D. 商业资本"],"ans":3,"explain":"与单个产业资本依次经历的三个阶段相适应，产业资本依次采取货币资本、生产资本、商品资本三种职能形式。"},{"id":"mk15044-pl-P1526397","type":"sc","tier":"基础","conf":"adapt","chap":"第4-5章","q":"资本主义经济危机的实质是（）。","opts":["A. 生产相对过剩","B. 生产绝对过剩","C. 生产相对短缺","D. 生产绝对短缺"],"ans":0,"explain":"资本主义经济危机是在资本主义经济发展过程中，周期性爆发的生产过剩危机。经济危机期间最根本的现象和典型特征是商品生产过剩。"},{"id":"mk15044-pl-P1526398","type":"sc","tier":"基础","conf":"adapt","chap":"第4-5章","q":"资本主义的利润率是（）。","opts":["A. 剩余价值与预付总资本的比率","B. 剩余价值与所费总资本的比率","C. 剩余价值与可变总资本的比率","D. 剩余价值与不变总资本的比率"],"ans":0,"explain":"利润是剩余价值的转化形式，它表现为全部预付资本的产物，因此，剩余价值与预付总资本的比率就是利润率。"},{"id":"mk15044-pl-P1526399","type":"sc","tier":"基础","conf":"adapt","chap":"第4-5章","q":"商业利润的真正来源是（）。","opts":["A. 商品流通领域中商品的加价","B. 商业店员所创造的剩余价值","C. 商业资本家在商品买卖中贱买贵卖","D. 产业工人创造的剩余价值的一部分"],"ans":3,"explain":"商业利润是产业资本家让渡给商业资本家的一部分剩余价值，其来源是产业部门的工人创造的剩余价值。"},{"id":"mk15044-pl-P1526400","type":"sc","tier":"基础","conf":"adapt","chap":"第4-5章","q":"借贷资本家贷出货币时（）。","opts":["A. 既让渡其使用权又放弃所有权","B. 只让渡其使用权没有放弃所有权","C. 只放弃所有权没有让渡使用权","D. 既不让渡使用权又不放弃所有权"],"ans":1,"explain":"借贷资本的产生，意味着资本的所有权和使用权发生分离。借贷资本家拥有自己的货币资本的所有权，他将其货币资本贷给职能资本家使用时，职能资本家就获得这部分货币资本的使用权。因此，借贷资本家贷出货币时只让渡其使用权没有放弃所有权。"},{"id":"mk15044-pl-P1526401","type":"sc","tier":"基础","conf":"adapt","chap":"第4-5章","q":"资本主义国家的国体是（）。","opts":["A. 资产阶级专政","B. 无产阶级专政","C. 农民阶级专政","D. 资产阶级和无产阶级联合专政"],"ans":0,"explain":"资本主义国家的国体是实行资产阶级专政；资本主义国家的政体是指资本主义国家的政权机构的构成形式。"},{"id":"mk15044-pl-P1526402","type":"sc","tier":"基础","conf":"adapt","chap":"第4-5章","q":"议会在国家政权结构中处于主导地位，它既是立法机构，也是国家最高权力机构，这样的资本主义制度是（）。","opts":["A. 民主共和制","B. 议会君主制","C. 二元君主制","D. 总统共和制"],"ans":1,"explain":"议会在国家政权结构中处于主导地位，它既是立法机构，又是国家最高权力机构。此种制度即为议会君主制。"},{"id":"mk15044-pl-P1526403","type":"sc","tier":"基础","conf":"adapt","chap":"第4-5章","q":"议会共和制国家的总统是（）。","opts":["A. 虚位元首","B. 实位元首","C. 政府首脑","D. 最高领袖"],"ans":0,"explain":"议会共和制又称内阁共和制，它是以议会为国家最高权力机构，政府由议会所产生。在议会共和制国家中，虽有由选举所产生的国家元首(总统)，但国家元首一般只具有虚位而无实权，属于“虚位元首”。"},{"id":"mk15044-pl-P1526404","type":"sc","tier":"基础","conf":"adapt","chap":"第4-5章","q":"瑞士等少数国家实行（）。","opts":["A. 半总统共和制","B. 专制独裁制","C. 总统共和制","D. 委员会制"],"ans":3,"explain":"委员会制也即合议制，它由议会所产生的委员会集体行使最高行政权力。委员会对议会负责，实际上是议会的执行机构。目前只有瑞士等少数国家实行此种制度。"},{"id":"mk15044-pl-P1526405","type":"sc","tier":"基础","conf":"adapt","chap":"第4-5章","q":"资本主义国家的立法机构是（）。","opts":["A. 法院","B. 检察机构","C. 议会或国会","D. 政府"],"ans":2,"explain":"资本主义国家的议会又称为国会或议院，它一般是资本主义国家的最高立法机关，通常由定期选举产生的议员所组成，由议长担任领导。"},{"id":"mk15044-pl-P1526406","type":"sc","tier":"基础","conf":"adapt","chap":"第4-5章","q":"资本主义议会的首要职权是（）。","opts":["A. 财政权","B. 倒阁权","C. 监督权","D. 立法权"],"ans":3,"explain":"资本主义国家议会的主要职权包括立法权、财政权和监督权。其中，立法权主要是指制定、修改、通过和废止法律的权力，它是议会的首要职权。"},{"id":"mk15044-pl-P1526407","type":"sc","tier":"基础","conf":"adapt","chap":"第4-5章","q":"资产阶级民主制的核心和主要标志是（）。","opts":["A. 议会制","B. 三权分立制","C. 民主共和制","D. 普选制"],"ans":0,"explain":"资产阶级民主制以议会制为核心和主要标志，以三权分立制、普选制、两党制（或多党制），以及公民享有各种权利为主要内容"},{"id":"mk15044-pl-P1526408","type":"sc","tier":"基础","conf":"adapt","chap":"第4-5章","q":"迄今为止资本主义社会的发展，大体可分为（）。","opts":["A. 自由竞争资本主义和垄断资本主义两个阶段","B. 垄断资本主义和非垄断资本主义两个阶段","C. 商品经济和市场经济两个阶段","D. 国内垄断和国际垄断两个阶段"],"ans":0,"explain":"迄今为止资本主义社会的发展，大体可分为自由竞争资本主义和垄断资本主义两个阶段。"},{"id":"mk15044-pl-P1526409","type":"sc","tier":"基础","conf":"adapt","chap":"第4-5章","q":"把在法律和生产上独立的企业在流通环节统一起来，进行垄断经营的企业组织形式是（）。","opts":["A. 卡特尔","B. 辛迪加","C. 托拉斯","D. 康采恩"],"ans":1,"explain":"20世纪上半期，较为重要的垄断组织形式有：卡特尔、辛迪加、托拉斯和康采恩。其中，辛迪加是指把一些在法律上和生产上还是独立的大垄断企业在流通环节上统一起来，进行垄断经营的组织形式。"},{"id":"mk15044-pl-P1526410","type":"sc","tier":"基础","conf":"adapt","chap":"第4-5章","q":"垄断了某种商品生产和经营全过程的独立的大型垄断企业是（）。","opts":["A. 辛迪加","B. 托拉斯","C. 卡特尔","D. 康采恩"],"ans":1,"explain":"20世纪上半期，较为重要的垄断组织形式有：卡特尔、辛迪加、托拉斯和康采恩。托拉斯，即垄断了某种商品生产和经营全过程的独立的大型垄断企业。"},{"id":"mk15044-pl-P1526411","type":"sc","tier":"基础","conf":"adapt","chap":"第4-5章","q":"在垄断资本主义阶段，占统治地位的资本是（）。","opts":["A. 工业资本","B. 银行资本","C. 商业资本","D. 金融资本"],"ans":3,"explain":"垄断资本主义国家内出现了一种新的资本形式一一金融资本，它是由垄断的工业资本和银行资本，通过金融联系、资本参与和人事参与，融合或混合生长构成的一种新的资本形式，是垄断资本主义国家中社会经济生活各个方面实际上的统治者。"},{"id":"mk15044-pl-P1526412","type":"sc","tier":"基础","conf":"adapt","chap":"第4-5章","q":"国家垄断资本主义的出现，其特定的历史条件和根源是（）。","opts":["A. 生产力的发展和生产社会化程度的提高","B. 资本主义国家从不发达走向发达","C. 资本主义国家对广大殖民地国家的掠夺","D. 生产关系在资本主义国家内部的自发调整"],"ans":0,"explain":"国家垄断资本主义出现的特定历史条件和根源，归根到底是生产力的发展，特别是生产社会化程度的提高，要求资本主义国家介入到社会经济生活中，起到私人资本不能起的一些作用，以维持资本主义社会的存在和发展，维护垄断资本的利益和统治。"},{"id":"mk15044-pl-P1526413","type":"sc","tier":"基础","conf":"adapt","chap":"第4-5章","q":"资本主义国家资本与私人资本在企业内部的结合方式不包括（）。","opts":["A. 国家购买一部分私人企业的股票","B. 原国有企业出卖一部分股票给私人","C. 原国有企业全部私有化","D. 国家和私人共同投资兴建新的企业"],"ans":2,"explain":"国家和私人资本在企业内部的结合，既可以是国家和私人资本共同投资于一个新的企业，也可以是国家通过出售一部分国有企业的股份，从而形成国家和私人资本共有的企业，还可以通过国家收购一部分原私有企业的股份而形成国家与私人资本相结合的企业。"},{"id":"mk15044-pl-P1526415","type":"sc","tier":"基础","conf":"adapt","chap":"第4-5章","q":"资本输出的两种基本形式是（）。","opts":["A. 借贷资本和生产资本输出","B. 借贷资本和商品资本输出","C. 生产资本和商品资本输出","D. 货币资本和生产资本输出"],"ans":0,"explain":"从资本形态上来看，资本输出大体有两种基本形式，即借贷资本输出和生产资本输出。借贷资本输出，即输出国的政府或私人银行和企业，把货币资本贷给输入国的政府、银行或企业，这是一种间接投资；生产资本输出，即输出国的政府或私人银行和企业，在国外直接投资办企业，这是一种直接投资。"},{"id":"mk15044-pl-P1526416","type":"sc","tier":"基础","conf":"adapt","chap":"第4-5章","q":"从性质上看，发达资本主义国家对发展中国家的“经济援助”是（）。","opts":["A. 帮助发展中国家克服经济困难的一种方式","B. 新殖民主义的一种方式","C. 扼杀发展中国家经济发展的手段","D. 促进发展中国家经济独立的工具"],"ans":1,"explain":"当代垄断资本主义国家多是采取比较缓和隐蔽的新殖民主义手法，打着所谓“援助”的旗号实现其对发展中国家的剥削和控制。"},{"id":"mk15044-pl-P1526417","type":"sc","tier":"基础","conf":"adapt","chap":"第4-5章","q":"经济全球化本质上是（）。","opts":["A. 产业资本的国际化","B. 资源配置的国际化","C. 商业资本的国际化","D. 借贷资本的国际化"],"ans":1,"explain":"经济全球化本质上是资源配置的国际化，其内容大体可从生产全球化、贸易全球化和资本全球化三方面来考察。"},{"id":"mk15044-pl-P1526418","type":"sc","tier":"基础","conf":"adapt","chap":"第4-5章","q":"垄断产生的物质条件和基础是（）。","opts":["A. 社会分工的发展","B. 自然分工的发展","C. 社会化生产力的发展","D. 商品经济的发展"],"ans":2,"explain":"社会化生产力的发展不仅是生产力发展的内在要求，也是垄断产生的物质条件和基础。"},{"id":"mk15044-pl-P1526419","type":"sc","tier":"基础","conf":"adapt","chap":"第4-5章","q":"垄断资本主义产生并占统治地位是（）。","opts":["A. 资本原始积累的结果","B. 争夺短缺资源的产物","C. 生产和资本集中发展到一定程度的必然结果","D. 资本主义国际竞争的结果"],"ans":2,"explain":"当生产和资本集中发展到一定程度时，就会自然而然地走向垄断。也就是说，垄断资本主义产生并占统治地位是生产和资本集中发展到一定程度的必然结果。"},{"id":"mk15044-pl-P1526420","type":"sc","tier":"基础","conf":"adapt","chap":"第4-5章","q":"国家垄断资本主义阶段大体形成于（）。","opts":["A. 资产阶级革命以后","B. 工业革命以后","C. 两次世界大战之间","D. 第二次世界大战以后"],"ans":3,"explain":"二战后出现了国家垄断资本主义，国家或者说政权的力量日益深入地介入到社会经济生活的各个领域，国家垄断取代私人垄断成为主要资本主义国家当代资本主义发展的新形式、新特征。"},{"id":"mk15044-pl-P1526421","type":"sc","tier":"基础","conf":"adapt","chap":"第4-5章","q":"战后各主要资本主义国家的垄断财团得到更大增强，其主要表现不包括（）。","opts":["A. 垄断财团经营日益国际化","B. 垄断财团实力的迅速增长","C. 垄断财团的经营向多样化方向发展","D. 大财团股权日益集中"],"ans":3,"explain":"战后各主要资本主义国家的垄断财团随着金融资本的发展也得到更大增强，主要表现在：(1)垄断财团实力的迅速增长。(2)垄断财团的经营向多样化方向发展。(3)垄断财团经营日益国际化。(4)大财团的资本结构日益社会化。"},{"id":"mk15044-pl-P1526422","type":"sc","tier":"基础","conf":"adapt","chap":"第4-5章","q":"政治经济学中的金融资本指的是（）。","opts":["A. 超大型、垄断性的银行资本","B. 在银行保险证券投资等金融领域活动的资本","C. 垄断的工业资本与垄断的银行资本融合形成的资本","D. 资本主义国家中央银行和商业银行资本的总和"],"ans":2,"explain":"金融资本是由垄断的工业资本和银行资本，通过金融联系、资本参与和人事参与，融合或混合生长构成的一种新的资本形式，是垄断资本主义国家中社会经济生活各个方面实际上的统治者。"},{"id":"mk15044-pl-P1526423","type":"sc","tier":"基础","conf":"adapt","chap":"第4-5章","q":"银行的作用在垄断资本主义阶段发生了根本变化，即银行（）。","opts":["A. 直接控制了工业生产","B. 由普通中介人变成了万能的垄断者","C. 不仅是信用中介，而且是支付和结算","D. 直接从事生产经营活动"],"ans":1,"explain":"在垄断资本主义阶段，垄断的银行资本由普通的借贷关系中介人变为社会经济生活中万能的垄断者。"},{"id":"mk15044-pl-P1526424","type":"sc","tier":"基础","conf":"adapt","chap":"第4-5章","q":"自由竞争与生产集中的关系是（）。","opts":["A. 自由竞争引起生产集中","B. 自由竞争阻碍生产集中","C. 生产集中引起自由竞争","D. 生产集中取代自由竞争"],"ans":0,"explain":"本题考查的知识点是自由竞争和生产集中的关系。资本主义企业在自由竞争中，会不断通过资本积聚和集中来扩大规模，从而引起生产和资本的不断集中。也就是说，自由竞争必然会引起生产和资本的集中。"},{"id":"mk15044-pl-P1526425","type":"sc","tier":"基础","conf":"adapt","chap":"第4-5章","q":"垄断阶段较之自由竞争阶段竞争范围的扩大主要体现在出现了（）。","opts":["A. 部门内部的竞争","B. 部门之间的竞争","C. 国内竞争","D. 国际竞争"],"ans":3,"explain":"本题考查的知识点是垄断阶段与自由竞争阶段竞争的不同。其主要表现在竞争的目的、手段、范围、激烈程度和后果等方面。就竞争范围而言，垄断阶段的竞争不仅存在于国内，而且扩展到了国外；除了经济领域的竞争外，还在政治、军事、文化等领域展开激烈的竞争。"},{"id":"mk15044-pl-P1526426","type":"sc","tier":"基础","conf":"adapt","chap":"第4-5章","q":"国家垄断资本主义的产生和发展是（）。","opts":["A. 资产阶级自觉适应生产力发展的产物","B. 资本主义国家力量逐渐增强的表现","C. 对资本主义生产无政府状态的反映","D. 社会生产力发展的要求和结果"],"ans":3,"explain":"国家垄断资本主义的产生，归根到底是社会生产力发展的要求和结果。"},{"id":"mk15044-pl-P1526427","type":"sc","tier":"基础","conf":"adapt","chap":"第4-5章","q":"第二次世界大战后，主要资本主义国家的经济发展进入到（）。","opts":["A. 自由竞争资本主义阶段","B. 垄断竞争资本主义阶段","C. 私人垄断资本主义阶段","D. 国家垄断资本主义阶段"],"ans":3,"explain":"第二次世界大战后，国家垄断资本主义在主要发达资本主义国家有很大发展，成为社会经济生活中一个非常重要的现象。"},{"id":"mk15044-pl-P1526428","type":"sc","tier":"基础","conf":"adapt","chap":"第4-5章","q":"资本主义国家向私人企业注入一定资本后该企业属于（）。","opts":["A. 资本主义的国有资本","B. 国家和私人资本在企业内部的结合","C. 私人资本主义企业","D. 国家和私人资本在企业外部的结合"],"ans":1,"explain":"国家和私人资本在企业内部的结合，也即资本主义国家中的国有资本与私人资本结合在一个企业中的经济形式。"},{"id":"mk15044-pl-P1526429","type":"sc","tier":"基础","conf":"adapt","chap":"第4-5章","q":"资本主义经济的发展是为更高级的生产方式创造物质条件，这主要表现为（）。","opts":["A. 创造高科技成果","B. 无产阶级队伍的成长和壮大","C. 发展社会劳动生产力","D. 资本主义市场经济制度的建立和发展"],"ans":2,"explain":"马克思指出：“发展社会劳动生产力，是资本主义的历史任务和存在理由。资本正是以此不自觉地为一个更高级的生产形式创造物质条件。”这是对资本主义历史过渡性最精辟而辩证的论述。"},{"id":"mk15044-pl-P1526430","type":"sc","tier":"基础","conf":"adapt","chap":"第4-5章","q":"资本主义造就的埋葬自身的社会力量是（）。","opts":["A. 无产阶级","B. 科学技术","C. 巨大的社会财富","D. 社会化的生产力"],"ans":0,"explain":"资本主义造就了置自身于死地的社会力量，即无产阶级。无产阶级代表了先进的生产力和社会发展的方向，其阶级利益与全社会的利益和发展方向相一致。"},{"id":"mk15044-pl-P1526431","type":"sc","tier":"基础","conf":"adapt","chap":"第4-5章","q":"当代资本主义国家在经济关系方面的一系列新变化表明（）","opts":["A. 其社会性质已经根本改变","B. 其基本矛盾已经彻底解决","C. 其阶级对立已经消失","D. 其社会性质发生了部分质变"],"ans":3,"explain":"目前西方发达资本主义国家的新变化，说明它在总的量变过程中，已经发生了某些阶段性的部分质变。资本主义的国有经济、计划调节、福利主义、工人参与管理等都是这种非爆发式质变的开端，也都是阶段性部分质变的表现。"},{"id":"mk15044-pl-P1526432","type":"sc","tier":"基础","conf":"adapt","chap":"第4-5章","q":"战后生产和资本进一步国际化的突出特点是 （）。","opts":["A. 商业资本国际化","B. 产业资本国际化","C. 借贷资本国际化","D. 货币资本国际化"],"ans":1,"explain":"战后以来，随着科技的进步和国家垄断资本主义的发展，资本国际化中产业资本国际化的进程大大加快了，这是战后生产和资本进一步国际化的突出特点。"},{"id":"mk15044-pl-P1527578","type":"sc","tier":"基础","conf":"adapt","chap":"第4-5章","q":"超额利润是商品的（）","opts":["A. 个别价值低于社会价值的差额","B. 生产价格低于价值的差额","C. 生产成本低于价值的差额","D. 个别生产价格低于社会生产价格的差额"],"ans":3,"explain":"从单个企业来看，由于其劳动生产率高，其产品的个别价格低于社会的生产价格，低于社会生产价格的这部分就是超额利润。"},{"id":"mk15044-pl-P1527579","type":"sc","tier":"基础","conf":"adapt","chap":"第4-5章","q":"相对剩余价值的获得是（ ）。","opts":["A. 延长工作日、增加剩余劳动时间的结果","B. 工作日不变、增加必要劳动时间的结果","C. 个别企业提高劳动生产率的结果","D. 全社会劳动生产率普遍提高的结果"],"ans":3,"explain":"相对剩余价值的获得是全社会劳动生产率普遍提高的结果。"},{"id":"mk15044-pl-P1527580","type":"sc","tier":"基础","conf":"adapt","chap":"第4-5章","q":"相对剩余价值生产的条件是（ ）","opts":["A. 个别企业劳动生产率的提高","B. 本部门劳动生产率的提高","C. 社会劳动生产率的提高","D. 个别企业劳动生产率的提高快于社会劳动生产率的提高"],"ans":2,"explain":"相对剩余价值生产是以社会劳动生产率提高为条件的。"},{"id":"mk15044-pl-P1527581","type":"sc","tier":"基础","conf":"adapt","chap":"第4-5章","q":"剩余价值产生于雇佣工人的（）","opts":["A. 必要劳动时间","B. 剩余劳动时间","C. 全部劳动时间","D. 具体劳动时间"],"ans":1,"explain":"在工作日长度不变的条件下，由于缩短必要劳动时间、相应延长剩余劳动时间而生产的剩余价值，叫作相对剩余价值。"},{"id":"mk15044-pl-P1527582","type":"sc","tier":"基础","conf":"adapt","chap":"第4-5章","q":"绝对剩余价值生产是（）","opts":["A. 个别资本家改进技术的结果","B. 全社会劳动生产率提高的结果","C. 在必要劳动时间不变的条件下延长工作日的结果","D. 在工作日长度不变的条件下缩短必要劳动时间的结果"],"ans":2,"explain":"在雇佣工人的必要劳动时间不变的条件下，由于工作日的绝对延长而生产的剩余价值，叫作绝对剩余价值。"},{"id":"mk15044-pl-P1527583","type":"sc","tier":"基础","conf":"adapt","chap":"第4-5章","q":"在必要劳动时间不变的情况下，将工作日延长所生产出的剩余价值是（ ）","opts":["A. 绝对剩余价值","B. 相对剩余价值","C. 超额剩余价值","D. 平均剩余价值"],"ans":0,"explain":"在雇佣工人的必要劳动时间不变的条件下，由于工作日的绝对延长而生产的剩余价值，叫作绝对剩余价值。"},{"id":"mk15044-pl-P1527584","type":"sc","tier":"基础","conf":"adapt","chap":"第4-5章","q":"对于提高劳动强度而生产的剩余价值属于（ ）。","opts":["A. 绝对剩余价值","B. 超额剩余价值","C. 相对剩余价值","D. 超额利润"],"ans":0,"explain":"在雇佣工人的必要劳动时间不变的条件下，由于工作日的绝对延长而生产的剩余价值，叫做绝对剩余价值。资本家除了用延长工作日的方法以外，还用提高劳动强度的方法加强对工人的剥削。个别企业工人由于提高劳动强度而生产的剩余价值，也属于绝对剩余价值。"},{"id":"mk15044-pl-P1527585","type":"sc","tier":"基础","conf":"adapt","chap":"第4-5章","q":"资本家提高劳动生产率的直接目的是（ ）","opts":["A. 生产绝对剩余价值","B. 获取超额剩余价值","C. 生产相对剩余价值","D. 降低劳动力价值"],"ans":1,"explain":"资本家提高劳动生产率的直接目的是获取超额剩余价值"},{"id":"mk15044-pl-P1527586","type":"sc","tier":"基础","conf":"adapt","chap":"第4-5章","q":"不变资本和可变资本数量构成上的比例是资本的（ ）","opts":["A. 有机构成","B. 价值构成","C. 技术构成","D. 数量构成"],"ans":1,"explain":"从价值形态看，资本是由一定数量的不变资本和可变资本构成的，它们之间的比例叫作资本价值构成。"},{"id":"mk15044-pl-P1527587","type":"sc","tier":"基础","conf":"adapt","chap":"第4-5章","q":"生产资料和劳动力实物构成上的比例是（ ）","opts":["A. 资本的有机构成","B. 资本的价值构成","C. 资本的技术构成","D. 资本的数量构成"],"ans":2,"explain":"生产资料和劳动力实物构成上的比例是资本的技术构成"},{"id":"mk15044-pl-P1527588","type":"sc","tier":"基础","conf":"adapt","chap":"第4-5章","q":"生产资料和劳动力实物构成上的比例是资本的（ ）。","opts":["A. 有机构成","B. 价值构成","C. 技术构成","D. 数量构成"],"ans":2,"explain":"生产资料和劳动力实物构成上的比例是资本的技术构成。"},{"id":"mk15044-pl-P1527589","type":"sc","tier":"基础","conf":"adapt","chap":"第4-5章","q":"剩余价值的资本化被称为（）","opts":["A. 资本积聚","B. 资本集中","C. 资本积累","D. 资本扩张"],"ans":2,"explain":"剩余价值的资本化，就叫作资本积累。"},{"id":"mk15044-pl-P1527590","type":"sc","tier":"基础","conf":"adapt","chap":"第4-5章","q":"由技术构成决定并反映其变化的资本价值构成是（）","opts":["A. 资本技术构成","B. 资本有机构成","C. 资本价值构成","D. 资本实物构成"],"ans":1,"explain":"由资本技术构成所决定，并且反映资本技术构成变化的资本价值构成，叫作资本有机构成。"},{"id":"mk15044-pl-P1527591","type":"sc","tier":"基础","conf":"adapt","chap":"第4-5章","q":"资本有机构成的提高是指C：V中（）","opts":["A. C的比重不断增大","B. V的比重不断增大","C. C与V按比例同时增加","D. C与V按比例同时减少"],"ans":0,"explain":"在资本积累过程中，由于追求更多剩余价值的内在动力和迫于竞争的外在压力，资本家必然会不断改进企业的生产技术装备，提高劳动生产率，企业中生产资料的增长要比使用这些生产资料的劳动力相对增长得快，结果在全部资本中，不变资本所占比重增大，可变资本所占比重缩小，从而导致资本有机构成的提高。"},{"id":"mk15044-pl-P1527592","type":"sc","tier":"基础","conf":"adapt","chap":"第4-5章","q":"资本积累的源泉是（ ）。","opts":["A. 使用价值","B. 剩余价值","C. 价值","D. 交换价值"],"ans":1,"explain":"资本积累的源泉是剩余价值。"},{"id":"mk15044-pl-P1527593","type":"sc","tier":"基础","conf":"adapt","chap":"第4-5章","q":"资本主义扩大再生产的重要源泉是（）","opts":["A. 剩余价值","B. 自由竞争","C. 资本积累","D. 资本集中"],"ans":2,"explain":"资本积累是资本主义扩大再生产的重要源泉。"},{"id":"mk15044-pl-P1527594","type":"sc","tier":"基础","conf":"adapt","chap":"第4-5章","q":"区分不变资本和可变资本的根据是资本的不同部分（）","opts":["A. 价值转移的方式不同","B. 在剩余价值中所起作用不同","C. 价值周转方式不同","D. 在价值形成中的作用不同"],"ans":1,"explain":"根据这两部分资本在剩余价值生产中所起的作用不同，资本区分为不变资本和可变资本。"},{"id":"mk15044-pl-P1527595","type":"sc","tier":"基础","conf":"adapt","chap":"第4-5章","q":"剩余价值的唯一源泉是工人的（ ）","opts":["A. 具体劳动","B. 必要劳动","C. 个别劳动","D. 剩余劳动"],"ans":3,"explain":"工人的剩余劳动是剩余价值的唯一源泉。"},{"id":"mk15044-pl-P1527596","type":"sc","tier":"基础","conf":"adapt","chap":"第4-5章","q":"货币转化为资本的关键是（ ）","opts":["A. 劳动力成为商品","B. 生产资料可以买卖","C. 货币是一般等价物","D. 货币是社会财富的一般代表"],"ans":0,"explain":"货币转化为资本的关键是劳动力成为商品"},{"id":"mk15044-pl-P1527597","type":"sc","tier":"基础","conf":"adapt","chap":"第4-5章","q":"货币转化为资本的决定性条件是在流通中购买到（ ）","opts":["A. 生产资料","B. 劳动力","C. 劳动资料","D. 劳动对象"],"ans":1,"explain":"货币转化为资本的决定性条件是在流通中购买到劳动力"},{"id":"mk15044-pl-P1527598","type":"sc","tier":"基础","conf":"adapt","chap":"第4-5章","q":"劳动力成为商品是（）","opts":["A. 自然经济解体的产物","B. 货币转化为资本的前提","C. 实行市场经济的前提","D. 资本原始积累的基础"],"ans":1,"explain":"劳动力成为商品是货币转化为资本的前提。"},{"id":"mk15044-pl-P1527599","type":"sc","tier":"基础","conf":"adapt","chap":"第4-5章","q":"劳动力价值决定的一个重要特点是（ ）","opts":["A. 它由剩余价值决定","B. 它由市场供求关系决定","C. 它由自身的使用价值决定","D. 它包括历史和道德因素"],"ans":3,"explain":"劳动力的价值决定还有一个重要的特点，就是它包括历史和道德的因素。"},{"id":"mk15044-pl-P1527600","type":"sc","tier":"基础","conf":"adapt","chap":"第4-5章","q":"劳动力的价值决定有一个重要特点，即（ ）。","opts":["A. 它由其生产的剩余价值决定","B. 它由其使用价值决定","C. 它包含历史和道德因素","D. 它包含习惯和法律因素"],"ans":2,"explain":"劳动力的价值决定有一个重要特点，即它包含历史和道德因素。"},{"id":"mk15044-pl-P1527601","type":"sc","tier":"基础","conf":"adapt","chap":"第4-5章","q":"劳动力商品的使用价值的特殊性在于，它在使用过程中（）","opts":["A. 创造商品的使用价值","B. 把自身价值转移到新产品中去","C. 转移和保持自身的价值","D. 创造比自身劳动力价值更大的价值"],"ans":3,"explain":"劳动力商品的使用价值的特殊性在于它不仅能创造出价值，而且能够创造出比劳动力自身的价值更大的价值，从而能为劳动力的购买者带来剩余价值，这对于剩余价值的生产具有决定性的意义。"},{"id":"mk15044-pl-P1527602","type":"sc","tier":"基础","conf":"adapt","chap":"第4-5章","q":"劳动力商品使用价值的特殊性是（ ）。","opts":["A. 能生产出具有使用价值的物品","B. 能生产出具有价值的物品","C. 仅能生产出自身价值","D. 能生产出大于自身价值的价值"],"ans":3,"explain":"劳动力商品使用价值的特殊性是能生产出大于自身价值的价值。"},{"id":"mk15044-pl-P1527603","type":"sc","tier":"基础","conf":"adapt","chap":"第4-5章","q":"下列选项中，准确表明资本家对工人剥削程度的是（）","opts":["A. 剩余价值率","B. 利润率","C. 平均利润率","D. 年剩余价值率"],"ans":0,"explain":"剩余价值是可变资本产生的，为准确地表明资本家对工人的剥削程度，应该用剩余价值同可变资本相比。"},{"id":"mk15044-pl-P1527604","type":"sc","tier":"基础","conf":"adapt","chap":"第4-5章","q":"以劳动力形式存在的那部分资本是（ ）。","opts":["A. 不变资本","B. 可变资本","C. 固定资本","D. 流通资本"],"ans":1,"explain":"以劳动力形式存在的那部分资本是可变资本。"},{"id":"mk15044-pl-P1527605","type":"sc","tier":"基础","conf":"adapt","chap":"第4-5章","q":"以生产资料形式存在的资本是（ ）","opts":["A. 不变资本","B. 可变资本","C. 流动资本","D. 流通资本"],"ans":0,"explain":"以生产资料形式存在的这部分资本，其物质形态在生产过程中被消耗，生产出新产品。其价值则转移到新产品中去，不会发生量的变化。由于以生产资料形式存在的资本，在生产过程中不发生价值量的变化，所以叫作不变资本（c）。"},{"id":"mk15044-pl-P1527606","type":"sc","tier":"基础","conf":"adapt","chap":"第4-5章","q":"以生产资料形式存在的资本属于（ ）。","opts":["A. 不变资本","B. 流通资本","C. 可变资本","D. 流动资本"],"ans":0,"explain":"以生产资料形式存在的资本属于不变资本。"},{"id":"mk15044-pl-P1527607","type":"sc","tier":"基础","conf":"adapt","chap":"第4-5章","q":"考察社会资本再生产，核心问题是分析（）","opts":["A. 社会总产品的各个构成部分是如何实现的","B. 剩余价值是如何转化为平均利润的","C. 剩余价值是怎样生产的","D. 资本循环是怎样运行的"],"ans":0,"explain":"考察社会总资本的运动即考察社会资本再生产，核心问题是要分析在社会资本再生产过程中，社会总产品的各个构成部分是如何实现的"},{"id":"mk15044-pl-P1527608","type":"sc","tier":"基础","conf":"adapt","chap":"第4-5章","q":"社会总产品是社会各个物质生产部门在一定时期（通常是一年）内生产的（）","opts":["A. 全部剩余价值的总和","B. 全部生产资料的总和","C. 全部物质资料的总和","D. 全部消费资料的总和"],"ans":2,"explain":"社会总产品就是社会各个物质生产部门在一定时期（一般以年为单位）内所生产的全部物质资料的总和。"},{"id":"mk15044-pl-P1527610","type":"sc","tier":"基础","conf":"adapt","chap":"第4-5章","q":"下列资本形式中不属于职能资本的是（）","opts":["A. 产业资本","B. 商业资本","C. 借贷资本","D. 农业资本"],"ans":2,"explain":"借贷资本是从职能资本（产业资本和商业资本）的运动中分离出来的特殊资本形式。"},{"id":"mk15044-pl-P1527611","type":"sc","tier":"基础","conf":"adapt","chap":"第4-5章","q":"剩余价值与利润从数量上看（）","opts":["A. 前者总是大于后者","B. 前者总是小于后者","C. 两者总是相等","D. 两者的大小无法判断"],"ans":2,"explain":"利润率是剩余价值率的转化形式，两者总是相等。"},{"id":"mk15044-pl-P1527612","type":"sc","tier":"基础","conf":"adapt","chap":"第4-5章","q":"资本主义商业利润的本质与真正来源是（）","opts":["A. 商品在流通过程中的加价","B. 商业店员创造的剩余价值","C. 产业工人创造的一部分剩余价值","D. 商业店员实现的剩余价值"],"ans":2,"explain":"商业利润是产业资本家让渡给商业资本家的一部分剩余价值，它的来源是产业部门的工人创造的剩余价值。"},{"id":"mk15044-pl-P1527613","type":"sc","tier":"基础","conf":"adapt","chap":"第4-5章","q":"资本主义经济中，农业资本家获得的剩余价值是（）","opts":["A. 级差地租","B. 绝对地租","C. 平均利润","D. 利息"],"ans":2,"explain":"资本主义经济中，农业资本家获得的剩余价值是平均利润"},{"id":"mk15044-pl-P1527614","type":"sc","tier":"基础","conf":"adapt","chap":"第4-5章","q":"产生资本主义经济危机的根源是（）","opts":["A. 生产相对过剩","B. 需求绝对减少","C. 资本主义基本矛盾","D. 生产和消费的矛盾"],"ans":2,"explain":"经济危机产生的根源在于资本主义生产方式的基本矛盾，即生产的社会化与生产资料私人资本主义占有形式之间的矛盾。当这个矛盾达到十分尖锐的程度，就会引起经济危机的爆发。资本主义基本矛盾是经济危机爆发的根源。"},{"id":"mk15044-pl-P1527615","type":"sc","tier":"基础","conf":"adapt","chap":"第4-5章","q":"资本主义经济危机从实质上说就是（ ）。","opts":["A. 生产不足的危机","B. 买卖脱节的危机","C. 生产绝对过剩的危机","D. 生产相对过剩的危机"],"ans":3,"explain":"资本主义经济危机从实质上说就是生产相对过剩的危机。"},{"id":"mk15044-pl-P1527616","type":"sc","tier":"基础","conf":"adapt","chap":"第4-5章","q":"资本主义经济危机从实质上就是说（）","opts":["A. 生产不足的危机","B. 买卖脱节的危机","C. 生产绝对过剩的危机","D. 生产相对过剩的危机"],"ans":3,"explain":"资本主义经济危机实质上是生产相对过剩的危机。"},{"id":"mk15044-pl-P1527617","type":"sc","tier":"基础","conf":"adapt","chap":"第4-5章","q":"资本主义经济危机中最典型的现象是（ ）。","opts":["A. 生产过剩","B. 商品短缺","C. 长期萧条","D. 持续高涨"],"ans":0,"explain":"资本主义经济危机中最典型的现象是生产过剩（产能相对过剩）。"},{"id":"mk15044-pl-P1527618","type":"sc","tier":"基础","conf":"adapt","chap":"第4-5章","q":"产业资本的循环包括（）","opts":["A. 生产、流通和销售阶段","B. 生产、储存和销售阶段","C. 购买、生产和销售阶段","D. 购买、生产和储存阶段"],"ans":2,"explain":"产业资本的全部循环运动依次经过购买、生产、销售三个阶段"},{"id":"mk15044-pl-P1527619","type":"sc","tier":"基础","conf":"adapt","chap":"第4-5章","q":"产业资本的循环运动（ ）。","opts":["A. 只包括流通阶段而不包括生产阶段","B. 只包括生产阶段而不包括流通阶段","C. 是购买生产销售三个阶段的统一","D. 是购买商品和销售商品两个阶段的统一"],"ans":2,"explain":"产业资本的循环运动是购买生产销售三个阶段的统一。"},{"id":"mk15044-pl-P1527620","type":"sc","tier":"基础","conf":"adapt","chap":"第4-5章","q":"产业资本循环采取的职能形式是（ ）。","opts":["A. 生产资本、流通资本和银行资本","B. 生产资本、商业资本和银行资本","C. 货币资本、生产资本和商品资本","D. 货币资本、生产资本和商业资本"],"ans":2,"explain":"产业资本循环采取的职能形式是货币资本、生产资本和商品资本。"},{"id":"mk15044-pl-P1527621","type":"sc","tier":"基础","conf":"adapt","chap":"第4-5章","q":"在产业资本循环过程中，资本顺次采取的三种职能形式是（）","opts":["A. 货币资本、生产资本、商品资本","B. 生产资本、货币资本、商品资本","C. 商品资本、生产资本、货币资本","D. 货币资本、商品资本、生产资本"],"ans":0,"explain":"产业资本依次采取货币资本、生产资本、商品资本三种职能形式。"},{"id":"mk15044-pl-P1527622","type":"sc","tier":"基础","conf":"adapt","chap":"第4-5章","q":"在产业资本循环的第一阶段，产业资本采取的职能形式是（）","opts":["A. 货币资本","B. 生产资本","C. 商品资本","D. 商业资本"],"ans":0,"explain":"单个产业资本在其现实循环运动过程中，依次经过三个阶段，即购买阶段、生产阶段、销售阶段；与这三个阶段相适应，产业资本依次采取货币资本、生产资本、商品资本三种职能形式。"},{"id":"mk15044-pl-P1527623","type":"sc","tier":"基础","conf":"adapt","chap":"第4-5章","q":"根据价值周转方式的不同，资本家的生产资本可以划分为（ ）。","opts":["A. 不变资本和可变资本","B. 固定资本和流动资本","C. 商品资本和流通资本","D. 个别资本和社会资本"],"ans":1,"explain":"根据价值周转方式的不同，资本家的生产资本可以划分为固定资本和流动资本。"},{"id":"mk15044-pl-P1527624","type":"sc","tier":"基础","conf":"adapt","chap":"第4-5章","q":"价值增殖产生于资本循环的（ ）。","opts":["A. 购买阶段","B. 生产阶段","C. 销售阶段","D. 运输阶段"],"ans":1,"explain":"价值增殖产生于资本循环的生产阶段。"},{"id":"mk15044-pl-P1527625","type":"sc","tier":"基础","conf":"adapt","chap":"第4-5章","q":"流通时间包括（）","opts":["A. 生产时间和购买时间","B. 购买时间和销售时间","C. 生产时间和劳动时间","D. 销售时间和非劳动时间"],"ans":1,"explain":"流通时间包括购买时间和销售时间。"},{"id":"mk15044-pl-P1527626","type":"sc","tier":"基础","conf":"adapt","chap":"第4-5章","q":"年剩余价值率是（）","opts":["A. 剩余价值与可变资本之比","B. 剩余价值与不变资本之比","C. 一年内剩余价值总量与一年预付可变资本之比","D. 一年内剩余价值总量与一年预付总资本之比"],"ans":2,"explain":"年剩余价值率为一年内生产的剩余价值总量与一年内预付的可变资本总量的比率。"},{"id":"mk15044-pl-P1527627","type":"sc","tier":"基础","conf":"adapt","chap":"第4-5章","q":"产业资本循环中生产剩余价值的阶段是（）","opts":["A. 购买阶段","B. 生产阶段","C. 销售阶段","D. 流通阶段"],"ans":1,"explain":"生产阶段是生产剩余价值的阶段，它在资本循环中是决定性的阶段。"},{"id":"mk15044-pl-P1527628","type":"sc","tier":"基础","conf":"adapt","chap":"第4-5章","q":"资本周转的时间是（）","opts":["A. 生产时间和购买时间的总和","B. 劳动时间和流通时间的总和","C. 生产时间和流通时间的总和","D. 劳动时间和购买时间的总和"],"ans":2,"explain":"生产时间和流通时间越长，资本周转速度就越慢。"},{"id":"mk15044-pl-P1527629","type":"sc","tier":"基础","conf":"adapt","chap":"第4-5章","q":"资本各形态能划分为固定资本和流动资本的是（）","opts":["A. 货币资本","B. 生产资本","C. 商品资本","D. 借贷资本"],"ans":1,"explain":"生产资本的构成，即生产资本中固定资本和流动资本的比例，以及固定资本和流动资本自身的周转速度。"},{"id":"mk15044-pl-P1527631","type":"sc","tier":"基础","conf":"adapt","chap":"第4-5章","q":"资本家加速资本周转的目的是（）","opts":["A. 提高平均利润率","B. 提高剩余价值率","C. 提高资本积累率","D. 提高年剩余价值率"],"ans":3,"explain":"由于加速资本周转可以增加年剩余价值量和提高年剩余价值率"},{"id":"mk15044-pl-P1527632","type":"sc","tier":"基础","conf":"adapt","chap":"第4-5章","q":"剩余价值的实现是在产业资本循环的（）","opts":["A. 购买阶段","B. 生产阶段","C. 销售阶段","D. 流通阶段"],"ans":2,"explain":"在这个阶段上，把生产出的新商品销售出去，换回一定数量的货币。但是换回的货币数量大于最初购买生产资口劳动力所垫支的货币数量，其中包含着剩余价值，因而它是已经发生价值增值的货币资本。销售阶段就是由商品资本转化为增值了的货币资本的阶段。"},{"id":"mk15044-pl-P1527633","type":"sc","tier":"基础","conf":"adapt","chap":"第4-5章","q":"资本主义的意识形态（ ）。","opts":["A. 只具有历史进步性","B. 只具有阶级局限性","C. 既无历史进步性也无阶级局限性","D. 既有历史进步性又有阶级局限性"],"ans":3,"explain":"资本主义的意识形态既有历史进步性又有阶级局限性。"},{"id":"mk15044-pl-P1527634","type":"sc","tier":"基础","conf":"adapt","chap":"第4-5章","q":"马克思主义认为，资本主义意识形态（）","opts":["A. 只具有历史进步性","B. 既有历史进步性又有阶级局限性","C. 只具有阶级局限性","D. 既无历史进步性又无阶级局限性"],"ans":1,"explain":"资本主义意识形态的历史进步性和阶级局限性"},{"id":"mk15044-pl-P1527635","type":"sc","tier":"基础","conf":"adapt","chap":"第4-5章","q":"资本主义意识形态的核心是（ ）。","opts":["A. 实用主义","B. 享乐主义","C. 功利主义","D. 利己主义"],"ans":3,"explain":"资本主义意识形态是以利己主义为核心的。"},{"id":"mk15044-pl-P1527636","type":"sc","tier":"基础","conf":"adapt","chap":"第4-5章","q":"资本主义国家的政体主要有（）","opts":["A. 两党制和多党制两种","B. 君主立宪制和民主共和制两种","C. 一党制、两党制和多党制三种","D. 君主立宪制、民主共和制和专制独裁制三种"],"ans":1,"explain":"资本主义国家的政体有君主立宪制、民主共和制和专制独裁制三种，但以君主立宪制和民主共和制这两种为主。"},{"id":"mk15044-pl-P1527637","type":"sc","tier":"基础","conf":"adapt","chap":"第4-5章","q":"资本主义民主制的核心和主要标志是（ ）。","opts":["A. 普选制","B. 三权分立制","C. 议会制","D. 民主共和制"],"ans":2,"explain":"资本主义民主制的核心和主要标志是议会制。"},{"id":"mk15044-pl-P1527638","type":"sc","tier":"基础","conf":"adapt","chap":"第4-5章","q":"资本主义政治制度的核心是（ ）。","opts":["A. 政党制度","B. 国家制度","C. 选举制度","D. 文官制度"],"ans":1,"explain":"资本主义政治制度的核心是国家制度。"},{"id":"mk15044-pl-P1527639","type":"sc","tier":"基础","conf":"adapt","chap":"第4-5章","q":"简单商品经济的基本矛盾是（ ）。","opts":["A. 使用价值和价值的矛盾","B. 价值和交换价值的矛盾","C. 具体劳动和抽象劳动的价值","D. 私人劳动和社会劳动的矛盾"],"ans":3,"explain":"简单商品经济的基本矛盾是私人劳动和社会劳动的矛盾。"},{"id":"mk15044-pl-P1527640","type":"sc","tier":"基础","conf":"adapt","chap":"第4-5章","q":"以私有制为基础的商品经济的基本矛盾是（）","opts":["A. 具体劳动和抽象劳动的矛盾","B. 私人劳动和社会劳动的矛盾","C. 个别劳动时间与社会必要劳动时间的矛盾","D. 生产社会化与生产资料私人占有的矛盾"],"ans":1,"explain":"社会劳动与私人劳动的矛盾是以私有制为基础的商品经济的基本矛盾。"},{"id":"mk15044-pl-P1527641","type":"sc","tier":"基础","conf":"adapt","chap":"第4-5章","q":"私人劳动和社会劳动矛盾形成的条件是（）","opts":["A. 自然分工和社会分工","B. 社会化大生产和生产资料私有制","C. 自然分工和生产资料私有制","D. 生产资料私有制和社会分工"],"ans":3,"explain":"私人劳动和社会劳动矛盾形成的条件是生产资料私有制和社会分工。"},{"id":"mk15044-pl-P1527642","type":"sc","tier":"基础","conf":"adapt","chap":"第4-5章","q":"私人劳动和社会劳动形成的条件是（ ）","opts":["A. 技术进步和生产资料公有制","B. 技术进步和生产资料私有制","C. 社会分工和生产资料公有制","D. 社会分工和生产资料私有制"],"ans":3,"explain":"私人劳动和社会劳动形成的条件是社会分工和生产资料私有制"},{"id":"mk15044-pl-P1527643","type":"sc","tier":"基础","conf":"adapt","chap":"第4-5章","q":"构成商品价格基础的是（ ）。","opts":["A. 使用价值","B. 价值","C. 商品供给","D. 商品需求"],"ans":1,"explain":"构成商品价格基础的是价值。"},{"id":"mk15044-pl-P1527644","type":"sc","tier":"基础","conf":"adapt","chap":"第4-5章","q":"按社会必要劳动时间决定的价值进行商品交换的规律是（）","opts":["A. 供求规律","B. 价格规律","C. 竞争规律","D. 价值规律"],"ans":3,"explain":"价值规律的基本内容和要求是：商品的价值由生产商品的社会必要劳动时间所决定，商品交换以价值为基础，实行等价交换。"},{"id":"mk15044-pl-P1527645","type":"sc","tier":"基础","conf":"adapt","chap":"第4-5章","q":"价值规律调节社会劳动在各部门的分配是通过（ ）。","opts":["A. 价格始终同价值相等实现的","B. 价格高于价值实现的","C. 价格低于价值实现的","D. 价格围绕价值上下波动实现的"],"ans":3,"explain":"价值规律调节社会劳动在各部门的分配是通过价格围绕价值上下波动实现的。"},{"id":"mk15044-pl-P1527646","type":"sc","tier":"基础","conf":"adapt","chap":"第4-5章","q":"价值规律是（ ）。","opts":["A. 自然经济的基本规律","B. 商品经济的基本规律","C. 资本主义经济的基本规律","D. 社会主义经济的基本规律"],"ans":1,"explain":"价值规律是商品经济的基本规律。"},{"id":"mk15044-pl-P1527647","type":"sc","tier":"基础","conf":"adapt","chap":"第4-5章","q":"商品经济的基本规律是（）","opts":["A. 货币流通规律","B. 价值规律","C. 资本积累规律","D. 剩余价值规律"],"ans":1,"explain":"价值规律是商品经济的基本经济规律。"},{"id":"mk15044-pl-P1527648","type":"sc","tier":"基础","conf":"adapt","chap":"第4-5章","q":"价值规律作用的表现形式是（ ）。","opts":["A. 商品价格围绕价值波动","B. 商品价格经常低于价值","C. 价值围绕商品价格波动","D. 商品价格往往高于价值"],"ans":0,"explain":"价值规律作用的表现形式是商品价格围绕价值波动。"},{"id":"mk15044-pl-P1527649","type":"sc","tier":"基础","conf":"adapt","chap":"第4-5章","q":"使资本主义制度取得胜利和最终确立的标志是（）","opts":["A. 小商品生产者两级分化","B. 资产阶级革命","C. 资本原始积累","D. 产业革命"],"ans":3,"explain":"产业革命使资本主义制度取得完全胜利和最终确立。"},{"id":"mk15044-pl-P1527650","type":"sc","tier":"基础","conf":"adapt","chap":"第4-5章","q":"单位商品的价值量与包含在商品中的社会必要劳动量（）","opts":["A. 成正比","B. 成反比","C. 不成比例","D. 没有关系"],"ans":0,"explain":"单位商品的价值量，与包含在商品中的社会必要劳动量成正比"},{"id":"mk15044-pl-P1527651","type":"sc","tier":"基础","conf":"adapt","chap":"第4-5章","q":"下列选项中，与生产该商品的劳动生产率成反比的是（）","opts":["A. 社会必要劳动时间","B. 单位商品的价值量","C. 简单劳动时间","D. 复杂劳动时间"],"ans":1,"explain":"单位商品的价值量，与包含在商品中的社会必要劳动量成正比，而与生产该商品的劳动生产率成反比。"},{"id":"mk15044-pl-P1527652","type":"sc","tier":"基础","conf":"adapt","chap":"第4-5章","q":"单位商品价值量与生产该商品的劳动生产率的关系是（）","opts":["A. 成正比","B. 成反比","C. 不成比例","D. 没有关系"],"ans":1,"explain":"单位商品的价值量，与包含在商品中的社会必要劳动量成正比，而与生产该商品的劳动生产率成反比。"},{"id":"mk15044-pl-P1527654","type":"sc","tier":"基础","conf":"adapt","chap":"第4-5章","q":"与商品的赊购赊销相联系的货币职能是（）","opts":["A. 价值尺度","B. 流通手段","C. 储藏手段","D. 支付手段"],"ans":3,"explain":"货币的支付手段职能，是指在商品赊购赊销过程中，当到期偿还货款时货币所执行的还款职能，以及用于清偿债务，支付赋税、租金、工资等所执行的职能。"},{"id":"mk15044-pl-P1527655","type":"sc","tier":"基础","conf":"adapt","chap":"第4-5章","q":"价格是商品价值的货币表现，所以（）","opts":["A. 价格和价值始终一致","B. 价格和价值始终不一致","C. 价格和货币价值有关","D. 价格和货币价值无关"],"ans":2,"explain":"价格是商品价值的货币表现，所以价格和货币价值有关。"},{"id":"mk15044-pl-P1527657","type":"sc","tier":"基础","conf":"adapt","chap":"第4-5章","q":"下列关于具体劳动概念的描述，正确的是（）","opts":["A. 具体劳动是生产商品劳动的本质属性","B. 具体劳动是生产商品劳动的社会属性","C. 具体劳动创造商品的价值","D. 具体劳动创造商品的使用价值"],"ans":3,"explain":"具体劳动创造出使用价值，不同的具体劳动创造出不同的使用价值。"},{"id":"mk15044-pl-P1527658","type":"sc","tier":"基础","conf":"adapt","chap":"第4-5章","q":"具体劳动（ ）","opts":["A. 反映人与自然的关系","B. 是劳动的社会属性","C. 反映社会生产关系","D. 创造剩余价值"],"ans":0,"explain":"具体劳动反映人与自然的关系"},{"id":"mk15044-pl-P1527659","type":"sc","tier":"基础","conf":"adapt","chap":"第4-5章","q":"决定商品价值量的是（ ）","opts":["A. 社会必要劳动时间","B. 必要劳动时间","C. 个别劳动时间","D. 剩余劳动时间"],"ans":0,"explain":"决定商品价值量的社会必要劳动时间，取决于该部门的平均劳动生产率，而不取决于个别企业的劳动生产率。"},{"id":"mk15044-pl-P1527660","type":"sc","tier":"基础","conf":"adapt","chap":"第4-5章","q":"两种商品可以按一定比例相互交换的原因，在于它们（ ）。","opts":["A. 有不同的使用价值","B. 都是具体劳动的产物","C. 对人们有共同的效应","D. 在生产中都耗费了一般的人类劳动"],"ans":3,"explain":"两种商品可以按一定比例相互交换的原因，在于它们在生产中都耗费了一般的人类劳动（价值）。"},{"id":"mk15044-pl-P1527661","type":"sc","tier":"基础","conf":"adapt","chap":"第4-5章","q":"商品的二因素指的是（ ）。","opts":["A. 使用价值和剩余价值","B. 使用价值和交换价值","C. 价值和使用价值","D. 价值和交换价值"],"ans":2,"explain":"商品的二因素指的是价值和使用价值。"},{"id":"mk15044-pl-P1527662","type":"sc","tier":"基础","conf":"adapt","chap":"第4-5章","q":"商品的价值是（）","opts":["A. 物品的有用性","B. 抽象劳动的凝结","C. 需求的满足度","D. 具体劳动创造的"],"ans":1,"explain":"商品的价值是无差别的一般人类劳动的凝结，也就是抽象劳动的凝结。"},{"id":"mk15044-pl-P1527663","type":"sc","tier":"基础","conf":"adapt","chap":"第4-5章","q":"商品的价值用货币来表现就是（）","opts":["A. 金属货币","B. 纸币","C. 价值尺度","D. 商品的价格"],"ans":3,"explain":"商品的价值用货币来表现就是商品的价格。"},{"id":"mk15044-pl-P1527664","type":"sc","tier":"基础","conf":"adapt","chap":"第4-5章","q":"社会必要劳动时间是以（ ）","opts":["A. 具体劳动为尺度的","B. 简单劳动为尺度的","C. 复杂劳动为尺度的","D. 个别劳动为尺度的"],"ans":1,"explain":"商品价值量和社会必要劳动时间以简单劳动为尺度"},{"id":"mk15044-pl-P1527665","type":"sc","tier":"基础","conf":"adapt","chap":"第4-5章","q":"商品生产者要获得更多收益必须使商品的（）","opts":["A. 个别价值小于社会价值","B. 个别价值大于社会价值","C. 个别价值等于社会价值","D. 个别价值不等于社会价值"],"ans":0,"explain":"商品交换是按照其社会价值进行的。如果某个商品生产者生产单位商品的个别劳动时间少于社会必要劳动时间，其商品的个别价值就小于社会价值，但该商品仍能按其社会价值进行交换，他就可以获得较多盈利，并在市场竞争中处于有利地位；反之，如果某个商品生产者所生产的单位商品的个别价值大于社会价值，他就会亏本甚至破产。"},{"id":"mk15044-pl-P1527666","type":"sc","tier":"基础","conf":"adapt","chap":"第4-5章","q":"商品经济产生和存在的决定性条件是（ ）。","opts":["A. 社会分工的出现和发展","B. 市场经济体制的建立","C. 劳动力成为商品","D. 生产资料和劳动产品属于不同的所有者"],"ans":3,"explain":"商品经济产生和存在的决定性条件是生产资料和劳动产品属于不同的所有者。"},{"id":"mk15044-pl-P1527667","type":"sc","tier":"基础","conf":"adapt","chap":"第4-5章","q":"商品经济产生和存在的条件是（ ）。","opts":["A. 自然经济的存在和发展","B. 社会化大生产的存在和发展","C. 资本主义私有制的存在和发展","D. 社会分工和生产资料及其产品属于不同所有者"],"ans":3,"explain":"商品经济产生和存在的条件是社会分工和生产资料及其产品属于不同所有者。"},{"id":"mk15044-pl-P1527669","type":"sc","tier":"基础","conf":"adapt","chap":"第4-5章","q":"商品经济成为最普遍的、占统治地位的经济形式的社会形态是（ ）。","opts":["A. 原始社会","B. 奴隶社会","C. 封建社会","D. 资本主义社会"],"ans":3,"explain":"商品经济成为最普遍的、占统治地位的经济形式的社会形态是资本主义社会。"},{"id":"mk15044-pl-P1527670","type":"sc","tier":"基础","conf":"adapt","chap":"第4-5章","q":"下列各项正确表述商品含义的是（ ）。","opts":["A. 具有使用价值的物品","B. 具有稀缺性的物品","C. 为自己而生产的有用物品","D. 为交换而生产的有用物品"],"ans":3,"explain":"商品是为交换而生产的有用物品。"},{"id":"mk15044-pl-P1527671","type":"sc","tier":"基础","conf":"adapt","chap":"第4-5章","q":"商品最本质的因素是（ ）。","opts":["A. 使用价值","B. 价值","C. 交换价值","D. 价格"],"ans":1,"explain":"商品最本质的因素是价值。"},{"id":"mk15044-pl-P1527673","type":"sc","tier":"基础","conf":"adapt","chap":"第4-5章","q":"关于社会分工的产生，下列表述中正确的是（ ）","opts":["A. 社会分工是私有制的产物","B. 社会分工是商品经济的产物","C. 社会分工是资本主义的产物","D. 社会分工是生产力发展的产物"],"ans":3,"explain":"社会分工是生产力发展的产物"},{"id":"mk15044-pl-P1527674","type":"sc","tier":"基础","conf":"adapt","chap":"第4-5章","q":"生产商品的劳动二重性是指（）","opts":["A. 具体劳动和抽象劳动","B. 个别劳动和社会劳动","C. 私人劳动和社会劳动","D. 脑力劳动和体力劳动"],"ans":0,"explain":"生产商品的劳动的二重性：具体劳动和抽象劳动"},{"id":"mk15044-pl-P1527676","type":"sc","tier":"基础","conf":"adapt","chap":"第4-5章","q":"商品的使用价值是（）","opts":["A. 物品的有用性","B. 抽象劳动凝结","C. 商品的社会属性","D. 商品的本质因素"],"ans":0,"explain":"使用价值是一种物品能够满足人们某种需要的属性，即物品的有用性。"},{"id":"mk15044-pl-P1527677","type":"sc","tier":"基础","conf":"adapt","chap":"第4-5章","q":"支付工资的货币执行的是货币的（ ）。","opts":["A. 价值尺度职能","B. 流通手段职能","C. 支付手段职能","D. 贮藏手段职能"],"ans":2,"explain":"支付工资的货币执行的是货币的支付手段。"},{"id":"mk15044-pl-P1527678","type":"sc","tier":"基础","conf":"adapt","chap":"第4-5章","q":"第二次世界大战后，资本国际化主要表现为（）","opts":["A. 商业资本的国际化","B. 借贷资本的国际化","C. 产业资本的国际化","D. 银行资本的国际化"],"ans":2,"explain":"第二次世界大战后，资本国际化主要表现为产业资本的国际化 。"},{"id":"mk15044-pl-P1527679","type":"sc","tier":"基础","conf":"adapt","chap":"第4-5章","q":"第一次工业革命时期，英美等主要资本主义国家处于（ ）。","opts":["A. 自由竞争资本主义阶段","B. 私人垄断资本主义阶段","C. 一般垄断资本主义阶段","D. 国家垄断资本主义阶段"],"ans":0,"explain":"第一次工业革命时期，英美等主要资本主义国家处于自由竞争资本主义阶段。"},{"id":"mk15044-pl-P1527680","type":"sc","tier":"基础","conf":"adapt","chap":"第4-5章","q":"一般而言，经济全球化的内容不包括（）","opts":["A. 生产全球化","B. 贸易全球化","C. 资本全球化","D. 劳动力流动全球化"],"ans":3,"explain":"经济全球化本质上是资源配置的国际化，其内容包括很多方面，大体可从生产全球化、贸易全球化和资本全球化三方面来考察。"},{"id":"mk15044-pl-P1527681","type":"sc","tier":"基础","conf":"adapt","chap":"第4-5章","q":"一般而言，经济全球化的主要内容不包括（ ）。","opts":["A. 生产全球化","B. 贸易全球化","C. 资本全球化","D. 劳动力流动全球化"],"ans":3,"explain":"一般而言，经济全球化的主要内容不包括劳动力流动全球化。生产全球化、贸易全球化、资本全球化是经济全球化的主要内容。"},{"id":"mk15044-pl-P1527682","type":"sc","tier":"基础","conf":"adapt","chap":"第4-5章","q":"早期资本主义世界经济体系中的国际分工主要是（）","opts":["A. 垂直分工","B. 水平分工","C. 专业分工","D. 横向分工"],"ans":0,"explain":"早期资本主义世界经济体系中的国际分工主要是所谓垂直分工"},{"id":"mk15044-pl-P1527683","type":"sc","tier":"基础","conf":"adapt","chap":"第4-5章","q":"一般而言资本国际化发展的顺序是（）","opts":["A. 产业资本、借贷资本到商业资本的国际化","B. 商业资本、借贷资本到产业资本的国际化","C. 借贷资本、产业资本到商业资本的国际化","D. 借贷资本、商业资本到产业资本的国际化"],"ans":1,"explain":"资本国际化发展的顺序是从商业资本、借贷资本到产业资本的国际化。"},{"id":"mk15044-pl-P1527684","type":"sc","tier":"基础","conf":"adapt","chap":"第4-5章","q":"列宁指出：国家垄断资本主义的产生和发展（）","opts":["A. 否定资本主义私有制","B. 杜绝了经济危机的爆发","C. 解决了资本主义的基本矛盾","D. 为向社会主义过渡准备了最充分的条件"],"ans":3,"explain":"家垄断资本主义的产生和发展，为全社会占有生产资料和共同组织社会化生产准备了最充分的物质条件和经济条件。"},{"id":"mk15044-pl-P1527685","type":"sc","tier":"基础","conf":"adapt","chap":"第4-5章","q":"垄断资本主义为向社会主义转变准备了日益完善的社会经济基础，这是指（）","opts":["A. 无产阶级的产生和壮大","B. 社会化大生产的全面发展","C. 社会基本矛盾的加剧","D. 国家管理经济职能的出现"],"ans":1,"explain":"社会主义必然取代资本主义，是生产关系一定要适合生产力状况这一经济规律的客观要求。资本主义条件下生产社会化的全面发展，推动了资本关系的日益社会化，为向社会主义转变准备了日益完备的社会经济基础。这样，从资本主义向社会主义过渡的条件也就日益成熟了。"},{"id":"mk15044-pl-P1527686","type":"sc","tier":"基础","conf":"adapt","chap":"第4-5章","q":"垄断资本主义的历史作用是（）。","opts":["A. 为一个更高级的生产形式创造物质条件","B. 建立完善的市场体系和市场机制","C. 实现生产社会化和经济全球化","D. 不断发展社会的民主与法制"],"ans":0,"explain":"发展社会劳动生产力，是资本主义的历史任务和存在理由。资本正是以此不自觉地创造着一种更高级的生产形式的物质条件。"},{"id":"mk15044-pl-P1527687","type":"sc","tier":"基础","conf":"adapt","chap":"第4-5章","q":"马克思说，资本主义“不自觉地为一个更高级的生产形式创造物质条件”，它的“历史任务和存在理由”是（）","opts":["A. 发明创造新科技成果","B. 发展社会劳动生产力","C. 生产先进的机器设备","D. 建立完善的市场经济"],"ans":1,"explain":"发展社会劳动生产力，是资本主义的历史任务和存在理由。资本正是以此不自觉地创造着一种更高级的生产形式的物质条件。"},{"id":"mk15044-pl-P1527688","type":"sc","tier":"基础","conf":"adapt","chap":"第4-5章","q":"马克思说，资本主义“不自觉地为一个更高级的生产形势创造物质条件”，它的“历史人物和存在理由”是（ ）。","opts":["A. 发明创造新科技成果","B. 发展社会劳动生产力","C. 生产先进的机器设备","D. 建立完善的市场经济"],"ans":1,"explain":"马克思说，资本主义“不自觉地为一个更高级的生产形势创造物质条件”，它的“历史人物和存在理由”是发展社会劳动生产力。"},{"id":"mk15044-pl-P1527689","type":"sc","tier":"基础","conf":"adapt","chap":"第4-5章","q":"资本主义各国之间经济政治的发展是不平衡的，这就决定了（）","opts":["A. 发达资本主义国家首先进入社会主义","B. 不发达资本主义国家首先进入社会主义","C. 资本主义向社会主义过渡是一个短暂的历史过程","D. 资本主义向社会主义过渡是一个相当长的历史过程"],"ans":3,"explain":"资本主义各国之间经济政治的发展是不平衡的，这就决定了资本主义向社会主义过渡是一个相当长的历史过程"},{"id":"mk15044-pl-P1527690","type":"sc","tier":"基础","conf":"adapt","chap":"第4-5章","q":"下列选项中不属于当代资本主义生产力方面新变化的是（ ）。","opts":["A. 生产者中脑力劳动者的比重增加","B. 机器生产由“三机系统”发展为“四机系统”","C. 生产管理增加了计算机信息技术等新手段和工具","D. 在生产资料所有制上出现了法人所有制等新形式"],"ans":3,"explain":"“在生产资料所有制上出现了法人所有制等新形式”属于生产关系方面的新变化。"},{"id":"mk15044-pl-P1527691","type":"sc","tier":"基础","conf":"adapt","chap":"第4-5章","q":"上世纪下半叶，从第二次世界大战结束后到冷战前，西方主要发达资本主义国家处于（ ）。","opts":["A. 自由竞争资本主义阶段","B. 私人垄断资本主义阶段","C. 垄断资本主义阶段","D. 国家垄断资本主义阶段"],"ans":3,"explain":"从第二次世界大战结束后到冷战前，西方主要发达资本主义国家处于国家垄断资本主义阶段。"},{"id":"mk15044-pl-P1527692","type":"sc","tier":"基础","conf":"adapt","chap":"第4-5章","q":"从资本形态上看，资本输出的基本形式是（ ）。","opts":["A. 私人资本输出和国家资本输出","B. 国内资本输出和国际资本输出","C. 借贷资本输出和生产资本输出","D. 商业资本输出和金融资本输出"],"ans":2,"explain":"从资本形态上看，资本输出的基本形式是借贷资本输出和生产资本输出。"},{"id":"mk15044-pl-P1527693","type":"sc","tier":"基础","conf":"adapt","chap":"第4-5章","q":"在对外经济侵略中，最具新殖民主义特点的做法是（）","opts":["A. 高价推销工业品和高科技产品","B. 低价收购初级产品和原材料","C. 实行“对外援助”","D. 大量对外输出“过剩资本”"],"ans":2,"explain":"当代垄断资本主义国家多是采取比较缓和隐蔽的新殖民主义手法，打着所谓“援助”的旗号实现其对发展中国家的剥削和控制。"},{"id":"mk15044-pl-P1527694","type":"sc","tier":"基础","conf":"adapt","chap":"第4-5章","q":"当代主要发达资本主义国家处于资本主义发展中的（ ）。","opts":["A. 自由竞争资本主义阶段","B. 私人垄断资本主义阶段","C. 一般垄断资本主义阶段","D. 国家垄断资本主义阶段"],"ans":3,"explain":"当代主要发达资本主义国家处于资本主义发展中的国家垄断资本主义阶段。"},{"id":"mk15044-pl-P1527695","type":"sc","tier":"基础","conf":"adapt","chap":"第4-5章","q":"中央银行在货币资本市场上公开出售有价证券直接导致了（）","opts":["A. 流通中货币量的增加","B. 流通中货币量的减少","C. 市场物价上升","D. 市场物价下降"],"ans":1,"explain":"公开市场业务，即由中央银行在货币资本市场上公开出售或收购有价证券，若是中央银行大量收购有价证券，则意味着一般商业银行手中的货币就有所增加，因而流通中的货币量就多了，反之则相反。"},{"id":"mk15044-pl-P1527696","type":"sc","tier":"基础","conf":"adapt","chap":"第4-5章","q":"国际垄断同盟在经济上瓜分世界是通过垄断组织间的协议实现的，而协议的订立（）","opts":["A. 是在平等互利的基础上达成的","B. 是以经济实力为后盾和基础的","C. 使各国和各垄断组织之间的竞争不复存在","D. 一旦形成就永远不变"],"ans":1,"explain":"国际垄断同盟在经济上瓜分世界，也即各垄断资本主义国家和垄断组织在世界市场上和国际经济关系中划分势力范围，形成国际垄断局面。这种瓜分多是通过垄断组织间的协议实现的，而协议的订立、瓜分的结果又是以经济实力为后盾和基础的。"},{"id":"mk15044-pl-P1527697","type":"sc","tier":"基础","conf":"adapt","chap":"第4-5章","q":"资本主义国家对国民经济的调节和控制，主要是运用（）","opts":["A. 计划手段","B. 经济手段","C. 法律手段","D. 行政手段"],"ans":1,"explain":"国家对经济的管理调控以经济手段为主的具体体现。"},{"id":"mk15044-pl-P1527698","type":"sc","tier":"基础","conf":"adapt","chap":"第4-5章","q":"国家垄断资本主义管理和调控经济的主要机制是（）","opts":["A. 国家调节市场，市场引导企业","B. 国家管理企业，企业引领市场","C. 国家宏观调控，企业微观规制","D. 国家政策引导，市场自由竞争"],"ans":0,"explain":"国家垄断资本主义管理和调控经济的主要机制是国家调节市场，市场引导企业"},{"id":"mk15044-pl-P1527699","type":"sc","tier":"基础","conf":"adapt","chap":"第4-5章","q":"国家垄断资本主义对宏观经济的管理和调控，主要是通过下列哪项经济调节机制实现的（）","opts":["A. 国家对企业的直接控制","B. 一定程度上实现国民经济计划化","C. 国家调节市场，市场引导企业","D. 国家指导企业，企业指导市场"],"ans":2,"explain":"国家垄断资本主义宏观经济管理和调控目标的实现，主要是通过国家调节市场、市场引导企业这样一种经济调节机制实现的，这也是国家对经济的管理调控以经济手段为主的具体体现。"},{"id":"mk15044-pl-P1527700","type":"sc","tier":"基础","conf":"adapt","chap":"第4-5章","q":"“过剩资本”的出现是（）","opts":["A. 资本积累的前提条件","B. 资本循环的物质基础","C. 资本输出的财力基础","D. 引进资本的必然结果"],"ans":2,"explain":"垄断阶段资本输出的必要性，在于大量所谓“过剩资本”的出现，这是资本输出的财力基础。"},{"id":"mk15044-pl-P1527701","type":"sc","tier":"基础","conf":"adapt","chap":"第4-5章","q":"垄断资本主义国家对外输出资本主要形式发展变化的顺序大体是（）","opts":["A. 商业资本输出-借贷资本输出-产业资本输出","B. 借贷资本输出-商业资本输出-产业资本输出","C. 产业资本输出-商业资本输出-借贷资本输出","D. 商业资本输出-产业资本输出-借贷资本输出"],"ans":0,"explain":"垄断资本主义国家对外输出资本主要形式发展变化的顺序大体是商业资本输出-借贷资本输出-产业资本输出"},{"id":"mk15044-pl-P1527702","type":"sc","tier":"基础","conf":"adapt","chap":"第4-5章","q":"垄断资本主义社会大体可分为（ ）。","opts":["A. 一般垄断资本主义和私人垄断资本主义两个阶段","B. 私人垄断资本主义和国家垄断资本主义两个阶段","C. 一般垄断资本主义、私人垄断资本主义和国家垄断资本主义三个阶段","D. 私人垄断资本主义、国家垄断资本主义和国际垄断资本主义三个阶段"],"ans":1,"explain":"垄断资本主义社会大体可分为私人垄断（一般垄断）资本主义和国家垄断资本主义两个阶段。"},{"id":"mk15044-pl-P1527704","type":"sc","tier":"基础","conf":"adapt","chap":"第4-5章","q":"由资本主义国家收购部分股权后的私人企业属于（ ）。","opts":["A. 国家和私人资本在企业外部的结合","B. 国家和私人资本在企业内部的结合","C. 资本主义国有经济","D. 资本主义私人经济"],"ans":1,"explain":"由资本主义国家收购部分股权后的私人企业属于国家和私人资本在企业内部的结合。"},{"id":"mk15044-pl-P1527705","type":"sc","tier":"基础","conf":"adapt","chap":"第4-5章","q":"在对外经济侵略中，新殖民主义不同于老殖民主义的手法是（ ）。","opts":["A. 高价出售工业产品","B. 低价收购原料和初级产品","C. 向外输出“过剩资本”获取高额海外利润","D. 打着“援助”旗号剥削和控制发展中国家"],"ans":3,"explain":"在对外经济侵略中，新殖民主义不同于老殖民主义的手法是打着“援助”旗号剥削和控制发展中国家。"},{"id":"mk15044-pl-P1527706","type":"sc","tier":"基础","conf":"adapt","chap":"第4-5章","q":"下列选项中不属于当代资本主义生产关系方面新变化的是（ ）。","opts":["A. 在生产管理方面，出现了一系列运用电子计算机等新技术的管理手段和工具","B. 在所有制方面，出现了资本社会化，股权分散化趋势，法人所有制崛起","C. 在劳资关系方面，建立了劳资共决，职工参与管理和持股，终身雇佣等制度","D. 在收入分配方面，推行社会福利正常，通过再分配手段缓和社会矛盾"],"ans":0,"explain":"从生产关系方面看。当代资本主义国家在所有制关系、劳资关系和分配关系三方面都做了一系列调整。在所有制关系上，出现了所谓资本社会化的趋势，建立和发展了一定比重的国有经济，并在国民经济的某些方面起到重要作用。同时私人企业股权分散化，法人资本所有制崛起。在劳资关系上，建立了所谓劳资共决、职工参与决策、终身雇佣、职工持股等制度。在分配关系上，许多发达国家对收入分配政策进行了某些调整，如实行社会福利政策，通过再分配手段在一定程度上缓和了社会矛盾。BCD三个选项属于当代资本主义生产关系新变化。A选项属于当代资本主义生产力方面的新变化，而不是生产关系，因此选A。"},{"id":"mk15044-pl-P1527707","type":"sc","tier":"基础","conf":"adapt","chap":"第4-5章","q":"当代资本主义国家在其自身范围内对生产关系进行不断调整，这种调整（）","opts":["A. 改变了资本主义私有制的性质","B. 适应了生产力发展的要求","C. 完全解决了生产力和生产关系的矛盾","D. 为向社会主义过渡准备了物质条件"],"ans":1,"explain":"在所有制关系上，资本主义国家在其自身范围内进行不断的调整，以适应生产力发展的要求。"},{"id":"mk15044-pl-P1527709","type":"sc","tier":"基础","conf":"adapt","chap":"第4-5章","q":"资本输出的形式，从资本形态上分，主要有（）","opts":["A. 商业资本输出和借贷资本输出","B. 借贷资本输出和生产资本输出","C. 私人资本输出和国家资本输出","D. 商业资本输出和生产资本输出"],"ans":1,"explain":"资本输出的形式有多种，从资本形态上来看大体有两种基本形式，即借贷资本输出和生产资本输出。"},{"id":"mk15044-pl-P1527710","type":"sc","tier":"基础","conf":"adapt","chap":"第4-5章","q":"取代商品输出成为垄断资本主义阶段对外经济特征的是（）","opts":["A. 货币输出","B. 资本输出","C. 劳动力输出","D. 自然资源输出"],"ans":1,"explain":"资本输出在各主要资本主义国家普遍而大规模地发展了起来，成为垄断资本主义时期资本主义经济关系，特别是对外经济关系中的一个重要特征。"},{"id":"mk15044-pl-P1527711","type":"sc","tier":"基础","conf":"adapt","chap":"第4-5章","q":"资本主义的国有资本和国有经济一般不参与（ ）。","opts":["A. 基础设施的建设","B. 战略性科学研究","C. 普通消费品生产","D. 公共产品生产"],"ans":2,"explain":"资本主义的国有资本和国有经济一般不参与普通消费品生产。"},{"id":"mk15044-pl-P1527712","type":"sc","tier":"基础","conf":"adapt","chap":"第4-5章","q":"资本主义国家调控经济的主要手段是（ ）。","opts":["A. 经济手段和经济计划","B. 经济手段和法律手段","C. 行政手段和经济计划","D. 法律手段和经济计划"],"ans":1,"explain":"资本主义国家调控经济的主要手段是经济手段和法律手段。"},{"id":"mk15044-pl-P1527713","type":"sc","tier":"基础","conf":"adapt","chap":"第4-5章","q":"资本主义国家对国民经济的管理和调节，主要依靠（ ）。","opts":["A. 经济手段","B. 法律手段","C. 行政手段","D. 计划手段"],"ans":0,"explain":"资本主义国家对国民经济的管理和调节，主要依靠经济手段。"},{"id":"mk15044-pl-P1527714","type":"sc","tier":"基础","conf":"adapt","chap":"第4-5章","q":"资本主义国家对国民经济的管理和调控（ ）。","opts":["A. 能够消除经济危机","B. 可以缓和资本主义内部的某些矛盾","C. 能够防止生产过剩","D. 可以根除资本主义基本矛盾"],"ans":1,"explain":"资本主义国家对国民经济的管理和调控可以缓和资本主义内部的某些矛盾。"},{"id":"mk15044-pl-P1527715","type":"sc","tier":"基础","conf":"adapt","chap":"第4-5章","q":"促进市场总供给和总需求的平衡是资本主义国家宏观调控的（）","opts":["A. 目标","B. 任务","C. 手段","D. 政策"],"ans":1,"explain":"资本主义国家宏观经济管理与调节的总任务，是促进市场总供给和总需求的平衡。"},{"id":"mk15044-pl-P1527716","type":"sc","tier":"基础","conf":"adapt","chap":"第4-5章","q":"资本主义国家宏观经济管理与调节的总任务是（ ）。","opts":["A. 实现充分就业","B. 稳定币值、汇率和物价","C. 促进市场总供需平衡","D. 推动经济发展与增长"],"ans":2,"explain":"资本主义国家宏观经济管理与调节的总任务是促进市场总供需平衡。"},{"id":"mk15044-pl-P1527717","type":"sc","tier":"基础","conf":"adapt","chap":"第4-5章","q":"资本主义国家通过财政政策和货币政策对经济运行进行调节属于运用（）","opts":["A. 计划手段","B. 经济手段","C. 法律手段","D. 行政手段"],"ans":1,"explain":"资本主义国家通过财政政策和货币政策对经济运行进行调节属于运用经济手段。"},{"id":"mk15044-pl-P1527718","type":"sc","tier":"基础","conf":"adapt","chap":"第4-5章","q":"资本主义国家向某个濒临破产的私人企业注入一定量的国有资本，使之能继续生存下去，此时这个企业的性质属于（ ）。","opts":["A. 资本主义国有经济","B. 资本主义私有经济","C. 资本主义国有资本和私人资本在企业内部的结合","D. 资本主义国有资本和私人资本在企业外部的结合"],"ans":2,"explain":"资本主义国家向某个濒临破产的私人企业注入一定量的国有资本，使之能继续生存下去，此时这个企业的性质属于资本主义国有资本和私人资本在企业内部的结合。"},{"id":"mk15044-pl-P1527719","type":"sc","tier":"基础","conf":"adapt","chap":"第4-5章","q":"资本主义经济中的计划管理（ ）。","opts":["A. 消除了资本主义的生产无政府状态","B. 能够自觉保持社会再生产的比例关系","C. 阻碍了生产的发展和经济结构的优化","D. 可以对经济周期进行一定的调节与控制"],"ans":3,"explain":"资本主义经济中的计划管理可以对经济周期进行一定的调节与控制。"},{"id":"mk15044-pl-P1527720","type":"sc","tier":"基础","conf":"adapt","chap":"第4-5章","q":"第二次世界大战后，垄断组织发展的最新形式是（）。","opts":["A. 卡特尔","B. 辛迪加","C. 托拉斯","D. 混合联合公司"],"ans":3,"explain":"20世纪后半叶，垄断组织的形式又有较大发展，主要特征是混合联合企业的兴起。"},{"id":"mk15044-pl-P1527721","type":"sc","tier":"基础","conf":"adapt","chap":"第4-5章","q":"20世纪后半叶兴起的混合联合公司是（）","opts":["A. 一个部门中从事生产经营的垄断组织形式","B. 从事同类产品生产经营的垄断组织形式","C. 从事跨部门，跨行业生产经营的垄断组织形式","D. 从事同类产品和相关产品生产经营的垄断组织形式"],"ans":2,"explain":"20世纪后半叶，垄断组织的形式又有较大发展，主要特征是混合联合企业的兴起。这种混合联合公司规模巨大，它们的生产经营项目已不仅限于同类或相关产品的生产和经营活动，而是跨行业跨部门进行混合联合生产与经营，在社会生产和生活中的各个产业都有所涉足。"},{"id":"mk15044-pl-P1527722","type":"sc","tier":"基础","conf":"adapt","chap":"第4-5章","q":"自由竞争和生产集中的关系是（）","opts":["A. 自由竞争引起生产集中","B. 自由竞争阻碍生产集中","C. 生产集中引起自由竞争","D. 生产集中根除自由竞争"],"ans":0,"explain":"从历史发展的脉络来看，是自由竞争引起生产集中，生产集中发展到一定程度就会自然而然地走向垄断。"},{"id":"mk15044-pl-P1527724","type":"sc","tier":"基础","conf":"adapt","chap":"第4-5章","q":"金融寡头在经济上的统治主要是实行参与制，这是指金融寡头（）","opts":["A. 直接参与工业企业的生产经营和管理","B. 直接参与银行的生产经营和管理","C. 通过控制一定数量的股票从而层层控制许多企业的经济上的统治方式","D. 通过购买所述公司的全部股票直接掌握许多企业的经济上的统治方式"],"ans":2,"explain":"金融寡头在经济上的统治主要是通过实行“参与制”实现的，参与制是通过控制一定数量的股票从而层层控制许多企业的经济上的统治方式。"},{"id":"mk15044-pl-P1527725","type":"sc","tier":"基础","conf":"adapt","chap":"第4-5章","q":"金融寡头在政治上的统治方式主要是（）","opts":["A. 参与制","B. 个人联合","C. 建立政策咨询研究机构","D. 控制新闻媒介"],"ans":1,"explain":"金融寡头在政治上的统治主要是通过“个人联合”的方式实现的。"},{"id":"mk15044-pl-P1527726","type":"sc","tier":"基础","conf":"adapt","chap":"第4-5章","q":"近几十年来垄断组织国际化的最主要形式是（ ）。","opts":["A. 国际卡特尔","B. 国际辛迪加","C. 国际康采恩","D. 跨国公司"],"ans":3,"explain":"近几十年来垄断组织国际化的最主要形式是跨国公司。"},{"id":"mk15044-pl-P1527729","type":"sc","tier":"基础","conf":"adapt","chap":"第4-5章","q":"垄断价格形成意味着（）","opts":["A. 价值规律不复存在","B. 价值规律的作用有限","C. 垄断价格完全可以脱离价值","D. 垄断价格仍然受到价值规律作用的约束"],"ans":3,"explain":"垄断价格是垄断组织在销售或购买商品时，凭借其垄断地位规定的、旨在保证获取最大限度利润的市场价格。"},{"id":"mk15044-pl-P1527730","type":"sc","tier":"基础","conf":"adapt","chap":"第4-5章","q":"垄断利润的真正来源是（ ）。","opts":["A. 垄断行为所创造的更多市场价值","B. 垄断势力在自由市场上的巧取豪夺","C. 工人阶级和劳动人民所创造的剩余价值","D. 生产和非生产领域劳动者共同创造的物质财富"],"ans":2,"explain":"垄断利润的真正来源是工人阶级和劳动人民所创造的剩余价值。"},{"id":"mk15044-pl-P1527731","type":"sc","tier":"基础","conf":"adapt","chap":"第4-5章","q":"垄断资本在经济上乃至政治上统治的目的，是为了获取高额垄断利润，下列关于垄断利润的表述正确的是（）","opts":["A. 垄断利润是垄断资本凭借其垄断地位获得的","B. 垄断利润是垄断统治在政治上的实现","C. 垄断利润的源泉是垄断企业的高生产率","D. 垄断利润获得的途径在于高价销售商品"],"ans":0,"explain":"垄断利润即垄断资本凭借其在生产和流通中的垄断地位所获得的大大超过平均利润的高额利润。"},{"id":"mk15044-pl-P1527732","type":"sc","tier":"基础","conf":"adapt","chap":"第4-5章","q":"垄断利润的获得，主要是通过（）","opts":["A. 垄断价格实现的","B. 自由竞争实现的","C. 市场调节实现的","D. 行政干预实现的"],"ans":0,"explain":"垄断利润主要是通过垄断组织制定的垄断价格来实现的"},{"id":"mk15044-pl-P1527733","type":"sc","tier":"基础","conf":"adapt","chap":"第4-5章","q":"垄断时期竞争的目的是为了获得（）","opts":["A. 平均利润","B. 高额垄断利润","C. 超额利润","D. 垄断地位"],"ans":1,"explain":"垄断时期竞争的目的是获取高额垄断利润"},{"id":"mk15044-pl-P1527734","type":"sc","tier":"基础","conf":"adapt","chap":"第4-5章","q":"垄断资本实现其经济上统治的方式是（ ）。","opts":["A. 股份制","B. 合作制","C. 垄断制","D. 参与制"],"ans":3,"explain":"垄断资本实现其经济上统治的方式是参与制。"},{"id":"mk15044-pl-P1527735","type":"sc","tier":"基础","conf":"adapt","chap":"第4-5章","q":"垄断利润归根到底来源于（）","opts":["A. 工人阶级和劳动人民创造的剩余价值","B. 垄断企业先进的技术设备","C. 垄断资本家制定的垄断价格","D. 垄断组织的垄断地位"],"ans":0,"explain":"垄断资本所获得的高额利润，归根到底来自工人阶级和劳动人民所创造的剩余价值。"},{"id":"mk15044-pl-P1527736","type":"sc","tier":"基础","conf":"adapt","chap":"第4-5章","q":"实行垄断价格的根本目的是为了（）","opts":["A. 最大限度占领市场","B. 最大限度降低成本","C. 获取高额垄断利润","D. 获取行业控制权力"],"ans":2,"explain":"垄断资本在经济乃至政治上统治的目的，归根到底是经济利益驱使的，是为了获取高额垄断利润。"},{"id":"mk15044-pl-P1527737","type":"sc","tier":"基础","conf":"adapt","chap":"第4-5章","q":"从政治经济学的角度看，当代资本主义国家中那些掌握了国民经济命脉、财力雄厚、进行跨部门经营、对社会生活各方面有巨大影响的大财团的资本属于（）","opts":["A. 工业资本","B. 商业资本","C. 金融资本","D. 银行资本"],"ans":2,"explain":"垄断资本主义国家内出现了一种新的资本形式——金融资本，它是由垄断的工业资本和银行资本，通过金融联系、资本参与和人事参与，融合或混合生长构成的一种新的资本形式，是垄断资本主义国家中社会经济生活各个方面实际上的统治者。"},{"id":"mk15044-pl-P1527738","type":"sc","tier":"基础","conf":"adapt","chap":"第4-5章","q":"垄断的工业资本和垄断的银行资本融合或混合生长所构成的资本是（）","opts":["A. 股份资本","B. 金融资本","C. 商业资本","D. 虚拟资本"],"ans":1,"explain":"垄断资本主义国家内出现了一种新的资本形式——金融资本，它是由垄断的工业资本和银行资本，通过金融联系、资本参与和人事参与，融合或混合生长构成的一种新的资本形式，是垄断资本主义国家中社会经济生活各个方面实际上的统治者。"},{"id":"mk15044-pl-P1527739","type":"sc","tier":"基础","conf":"adapt","chap":"第4-5章","q":"垄断资本主义国家的金融资本是指（）","opts":["A. 资本主义国家处于垄断地位的银行资本","B. 资本主义国家金融领域中流通的所有资本的总和","C. 资本主义国家银行和非国家银行金融机构资本的总和","D. 垄断的工业资本和银行资本融合形成的资本"],"ans":3,"explain":"垄断资本主义国家内出现了一种新的资本形式——金融资本，它是由垄断的工业资本和银行资本，通过金融联系、资本参与和人事参与，融合或混合生长构成的一种新的资本形式，是垄断资本主义国家中社会经济生活各个方面实际上的统治者。"},{"id":"mk15044-pl-P1527740","type":"sc","tier":"基础","conf":"adapt","chap":"第4-5章","q":"垄断组织的形式不同，但其本质都是为了（）","opts":["A. 获得垄断利润","B. 控制商品生产","C. 控制商品销售","D. 垄断先进技术"],"ans":0,"explain":"垄断组织的形式不同，但其本质都是为了获得垄断利润。"},{"id":"mk15044-pl-P1527741","type":"sc","tier":"基础","conf":"adapt","chap":"第4-5章","q":"垄断组织获取垄断利润的主要形式是（ ）。","opts":["A. 垄断价格","B. 个人联合","C. 参与制","D. 资本输出"],"ans":0,"explain":"垄断组织获取垄断利润的主要形式是垄断价格。"},{"id":"mk15044-pl-P1527742","type":"sc","tier":"基础","conf":"adapt","chap":"第4-5章","q":"垄断组织实行垄断价格的根本目的是为了（ ）。","opts":["A. 扩大市场份额","B. 降低生产成本","C. 获取高额垄断利润","D. 获取平均利润"],"ans":2,"explain":"垄断组织实行垄断价格的根本目的是为了获取高额垄断利润。"},{"id":"mk15044-pl-P1527743","type":"sc","tier":"基础","conf":"adapt","chap":"第4-5章","q":"从兼并形式上看二战后的兼并更多的表现为（）","opts":["A. 混合兼并","B. 横向兼并","C. 纵向兼并","D. 垂直兼并"],"ans":0,"explain":"企业兼并速度加快，混合兼并占主导地位。"},{"id":"mk15044-pl-P1527744","type":"sc","tier":"基础","conf":"adapt","chap":"第4-5章","q":"第二次世界大战后兴起的新型国际垄断组织是（）","opts":["A. 国际卡特尔","B. 国际托拉斯","C. 国际辛迪加","D. 跨国公司"],"ans":3,"explain":"随着生产社会化与国际化程度的提高，世界经济和世界市场的发展，在经济全球化的过程中，垄断组织不但规模扩大，而且将其生产经营的范围扩展到本国国界以外，形成了新的垄断组织形式和垄断资本国际经济组织的载体——跨国公司"},{"id":"mk15044-pl-P1527745","type":"sc","tier":"基础","conf":"adapt","chap":"第4-5章","q":"垄断了某种商品生产和经营全过程的独立的大型垄断企业称作（）","opts":["A. 卡特尔","B. 辛迪加","C. 托拉斯","D. 康采恩"],"ans":2,"explain":"托拉斯（源自英语Trust），即垄断了某种商品生产和经营全过程的独立的大型垄断企业"},{"id":"mk15044-pl-P1527746","type":"sc","tier":"基础","conf":"adapt","chap":"第4-5章","q":"垄断的银行资本在资本主义社会中的作用是（）","opts":["A. 充当借贷关系中的中介人","B. 成为万能的垄断者","C. 直接控制了所有的货币流通","D. 排斥了中小银行的存在可能"],"ans":1,"explain":"在垄断的银行资本由普通的借贷关系中介人变为社会经济生活中万能的垄断者的同时，也开始了垄断的工业资本与银行资本的融合，这包括了日益紧密、相对固定的银企关系的形成，工业企业与银行之间相互持股以便实现对对方的控制和操纵，乃至银企之间人事上的相互融合。"},{"id":"mk15044-pl-P1526523","type":"sa","tier":"创新","conf":"adapt","chap":"第4-5章","q":"简述价值规律的内容和要求。","opts":[],"ans":null,"explain":"价值规律的基本内容和要求是：商品的价值由生产商品的社会必要劳动时间所决定，商品交换以价值为基础，实行等价交换。概括地表述，价值规律就是商品按照由社会必要劳动时间决定的价值进行交换的规律。这个规律体现着商品经济发展运动过程的必然趋势，它在商品经济条件下，必然存在和起作用，是商品经济的基本经济规律。"},{"id":"mk15044-pl-P1526524","type":"sa","tier":"创新","conf":"adapt","chap":"第4-5章","q":"简述资本原始积累的实质。","opts":[],"ans":null,"explain":"资本原始积累的实质是用暴力手段剥夺小生产者的生产资料，强迫劳动者同生产资料相分离，使生产资料和货币财富在少数资本家手中迅速积累起来，并使劳动者沦为出卖劳动力的雇佣工人。"},{"id":"mk15044-pl-P1526525","type":"sa","tier":"创新","conf":"adapt","chap":"第4-5章","q":"简述影响资本周转速度的因素。","opts":[],"ans":null,"explain":"(1)影响资本周转速度的快慢有两个因素：一是资本周转时间的长短；二是生产资本的构成。<br/>(2)资本周转速度的快慢，受生产时间和流通时间的重要影响。生产时间和流通时间越短，资本周转速度就越快；反之，生产时间和流通时间越长，资本周转速度就越慢。<br/>(3)生产资本的构成是生产过程中影响资本周转速度的重要因素。这种影响来自两个方面，一是生产固定资本和流动资本的比例。在生产资本中流动固定资本所占的比重越大，预付总资本的总周转速度就越慢；在生产资本中流动资本所占的比重越大，预付资本的总周转速度就越快。二是固定资本和流动资本本身的周转速度。在生产资本中的固定资本与流动资本的比例一定的条件下，预付资本的总周转速度与固定资本和流动资本本身的周转速度成正比变化。"},{"id":"mk15044-pl-P1526526","type":"sa","tier":"创新","conf":"adapt","chap":"第4-5章","q":"简述社会总产品的构成。","opts":[],"ans":null,"explain":"社会总产品的构成包括两个方面：一方面，社会总产品从实物形态上按其最终用途可分为生产资料和消费资料。与此相适应，整个社会生产也可以分为两大部类：第一部类是制造生产资料的部类(用I表示)；第二部类是制造消费资料的部类(用Ⅱ表示)。另一方面，社会总产品从价值形态上分为不变资本价值(c)、可变资本价值(v)、剩余价值(m)三部分。"},{"id":"mk15044-pl-P1526527","type":"sa","tier":"创新","conf":"adapt","chap":"第4-5章","q":"简述商业利润的形成与来源。","opts":[],"ans":null,"explain":"(1)商业利润是产业资本家让渡给商业资本家的一部分剩余价值，它的来源是产业部门的工人创造的剩余价值。<br/>(2)产业资本家之所以要把一部分剩余价值让渡给商业资本家，是因为商业资本家为产业资本家提供的服务，使产业资本家获得更多的剩余价值，因而产业资本家就必须，而且也愿意把剥削来的剩余价值的一部分转让给商业资本家，这比他自己兼营商业更为有利。"},{"id":"mk15044-pl-P1526528","type":"sa","tier":"创新","conf":"adapt","chap":"第4-5章","q":"简述二战后垄断统治进一步加强的主要表现。","opts":[],"ans":null,"explain":"(1)企业兼并速度加快，混合兼并占主导地位。<br/>(2)企业规模扩大，垄断程度提高。<br/>(3)垄断组织的生产经营多样化，混合联合企业大量涌现。<br/>(4)垄断组织向国际化方向发展，跨国公司迅速增加。"},{"id":"mk15044-pl-P1526529","type":"sa","tier":"创新","conf":"adapt","chap":"第4-5章","q":"简述垄断利润的来源。","opts":[],"ans":null,"explain":"具体说来垄断利润的来源大体有以下几个方面：<br/>(1)来自对本国无产阶级和其他劳动人民的剥削；<br/>(2)由于垄断资本可以通过垄断高价和垄断低价来控制市场，使得它能获得一些其他企业，特别是非垄断企业的利润；<br/>(3)通过加强对其他国家劳动人民的剥削和掠夺，获取海外利润；<br/>(4)通过资本主义国家政权进行有利于垄断资本的再分配，从而将劳动人民创造的国民收入的一部分变成垄断资本的收入。"},{"id":"mk15044-pl-P1526530","type":"sa","tier":"创新","conf":"adapt","chap":"第4-5章","q":"简述国家垄断资本主义的基本形式。","opts":[],"ans":null,"explain":"(1)国家直接掌握的垄断资本，也就是资本主义国家中的国有经济、国有企业。<br/>(2)国家和私人资本在企业内部的结合，也即资本主义国家中的国有资本与私人资本结合在一个企业中的经济形式。<br/>(3)国家和私人资本在企业外部的结合，也就是国家垄断资本主义在资本主义私人企业的外部起作用。"},{"id":"mk15044-pl-P1526531","type":"sa","tier":"创新","conf":"adapt","chap":"第4-5章","q":"简述资本主义国家宏观经济管理与调节的任务和目标。","opts":[],"ans":null,"explain":"资本主义国家宏观经济管理与调节的总任务，是促进市场总供给和总需求的平衡。资本主义国家宏观经济管理与调节的主要目标，包括保持经济的稳定和一定程度的增长，保持币值和物价的稳定，实现充分就业，保持国际国内收支的大体平衡等。"},{"id":"mk15044-pl-P1526532","type":"sa","tier":"创新","conf":"adapt","chap":"第4-5章","q":"简述当代资本主义新变化的原因。","opts":[],"ans":null,"explain":"(1)生产力方面。当代资本主义经济之所以能在一定程度上快速发展，有生产力自身发展规律，特别是科学技术自身发展规律作用的原因。<br/>(2)生产关系方面。在所有制关系上，资本主义国家在其自身范围内进行不断的调整，以适应生产力发展的要求。这种资本主义内部的自我调节，表现在对生产关系的调整和经济运行的调控上，主要有三个方面：<br/>①进行了社会改良。<br/>②对经济实行政府干预和宏观调控。<br/>③加强了对科技创新和新兴产业的扶持。<br/>(3)上层建筑方面。马克思主义认为，建立在生产关系总和即社会的经济基础之上的政治法律制度和意识形态等上层建筑，必须适应经济基础的要求。"},{"id":"mk15044-pl-P1527947","type":"sa","tier":"创新","conf":"adapt","chap":"第4-5章","q":"简述剩余价值生产的两种基本方法。","opts":[],"ans":null,"explain":"（1）绝对剩余价值生产：指在雇佣工人的必要劳动时间不变的条件下，通过绝对地延长工人的工作日长度来生产剩余价值的方法；<br/>（2）相对剩余价值的生产：指工人的工作日长度不变的条件下，通过改变工作中必要劳动时间和剩余劳动时间的比例，从而延长剩余劳动时间来生产剩余价值的方法。"},{"id":"mk15044-pl-P1527948","type":"sa","tier":"创新","conf":"adapt","chap":"第4-5章","q":"如何理解剩余价值规律是资本主义的基本经济规律？","opts":[],"ans":null,"explain":"（1）剩余价值规律的内容，就是通过资本对雇佣劳动的支配，不断提高对雇佣劳动的剥削程度来达到获取剩余价值的目的。<br/>（2）剩余价值规律体现着资本主义的生产目的；剩余价值规律决定着资本主义生产的一切主要方面和主要过程，支配着资本主义的生产、分配、交换和消费的各个环节；剩余价值规律决定着资本主义生产方式的产生、发展和衰亡的全过程。"},{"id":"mk15044-pl-P1527949","type":"sa","tier":"创新","conf":"adapt","chap":"第4-5章","q":"试述资本积累的客观必然性、实质及其后果。","opts":[],"ans":null,"explain":"（1）资本积累的客观必然性：对剩余价值的无限追求、竞争--资本积累的外在压力；<br/>（2）资本积累的实质：资本家无偿占有工人创造的剩余价值，进行资本积累来增大资本的规模；资本规模的扩大，是资本家能够继续占有更多的剩余价值，从而扩大对工人的剥削和统治；<br/>（3）资本积累的后果：资本有机构成的提高、相对过剩人口的形成、严重的贫富两极分化。"},{"id":"mk15044-pl-P1527950","type":"sa","tier":"创新","conf":"adapt","chap":"第4-5章","q":"简述不变资本和可变资本的划分及其意义。","opts":[],"ans":null,"explain":"（1）根据资本在剩余价值生产中所起的作用不同，把资本区分为不变资本和可变资本。<br/>①以生产资料形式存在的这部分资本，在生产过程中不会发生价值量的变化，所以叫做不变资本（c）。<br/>②以劳动力形式存在的资本不仅再生产出劳动力的价值，并且生产出剩余价值，在生产过程中发生了量的变化，实现了价值增殖，所以叫做可变资本（v）。<br/>（2）不变资本和可变资本的区分，是马克思的重要理论贡献，它的意义在于：<br/>①进一步揭露了剩余价值的源泉和资本主义的剥削实质，说明剩余价值不是由全部资本产生的，而是由可变资本产生的，工人的剩余劳动是剩余价值的唯一源泉；<br/>②为揭示资本家对工人的剥削程度提供了科学根据，正确地表明资本主义剥削程度的是剩余价值率。"},{"id":"mk15044-pl-P1527951","type":"sa","tier":"创新","conf":"adapt","chap":"第4-5章","q":"为什么说资本主义生产过程是劳动过程与价值增殖过程的统一?","opts":[],"ans":null,"explain":"<p>（1）劳动过程是人们通过有目的的活动，运用劳动资料对劳动对象进行加工，创造具有特定使用价值的产品的过程。这个过程是一切社会所共有的。资本主义劳动过程是资本家的各种生产要素相结合的过程，因而劳动成果也就归资本家所有。</p><p>（2）资本家会迫使工人的劳动时间超过创造其自身价值所需的时间，从而为其创造出剩余价值，资本主义生产过程也因此转化为价值增殖过程。</p>"},{"id":"mk15044-pl-P1527952","type":"sa","tier":"创新","conf":"adapt","chap":"第4-5章","q":"试述劳动力商品的价值和使用价值。","opts":[],"ans":null,"explain":"劳动力作为商品同样具有价值和使用价值。但是，劳动力是特殊商品，它的价值和使用价值也具有不同于普通商品的特点：<br/>（1）劳动力商品的价值也和其他商品的价值一样，是由生产和再生产劳动力商品的社会必要劳动时间决定的。劳动力商品的价值包括以下三部分生活资料的价值：<br/>一是维持劳动者自身生存所必需的生活资料的价值，用以再生产他的劳动力。<br/>二是劳动者繁育后代所必需的生活资料的价值，用以延续劳动力的供给。<br/>三是劳动者接受教育和训练所支出的费用，用以培训适合资本主义再生产所需要的劳动力。<br/>劳动力的价值决定还有一个重要的特点，就是它包括历史和道德的因素。<br/>（2）劳动力商品的使用价值也具有重要的特点。劳动力商品的使用价值的特殊性在于它不仅能创造出价值，而且能够创造出比劳动力自身的价值更大的价值，从而能为它的购买者带来剩余价值，这对于剩余价值的生产具有决定性的意义。因此，劳动力成为商品是货币转化为资本的前提。"},{"id":"mk15044-pl-P1527953","type":"sa","tier":"创新","conf":"adapt","chap":"第4-5章","q":"试述资本主义商业资本的本质、职能与作用。","opts":[],"ans":null,"explain":"（1）资本主义商业资本的本质是产业资本的商品资本职能中分离出来的独立化的职能资本形式。<br/>（2）职能：商业资本在流通领域中发生作用的资本，它所执行的职能就是商品资本的职能，即销售商品，实现价值和剩余价值。<br/>（3）作用：第一，商业资本的存在有利于产业资本家提高经济效益。第二，商业资本的存在有利于节省流通资本。第三，商业资本的活动，可以加速产业资本的周转。第四，商业资本的活动可以缩短流通时间。商业资本的存在，有利于资本主义经济的发展。但商业资本要能够起到有利作用的是有条件的，关键在于，在社会总资本中，商业资本所占的比例不超过社会必要的限度。商业资本的数量如果超过了社会必要的比例限度，那不仅是一种浪费，还会降低平均利润率。"},{"id":"mk15044-pl-P1527954","type":"sa","tier":"创新","conf":"adapt","chap":"第4-5章","q":"资本主义经济危机的实质和根源是什么？","opts":[],"ans":null,"explain":"（1）资本主义经济危机实质上是生产相对过剩的危机。这种过剩不是与劳动者实际需要相比的生产绝对过剩，而是与劳动者有支付能力的需求即货币购买力相比的相对过剩；<br/>（2）经济危机产生的根源在于资本主义生产方式的基本矛盾，即生产的社会化与生产资料资本主义私人占有形式之间的矛盾。当该矛盾达到十分尖锐的程度，就会引起经济危机的爆发；<br/>（3）资本主义基本矛盾有两种主要表现形式：一种是个别企业内部生产的有组织性和整个社会生产无政府状态之间的矛盾；另一种是资本主义生产无限扩大的趋势和劳动人民有支付能力的需求相对缩小之间的矛盾。"},{"id":"mk15044-pl-P1527955","type":"sa","tier":"创新","conf":"adapt","chap":"第4-5章","q":"试述影响资本周转速度的因素。","opts":[],"ans":null,"explain":"（1）影响资本周转速度的快慢有两个因素：一是资本周转时间的长短，包括生产时间和流通时间的长短；二是生产资本的构成，依据其价值周转方式的不同，生产资本划分固定资本和流动资本。<br/>（2）资本周转速度的快慢，受生产时间和流通时间的重要影响。生产时间和流通时间越短，资本周转速度就越快；反之，生产时间和流通时间越长，资本周转速度就越慢。<br/>（3）生产资本的构成是生产过程中影响资本周转速度的重要因素。生产资本的构成对预付资本周转速度的影响来自两个方面：一是资本中固定资本和流动资本的比例；二是固定资本和流动资本本身的周转速度。"},{"id":"mk15044-pl-P1527956","type":"sa","tier":"创新","conf":"adapt","chap":"第4-5章","q":"试述资本周转速度对剩余价值的影响。","opts":[],"ans":null,"explain":"（1）资本周转速度对年剩余价值量的影响。产业资本周转速度的快慢，影响到一定数量的预付资本在一定时期内（一般以年为单位）所能带来的剩余价值量的多少。在全部预付资本中，只有其中的可变资本是剩余价值的源泉。在一年之内，可变资本周转的速度越快，带来的年剩余价值总量就越多；反之，带来的年剩余价值总量就越少。<br/>（2）资本周转速度对年剩余价值率的影响。资本周转速度的快慢，影响到一定数量的预付资本的年剩余价值率的高低。年剩余价值率是一年内生产的剩余价值总量同一年内预付可变资本数量的比率，它表示预付可变资本在一年中的增值程度。预付产业资本的周转速度越快，实际发挥作用的可变资本就越多，带来的年剩余价值总量也就越多，从而年剩余价值率也就越高；反之，年剩余价值率就越低。"},{"id":"mk15044-pl-P1527957","type":"sa","tier":"创新","conf":"adapt","chap":"第4-5章","q":"简述资本主义意识形态的核心及其主要特征。","opts":[],"ans":null,"explain":"（1）资本主义意识形态是资本主义社会条件下的观念上层建筑。是为资本主义社会形态的经济基础服务的。<br/>（2）资本主义意识形态是资产阶级的阶级意识的集中体现，资本主义意识形态包括资产阶级的政治法律思想，哲学思想，经济思想，教育思想，文学艺术思想等各种理论思想形式，涵盖人生观，价值观，宗教观等各种思想观念。它们相互联系，渗透到资本主义社会生活的各个方面，资本主义意识形态本质上是维护资本主义剥削制度的思想体系。当资产阶级掌握了政权，资本主义制度确立以后，特别是无产阶级作为独立的政治力量登上历史舞台以后，随着无产阶级同资产阶级之间斗争的展开，资本主义变成公开为资本主义剥削制度辩护。充分暴露出资本主义意识形态的阶级本质和阶级局限性。"},{"id":"mk15044-pl-P1527958","type":"sa","tier":"创新","conf":"adapt","chap":"第4-5章","q":"试述价值规律的内容及其对社会经济发展的作用。","opts":[],"ans":null,"explain":"（1）价值规律的基本内容：商品的价值由生产该商品的社会必要劳动时间所决定，商品交换以价值为基础，实行等价交换。<br/>（2）价值规律对社会经济的发展有以下几方面作用：价值规律自发地调节生产资料和劳动力在社会生产各部门之间分配的比例，即调节社会资源的配置；价值规律自发地促进社会生产力的发展；价值规律会引起和促进商品生产者的分化。"},{"id":"mk15044-pl-P1527959","type":"sa","tier":"创新","conf":"adapt","chap":"第4-5章","q":"货币的本质及职能。","opts":[],"ans":null,"explain":"（1）货币：固定地充当一般等价物的商品。货币的产生和起源是商品交换长期发展的产物。<br/>（2）价值尺度职能，即衡量和计算一切商品价值量大小的社会尺度；<br/>流通手段职能，即货币起着商品交换媒介的作用；<br/>贮藏手段职能，即货币退出流通领域，作为社会财富的一般代表被保存起来；支付手段职能，即商品在赊购赊销过程中，当到期偿还贷款时货币所执行的还款职能；<br/>世界货币职能，即货币超越出一国的范围，在世界市场上发挥一般等价物的作用。"},{"id":"mk15044-pl-P1527960","type":"sa","tier":"创新","conf":"adapt","chap":"第4-5章","q":"简述商品经济产生和存在的条件。","opts":[],"ans":null,"explain":"商品经济是在一定历史条件下才产生、发展和存在的。<br/>（1）第一个条件，是社会分工的产生和存在。社会分工是指社会生产划分为不同行业和不同部门的分工，随着社会分工的产生和逐渐发展，形成了专门生产各种不同产品的生产者或经济单位，他们相互联系和依赖，彼此都需要对方的产品以满足自身的生产和生活需要，因而有必要相互交换自己所生产的产品。所以，社会分工是商品经济产生和存在的一般条件和基础。<br/>（2）第二个条件，是生产资料和劳动产品属于不同的所有者。不同的所有者都有自身的经济利益，他们相互之间在交换各自的产品时，在市场上处于权利平等的地位。为了维护自身的经济利益，要求遵循对等的原则，即按照商品价值的大小进行等价交换，这样，他们的生产和交换便会采取商品生产和商品交换的形式，从而导致商品经济的产生。"},{"id":"mk15044-pl-P1527961","type":"sa","tier":"创新","conf":"adapt","chap":"第4-5章","q":"如何理解生产商品的劳动二重性？","opts":[],"ans":null,"explain":"商品是通过人的劳动所生产出来的，因而商品的使用价值和价值二因素也是由生产商品的劳动的二重性所决定的。这种劳动的二重性就是具体劳动和抽象劳动。具体劳动和抽象劳动是商品生产者的同一劳动过程的不可分割的两个方面，它们在时间上和空间上是统一的，并不是各自独立存在的两种劳动或两次劳动。商品生产者在从事具体劳动的同时，也就支出了抽象劳动。具体劳动是生产商品劳动的自然属性，抽象劳动是生产商品劳动的社会属性。具体劳动反映人与自然的关系，抽象劳动反映社会生产关系。"},{"id":"mk15044-pl-P1527962","type":"sa","tier":"创新","conf":"adapt","chap":"第4-5章","q":"经济全球化是如何发展起来的？","opts":[],"ans":null,"explain":"从商业资本、借贷资本到产业资本的国际化，表明资本国际化的发展促使国际经济关系逐步向深度和广度扩展，导致经济全球化的到来。"},{"id":"mk15044-pl-P1527963","type":"sa","tier":"创新","conf":"adapt","chap":"第4-5章","q":"试述经济全球化的含义、原因和主要内容。","opts":[],"ans":null,"explain":"（1）经济全球化（Economic Globalization）是指世界经济活动超越国界、通过对外贸易、资本流动、技术转移、提供服务、相互依存、相互联系而形成的全球范围的有机经济整体的过程。是商品、技术、信息、服务、货币、人员等生产要素跨国跨地区的流动（简单的说也就是世界经济日益成为紧密联系的一个整体）。经济全球化是当代世界经济的重要特征之一，也是世界经济发展的重要趋势。<br/>（2）经济全球化的原因：①新科学技术，特别是计算机、通信技术日新月异的进步和在社会经济生活中广泛应用，加强了国际经济联系；②国际贸易的自由程度大提高；国际资本流动的大幅增加。<br/>（3）经济全球化的主要内容：生产全球化、贸易全球化、资本全球化。"},{"id":"mk15044-pl-P1527964","type":"sa","tier":"创新","conf":"adapt","chap":"第4-5章","q":"简述发达市场经济国家调控货币量的主要方法。","opts":[],"ans":null,"explain":"发达市场经济国家调控货币量的手段主要有：<br/>一是公开市场业务，即由中央银行在货币资本市场上公开出售或收购有价证券，以调节流通中的货币量。<br/>二是最低准备金率政策，即通过调整商业银行在中央银行的准备金率，来调节流通中的货币量<br/>。三是再贴现率政策，即通过调整商业银行到中央银行再贴现票据的利率，来调节流通中的货币量。"},{"id":"mk15044-pl-P1527965","type":"sa","tier":"创新","conf":"adapt","chap":"第4-5章","q":"简述第二次世界大战后国家垄断资本主义大发展的原因。","opts":[],"ans":null,"explain":"（1）仅靠私人垄断资本的力量，无法满足大规模经济建设所需要的巨额资金；<br/>（2）在一些大规模公共设施的建设上，私人垄断资本无能为力或不愿进行投资建设；<br/>（3）一些大型、基础性、前导性的科学研究项目，也是私人垄断资本不愿意涉足的领域；<br/>（4）日益严重的生产过剩问题仅靠私人垄断资本难以解决；<br/>（5）社会化大生产的发展要求国家出面进行某些宏观经济调控；<br/>（6）在经济利益关系的调整方面，国家的再分配功能也越来越重要。"},{"id":"mk15044-pl-P1527966","type":"sa","tier":"创新","conf":"adapt","chap":"第4-5章","q":"简述国家垄断资本主义的主要形式。","opts":[],"ans":null,"explain":"国家垄断资本主义即资本主义国家与垄断资本相结合的资本主义，这种结合多种形式，但其根本形式可归纳为三种类型：<br/>（1）国家直接掌握的垄断资本，即资本主义国家中的国有经济；<br/>（2）国家和私人资本在企业内部的结合；<br/>（3）国家和私人资本在企业外部相结合。"},{"id":"mk15044-pl-P1527967","type":"sa","tier":"创新","conf":"adapt","chap":"第4-5章","q":"试述当代资本主义新变化的原因及实质。","opts":[],"ans":null,"explain":"（1）生产力方面。当代资本主义经济之所以能在一定程度上快速发展，有生产力自身发展规律，特别是科学技术自身发展规律作用的原因。社会生产力总是处于不断发展变化中，在它与生产关系的相互作用中发展的同时，生产力还有着它自身不断加速发展的规律。<br/>（2）生产关系方面。在所有制关系上，资本主义国家在其自身范围内进行不断的调整，以适应生产力发展的要求。无论是资本社会化还是股权分散化都是在资本主义私有制基础上的一种局部调整，以适应资本主义自身创造出的巨大的社会化生产力的要求。<br/>（3）上层建筑方面。当代资本主义国家中上层建筑的新变化归根结底是经济基础发展变化所要求的。生产社会化、国际化和经济全球化的发展，资本社会化、股权分散化的现实，必然要求资本主义政治制度与国家法制在有利于资产阶级的范围内健全、充实与完善，从而为资本主义制度的存在和发展服务。<br/>（4）实质：当代资本主义虽然发生了许多新变化，但它的经济基础仍然是资本主义的私人占有制。在资本主义社会，控股权还是掌握在少数资本家手中。"},{"id":"mk15044-pl-P1527968","type":"sa","tier":"创新","conf":"adapt","chap":"第4-5章","q":"试述垄断资本主义国家的资本输出及其作用和后果。","opts":[],"ans":null,"explain":"垄断资本主义经济侵略的重要一手就是资本输出，即把他们手中掌握和控制的大量资本输往国外，利用这些资本作武器，控制资本输入国的经济命脉，剥削、压迫这些的国家劳动人民，掠夺这些国家的自然资源和物质财富，最终为金融资本控制这些国家、形成金融资本的国际统治服务。<br/>从资本输出国即垄断资本主义国家这方面看，资本输出的作用和后果是：（1）为过剩资本找到了出路，并由此获得大量来自海外的高额利润和利息；<br/>（2）资本输出是输出国控制输入国的重要手段；<br/>（3）资本输出是输出国扩大商品出口的重要手段；<br/>（4）资本输出使金融资本的银行网遍布全世界，从而强化了金融资本在世界经济、政治舞台上的统治地位。<br/>对于那些处于较低发展阶段上的、经济比较落后的资本输入国来说，大量国外资本的输入，有两重作用：<br/>（1）一方面，外来资本和生产方式的进入，促进了这些国家自然经济的瓦解、商品经济和资本主义经济关系的生长和发展，建设了一些近现代的工商企业和发展经济所必需的基础设施，也在一定程度上促进了这些国家民族经济的发展和整个国民经济水平的提高。<br/>（2）但另一方面，国外资本主义势力的侵入，也给这些国家带来一系列经济社会问题。垄断资本主义国家的资本输出并不是平等互利的，他们通过不平等的贷款条件、不等价交换等方式掠夺、剥削输入国人民，攫取了输入国巨额的国民财富，又使这些国家长期得不到顺利发展，继续处于贫穷落后的境地。"},{"id":"mk15044-pl-P1527969","type":"sa","tier":"创新","conf":"adapt","chap":"第4-5章","q":"简述私人垄断资本主义的基本经济特征。","opts":[],"ans":null,"explain":"私人垄断资本主义的基本经济特征表现为：<br/>（1）垄断在经济生活中占统治地位；<br/>（2）金融资本和金融寡头的统治；<br/>（3）资本输出在经济生活中占重要地位；<br/>（4）国际垄断同盟在经济上瓜分世界；<br/>（5）垄断资本主义列强瓜分和重新瓜分世界。"},{"id":"mk15044-pl-P1527970","type":"sa","tier":"创新","conf":"adapt","chap":"第4-5章","q":"垄断资本主义的基本经济特征有哪些？其当代发展的新特点，新形式是什么？","opts":[],"ans":null,"explain":"（1）垄断资本主义基本经济特征：<br/>①垄断在经济生活中占统治地位；<br/>②金融资本和金融寡头的统治；<br/>③资本输出在经济生活中占重要地位<br/>；④国际垄断同盟在经济上瓜分世界；<br/>⑤垄断资本主义列强瓜分和重新瓜分世界。<br/>（2）二战后，私人垄断资本主义进一步发展为国家垄断资本主义，即垄断资本与国家政权相结合的资本主义。国家垄断资本主义取代私人垄断成为主要资本主义国家当代资本主义发展的新形式、新特征。<br/>具体表现在：①在生产力方面，劳动生产率大幅度提高，社会财富迅猛增长，经济保持了较长时期的相对稳定发展。<br/>②当代资本主义国家在所有制关系、劳动关系和分配关系方面都做了一系列调整。<br/>③资本主义发展到国家垄断资本主义阶段，已经建立起比较成熟的政治制度和法制制度。"},{"id":"mk15044-pl-P1526494","type":"sa","tier":"创新","conf":"adapt","chap":"第4-5章","q":"论述资产阶级的人生观、价值观和道德观。","opts":[],"ans":null,"explain":"1.人生观<br/>(1)资产阶级作为资本主义私有制的代表者，其人生观必然是从维护其一己私利出发，主张个人至上。<br/>(2)资产阶级主张利己主义的人生观，其论据是人的“自然本性”就是从感性出发而趋乐避苦，总是出于生理本能的需要而追求于己有利的事物，从而得出人的本性是极端利己的结论。<br/>(3)资产阶级的利己主义人生观，宣扬人生的目的就是谋求个人利益，追求个人的幸福和享乐。为此就要采取各种手段获取实现其个人利益和享乐的金钱，因而赚钱成为实现其人生利益的最好手段。<br/>2.价值观<br/>(1)资产阶级抹煞价值观的阶级性，宣扬价值观的主观性，认为价值观是从个人的主观意志和心理感受出发来加以判断，是由人的兴趣、爱好、欲望、目的等主观因素所决定的，大肆宣扬什么“普世价值观”，这是以一种超阶级的价值观来掩盖价值观的阶级性。<br/>(2)资产阶级价值观的重要特征是以金钱作为价值判断的重要标准，以获取金钱作为人及其实践活动的价值的体现，把是否能获取金钱和获取金钱的多少看做有无价值和价值大小的真实尺度。<br/>3.道德观<br/>(1)当代资本主义社会中，伦理道德观念出现十分混乱的现象，享乐主义、颓废主义、孤立主义、消费主义等形形色色的腐朽道德观泛滥。<br/>(2)应当明确，在资本主义社会中，占统治地位的道德观是资产阶级道德观。在资本主义社会生活中，也保留和存在着一些好的社会风尚，不能与资产阶级道德观混为一谈。"},{"id":"mk15044-pl-P1526495","type":"sa","tier":"创新","conf":"adapt","chap":"第4-5章","q":"试述资本主义再生产周期的阶段及各阶段的特点。","opts":[],"ans":null,"explain":"经济危机的周期爆发，使资本主义再生产也具有了周期性。从一次危机的开始到下一次危机的开始，其间所经历的时间便是一个再生产的周期。资本主义再生产周期一般来说包括危机、萧条、复苏、高涨四个阶段。<br/>(1)危机阶段是再生产周期的决定性阶段。这个阶段的特点是，商品销售困难甚至被销毁，企业开工不足甚至倒闭，生产下降，工人大批失业，货币信用制度被破坏，整个社会经济生活陷于瘫痪和混乱，生产力遭到严重破坏。<br/>(2)萧条阶段的特点是，生产不再下降，企业停止倒闭，失业人数不再增加，但商品销售仍很困难，信贷关系呆滞。<br/>(3)复苏阶段的特点是，市场销售扩大，生产逐渐回升，企业利润增加，就业日益增多，信贷关系逐渐活跃，当社会生产赶上和超过危机前的最高点时，便过渡到高涨阶段。<br/>(4)高涨阶段的特点是，市场繁荣，生产上升，企业规模扩大，增加新建企业，就业人数明显增加，社会购买力提高，信贷关系兴旺。整个社会经济呈现一片繁荣景象。"},{"id":"mk15044-pl-P1526496","type":"sa","tier":"创新","conf":"adapt","chap":"第4-5章","q":"如何认识资本主义意识形态的历史进步性和阶级局限性？","opts":[],"ans":null,"explain":"(1)资本主义意识形态在反对封建专制的斗争中，以及在资本主义生产方式产生与发展的上升时期，反映了社会进步的要求。早期的资产阶级启蒙学者和思想家，在政治、哲学、法律、经济、文化、艺术、教育、道德等方面，提出了许多富于进取精神的先进思想、理论和观念，继承和发扬了人类优秀的思想文化成果，是人类思想的一次大解放，具有历史进步意义。<br/>(2)资本主义意识形态毕竟是建立在资本主义经济基础之上，是为资本主义私有制和雇佣劳动制度服务的，因而资本主义意识形态本质上是维护资本主义剥削制度的思想体系。随着无产阶级同资产阶级之间斗争的展开，资本主义意识形态在整体上逐渐丧失其历史进步性，日益演变成公开为资本主义剥削制度辩护、竭力反对马克思主义，反对社会主义的理论思想体系。"},{"id":"mk15044-pl-P1526497","type":"sa","tier":"创新","conf":"adapt","chap":"第4-5章","q":"什么是金融资本和金融寡头？金融寡头怎样实现其在经济和政治上的统治？","opts":[],"ans":null,"explain":"(1)金融资本是由垄断的工业资本和银行资本，通过金融联系、资本参与和人事参与，融合或混合生长构成的一种新的资本形式，是垄断资本主义国家中社会经济生活各个方面实际上的统治者。<br/>(2)掌握了金融资本，操纵国民经济命脉，并在实际上控制国家政权的少数垄断资本家或垄断资本家集团称为金融寡头。<br/>(3)金融寡头在经济上的统治主要是通过实行参与制实现的，参与制是通过控制一定数量的股票从而层层控制许多企业的经济上的统治方式。金融寡头在政治上的统治主要是通过个人联合的方式实现的。金融寡头还可以通过建立政策研究咨询机构等方式来对政府的政策施加影响，通过掌握舆论工具、新闻媒介来对社会生活施加影响，从而实现其对社会经济生活的统治。"},{"id":"mk15044-pl-P1526498","type":"sa","tier":"创新","conf":"adapt","chap":"第4-5章","q":"试述经济全球化对发展中国家的影响。","opts":[],"ans":null,"explain":"经济全球化对广大发展中国家有一定积极影响：它们可以在经济全球化的进程中引进国外的先进技术、资金和管理经验，调整与优化国民经济结构，增强自身的经济实力，缩短与发达国家的差距，增加国内的就业，促进国内的消费，加强同世界各国的联系与交流。但是，经济全球化是一个充满矛盾的进程，是一把双刃剑，既有积极的一面，也有消极的影响，这方面的表现是：(1)发达国家与发展中国家的差距在扩大。虽然发达国家与发展中国家都在经济全球化过程中有所受益，但由于经济全球化的规则是发达国家主导制定的、进程是发达国家主导的，发展中国家受益少，甚至有被边缘化的风险。一些发展中国家发展资金匮乏、债务负担沉重、贸易条件恶化、金融风险增加、技术水平落后，处于十分不利的境地。发达国家在经济全球化的进程中，也出现了产业空心化、实体经济萎缩、失业增加、金融风险加大、过分依赖国外资源等诸多问题。(2)在经济增长中忽视社会进步，环境恶化与经济全球化有可能同时发生。(3)各国特别是相对落后国家原有的体制、政府领导能力、社会设施、政策体系、价值观念和文化等都面临着全球化的冲击，国家内部和国际社会都出现不同程度的治理危机。(4)经济全球化使各国之间的经济联系。越来越紧密，相互依赖越来越强，而有效的全球性协调机制却没有建立起来，这就使得爆发全球性经济危机的风险不断增大。"},{"id":"mk15044-pl-P1526499","type":"sa","tier":"创新","conf":"adapt","chap":"第4-5章","q":"试述20世纪80年代以来，经济全球化进程明显加快的原因。","opts":[],"ans":null,"explain":"(1)新科学技术，特别是计算机、通信技术日新月异的进步和在社会经济生活中的广泛应用，加强了国际经济联系。<br/>(2)国际贸易的自由程度大大提高。当今世界无论是发达国家还是发展中国家都有发展国际经济关系的迫切要求，因而加快了经济全球化的步伐。<br/>(3)国际资本流动的大幅增加。吸引外资发展本国经济，不但是发展中国家的迫切要求，也是发达国家过剩资本的一个出路，而且发达国家间的相互投资也在增加。"},{"id":"mk15044-pl-P1526433","type":"sc","tier":"基础","conf":"adapt","chap":"第6-7章","q":"早期空想社会主义的代表作有（）。","opts":["A. 康帕内拉的《太阳城》","B. 傅立叶的《新世界》","C. 摩莱里的《巴齐里阿达》","D. 欧文的《新社会观》"],"ans":0,"explain":"早期空想社会主义的代表作是英国人莫尔的《乌托邦》和意大利人康帕内拉的《太阳城》。"},{"id":"mk15044-pl-P1526434","type":"sc","tier":"基础","conf":"adapt","chap":"第6-7章","q":"1978年（）重新确立了思想、实事求是的思想路线，开创了社会主义建设的新时期。","opts":["A. 党的十一届三中全会","B. 党的十八大","C. 邓小平南方讲话","D. 党的十九大"],"ans":0,"explain":"1978年党的十一届三中全会重新确立了解放思想、实事求是的思想路线，彻底否定了“以阶级斗争为纲”的错误理论和实践，以巨大的政治勇气和理论勇气，做出了进行改革开放的重大决策，开创了社会主义建设的新时期。"},{"id":"mk15044-pl-P1526435","type":"sc","tier":"基础","conf":"adapt","chap":"第6-7章","q":"无产阶级社会主义革命的发生，归根结底是由（）所决定的。","opts":["A. 工人阶级","B. 政治思想文化","C. 资本主义内在矛盾","D. 生产力发展水平"],"ans":3,"explain":"无产阶级社会主义革命的发生，归根结底是由生产力发展水平所决定的。"},{"id":"mk15044-pl-P1526436","type":"sc","tier":"基础","conf":"adapt","chap":"第6-7章","q":"（）是建立无产阶级专政的政权的第一次尝试。","opts":["A. 俄国十月革命","B. 巴黎公社","C. 东欧巨变","D. 苏联解体"],"ans":1,"explain":"1871年的巴黎公社的实践，它是在一个国家一个城市爆发的无产阶级革命，是建立无产阶级专政的政权的第一次尝试。"},{"id":"mk15044-pl-P1526437","type":"sc","tier":"基础","conf":"adapt","chap":"第6-7章","q":"无产阶级政党实行（）的组织原则。","opts":["A. 中央集权制","B. 地方分权制","C. 民主集中制","D. 三权分立制"],"ans":2,"explain":"无产阶级政党实行民主集中制的组织原则，依靠统一的纲领和严格的纪律形成强大的组织力量。"},{"id":"mk15044-pl-P1526438","type":"sc","tier":"基础","conf":"adapt","chap":"第6-7章","q":"社会主义阶段个人消费品的分配原则是（）。","opts":["A. 各尽所能，按需分配","B. 各尽所能，按才能分配","C. 各尽所能，按劳分配","D. 各尽所能，按地位分配"],"ans":2,"explain":"个人消费品的分配应当实行按劳分配原则。这种分配方式尽管存在历史局限性，但在社会主义阶段是无法避免的。"},{"id":"mk15044-pl-P1526439","type":"sc","tier":"基础","conf":"adapt","chap":"第6-7章","q":"无产阶级革命的目的是（）。","opts":["A. 建立无产阶级专政的国家","B. 推翻资本主义","C. 发展共产主义","D. 发展社会主义"],"ans":0,"explain":"无产阶级革命是无产阶级进行斗争的最高形式，以建立无产阶级专政的国家为目的。暴力革命是无产阶级革命的一般形式。"},{"id":"mk15044-pl-P1526440","type":"sc","tier":"基础","conf":"adapt","chap":"第6-7章","q":"下列属于五位一体的内容是（）。","opts":["A. 建成小康社会","B. 从严治党","C. 深化改革","D. 生态文明建设"],"ans":3,"explain":"2012年党的十八大以来，以习近平同志为核心的党中央，以强烈的历史担当、高超的政治智慧和顽强的意志品格，团结带领全国人民统筹推进“五位一体”(指经济建设、政治建设、文化建设、社会建设、生态文明建设）总体布局，协调推进“四个全面”（指全面建成小康社会、全面深化改革、全面依法治国、全面从严治党）战略布局，推动当代中国取得了历史性成就，发生了历史性变革。"},{"id":"mk15044-pl-P1526441","type":"sc","tier":"基础","conf":"adapt","chap":"第6-7章","q":"19世纪初期欧洲空想社会主义的代表人物不包括（）。","opts":["A. 法国的圣西门","B. 法国的傅立叶","C. 英国的欧文","D. 德国的黑格尔"],"ans":3,"explain":"英法两国的空想社会主义指19世纪上半叶以圣西门、傅立叶、欧文为代表的三大空想社会主义者的学说。"},{"id":"mk15044-pl-P1526442","type":"sc","tier":"基础","conf":"adapt","chap":"第6-7章","q":"在前苏联推行所谓“社会主义苏联模式”的领导人是（）。","opts":["A. 列宁","B. 恩格斯","C. 马克思","D. 斯大林"],"ans":3,"explain":"列宁逝世后，苏联在斯大林的领导下，逐步建成了以生产资料公有制为基础的社会主义计划经济制度，形成了后来所称的社会主义的苏联模式。"},{"id":"mk15044-pl-P1526443","type":"sc","tier":"基础","conf":"adapt","chap":"第6-7章","q":"科学社会主义思想史上的第一个纲领性文件是（）。","opts":["A. 《德意志意识形态》","B. 《关于费尔巴哈的提纲》","C. 《共产党宣言》","D. 《哥达纲领批判》"],"ans":2,"explain":"马克思和恩格斯在1847年创建世界上第一个无产阶级政党“共产主义者同盟”的委托起草并于1848年2月发表的《共产党宣言》，是社会主义思想史上的第一个纲领性文件，它标志着科学社会主义理论公开面世。"},{"id":"mk15044-pl-P1526444","type":"sc","tier":"基础","conf":"adapt","chap":"第6-7章","q":"以下不属于空想社会主义观点的是（）。","opts":["A. 实行共同劳动，合理分配","B. 要有计划地组织生产","C. 实行按劳分配的社会主义分配原则","D. 消灭城乡、体脑差别"],"ans":2,"explain":"空想社会主义者提出社会主义要废除私有制和雇佣劳动，消灭阶级和阶级差别；实行共同劳动，合理分配；要有计划地组织生产；消灭城乡、体脑差别；把国家变成纯粹的管理机构，直至其最后消亡；提倡妇女解放和婚姻自由等。"},{"id":"mk15044-pl-P1526445","type":"sc","tier":"基础","conf":"adapt","chap":"第6-7章","q":"提出社会主义革命同时胜利论的是（）。","opts":["A. 马克思和恩格斯","B. 列宁","C. 斯大林","D. 毛泽东"],"ans":0,"explain":"马克思、恩格斯所讲的同时胜利论是指主要资本主义国家在革命时机成熟时，在一个时期内相继爆发无产阶级革命，形成一个相互支持和相互促进的革命高涨的局面。"},{"id":"mk15044-pl-P1526446","type":"sc","tier":"基础","conf":"adapt","chap":"第6-7章","q":"社会主义从一国向多国发展壮大起始于（）。","opts":["A. 第一次世界大战以后","B. 第二次世界大战以后","C. 中国社会主义革命以后","D. 古巴社会主义革命以后"],"ans":1,"explain":"从十月革命到卫国战争胜利，苏联在社会主义革命后短短的几十年时间里，把一个经济文化较为落后的资本主义旧俄国变成为世界上位居前列的经济政治军事强国，社会主义集中力量办大事的优越性得到充分体现，第二次世界大战以后社会主义事业从一国向多国发展壮大。"},{"id":"mk15044-pl-P1526447","type":"sc","tier":"基础","conf":"adapt","chap":"第6-7章","q":"二战后欧洲出现的社会主义国家不包括（）。","opts":["A. 波兰","B. 瑞士","C. 罗马尼亚","D. 保加利亚"],"ans":1,"explain":"在二次世界大战后的欧洲，出现了波兰、捷克斯洛伐克、罗马尼亚、保加利亚、匈牙利、民主德国、南斯拉夫和阿尔巴尼亚等一批社会主义国家，瑞士不在其中。"},{"id":"mk15044-pl-P1526448","type":"sc","tier":"基础","conf":"adapt","chap":"第6-7章","q":"下列属于19世纪初欧洲空想社会主义者的是（）。","opts":["A. 黑格尔","B. 圣西门","C. 费尔巴哈","D. 李嘉图"],"ans":1,"explain":"19世纪初期欧洲的三大空想社会主义者，有法国的圣西门、傅立叶和英国的欧文，他们在前人思想的基础上提出了自己的社会主义思想和方案，并进行了一些社会改造的尝试。"},{"id":"mk15044-pl-P1526449","type":"sc","tier":"基础","conf":"adapt","chap":"第6-7章","q":"政党的出现，政党政治的发展是（）。","opts":["A. 社会主义社会的产物","B. 无产阶级斗争的产物","C. 资产阶级斗争的产物","D. 资本主义社会的产物"],"ans":3,"explain":"政党的出现，政党政治的发展是资本主义社会的产物。"},{"id":"mk15044-pl-P1526450","type":"sc","tier":"基础","conf":"adapt","chap":"第6-7章","q":"马克思主义政党产生的条件是（）。","opts":["A. 马克思主义理论的诞生","B. 资产阶级运动的发展","C. 空想社会主义理论的传播","D. 工人运动的发展和科学社会主义理论的传播"],"ans":3,"explain":"马克思主义政党产生的条件包括：(1)工人运动的发展。(2)科学社会主义理论的传播。"},{"id":"mk15044-pl-P1526451","type":"sc","tier":"基础","conf":"adapt","chap":"第6-7章","q":"马克思主义政党是（）。","opts":["A. 马克思主义者的群众组织","B. 工人阶级的群众组织","C. 工人阶级的先锋队","D. 各个阶段先进分子组成的政党"],"ans":2,"explain":"工人阶级的先锋队是马克思主义政党性质最简要最明确的表述。"},{"id":"mk15044-pl-P1526452","type":"sc","tier":"基础","conf":"adapt","chap":"第6-7章","q":"马克思主义政党的最高纲领和奋斗目标是（）。","opts":["A. 解放生产力，发展生产力","B. 建设高度发达的社会主义精神文明","C. 建设富强、文明、民主的社会主义国家","D. 实现共产主义"],"ans":3,"explain":"马克思主义政党的最高纲领和最终奋斗目标，是实现共产主义。"},{"id":"mk15044-pl-P1526453","type":"sc","tier":"基础","conf":"adapt","chap":"第6-7章","q":"代表最先进的社会生产力，且是最先进、最革命的阶级是（）。","opts":["A. 农民阶级","B. 工人阶级","C. 资产阶级","D. 商人"],"ans":1,"explain":"在资本主义制度下，社会化大生产的发展，一方面形成了巨大的社会生产力，另一方面也使得工人阶级发展壮大起来。工人阶级代表最先进的社会生产力，是最先进、最革命的阶级。"},{"id":"mk15044-pl-P1526454","type":"sc","tier":"基础","conf":"adapt","chap":"第6-7章","q":"社会主义民主政治的首要内容是（）。","opts":["A. 坚持党的领导","B. 坚持人民民主专政","C. 坚持社会主义道路","D. 坚持马克思主义"],"ans":0,"explain":"社会主义民主政治的首要内容是坚持党的领导。"},{"id":"mk15044-pl-P1526455","type":"sc","tier":"基础","conf":"adapt","chap":"第6-7章","q":"马克思主义政党自身建设的根本任务和永恒课题是（）","opts":["A. 始终代表最广大人民的根本利益","B. 与时俱进","C. 保持和发展党的先进性","D. 党要管党、从严治党"],"ans":2,"explain":"加强和改善党的领导，必须加强马克思主义政党的先进性建设。先进性是马克思主义政党的本质属性，是马克思主义政党的生命所系，力量所在。保持和发展党的先进性是马克思主义政党自身建设的根本任务和永恒课题。"},{"id":"mk15044-pl-P1526456","type":"sc","tier":"基础","conf":"adapt","chap":"第6-7章","q":"马克思主义政党的根本宗旨是（）。","opts":["A. 为人民群众谋利益","B. 发展社会生产力","C. 实现共同富裕","D. 全人类的解放"],"ans":0,"explain":"马克思主义政党是一种为人民服务的新型政党，马克思主义政党的根本宗旨是为人民群众谋利益。"},{"id":"mk15044-pl-P1526458","type":"sc","tier":"基础","conf":"adapt","chap":"第6-7章","q":"一种新的社会制度具有巨大优越性的集中表现，在于（）。","opts":["A. 新社会制度能够得到人民群众的支持","B. 新社会制度能够创造出比以往社会更高的劳动生产率","C. 新社会制度能够鼓舞人们的信心和斗志","D. 新社会制度能够更好地调节生产关系"],"ans":1,"explain":"一种新的社会制度具有巨大优越性的集中表现在于新社会制度能够创造出比以往社会更高的劳动生产率。"},{"id":"mk15044-pl-P1526459","type":"sc","tier":"基础","conf":"adapt","chap":"第6-7章","q":"共产主义社会的物质基础是（）。","opts":["A. 比资本主义社会高的社会生产力","B. 与发达资本主义国家相同的社会生产力","C. 远远高于以往一切社会的高度发达的社会生产力","D. 高新技术发达的社会生产力"],"ans":2,"explain":"共产主义社会是人类社会发展的最高社会形态，它的物质基础，是远远高于以往一切社会的高度发达的社会生产力。"},{"id":"mk15044-pl-P1526460","type":"sc","tier":"基础","conf":"adapt","chap":"第6-7章","q":"下列各项不属于共产主义社会经济上的特征的是（）。","opts":["A. 生产力极大提高和物质财富极大丰富","B. 实行按劳分配","C. 生产资料的单一社会公有制","D. 对社会经济的计划管理与调节"],"ans":1,"explain":"共产主义社会的经济特征主要包括：社会生产力高度发展和物质财富极大丰富、实行社会公有制和按需分配、经济的计划调节管理和商品经济的消失、也实现了生产资料的单一化公有制等七个特征，B项错在按劳分配，共产主义是按需分配。"},{"id":"mk15044-pl-P1526461","type":"sc","tier":"基础","conf":"adapt","chap":"第6-7章","q":"“各尽所能，按需分配”是（）。","opts":["A. 原始社会的分配原则","B. 阶级社会的分配原则","C. 社会主义社会的分配原则","D. 共产主义社会的分配原则"],"ans":3,"explain":"“各尽所能、按需分配”不只是一个个人消费品分配方式，而且是和本质要求的原则标志。"},{"id":"mk15044-pl-P1526462","type":"sc","tier":"基础","conf":"adapt","chap":"第6-7章","q":"共产主义社会的生产资料所有制是（）。","opts":["A. 生产资料的单一社会公有制","B. 多种形式的生产资料公有制并存","C. 公有制和非公有制经济形式并存","D. 生产资料的个人和公共所有并存"],"ans":0,"explain":"在共产主义社会，由于实现生产资料的单一社会公有制既不存在公有制的多种形式，更不存在非公有制经济形式，社会各经济单位不具有由生产资料占有关系上的差别所引起的经济利益关系的差别。"},{"id":"mk15044-pl-P1526463","type":"sc","tier":"基础","conf":"adapt","chap":"第6-7章","q":"社会阶级的消灭是以（）为前提的。","opts":["A. 生产资料完全公有化","B. 社会化大生产","C. 民主政治高度发达","D. 生产高度发展的阶段"],"ans":3,"explain":"恩格斯指出：社会阶级的消灭是以生产高度发展的阶段为前提的。"},{"id":"mk15044-pl-P1526464","type":"sc","tier":"基础","conf":"adapt","chap":"第6-7章","q":"马克思主义认为，阶级消灭和国家消亡是在（）。","opts":["A. 社会主义革命中实现的","B. 社会主义初级阶段实现的","C. 社会主义高级阶段实现的","D. 共产主义社会实现的"],"ans":3,"explain":"马克思主义经典著作中所说的消灭阶级，首先是指消灭剥削和被剥削阶级的差别与对立，同时也包括工人和农民作为阶级的差别。实践证明，彻底消灭阶级，只能在共产主义社会实现。"},{"id":"mk15044-pl-P1526465","type":"sc","tier":"基础","conf":"adapt","chap":"第6-7章","q":"马克思强调指出，共产主义社会是（）为基本原则的社会形式。","opts":["A. 以社会精英的全面发展和自由发展","B. 以统治阶级的全面发展和自由发展","C. 以每个人的全面发展和自由发展","D. 以人民大众的全面发展和自由发展"],"ans":2,"explain":"马克思指出：共产主义社会是“以每个人的全面而自由的发展为基本原则的社会形式。”"},{"id":"mk15044-pl-P1526466","type":"sc","tier":"基础","conf":"adapt","chap":"第6-7章","q":"劳动不再仅仅是一种谋生手段而同时成为人们生活第一需要的社会是（）。","opts":["A. 社会主义社会","B. 共产主义社会","C. 资本主义社会","D. 信息社会"],"ans":1,"explain":"在共产主义社会，随着劳动生产率的极大提高和按需分配的实行，劳动不仅摆脱了强制性，而且摆脱了繁重的、单一的体力劳动，人们的劳动时间也大为缩短，参加劳动成为一种为社会公共利益服务的自觉要求，成为使自身体力智力健康发展的自然习惯，成为人们全面发展的内在因素。这样就导致劳动性质发生根本变化，劳动不再仅仅是一种谋生的手段，而同时成为生活的第一需要，劳动变为一种快乐，从而为人们自由而全面发展创造了条件。"},{"id":"mk15044-pl-P1526467","type":"sc","tier":"基础","conf":"adapt","chap":"第6-7章","q":"劳动的旧式分工，在人类历史上突出表现为（）。","opts":["A. 工农分工","B. 城乡分工","C. 脑力劳动与体力劳动分工","D. 以上说法均正确"],"ans":3,"explain":"劳动的旧式分工在人类历史上突出表现为由工农分工、城乡分工、脑力劳动与体力劳动分工所形成的“三大差别”，即工农差别、城乡差别、脑力劳动与体力劳动差别。"},{"id":"mk15044-pl-P1526468","type":"sc","tier":"基础","conf":"adapt","chap":"第6-7章","q":"共产主义社会将要消灭的“三大差别”不包括（）。","opts":["A. 脑力劳动与体力劳动差别","B. 干部和群众的差别","C. 工农差别","D. 城乡差别"],"ans":1,"explain":"劳动的旧式分工在人类历史上突出表现为由工农分工、城乡分工、脑力劳动与体力劳动分工所形成的“三大差别”，即工农差别、城乡差别、脑力劳动与体力劳动差别。而在共产主义社会中，旧式分工完全消失，人们从它的束缚下解放出来。"},{"id":"mk15044-pl-P1526469","type":"sc","tier":"基础","conf":"adapt","chap":"第6-7章","q":"在共产主义的生产资料社会公有制条件下，生产资料的所有者是（）。","opts":["A. 全体劳动者","B. 集体","C. 全部公民","D. 社会组织"],"ans":0,"explain":"在共产主义的生产资料社会公有制条件下，全体劳动者都成为生产资料的所有者，劳动成果也属劳动者所有，劳动者完全从私有制和阶级剥削的桎梏下解放出来，成为真正意义上的生产过程的主人，从而为每个人的自由而全面发展提供了经济前提。"},{"id":"mk15044-pl-P1526470","type":"sc","tier":"基础","conf":"adapt","chap":"第6-7章","q":"资本主义社会为自身被新的社会制度所取代准备的物质条件是（）。","opts":["A. 社会化大生产","B. 现代无产阶级","C. 马克思主义理论","D. 市场经济体制"],"ans":0,"explain":"资本主义社会为自身被新的社会制度所取代准备了主客观条件，即物质条件——社会化大生产，社会条件——现代无产阶级，精神条件——马克思主义理论。"},{"id":"mk15044-pl-P1526471","type":"sc","tier":"基础","conf":"adapt","chap":"第6-7章","q":"资本主义社会为自身被新的社会制度所取代准备的精神条件是（）。","opts":["A. 社会化大生产","B. 现代无产阶级","C. 马克思主义理论","D. 市场经济体制"],"ans":2,"explain":"资本主义社会为自身被新的社会制度所取代准备了主客观条件，这些条件包括：物质条件——社会化大生产，社会条件——现代无产阶级，精神条件——马克思主义理论。"},{"id":"mk15044-pl-P1526472","type":"sc","tier":"基础","conf":"adapt","chap":"第6-7章","q":"无产阶级要最终实现自身解放，只有（）。","opts":["A. 打碎旧的国家机器","B. 建立社会公有制","C. 提高劳动生产率","D. 解放全人类"],"ans":3,"explain":"无产阶级争取解放的事业，不仅是为了解放无产阶级自己，而且是要解放全人类。无产阶级也只有解放全人类，才能最终解放自己。"},{"id":"mk15044-pl-P1526473","type":"sc","tier":"基础","conf":"adapt","chap":"第6-7章","q":"社会主义社会和共产主义社会都存在的经济关系是（）。","opts":["A. 生产资料的社会公有制","B. 按劳分配","C. 按需分配","D. 市场经济体制"],"ans":0,"explain":"社会主义社会和共产主义社会共同的基本特征主要包括：(1)二者都是以生产资料公有制作为社会经济制度的基础。(2)二者的生产目的都是为了满足劳动人民日益增长的物质文化生活需要，实现劳动人民的共同富裕。(3)二者在公有制范围内的产品分配，都按照有利于社会发展和实现劳动人民利益的原则进行。(4)二者都要消灭剥削制度，劳动人民成为社会的主人，他们之间的本质关系是平等和谐、互助合作的关系。(5)二者都以马克思主义为指导思想,以集体主义为意识形态的核心。"},{"id":"mk15044-pl-P1526474","type":"sc","tier":"基础","conf":"adapt","chap":"第6-7章","q":"马克思主义科学地预见到，共产主义社会形态在其发展进程中，将经历两个不同的发展阶段，第一阶段为（）。","opts":["A. 社会主义社会","B. 共产主义社会","C. 产品经济社会","D. 商品经济社会"],"ans":0,"explain":"马克思主义科学地预见到：共产主义社会形态在其发展进程中，将经历低级（第一阶段）和高级（第二阶段）两个成熟程度不同的发展阶段。低级阶段为社会主义社会，高级阶段为共产主义社会。"},{"id":"mk15044-pl-P1526475","type":"sc","tier":"基础","conf":"adapt","chap":"第6-7章","q":"社会主义社会虽已建立了新型的社会主义意识形态和道德观念，但仍存在而且将长期存在（）。","opts":["A. 封建主义的思想影响","B. 资本主义的思想影响","C. 小资产阶级习惯势力","D. 以上说法均正确"],"ans":3,"explain":"社会主义社会虽然已经建立了新型的社会主义意识形态和道德观念，但仍存在封建主义和资本主义思想影响，小资产阶级习惯势力也长期存在。"},{"id":"mk15044-pl-P1526476","type":"sc","tier":"基础","conf":"adapt","chap":"第6-7章","q":"下列关于共产主义的说法中，错误的是（）。","opts":["A. 这是人类最伟大的事业","B. 是崇高理想与科学理想的统一","C. 属于新生事物，必将灭亡","D. 经过社会主义社会的长期发展最终必然实现"],"ans":2,"explain":"实现共产主义是人类最伟大的事业，经过长期的发展最终必然会实现。共产主义之所以是人类最伟大的事业，就在于它是崇高理想与科学理想的统一，体现了人类对理想社会目标的追求与符合规律的科学社会实践的有机结合。"},{"id":"mk15044-pl-P1526477","type":"sc","tier":"基础","conf":"adapt","chap":"第6-7章","q":"我国建立社会主义制度以后，必须经历一个社会主义初级阶段的长期发展过程，以便实现工业化与经济的（）。","opts":["A. 社会化","B. 市场化","C. 现代化","D. 以上说法均正确"],"ans":3,"explain":"我国建立社会主义制度以后，必须经历一个社会主义初级阶段的长期发展过程，以便实现工业化与经济的社会化、市场化、现代化、信息化和国际化。这是不可逾越的历史阶段。"},{"id":"mk15044-pl-P1526478","type":"sc","tier":"基础","conf":"adapt","chap":"第6-7章","q":"热心于共产主义，首先要热心于（）。","opts":["A. 社会生产力的发展","B. 国家经济的发展","C. 劳动者生活的改善","D. 国际形势的改善"],"ans":0,"explain":"实现共产主义所必须具备的基本条件，要在社会主义历史阶段经过长期的努力奋斗才能创造出来。热心于共产主义，首先要热心于社会生产力的发展。不经过社会主义社会的长期发展，不具备向共产主义过渡的条件，实现高级阶段的共产主义社会只是一句空话。"},{"id":"mk15044-pl-P1526479","type":"sc","tier":"基础","conf":"adapt","chap":"第6-7章","q":"社会理想具有鲜明的（）。","opts":["A. 现实性","B. 阶级性","C. 阶段性","D. 长远性"],"ans":1,"explain":"社会理想具有鲜明的阶级性：各阶级都有自己的社会理想。工人阶级是与社会化大生产相联系的先进阶级，它的历史使命和社会理想就是彻底解放全人类，在全世界实现共产主义。"},{"id":"mk15044-pl-P1526480","type":"sc","tier":"基础","conf":"adapt","chap":"第6-7章","q":"（）是人们对社会制度和社会面貌的预见和期望。","opts":["A. 社会理想","B. 职业理想","C. 生活理想","D. 道德理想"],"ans":0,"explain":"社会理想作为人们最根本的、起主要和决定作用的理想而贯穿于其他理想之中，它是人们对社会制度和社会面貌的预见和期望。"},{"id":"mk15044-pl-P1526481","type":"sc","tier":"基础","conf":"adapt","chap":"第6-7章","q":"在当代中国真正坚持社会主义就要（）。","opts":["A. 坚持进行市场导向的改革","B. 坚持中国特色社会主义道路","C. 坚持在政治经济社会诸方面与国际接轨","D. 坚持马克思主义经典著作的所有结论"],"ans":1,"explain":"在当代中国，坚持中国特色社会主义道路，就是真正坚持社会主义。"},{"id":"mk15044-pl-P1527354","type":"sc","tier":"基础","conf":"adapt","chap":"第6-7章","q":"把社会主义本质概括为“解放生产力，发展生产力，消灭剥削，消除两极分化，最终达到共同富裕”的中国共产党人是()","opts":["A. 毛泽东","B. 刘少奇","C. 周恩来","D. 邓小平"],"ans":3,"explain":"把社会主义本质概括为“解放生产力，发展生产力，消灭剥削，消除两极分化，最终达到共同富裕”的中国共产党人是邓小平"},{"id":"mk15044-pl-P1527355","type":"sc","tier":"基础","conf":"adapt","chap":"第6-7章","q":"社会主义制度优越性最根本的一条是（）","opts":["A. 解放生产力发展生产力创造比资本主义更高的生产率","B. 建立和完善社会主义市场资料公有制，最终达到共同富裕","C. 实行各尽所能按劳分配消灭剥削消除两极分化","D. 发展社会主义民主完善社会主义法治，建设社会主义政治文明"],"ans":0,"explain":"解放和发展生产力，创造高度发达的生产力和比资本主义更高的劳动生产率。这是社会主义制度优越性最根本的一条。"},{"id":"mk15044-pl-P1527356","type":"sc","tier":"基础","conf":"adapt","chap":"第6-7章","q":"马克思所说未来社会的第一阶段是指（）","opts":["A. 社会主义革命时期","B. 向社会主义过渡时期","C. 社会主义初级阶段","D. 社会主义社会"],"ans":3,"explain":"社会主义社会是共产主义社会的第一阶段或低级阶段，其目标是走向共产主义社会的高级阶段。"},{"id":"mk15044-pl-P1527357","type":"sc","tier":"基础","conf":"adapt","chap":"第6-7章","q":"社会主义社会组织生产的根本目的在于（ ）。","opts":["A. 资本的价值增值","B. 满足全体社会成员的需要","C. 满足无产阶级的需要","D. 满足人民群众的需要"],"ans":1,"explain":"社会主义社会组织生产的根本目的在于满足全体社会成员的需要。"},{"id":"mk15044-pl-P1527358","type":"sc","tier":"基础","conf":"adapt","chap":"第6-7章","q":"（）是无产阶级进行斗争的最高形式，以建立无产阶级专政的国家为主要目的。","opts":["A. 无产阶级革命","B. 资产阶级革命","C. 社会主义改革","D. 资产阶级改革"],"ans":0,"explain":"无产阶级革命是无产阶级进行斗争的最高形式，以建立无产阶级专政的国家为目的"},{"id":"mk15044-pl-P1527359","type":"sc","tier":"基础","conf":"adapt","chap":"第6-7章","q":"无产阶级政党的组织原则是（）","opts":["A. 集体领导制","B. 首长负责制","C. 集体问责制","D. 民主集中制"],"ans":3,"explain":"无产阶级政党实行民主集中制的组织原则"},{"id":"mk15044-pl-P1527360","type":"sc","tier":"基础","conf":"adapt","chap":"第6-7章","q":"资本主义必然灭亡，社会主义必然胜利的根本依据是（ ）。","opts":["A. 人类社会发展规律和资本主义基本矛盾","B. 社会化生产力的发展","C. 资本主义周期性经济危机","D. 科学社会主义的传播和发展"],"ans":0,"explain":"资本主义必然灭亡，社会主义必然胜利的根本依据是人类社会发展规律和资本主义基本矛盾。"},{"id":"mk15044-pl-P1527361","type":"sc","tier":"基础","conf":"adapt","chap":"第6-7章","q":"社会主义在实践中发展，下列不属于发展道路多样性的原因的是（）","opts":["A. 各国生产力状况和社会发展阶段不同","B. 各国历史传统、文化习俗以及具体国情不同","C. 适合各国国情的发展的道路不同","D. 实现按劳分配的分配原则"],"ans":3,"explain":"社会主义发展道路多样性的原因 （1）各国在社会主义革命时，其生产力状况和社会发展阶段是不同的，由此决定不同社会主义国家的发展道路具有不同的特点。 （2）各国的历史传统、文化习俗及具体国情各不相同，这是各国的发展道路不同的另一原因。例如，东欧国家和中国等亚洲国家在历史文化、宗教信仰等方面有很大差异，这必然对这些国家在社会主义革命后的具体发展道路有不同影响。 （3）在社会主义的实践中，各国都在探索适合本国国情的发展道路，时代在前进，实践在发展，社会主义的发展道路因此而更具多样性"},{"id":"mk15044-pl-P1527362","type":"sc","tier":"基础","conf":"adapt","chap":"第6-7章","q":"同样是农业集体化道路，在苏联采取的是集体农庄的形式，而中国则采取从互助组到初级社，再到高级社这样循序渐进的形式。这说明（）","opts":["A. 社会主义的发展道路是没有规律可循的","B. 社会主义的发展阶段是不同的","C. 社会主义的发展道路是具有偶然性的","D. 由于国情不同，社会主义的发展道路是具有多样性的"],"ans":3,"explain":"同样是农业集体化道路，在苏联采取的是集体农庄的形式，而中国则采取从互助组到初级社，再到高级社这样循序渐进的形式。这说明由于国情不同，社会主义的发展道路是具有多样性的"},{"id":"mk15044-pl-P1527364","type":"sc","tier":"基础","conf":"adapt","chap":"第6-7章","q":"社会主义社会的改革是（ ）。","opts":["A. 社会主义基本经济制度的改变","B. 社会主义核心价值观的根本改变","C. 社会主义基本政治制度的改变","D. 社会主义制度的自我完善和发展"],"ans":3,"explain":"社会主义社会的改革是社会主义制度的自我完善和发展。"},{"id":"mk15044-pl-P1527365","type":"sc","tier":"基础","conf":"adapt","chap":"第6-7章","q":"社会主义的根本任务是（）","opts":["A. 解放和发展生产力","B. 巩固无产阶级专政","C. 坚持和改善党的领导","D. 发展社会主义民主法制"],"ans":0,"explain":"解放生产力、发展生产力是社会主义的根本任务。"},{"id":"mk15044-pl-P1527366","type":"sc","tier":"基础","conf":"adapt","chap":"第6-7章","q":"社会主义根本的和首要的任务是（ ）。","opts":["A. 解放和发展生产力","B. 加强无产阶级专政","C. 巩固共产党的领导","D. 镇压资产阶级的反抗"],"ans":0,"explain":"社会主义根本的和首要的任务是解放和发展生产力。"},{"id":"mk15044-pl-P1527367","type":"sc","tier":"基础","conf":"adapt","chap":"第6-7章","q":"以下哪个是社会主义民主的本质（）","opts":["A. 一切权利归属人民","B. 人民当家作主","C. 人民是国家的主人","D. 人民享有广泛而深入的自由"],"ans":1,"explain":"社会主义国家是人民当家作主的国家"},{"id":"mk15044-pl-P1527368","type":"sc","tier":"基础","conf":"adapt","chap":"第6-7章","q":"自有阶级社会以来，人类历史上出现的人类社会最高类型的民主是（）","opts":["A. 资本主义社会","B. 社会主义社会","C. 无产阶级社会","D. 共产主义社会"],"ans":1,"explain":"社会主义国家是人民当家作主的国家，而非少数剥削阶级统治的国家，因而，社会主义民主是最高类型的民主。"},{"id":"mk15044-pl-P1527369","type":"sc","tier":"基础","conf":"adapt","chap":"第6-7章","q":"社会主义民主的本质是（ ）。","opts":["A. 人民当家做主","B. 解放和发展生产力","C. 消灭剥削压迫","D. 促进人的全面发展"],"ans":0,"explain":"社会主义民主的本质是人民当家做主。"},{"id":"mk15044-pl-P1527370","type":"sc","tier":"基础","conf":"adapt","chap":"第6-7章","q":"关于社会主义民主，下列不正确的选项是（ ）。","opts":["A. 人类社会最高类型的民主","B. 绝大多数人的民主","C. 人民群众完全自由","D. 人民当家做主"],"ans":2,"explain":"社会主义民主是人类社会最高类型的民主、绝大多数人的民主，人民处于当家做主的地位。"},{"id":"mk15044-pl-P1527373","type":"sc","tier":"基础","conf":"adapt","chap":"第6-7章","q":"实现工人阶级历史使命的根本保证是（）","opts":["A. 正确思想的指导","B. 革命形势的到来","C. 马克思主义政党的领导","D. 严密的组织纪律性"],"ans":2,"explain":"马克思主义政党的领导是实现工人阶级历史使命的根本保证。"},{"id":"mk15044-pl-P1527374","type":"sc","tier":"基础","conf":"adapt","chap":"第6-7章","q":"因为马克思主义政党在社会主义国家中领导人民实现国家管理国家和社会事务的权利，所有坚持社会主义就必须坚持（）","opts":["A. 工人阶级的主人翁地位","B. 党的领导核心地位","C. 无产阶级领袖的指导地位","D. 不断改善党的领导"],"ans":1,"explain":"因为马克思主义政党代表人民群众的根本利益，作为执政党在社会主义国家中领导人民实现管理国家和社会事务的权利。放弃党的领导，人民群众的民主权利和根本利益就无法保障，社会主义民主也就无从谈起。因此坚持社会主义就必须坚持马克思主义政党的领导核心地位。"},{"id":"mk15044-pl-P1527375","type":"sc","tier":"基础","conf":"adapt","chap":"第6-7章","q":"对马克思主义政党性质最简要、最明确的表述是（）","opts":["A. 马克思主义政党是中华民族的先锋队","B. 马克思主义政党是无产阶级的先锋队","C. 马克思主义政党是工人阶级的先锋队","D. 马克思主义政党是劳动人民的先锋队"],"ans":2,"explain":"对马克思主义政党性质最简要、最明确的表述是克思主义政党是工人阶级的先锋队"},{"id":"mk15044-pl-P1527376","type":"sc","tier":"基础","conf":"adapt","chap":"第6-7章","q":"马克思主义政党产生的充分条件是（ ）。","opts":["A. 马克思主义理论的诞生","B. 工人运动的发展","C. 马克思主义理论的传播","D. 马克思主义与工人运动相结合"],"ans":3,"explain":"马克思主义政党产生的充分条件是马克思主义与工人运动相结合."},{"id":"mk15044-pl-P1527377","type":"sc","tier":"基础","conf":"adapt","chap":"第6-7章","q":"马克思主义政党的产生有两个条件，一是工人运动的发展，二是（）","opts":["A. 贫富差距的拉大","B. 革命领袖的出现","C. 政治腐败的蔓延","D. 科学社会主义理论的传播"],"ans":3,"explain":"马克思主义政党产生的条件，一是工人运动的发展，二是科学社会主义理论的传播。"},{"id":"mk15044-pl-P1527378","type":"sc","tier":"基础","conf":"adapt","chap":"第6-7章","q":"马克思主义政党产生的条件有二：一是工人运动的发展，二是（ ）。","opts":["A. 农民运动的发展","B. 科学社会主义理论的传播","C. 阶级矛盾的激化","D. 杰出人物的出现"],"ans":1,"explain":"马克思主义政党产生的条件有二：一是工人运动的发展，二是科学社会主义理论的传播。"},{"id":"mk15044-pl-P1527380","type":"sc","tier":"基础","conf":"adapt","chap":"第6-7章","q":"马克思主义政党的组织原则是（ ）。","opts":["A. 集体领导制","B. 个人负责制","C. 民主监督制","D. 民主集中制"],"ans":3,"explain":"马克思主义政党的组织原则是民主集中制。"},{"id":"mk15044-pl-P1527381","type":"sc","tier":"基础","conf":"adapt","chap":"第6-7章","q":"马克思主义政党的最高纲领和最终奋斗目标是（ ）。","opts":["A. 消除两极分化","B. 巩固无产阶级专政","C. 实现共产主义","D. 最终达到共同富裕"],"ans":2,"explain":"马克思主义政党的最高纲领和最终奋斗目标是实现共产主义（最高理想）。"},{"id":"mk15044-pl-P1527383","type":"sc","tier":"基础","conf":"adapt","chap":"第6-7章","q":"无产阶级政党的根本宗旨是（）","opts":["A. 为社会主义事业添砖加瓦","B. 为实现共产主义事业而奋斗36","C. 为人民群众谋利益","D. 为最终解放无产阶级而奋斗"],"ans":2,"explain":"马克思主义政党是为人民服务的新型政党，它的根本宗旨是为人民群众谋利益。"},{"id":"mk15044-pl-P1527384","type":"sc","tier":"基础","conf":"adapt","chap":"第6-7章","q":"马克思主义政党在不同国家和不同的历史时期，有不同的名称，但其性质都是（）","opts":["A. 无产阶级的国际组织","B. 共产主义者的同盟","C. 工人阶级的先锋队","D. 先进阶级的革命组织"],"ans":2,"explain":"马克思主义政党在不同国家和不同的历史时期，有共产党、工人党或是其他的名称，但其性质都是工人阶级的先锋队，这是马克思主义政党性质最简要、最明确的表述。"},{"id":"mk15044-pl-P1527385","type":"sc","tier":"基础","conf":"adapt","chap":"第6-7章","q":"以下哪个是马克思主义政党的组织原则（）","opts":["A. 普选制","B. 一人一票制","C. 民主集中制","D. 党委负责制"],"ans":2,"explain":"民主集中制是马克思主义政党的组织原则。"},{"id":"mk15044-pl-P1527386","type":"sc","tier":"基础","conf":"adapt","chap":"第6-7章","q":"提出并实施新经济政策的是（）","opts":["A. 列宁","B. 恩格斯","C. 马克思","D. 斯大林"],"ans":0,"explain":"1921年春，苏维埃俄国击退了外国武装干涉，平息了国内叛乱，开始了和平建设时期。这时列宁果断地结束战时共产主义，转而实行新经济政策。"},{"id":"mk15044-pl-P1527388","type":"sc","tier":"基础","conf":"adapt","chap":"第6-7章","q":"20世纪各社会主义国家的实践，使社会主义从理论在多国变成现实，这是人类历史上的（）","opts":["A. 重要发展","B. 重大转变","C. 巨大飞跃","D. 新纪元"],"ans":2,"explain":"20世纪各社会主义国家的实践，使社会主义从理论在多国变为现实，是人类历史上的巨大飞跃。"},{"id":"mk15044-pl-P1527389","type":"sc","tier":"基础","conf":"adapt","chap":"第6-7章","q":"社会主义事业从一国向多国发展不断壮大开始于（）","opts":["A. 第一次世界大战后，","B. 第二次世界大战后","C. 中华人民共和国成立后","D. 苏联建成社会主义国家后"],"ans":1,"explain":"第二次世界大战以后社会主义事业从一国向多国发展壮大。"},{"id":"mk15044-pl-P1527390","type":"sc","tier":"基础","conf":"adapt","chap":"第6-7章","q":"社会主义事业从一国向多国发展壮大开始于（ ）。","opts":["A. 第一世界大战之","B. 第二次世界大战之后","C. 中华人民共和国成立之后","D. 苏联建立社会主义国家之后"],"ans":1,"explain":"社会主义事业从一国向多国发展壮大开始于第二次世界大战之后。"},{"id":"mk15044-pl-P1527391","type":"sc","tier":"基础","conf":"adapt","chap":"第6-7章","q":"20世纪社会主义的实践，有辉煌的成绩，也发生过曲折。总结历史经验和教训，我们在发展道路问题上的重要认识是（）","opts":["A. 要把科学社会主义理论与各国实践相结合，探索符合本国国情的社会主义发展道路","B. 社会主义的社会主义经济体制并非只有一种模式，要解放思想，勇于探索","C. 要坚持共产党的领导，不断发展社会主义民主政治，形成一种生动活泼的政治局面","D. 要善于吸收资本主义发达国家一切能为我所用的东西，学习人类发展中的优秀成果"],"ans":0,"explain":"总结这些历史经验和教训使我们认识到：要正视经济社会发展较为落后的国家在特定历史条件下进入社会主义的特殊性，要把科学社会主义理论与各国的实践相结合，探索符合本国国情的社会主义发展道路。"},{"id":"mk15044-pl-P1527392","type":"sc","tier":"基础","conf":"adapt","chap":"第6-7章","q":"（ ）重新确立了解放思想、实事求是的思想路线。","opts":["A. 党的十二届三中全会","B. 党的十三届三中全会","C. 党的十一届三中全会","D. 党的十五届三中全会"],"ans":2,"explain":"1978年党的十一届三中全会重新确立了解放思想、实事求是的思想路线"},{"id":"mk15044-pl-P1527393","type":"sc","tier":"基础","conf":"adapt","chap":"第6-7章","q":"马克思主义是普遍真理，对我们的实践具有指导意义，这一观点的正确理解是（）","opts":["A. 在实践中照搬马克思主义经典作家的条文词句","B. 用马克思主义理论去剪裁实际","C. 用马克思主义的基本观点立场方法去研究所遇到的实际","D. 马克思主义经典作家为我们的实践问题已提供了直接现成的答案"],"ans":2,"explain":"把马克思主义的普遍真理同我国的具体实际结合起来，走自己的道路，建设有中国特色的社会主义，这就是我们总结长期历史经验得出的基本结论。"},{"id":"mk15044-pl-P1527394","type":"sc","tier":"基础","conf":"adapt","chap":"第6-7章","q":"当前时代，我国发展中国特色社会主义的总任务是（ ）。","opts":["A. 实现社会主义现代化和中华民族的伟大复兴","B. 完善中国特色社会主义制度","C. 推进国家治理体系和治理能力的现代化","D. 建设中国特色社会主义法治体系"],"ans":0,"explain":"当前时代，我国发展中国特色社会主义的总任务是实现社会主义现代化和中华民族的伟大复兴。"},{"id":"mk15044-pl-P1527395","type":"sc","tier":"基础","conf":"adapt","chap":"第6-7章","q":"党的（ ）报告阐述了新时代中国特色社会主义思想的“八个明确”和“十四个基本方略”。","opts":["A. 十九大","B. 十六大","C. 十八大","D. 党的十一届三中全会"],"ans":0,"explain":"党的十九大报告阐述了新时代中国特色社会主义思想的“八个明确”和“十四个基本方略”。"},{"id":"mk15044-pl-P1527396","type":"sc","tier":"基础","conf":"adapt","chap":"第6-7章","q":"下列选项中体现社会主义的本质属性和要求的是（ ）。","opts":["A. 促进人的全面发展和社会和谐","B. 实行高度发达的商品经济","C. 建立完全纯粹的公有制经济","D. 实行严格管控的计划经济"],"ans":0,"explain":"社会主义的本质属性和要求是促进人的全面发展和社会和谐。"},{"id":"mk15044-pl-P1527397","type":"sc","tier":"基础","conf":"adapt","chap":"第6-7章","q":"社会主义社会的本质属性和要求是（）","opts":["A. 解放生产力发展生产力","B. 消灭剥削消除两极分化，最终达到共同富裕35","C. 建立和完善社会主义公有制","D. 促进人的全面发展和社会和谐"],"ans":3,"explain":"社会主义社会的本质属性和要求是促进人的全面发展和社会和谐。"},{"id":"mk15044-pl-P1527398","type":"sc","tier":"基础","conf":"adapt","chap":"第6-7章","q":"在科学社会主义运动史上，第一个国际性的马克思主义政党是（）","opts":["A. 共产主义者同盟","B. 德国社会民主工党","C. 俄国社会民主工党","D. 中国共产党"],"ans":0,"explain":"1847年年底他们受世界上第一个无产阶级政党“共产主义者同盟”的委托起草并于1848年2月发表的《共产党宣言》，是社会主义思想史上的第一个纲领性文件，它标志着科学社会主义理论公开面世。"},{"id":"mk15044-pl-P1527399","type":"sc","tier":"基础","conf":"adapt","chap":"第6-7章","q":"标志着科学社会主义公开问世的经典著作是（）","opts":["A. 《共产党宣言》","B. 《哥达纲领批判》","C. 《资本论》","D. 《国家与革命》"],"ans":0,"explain":"1847年年底他们受世界上第一个无产阶级政党“共产主义者同盟”的委托起草并于1848年2月发表的《共产党宣言》，是社会主义思想史上的第一个纲领性文件，它标志着科学社会主义理论公开面世。"},{"id":"mk15044-pl-P1527400","type":"sc","tier":"基础","conf":"adapt","chap":"第6-7章","q":"社会主义思想史上第一个纲领性文件是（）","opts":["A. 《乌托邦》","B. 《太阳城》","C. 《共产党宣言》","D. 《哥达纲领批判》"],"ans":2,"explain":"1847年年底他们受世界上第一个无产阶级政党“共产主义者同盟”的委托起草并于1848年2月发表的《共产党宣言》，是社会主义思想史上的第一个纲领性文件，它标志着科学社会主义理论公开面世。"},{"id":"mk15044-pl-P1527401","type":"sc","tier":"基础","conf":"adapt","chap":"第6-7章","q":"标志着科学社会主义理论公开面世的纲领性文件是（）","opts":["A. 《共产主义原理》","B. 《共产党宣言》","C. 《哥达纲领批判》","D. 《国家与革命》"],"ans":1,"explain":"1847年年底他们受世界上第一个无产阶级政党“共产主义者同盟”的委托起草并于1848年2月发表的《共产党宣言》，是社会主义思想史上的第一个纲领性文件，它标志着科学社会主义理论公开面世。"},{"id":"mk15044-pl-P1527402","type":"sc","tier":"基础","conf":"adapt","chap":"第6-7章","q":"标志着社会主义由空想变为科学的著作是（）","opts":["A. 《反杜林论》","B. 《德意志意识形态》","C. 《共产党宣言》","D. 《资本论》"],"ans":2,"explain":"1847年年底他们受世界上第一个无产阶级政党“共产主义者同盟”的委托起草并于1848年2月发表的《共产党宣言》，是社会主义思想史上的第一个纲领性文件，它标志着科学社会主义理论公开面世。"},{"id":"mk15044-pl-P1527403","type":"sc","tier":"基础","conf":"adapt","chap":"第6-7章","q":"除《哲学的贫困》外，标志马克思主义公开问世的经典著作是（ ）。","opts":["A. 《关于费尔巴哈的提纲》","B. 《德意志意识形态》","C. 《共产党宣言》","D. 《资本论》"],"ans":2,"explain":"标志马克思主义公开问世的经典著作是《哲学的贫困》和《共产党宣言》。"},{"id":"mk15044-pl-P1527404","type":"sc","tier":"基础","conf":"adapt","chap":"第6-7章","q":"下列选项中，属于无产阶级革命正当选择革命形势和道路应该遵循的基本原则的是（）","opts":["A. 暴力革命是无产阶级革命的唯一形式的原则","B. 马克思主义普遍真理与本国具体实际相结合的原则","C. 在任何情况下都要争取革命的和平发展的原则","D. 在经济文化落后的国家首先进行社会主义革命的原则"],"ans":1,"explain":"第二次世界大战后建立起来的各个社会主义国家，也都是通过革命战争、武装起义等暴力革命的方式夺取政权，建立起社会主义国家的。世界经济政治军事格局在不断变化，资本主义国家内部也在不断进行着局部调整，在今后的社会发展中，社会主义革命将采取何种形式，只能由各国无产阶级政党和人民根据马克思主义基本原理同本国实际情况相结合的原则做出决定。"},{"id":"mk15044-pl-P1527405","type":"sc","tier":"基础","conf":"adapt","chap":"第6-7章","q":"世界上第一个社会主义国家建立是在（）","opts":["A. 法国","B. 苏维埃俄国","C. 中国","D. 朝鲜"],"ans":1,"explain":"俄国无产阶级于1917年11月7日（俄历10月25日）在彼得格勒举行了十月革命武装起义，建立起世界上第一个社会主义国家。"},{"id":"mk15044-pl-P1527406","type":"sc","tier":"基础","conf":"adapt","chap":"第6-7章","q":"马克思和恩格斯认为，革命的发生归根到底取决于（）","opts":["A. 生产力的发展水平","B. 生产资料公有化的程度","C. 人民群众的觉悟程度","D. 马克思主义政党的正确领导"],"ans":0,"explain":"革命的发生归根结底是由生产力发展水平决定的。"},{"id":"mk15044-pl-P1527407","type":"sc","tier":"基础","conf":"adapt","chap":"第6-7章","q":"成为马克思主义科学社会主义的直接理论来源的是（）","opts":["A. 德国古典哲学","B. 英国古典经济学","C. 莫尔的《乌托邦》和康帕内拉的《太阳城》","D. 19世纪英法两国的空想社会主义学说"],"ans":3,"explain":"空想社会主义是马克思主义科学社会主义的直接理论来源"},{"id":"mk15044-pl-P1527408","type":"sc","tier":"基础","conf":"adapt","chap":"第6-7章","q":"列宁对于无产阶级革命的重大理论贡献是（ ）。","opts":["A. 提出了战时共产主义政策","B. 提出了新经济政策","C. 提出了利用资本主义发展社会主义的理论","D. 提出了社会主义革命将首先在一国或数国胜利的理论"],"ans":3,"explain":"列宁对于无产阶级革命的重大理论贡献是提出了社会主义革命将首先在一国或数国胜利的理论。"},{"id":"mk15044-pl-P1527409","type":"sc","tier":"基础","conf":"adapt","chap":"第6-7章","q":"列宁所提出的社会主义革命在一国或数国首先胜利的理论立足于（）","opts":["A. 马克思恩格斯的科学预言．","B. 巴黎公社原则","C. 资本主义发展不平衡规律","D. 生产力决定论"],"ans":2,"explain":"列宁所提出的社会主义革命在一国或数国首先胜利的理论立足于资本主义发展不平衡规律"},{"id":"mk15044-pl-P1527411","type":"sc","tier":"基础","conf":"adapt","chap":"第6-7章","q":"社会主义革命可以在一国或数国首先胜利理论的提出者是（）","opts":["A. 马克思","B. 恩格斯","C. 列宁","D. 毛泽东"],"ans":2,"explain":"列宁提出的社会主义革命一国或数国首先胜利论"},{"id":"mk15044-pl-P1527412","type":"sc","tier":"基础","conf":"adapt","chap":"第6-7章","q":"列宁提出社会主义可能在一国或数国首先胜利的理论依据是()","opts":["A. 资本主义必然灭亡社会主义必然胜利的规律","B. 帝国主义时代资本主义政治经济发展不平衡的规律","C. 资本主义国家无产阶级与资产阶级斗争的规律","D. 生产关系必须适合生产力发展要求的规律"],"ans":1,"explain":"列宁提出的社会主义革命一国或数国首先胜利论，是在新形势下对马克思主义无产阶级革命理论的发展。它以帝国主义阶段经济政治发展不平衡规律为依据，是符合当时的实际情况的。"},{"id":"mk15044-pl-P1527413","type":"sc","tier":"基础","conf":"adapt","chap":"第6-7章","q":"提出社会主义革命可能在一国或数国首先胜利理论的是（）","opts":["A. 马克思","B. 恩格斯","C. 列宁","D. 斯大林"],"ans":2,"explain":"列宁研究了帝国主义时期资本主义经济政治的新情况、新问题、新特点，集中了俄国布尔什维克党的智慧，立足于资本主义发展不平衡规律，提出了社会主义革命可以在一国或数国首先胜利的理论。"},{"id":"mk15044-pl-P1527414","type":"sc","tier":"基础","conf":"adapt","chap":"第6-7章","q":"下列选项属于马克思主义三个组成部分之一的是（ ）。","opts":["A. 马克思主义政治学","B. 马克思主义哲学","C. 马克思主义伦理学","D. 马克思主义社会学"],"ans":1,"explain":"马克思主义三个组成部分分别是：马克思主义哲学、马克思主义政治经济学、科学社会主义。"},{"id":"mk15044-pl-P1527415","type":"sc","tier":"基础","conf":"adapt","chap":"第6-7章","q":"马克思主义认为，暴力革命是无产阶级革命的（）","opts":["A. 唯一形式","B. 基本形式","C. 辅助形式","D. 特殊形式"],"ans":1,"explain":"迄今的实践中，暴力革命是主要的基本形式。"},{"id":"mk15044-pl-P1527416","type":"sc","tier":"基础","conf":"adapt","chap":"第6-7章","q":"圣西门、傅里叶、欧文是（ ）。","opts":["A. 德国古典哲学的代表人物","B. 英国古典政治经济学的代表人物","C. 英法两国空想社会主义的代表人物","D. 美国空想社会主义的代表人物"],"ans":2,"explain":"圣西门、傅里叶、欧文是英法两国空想社会主义的代表人物。"},{"id":"mk15044-pl-P1527417","type":"sc","tier":"基础","conf":"adapt","chap":"第6-7章","q":"在世界经济政治军事格局不断变化的条件下，社会主义革命将采取何种形式，只能有各国无产阶级政党和人民根据马克思主义基本原理同自己国家的实际情况相结合，作出决定。这一观点是（）","opts":["A. 符合马克思主义的正确观点","B. 实用主义的错误观点","C. 形而上学的机械决定论","D. 否认理性作用的经验论"],"ans":0,"explain":"世界经济政治军事格局在不断变化，资本主义国家内部也在不断进行着局部调整，在今后的社会发展中，社会主义革命将采取何种形式，只能由各国无产阶级政党和人民根据马克思主义基本原理同本国实际情况相结合的原则做出决定。"},{"id":"mk15044-pl-P1527418","type":"sc","tier":"基础","conf":"adapt","chap":"第6-7章","q":"世界上第一个社会主义国家是（ ）。","opts":["A. 波兰人民共和国","B. 巴黎公社","C. 苏维埃俄国","D. 中华人民共和国"],"ans":2,"explain":"世界上第一个社会主义国家是苏维埃俄国。"},{"id":"mk15044-pl-P1527419","type":"sc","tier":"基础","conf":"adapt","chap":"第6-7章","q":"世界上第一个无产阶级政党是（ ）。","opts":["A. 共产主义者同盟","B. 布尔什维克","C. 德国社会民主工党","D. 中国共产党"],"ans":0,"explain":"世界上第一个无产阶级政党是共产主义者同盟。"},{"id":"mk15044-pl-P1527421","type":"sc","tier":"基础","conf":"adapt","chap":"第6-7章","q":"无产阶级革命的发生归根结底是由（ ）。","opts":["A. 生产力发展水平决定的","B. 生产关系的性质决定的","C. 无产阶级的意愿决定的","D. 资产阶级的行为决定的"],"ans":0,"explain":"无产阶级革命的发生归根结底是由生产力发展水平决定的。"},{"id":"mk15044-pl-P1527422","type":"sc","tier":"基础","conf":"adapt","chap":"第6-7章","q":"迄今为止人类历史上最深刻、最广泛、最彻底的革命是（）","opts":["A. 民族民主革命","B. 工人阶级革命","C. 无产阶级革命","D. 社会主义革命"],"ans":2,"explain":"无产阶级革命是迄今人类历史上最广泛、最彻底、最深刻的革命"},{"id":"mk15044-pl-P1527423","type":"sc","tier":"基础","conf":"adapt","chap":"第6-7章","q":"早期空想社会主义的代表作《乌托邦》的作者是（）","opts":["A. 英国人莫尔","B. 意大利人康帕雷拉","C. 法国人圣西门傅立叶","D. 英国人欧文"],"ans":0,"explain":"英国人莫尔——《乌托邦》"},{"id":"mk15044-pl-P1527424","type":"sc","tier":"基础","conf":"adapt","chap":"第6-7章","q":"在国际共识上，提出社会主义革命同时胜利论的是（）","opts":["A. 马克思、恩格斯","B. 列宁","C. 斯大林","D. 毛泽东"],"ans":0,"explain":"在国际共识上，提出社会主义革命同时胜利论的是马克思和恩格斯。"},{"id":"mk15044-pl-P1527425","type":"sc","tier":"基础","conf":"adapt","chap":"第6-7章","q":"在国家垄断资本主义阶段之前，资本主义处于（ ）。","opts":["A. 自由竞争资本主义阶段","B. 私人垄断资本主义阶段","C. 垄断竞争资本主义阶段","D. 金融垄断资本主义阶段"],"ans":1,"explain":"在国家垄断资本主义阶段之前，资本主义处于私人垄断资本主义阶段。"},{"id":"mk15044-pl-P1527426","type":"sc","tier":"基础","conf":"adapt","chap":"第6-7章","q":"19世纪初期欧洲的空想社会主义者不包括（ ）。","opts":["A. 法国的圣西门","B. 法国的傅立叶","C. 英国的欧文","D. 英国的莫尔"],"ans":3,"explain":"19世纪初期欧洲的空想社会主义者包括圣西门、傅里叶和欧文，不包括莫尔，莫尔生活于15世纪。"},{"id":"mk15044-pl-P1527429","type":"sc","tier":"基础","conf":"adapt","chap":"第6-7章","q":"劳动不再仅仅是一种谋生手段而成为人们生活第一需要的社会是（ ）。","opts":["A. 社会主义社会","B. 共产主义社会","C. 资本主义社会","D. 信息网络社会"],"ans":1,"explain":"劳动不再仅仅是一种谋生手段而成为人们生活第一需要的社会是共产主义社会。"},{"id":"mk15044-pl-P1527430","type":"sc","tier":"基础","conf":"adapt","chap":"第6-7章","q":"劳动不再是一种谋生手段，而成为人们生活第一需要的社会是（）","opts":["A. 社会主义社会","B. 共产主义社会","C. 资本主义社会","D. 信息社会"],"ans":1,"explain":"社会主义社会还存在旧式分工和三大差别，劳动还仅仅是一种谋生的手段。而在共产主义社会，旧式分工和三大差别已消失，劳动不再仅仅是谋生的手段，同时成为生活的第一需要，人们将获得自由而全面的发展。"},{"id":"mk15044-pl-P1527431","type":"sc","tier":"基础","conf":"adapt","chap":"第6-7章","q":"共产主义社会的生产资料公有制，是指（）","opts":["A. 全民所有制","B. 集体所有制","C. 多种所有制形式","D. 单一的社会公有制"],"ans":3,"explain":"社会主义社会实现了生产资料公有制，但公有制本身还存在全民所有制和集体所有制等多种形式，而且在社会主义初级阶段还存在公有制为主体地位条件下的非公有制经济形式。而共产主义社会则建立起单一的社会公有制。"},{"id":"mk15044-pl-P1527432","type":"sc","tier":"基础","conf":"adapt","chap":"第6-7章","q":"社会主义的分配原则是（）","opts":["A. 按生产要素分配","B. 按资分配","C. 按劳分配","D. 按需分配"],"ans":2,"explain":"社会主义社会在公有制范围内的个人收入分配实行按劳分配原则"},{"id":"mk15044-pl-P1527433","type":"sc","tier":"基础","conf":"adapt","chap":"第6-7章","q":"从社会主义过渡到共产主义社会是（）","opts":["A. 同一社会形态内部的过渡和变化","B. 一种社会形态取代另一种社会形态","C. 一种社会制度取代另一种社会制度","D. 一种生产关系取代另一种生产关系"],"ans":0,"explain":"因而从社会主义社会过渡到共产主义社会，只是从不成熟的共产主义社会发展到成熟的共产主义社会，表现为同一社会形态内部的过渡和变化。"},{"id":"mk15044-pl-P1527434","type":"sc","tier":"基础","conf":"adapt","chap":"第6-7章","q":"当代中国人民的历史使命是（ ）。","opts":["A. 建设中国特色社会主义","B. 实现社会绝对的公平正义","C. 实现国家完全的文明和谐","D. 实现公民彻底的自由平等"],"ans":0,"explain":"当代中国人民的历史使命是建设中国特色社会主义（共同理想）"},{"id":"mk15044-pl-P1527435","type":"sc","tier":"基础","conf":"adapt","chap":"第6-7章","q":"当前全国人民为之奋斗的共同理想是（ ）。","opts":["A. 实现共产主义","B. 建设中国特色社会主义","C. 实现博爱平等","D. 实现平均分配"],"ans":1,"explain":"当前全国人民为之奋斗的共同理想是建设中国特色社会主义，最高理想是实现共产主义。"},{"id":"mk15044-pl-P1527436","type":"sc","tier":"基础","conf":"adapt","chap":"第6-7章","q":"实现人生价值的基础和归宿是（）","opts":["A. 投身中国特色社会主义事业","B. 树立共产主义远大理想","C. 热心于社会生产力的发展","D. 服务于劳动人民的共同富裕"],"ans":1,"explain":"坚定共产主义远大理想信念是我们实现人生价值的基础和归宿"},{"id":"mk15044-pl-P1527437","type":"sc","tier":"基础","conf":"adapt","chap":"第6-7章","q":"中国各族人民的共同理想（ ）","opts":["A. 建设中国特色社会主义","B. 高扬社会主义的平等思想","C. 提倡诚实守信的伦理来源","D. 倡导社会主义的民主精神"],"ans":0,"explain":"建设中国特色社会主义是全国人民为之奋斗的共同理想"},{"id":"mk15044-pl-P1527438","type":"sc","tier":"基础","conf":"adapt","chap":"第6-7章","q":"马克思对于理想的划分中（）是作为核心的存在","opts":["A. 生活理想","B. 社会理想","C. 职业理想","D. 道德理想"],"ans":1,"explain":"马克思对于理想的划分中社会理想是作为核心的存在"},{"id":"mk15044-pl-P1527439","type":"sc","tier":"基础","conf":"adapt","chap":"第6-7章","q":"理想是人生奋斗的目标，在人们所追求的理想中，最根本的、其主要和决定作用的理想是（）","opts":["A. 社会理想","B. 职业理想","C. 生活理想","D. 道德理想"],"ans":0,"explain":"社会理想是人们对社会制度和社会面貌的预见和期望，它是人们的最根本的、起主要和决定作用的理想，贯穿于其他理想之中。"},{"id":"mk15044-pl-P1527440","type":"sc","tier":"基础","conf":"adapt","chap":"第6-7章","q":"在理想的各种内容中，处于核心地位的是（）","opts":["A. 社会理想","B. 生活理想","C. 职业理想","D. 道德理想"],"ans":0,"explain":"社会理想是人们对社会制度和社会面貌的预见和期望，它是人们的最根本的、起主要和决定作用的理想，贯穿于其他理想之中。"},{"id":"mk15044-pl-P1527441","type":"sc","tier":"基础","conf":"adapt","chap":"第6-7章","q":"我们实现人生价值的最终归宿是（ ）。","opts":["A. 社会主义共同理想","B. 共产主义远大理想","C. 天下大同的社会理想","D. 克己奉公的道德理想"],"ans":1,"explain":"实现人生价值的最终归宿共产主义远大理想"},{"id":"mk15044-pl-P1527442","type":"sc","tier":"基础","conf":"adapt","chap":"第6-7章","q":"当前，我国人民的历史使命和共同理想是（）","opts":["A. 跑步进入共产主义","B. 建设中国特色社会主义","C. 建设新民主主义和谐社会","D. 建设共产主义劳动公社联合体"],"ans":1,"explain":"我国人民的历史使命和共同理想是建设中国特色社会主义"},{"id":"mk15044-pl-P1527443","type":"sc","tier":"基础","conf":"adapt","chap":"第6-7章","q":"在当前社会主义初级阶段，我国人民的历史使命和共同理想是（）","opts":["A. 实现共产主义","B. 建设中国特色社会主义","C. 实现平均分配","D. 实现全人类的彻底解放"],"ans":1,"explain":"我国人民的历史使命和共同理想是建设中国特色社会主义"},{"id":"mk15044-pl-P1527444","type":"sc","tier":"基础","conf":"adapt","chap":"第6-7章","q":"在我国社会主义国家政权的具体形式是（）","opts":["A. 人民公社","B. 无产阶级专政","C. 工人阶级先锋队共产党的领导","D. 以人民代表大会为根本制度的人民民主专政"],"ans":3,"explain":"在我国社会主义国家政权的具体形式是以人民代表大会为根本制度的人民民主专政"},{"id":"mk15044-pl-P1527445","type":"sc","tier":"基础","conf":"adapt","chap":"第6-7章","q":"在马克思主义发展史上，明确的将共产主义的第一阶段称之为社会主义社会的是（）","opts":["A. 马克思","B. 恩格斯","C. 列宁","D. 毛泽东"],"ans":2,"explain":"在马克思主义发展史上，明确的将共产主义的第一阶段称之为社会主义社会的是列宁"},{"id":"mk15044-pl-P1527446","type":"sc","tier":"基础","conf":"adapt","chap":"第6-7章","q":"共产主义社会形态在其发展进程中的第二阶段为（）","opts":["A. 社会主义初级阶段","B. 社会主义社会","C. 共产主义社会","D. 商品经济社会"],"ans":2,"explain":"第二阶段或高级阶段为共产主义社会。"},{"id":"mk15044-pl-P1527447","type":"sc","tier":"基础","conf":"adapt","chap":"第6-7章","q":"下列各项不属于共产主义社会基本特征的是（ ）。","opts":["A. 生产力高度发展和物质财富极大丰富","B. 实行社会公有制和按需分配","C. 计划经济和市场经济相结合","D. 人的自由而全面发展"],"ans":2,"explain":"共产主义社会基本特征是生产力高度发展和物质财富极大丰富、实行社会公有制和按需分配、实现人的自由而全面发展。"},{"id":"mk15044-pl-P1527448","type":"sc","tier":"基础","conf":"adapt","chap":"第6-7章","q":"广义的共产主义社会包含（ ）。","opts":["A. 社会主义社会和共产主义社会","B. 商品经济社会和产品经济社会","C. 社会主义初级阶段和高级阶段","D. 社会主义第一阶段和高级阶段"],"ans":0,"explain":"广义的共产主义社会包含社会主义社会和共产主义社会。"},{"id":"mk15044-pl-P1527449","type":"sc","tier":"基础","conf":"adapt","chap":"第6-7章","q":"共产主义社会个人消费品的分配原则是（）","opts":["A. 按劳分配","B. 按资分配","C. 按需分配","D. 平均分配"],"ans":2,"explain":"个人消费品相应地实行“按需分配”原则"},{"id":"mk15044-pl-P1527450","type":"sc","tier":"基础","conf":"adapt","chap":"第6-7章","q":"共产主义社会的分配原则是（ ）。","opts":["A. 按劳分配","B. 按需分配","C. 平均分配","D. 定量分配"],"ans":1,"explain":"共产主义社会的分配原则是按需分配。"},{"id":"mk15044-pl-P1527451","type":"sc","tier":"基础","conf":"adapt","chap":"第6-7章","q":"共产主义社会的显著特征和一面旗帜是（ ）。","opts":["A. 各尽所能，平均分配","B. 各尽所能，公平分配","C. 各尽所能，按劳分配","D. 各尽所能，按需分配"],"ans":3,"explain":"共产主义社会的显著特征和一面旗帜是各尽所能，按需分配。"},{"id":"mk15044-pl-P1527452","type":"sc","tier":"基础","conf":"adapt","chap":"第6-7章","q":"共产主义社会所有制实行（）","opts":["A. 生产资料社会公有制","B. 多种公有制形式","C. 公有制为主的经济形式","D. 生产资料全民所有制"],"ans":0,"explain":"共产主义社会高度社会化的生产，要求由社会占有全部生产资料，实行生产资料社会公有制。"},{"id":"mk15044-pl-P1527453","type":"sc","tier":"基础","conf":"adapt","chap":"第6-7章","q":"集中体现着共产主义社会主要特征和本质要求的原则标志着（ ）。","opts":["A. 各尽所能，按需分配","B. 各尽所能，按才能分配","C. 各尽所能，按劳分配","D. 各尽所能，按地位分配"],"ans":0,"explain":"集中体现着共产主义社会主要特征和本质要求的原则标志着各尽所能，按需分配。"},{"id":"mk15044-pl-P1527455","type":"sc","tier":"基础","conf":"adapt","chap":"第6-7章","q":"下列选项中属于共产主义社会显著特征的是（）","opts":["A. 按生产要素分配","B. 各尽所能，按劳分配","C. 按能力大小分配","D. 各尽所能，按需分配"],"ans":3,"explain":"马克思十分强调“各尽所能，按需分配”是共产主义社会的显著特征"},{"id":"mk15044-pl-P1527456","type":"sc","tier":"基础","conf":"adapt","chap":"第6-7章","q":"共产主义社会的主要特征和本质要求是（）","opts":["A. 各尽所能，平均分配","B. 各尽所能，按劳分配","C. 各尽所能，按资分配","D. 各尽所能，按需分配"],"ans":3,"explain":"马克思十分强调“各尽所能，按需分配”是共产主义社会的显著特征，并把它作为共产主义社会的一面旗帜加以突出论述。"},{"id":"mk15044-pl-P1527459","type":"sc","tier":"基础","conf":"adapt","chap":"第6-7章","q":"以每个人自由全面发展为基本原则的社会形式这种社会形式是指（）","opts":["A. 资本主义社会","B. 社会主义初级阶段","C. 社会主义社会","D. 共产主义社会"],"ans":3,"explain":"共产主义社会中人的自由全面发展和社会的全面发展是相互联系、相互促进、密不可分的"},{"id":"mk15044-pl-P1527460","type":"sc","tier":"基础","conf":"adapt","chap":"第6-7章","q":"共产主义的本质因素是（）","opts":["A. 实现生产资料公有制","B. 人民生活富裕","C. 实行按需分配","D. 人的自由而全面发展"],"ans":3,"explain":"马克思主义对共产主义社会的展望，总是把人的自由而全面发展作为共产主义社会的本质因素而加以描述，十分强调与共产主义社会制度相适应的社会成员必将是自由而全面发展的共产主义新人。"},{"id":"mk15044-pl-P1527461","type":"sc","tier":"基础","conf":"adapt","chap":"第6-7章","q":"在马克思主义对共产主义社会的展望中，作为共产主义社会的本质因素而加以描述的是（）","opts":["A. 社会生产力高度发展","B. 物质财富极大丰富","C. 国家自行消亡","D. 人的自由而全面发展"],"ans":3,"explain":"马克思主义对共产主义社会的展望，总是把人的自由而全面发展作为共产主义社会的本质因素而加以描述，十分强调与共产主义社会制度相适应的社会成员必将是自由而全面发展的共产主义新人。"},{"id":"mk15044-pl-P1527462","type":"sc","tier":"基础","conf":"adapt","chap":"第6-7章","q":"资本主义社会为新的社会制度准备的精神条件是（）","opts":["A. 社会化大生产","B. 现代无产阶级","C. 社会精神文明","D. 马克思主义理论"],"ans":3,"explain":"精神条件——马克思主义理论。"},{"id":"mk15044-pl-P1527463","type":"sc","tier":"基础","conf":"adapt","chap":"第6-7章","q":"社会化大生产是资本主义社会为新的社会制度准备的（）","opts":["A. 社会条件","B. 物质条件","C. 精神条件","D. 市场条件"],"ans":1,"explain":"物质条件——社会化大生产"},{"id":"mk15044-pl-P1527464","type":"sc","tier":"基础","conf":"adapt","chap":"第6-7章","q":"资本主义经济的发展为向更高级的生产方式过渡创造物质条件，这主要体现在（ ）。","opts":["A. 无产阶级队伍的壮大","B. 科学技术水平的不断提高","C. 社会化大生产的发展","D. 市场经济体制的发展完善"],"ans":2,"explain":"资本主义经济的发展为向更高级的生产方式过渡创造物质条件，这主要体现在社会化大生产的发展。"},{"id":"mk15044-pl-P1527465","type":"sc","tier":"基础","conf":"adapt","chap":"第6-7章","q":"资本主义经济发展为向更高级的生产方式过渡创造物质条件，主要表现在（）","opts":["A. 无产阶级队伍的壮大","B. 科学技术水平的不断提高","C. 社会化大生产的发展","D. 市场经济体制的发展完善"],"ans":2,"explain":"资本主义经济发展为向更高级的生产方式过渡创造物质条件，主要表现在社会化大生产的发展"},{"id":"mk15044-pl-P1527466","type":"sc","tier":"基础","conf":"adapt","chap":"第6-7章","q":"资本主义社会为新的社会制度准备的社会条件是（）","opts":["A. 社会化大生产","B. 现代无产阶级","C. 市场经济体制","D. 马克思主义理论"],"ans":1,"explain":"资本主义社会为自身被新的社会制度所取代准备了主客观条件： 物质条件——社会化大生产； 社会条件——现代无产阶级； 精神条件——马克思主义理论。"},{"id":"mk15044-pl-P1527467","type":"sc","tier":"基础","conf":"adapt","chap":"第6-7章","q":"人们在共产主义社会的劳动具有（）","opts":["A. 价值的交换性","B. 直接的社会性","C. 间接的社会性","D. 不等价交换性"],"ans":1,"explain":"因为人们的劳动具有直接的社会性，个人劳动不必通过价值交换的方式转化为社会劳动，从而使商品经济存在的条件归于消失。"},{"id":"mk15044-pl-P1527469","type":"sc","tier":"基础","conf":"adapt","chap":"第6-7章","q":"在共产主义社会里，国家将不复存在，国家是（）","opts":["A. 被废除的","B. 被消灭的","C. 自行消亡的","D. 被取代的"],"ans":2,"explain":"恩格斯指出：“随着阶级的消失，国家也不可避免地要消失。”“国家不是‘被废除’的，它是自行消亡的。”"},{"id":"mk15044-pl-P1527470","type":"sc","tier":"基础","conf":"adapt","chap":"第6-7章","q":"在共产主义社会，商品经济必将（）","opts":["A. 完全消失","B. 部分保留","C. 高度发达","D. 长期存在"],"ans":0,"explain":"而共产主义社会在生产力高度发展基础上，随着世界范围内彻底消灭了私有制，从而铲除了阶级对立存在的深刻经济根源，依靠生产资料私有制所形成的剥削阶级将归于消失，一切阶级差别和阶级矛盾也将不复存在。"},{"id":"mk15044-pl-P1527471","type":"sc","tier":"基础","conf":"adapt","chap":"第6-7章","q":"马克思主义正确揭示了国家的起源，它认为国家是（）","opts":["A. 适应社会公共管理事务需要的产物","B. 阶级矛盾不可调和的产物","C. 维护社会秩序和社会正义的产物","D. 防御外敌颠覆活动的需要"],"ans":1,"explain":"国家是阶级矛盾不可调和的产物，是一个阶级压迫另一个阶级的统治工具。"},{"id":"mk15044-pl-P1527472","type":"sc","tier":"基础","conf":"adapt","chap":"第6-7章","q":"阶级消灭和国家消亡是在（）","opts":["A. 社会主义革命中实现的","B. 社会主义建设中实现的","C. 社会主义发达阶段实现的","D. 共产主义社会实现的"],"ans":3,"explain":"践证明，彻底消灭阶级，只能在共产主义社会实现。"},{"id":"mk15044-pl-P1527473","type":"sc","tier":"基础","conf":"adapt","chap":"第6-7章","q":"作为人类社会发展的最高社会形态，共产主义社会的物质基础是（ ）。","opts":["A. 与任何繁荣的封建社会相当的社会生产力","B. 与一般资本主义社会相当的社会生产力","C. 与发达资本主义国家相当的社会生产力","D. 远远高于以往一切社会的高度发达的社会生产力"],"ans":3,"explain":"高度发展的社会生产力是实现共产主义社会的前提"},{"id":"mk15044-pl-P1527475","type":"sc","tier":"基础","conf":"adapt","chap":"第6-7章","q":"实现共产主义的根本条件和基础是（）","opts":["A. 社会生产力的高度发展","B. 人与人关系的高度和谐","C. 人的思想觉悟的极大提高","D. 人与自然关系的高度和谐"],"ans":0,"explain":"社会生产力的高度发展，是实现共产主义社会的根本条件和基础。"},{"id":"mk15044-pl-P1527476","type":"sc","tier":"基础","conf":"adapt","chap":"第6-7章","q":"实现共产主义社会的根本条件和基础是（ ）。","opts":["A. 社会生产力的高度发展","B. 人与人关系的高度和谐","C. 人的思想觉悟的极大提高","D. 自然生态环境的极大改善"],"ans":0,"explain":"实现共产主义社会的根本条件和基础是社会生产力的高度发展。"},{"id":"mk15044-pl-P1526533","type":"sa","tier":"创新","conf":"adapt","chap":"第6-7章","q":"简述社会主义发展道路多样性的原因。","opts":[],"ans":null,"explain":"(1)各国在社会主义革命时，其生产力状况和社会发展阶段是不同的，由此决定，不同社会主义国家的发展道路具有不同的特点。<br/>(2)各国的历史传统、文化习俗及具体国情各不相同，这是各国的发展道路不同的另一原因。<br/>(3)在社会主义的实践中，各国都在探索适合本国国情的发展道路。时代在前进，实践在发展，社会主义的发展道路因此而更具多样性。"},{"id":"mk15044-pl-P1526534","type":"sa","tier":"创新","conf":"adapt","chap":"第6-7章","q":"总结中国改革开放的实践经验，我们可以得到哪些启示？","opts":[],"ans":null,"explain":"(1)要坚持正确的理论指导。要把坚持马克思主义基本原理同推进马克思主义中国化结合起来，以实践基础上的理论创新为改革开放提供理论指导。<br/>(2)要坚持改革的正确方向。必须把坚持四项基本原则同坚持改革开放结合起来，以经济建设为中心，保持改革开放的正确方向，决不走封闭僵化的老路，也决不走改旗易帜的邪路，而是坚定不移地走中国特色社会主义道路。<br/>(3)要选择正确的改革方式与步骤，因地制宜，循序渐进。社会主义的改革事业不但要有正确的指导思想，还要在具体实施方法和步骤上，既探索创新，又切实可行。需要借鉴包括资本主义国家的经验在内的人类一切文明成果，但不能照搬任何国家的模式。要警惕和平演变的图谋。<br/>(4)要妥善处理改革、发展与稳定的关系。改革是动力，发展是目的，稳定是保证。改革要有稳定的社会政治环境，又要有一定的发展速度。改革会触动既得利益格局的变化，引起一些社会不稳定因素，这就需要用发展的方法在前进中解决问题。要坚持以人为本，全面协调可持续发展，统筹兼顾，实现经济建设、政治建设、文化建设、社会建设相协调。"},{"id":"mk15044-pl-P1526535","type":"sa","tier":"创新","conf":"adapt","chap":"第6-7章","q":"为什么说马克思主义政党是新型的革命政党？","opts":[],"ans":null,"explain":"(1)马克思主义政党是科学社会主义与工人运动相结合的产物。<br/>(2)马克思主义政党是工人阶级先锋队。<br/>(3)马克思主义政党是为实现共产主义而奋斗的党。<br/>(4)马克思主义政党是为人民群众谋利益的党。<br/>(5)马克思主义政党是按照民主集中制原则组织起来的团结统一的党。"},{"id":"mk15044-pl-P1526536","type":"sa","tier":"创新","conf":"adapt","chap":"第6-7章","q":"为什么说工人阶级的历史使命是由其历史地位决定的?","opts":[],"ans":null,"explain":"(1)工人阶级是社会化大生产的产物，与先进的生产方式相联系，是先进生产力的代表，是最有前途的阶级。<br/>(2)工人阶级是资本主义社会中的被剥削、被压迫的阶级，他们与资产阶级直接对立，具有革命彻底性，只有他们能肩负起推翻资产阶级统治、建立社会主义新社会的任务。<br/>(3)工人阶级会在斗争中不断成熟，从自在的阶级走向自为的阶级。"},{"id":"mk15044-pl-P1526537","type":"sa","tier":"创新","conf":"adapt","chap":"第6-7章","q":"简述“各尽所能，按需分配”的原则。","opts":[],"ans":null,"explain":"1.各尽所能，按需分配是共产主义社会的显著特征，是共产主义社会的伟大旗帜。<br/>2.这里的各尽所能，既体现着每个社会成员把向社会贡献自己的能力作为一种自觉自愿的应尽的社会义务，又体现着每个社会成员都摆脱了旧式分工的束缚，劳动不再仅仅是谋生或生存发展的手段，而是成为人们生活的第一需要，从而都能充分地施展和全面发挥自己的一切才能。<br/>3.所以，各尽所能，按需分配不只是一个个人消费品分配方式，而是一个集中体现着共产主义社会主要特征和本质要求的原则标志。"},{"id":"mk15044-pl-P1526538","type":"sa","tier":"创新","conf":"adapt","chap":"第6-7章","q":"社会主义与共产主义的共同点和差别表明了什么？","opts":[],"ans":null,"explain":"1.社会主义社会与共产主义社会的共同点表明，二者具有本质的內在联系，是共产主义社会形态的前后紧密衔接的两个发展阶段，它们与资本主义社会是根本性质不同的社会制度。<br/>2.社会主义社会与共产主义社会的差别表明，二者作为共产主义社会形态成熟程度不同的两个阶段，因而第一，社会主义社会在发展中日益成熟和完善，将来必然逐渐成长为共产主义社会；第二，共产主义社会只能经过社会主义社会的长期发展才能最终实现。"},{"id":"mk15044-pl-P1526539","type":"sa","tier":"创新","conf":"adapt","chap":"第6-7章","q":"简述实现共产主义需要具备的基本条件。","opts":[],"ans":null,"explain":"(1)社会生产力的高度发展，为实现共产主义创造物质技术基础；<br/>(2)全体社会成员的文化教育的普及和科学技术水平的极大提高；<br/>(3)全体社会成员的思想觉悟和道德品质的极大提高；<br/>(4)建立起同高度社会化生产相适应的生产资料社会公有制；<br/>(5)消灭旧的社会分工特别是三大差别，造就出体力和智力全面发展的新人；<br/>(6)在全世界消灭一切剥削制度和剥削阶级，作为阶级统治工具的国家自行消亡。"},{"id":"mk15044-pl-P1526540","type":"sa","tier":"创新","conf":"adapt","chap":"第6-7章","q":"如何理解人的自由而全面的发展？","opts":[],"ans":null,"explain":"(1)人们完全摆脱了生产资料私有制和阶级压迫的束缚。<br/>(2)人们完全摆脱了旧式分工的束缚。<br/>(3)人们完全摆脱了仅仅是谋生手段的劳动的束缚。<br/>(4)人们完全摆脱了接受教育和训练的限制。"},{"id":"mk15044-pl-P1527921","type":"sa","tier":"创新","conf":"adapt","chap":"第6-7章","q":"如何正确把握科学社会主义的一般原则？","opts":[],"ans":null,"explain":"（1）必须始终坚持科学社会主义一般原则，反对任何背离这些原则的错误倾向。<br/>（2）要善于把科学社会主义一般原则与本国实际相结合，创造性地回答和解决革命、建设、改革中的重大问题。<br/>（3）要紧跟时代和实践的发展，在不断总结新鲜经验中进一步丰富和发展科学社会主义一般原则。"},{"id":"mk15044-pl-P1527922","type":"sa","tier":"创新","conf":"adapt","chap":"第6-7章","q":"列宁指出：设想社会历史会一帆风顺，按部就班的向前发展，不会有时出现大幅度的跃进，那是不辩证的，不科学的，在理论上是不正确的。”社会主义也同样是在探索中曲折前进的，你对此如何理解？","opts":[],"ans":null,"explain":"世间一切事物都是波浪式发展、螺旋式上升的，社会主义运动，也是在探索中曲折前进的。社会主义在曲折中前进，主要是由以下因素决定的：<br/>（1）同一切新生事物一样，社会主义作为一种崭新的社会经济制度，其成长过程必然不会一帆风顺。<br/>（2）作为发展中国家的社会主义的基本矛盾运动，推动了社会主义的经济社会发展，但对基本矛盾的认识及其矛盾的运动发展是一个长期曲折的过程。<br/>（3）世界经济政治形势错综复杂的发展变化，国际经济政治秩序和格局的变动演化，也是决定社会主义曲折发展的一个影响因素。"},{"id":"mk15044-pl-P1527923","type":"sa","tier":"创新","conf":"adapt","chap":"第6-7章","q":"为什么说社会主义是在曲折中前进的?","opts":[],"ans":null,"explain":"（1）同一切新生事物一样，社会主义作为一种崭新的社会经济制度，其成长过程必然不会一帆风顺；<br/>（2）无产阶级及其政党对于社会主义建设规律的认识不可能一次完成而是一个不断反复的过程，从而导致社会主义的发展是一个曲折前进的过程；<br/>（3）世界经济政治形势变化错综复杂的发展变化，也是导致社会主义曲折发展的一个影响因素。"},{"id":"mk15044-pl-P1527924","type":"sa","tier":"创新","conf":"adapt","chap":"第6-7章","q":"马克思主义政党在社会主义建设中的领导核心作用主要体现在哪些方面？","opts":[],"ans":null,"explain":"（1）思想领导方面。马克思主义是社会主义国家的指导思想，在社会主义建设中，需要不断探索，把马克思主义基本原理同本国建设的具体实践相结合。<br/>（2）政治领导方面。作为社会主义国家执政党的马克思主义政党，在社会主义民主政治建设和政治体制改革中，在对社会各项事业进行政治领导的实践中，党要起到总揽全局、协调各方的政治领导核心的作用，保证社会主义建设沿着正确的方向前进。<br/>（3）在组织领导方面。社会主义建设是全体人民的共同事业，要在执政党的领导下，有组织、有系统、有管理、有序地进行。"},{"id":"mk15044-pl-P1527926","type":"sa","tier":"创新","conf":"adapt","chap":"第6-7章","q":"简述列宁发展马克思主义理论方面所作出的主要贡献。","opts":[],"ans":null,"explain":"首先，把社会主义建设作为一个长期探索、不断实践的过程。其次，把大力发展生产力、提高劳动生产率放在首位。再次，认识到在社会主义建设中，特别是过渡时期不能人为取消商品经济，而要利用商品货币关系发展经济。最后，列宁还提出利用资本主义，建设社会主义。"},{"id":"mk15044-pl-P1527927","type":"sa","tier":"创新","conf":"adapt","chap":"第6-7章","q":"简述构建新时代坚持和发展中国特色社会主义的基本方略。","opts":[],"ans":null,"explain":"坚持党对一切工作的领导。坚持以人民为中心。坚持全面深化改革。坚持新发展理念。坚持人民当家做主。坚持全面依法治国。坚持社会主义核心价值体系。坚持在发展中保障和改善民生。坚持人与自然和谐共生。坚持总体国家安全观。坚持党对人民军队的绝对领导。坚持“一国两制”和推进祖国统一。坚持推动构建人类命运共同体。坚持全面从严治党。以上十四条构成了新时代坚持和发展中国特色社会主义的基本方略。"},{"id":"mk15044-pl-P1527928","type":"sa","tier":"创新","conf":"adapt","chap":"第6-7章","q":"为什么说无产阶级革命是人类历史上最彻底最深刻的革命。","opts":[],"ans":null,"explain":"（1）无产阶级革命是要消灭私有制、建立公有制的社会革命，这是同以往私有制之间相互取代所发生的革命根本不同的<br/>（2）无产阶级革命是最终要彻底消灭一切阶级剥削和阶级统治的革命<br/>（3）无产阶级革命是为绝大多数人谋利益的运动<br/>（4）无产阶级革命是不断前进的历史进程"},{"id":"mk15044-pl-P1527929","type":"sa","tier":"创新","conf":"adapt","chap":"第6-7章","q":"为什么说无产阶级革命是人类历史上最广泛、最彻底、最深刻的革命？","opts":[],"ans":null,"explain":"（1）它是要消灭私有制、建立公有制的社会革命，这是不同私有制之间相互取代发生的革命不可比拟的。<br/>（2）它是最终要彻底消灭一切阶级和统治阶级的革命。<br/>（3）它是为绝大多数人谋利的运动，是解放全人类的革命。<br/>（4）它是不断前进的历史进程，它的最终目标是实现共产主义，使人得到全面发展。"},{"id":"mk15044-pl-P1527930","type":"sa","tier":"创新","conf":"adapt","chap":"第6-7章","q":"为什么说实现共产主义是人类最伟大的事业？","opts":[],"ans":null,"explain":"（1）共产主义事业是最崇高理想与科学理念的统一。古往今来，人类对理想社会的追求，经历了漫长的道路。一些志士仁人都提出过建立平等自由的大同社会的理想主张。但他们所追求的理想社会，不是建立在认识发展规律基础上的科学理想，难免流于空幻。<br/>（2）马克思和恩格斯深刻分析了社会运动的规律和趋势，总结了国际工人运动的历史经验，继承和发展了人类历史上一切进步思想的优秀成果，科学地预见了共产主义社会这一理想制度的基本特征，向全世界劳动群众展示人类社会终将进入共产主义的美好社会前景。<br/>（3）共产主义之所以是人类最伟大的事业，就在于它是崇高理想与科学理想的统一，体现了人类对理想社会目标的追求与符合规律的科学社会实践的有机结合。"},{"id":"mk15044-pl-P1527931","type":"sa","tier":"创新","conf":"adapt","chap":"第6-7章","q":"简述共产主义远大理想和中国特色社会主义共同理想的关系。","opts":[],"ans":null,"explain":"（1）共产主义远大理想和中国特色社会主义共同理想，二者相辅相成，相互促进，有机联系和统一。<br/>（2）远大理想是现阶段共同理想的奋斗目标。<br/>（3）现阶段的共同理想是远大理想的坚实基础。"},{"id":"mk15044-pl-P1527932","type":"sa","tier":"创新","conf":"adapt","chap":"第6-7章","q":"实现共产主义需要具备哪些基本条件？","opts":[],"ans":null,"explain":"（1）社会生产力高度发展，物质产品极大丰富；<br/>（2）全体社会成员的文化教育的普及和科学技术水平的极大提高；<br/>（3）全体社会成员的思想觉悟和道德品质的极大提高；<br/>（4）建立同高度社会化生产相适应的生产资料社会公有制；<br/>（5）消灭旧的社会分工特别是三大差别；（6）消灭一切剥削制度和剥削阶段，国家自行消亡。"},{"id":"mk15044-pl-P1527933","type":"sa","tier":"创新","conf":"adapt","chap":"第6-7章","q":"为什么说社会主义是走向共产主义的必由之路？","opts":[],"ans":null,"explain":"共产主义社会是人类历史上最美好和最理想的社会制度，但是，实现共产主义的物质的和社会的条件，只能在社会主义阶段的长期发展建设过程中逐渐形成。依据共产主义社会发展两阶段原理，人类社会的发展，只能从资本主义社会首先过渡到社会主义社会，而不能超越社会主义这个历史阶段。社会主义社会是共产主义社会的低级阶段，是走向共产主义高级阶段的必由之路。只有经过社会主义社会的长期发展，在社会生产力高度发展的基础上，随着物质文明和精神文明以及社会文化的长足发展，才能使旧的社会痕迹逐步消失，从而为实现共产主义铺平道路。所以，社会主义是走向共产主义的必经阶段和必由之路。"},{"id":"mk15044-pl-P1527934","type":"sa","tier":"创新","conf":"adapt","chap":"第6-7章","q":"简述“人的自由而全面的发展”的含义。","opts":[],"ans":null,"explain":"人的自由全面发展，是指每个社会成员的体力智力获得全面发展和自由运用，个人的全部智慧、力量和潜能素质都能全面自由地尽量发挥，每个社会成员可以按照自己的兴趣、爱好、意愿以及社会的需要自由地选择职业。"},{"id":"mk15044-pl-P1527935","type":"sa","tier":"创新","conf":"adapt","chap":"第6-7章","q":"为什么说共产主义社会要建立在社会生产力高度发展的基础上？","opts":[],"ans":null,"explain":"（1）社会生产力是社会发展和社会进步的最终决定力量，是全部社会历史的物质基础。<br/>（2）共产主义社会是人类社会发展的最高形态，它的物质基础应该是远远高于以往一切社会的高度发达的社会生产力。<br/>（3）只有在社会生产力高度发展的基础上，才有可能建立其共产主义的经济基础和上层建筑，从而进入共产主义社会。"},{"id":"mk15044-pl-P1526500","type":"sa","tier":"创新","conf":"adapt","chap":"第6-7章","q":"如何坚持和改善马克思主义政党的领导？","opts":[],"ans":null,"explain":"(1)马克思主义政党的领导是实现工人阶级历史使命的根本保证。在社会主义建设的各个时期都离不开马克思主义政党的坚强领导。因此要在坚持党的领导核心地位的同时不断改进完善党的领导。<br/>(2)坚持党的领导是社会主义民主政治的首要内容。社会主义民主离不开马克思主义政党的领导，因为马克思主义政党代表人民群众的根本利益，作为执政党在社会主义国家中领导人民实现管理国家和社会事务的权利。放弃党的领导，人民群众的民主权利和根本利益就无法保障，社会主义民主也就无从谈起。因此坚持社会主义就必须坚持马克思主义政党的领导核心地位。<br/>(3)坚持党的领导必须不断改善党的领导。社会主义事业是一项前无古人的崭新事业，人们在社会主义实践中不断探索，对层出不穷的新情况、新问题，要善于学习和总结经验，在发扬成绩、纠正错误中不断前进。对党的领导同样如此，要在实践中探索党在新形势下实现其思想、政治、组织领导的新形式、新方法。<br/>(4)加强和改善党的领导，必须加强马克思主义政党的先进性建设。先进性是马克思主义政党的本质属性，是马克思主义政党的生命所系，力量所在。保持和发展党的先进性是马克思主义政党自身建设的根本任务和永恒课题。"},{"id":"mk15044-pl-P1526501","type":"sa","tier":"创新","conf":"adapt","chap":"第6-7章","q":"试述从社会主义向共产主义过渡的特点。","opts":[],"ans":null,"explain":"从社会主义社会过渡到共产主义社会，同历史上以往的不同性质的社会形态之间的过渡和更迭具有重大差别。<br/>(1)以往不同性质的社会形态的过渡和更迭，不是通过旧社会形态内部的自我完善和发展，在原有的生产关系和上层建筑逐步调整和成熟中实现的，而是由新的、性质完全不同的生产关系和上层建筑取代旧的生产关系和上层建筑而实现的。伴随着这种过渡和更迭，必然是尖锐的矛盾和激烈的斗争，以至通过武装斗争的形式来实现。<br/>(2)社会主义社会和共产主义社会是同一种社会形态的两个成熟程度不同的发展阶段，它们都是以生产资料公有制为基础的社会制度，二者之间不存在对抗性矛盾。<br/>(3)因而从社会主义社会过渡到共产主义社会，只是从不成熟的共产主义社会发展到成熟的共产主义社会，它表现为同一社会形态内部的过渡和变化。"},{"id":"mk15044-pl-P1526502","type":"sa","tier":"创新","conf":"adapt","chap":"第6-7章","q":"简述共产主义社会中人的自由全面发展和社会的全面发展的关系。","opts":[],"ans":null,"explain":"共产主义社会中人的自由全面发展和社会的全面发展是相互联系、相互促进、密不可分的。一方面，个人的自由全面发展只有在社会集体中才能实现，要以社会的物质文明和精神文明的全面发展为支撑。另一方面，人的自由全面发展，又能促进社会经济文化的发展，创造出更加璀璨的物质文明和精神文明，有力地推动社会全面发展。"}];
